class Diameter
{
public:
	vec<vec<int>> g;
	pair<int, int> ps;
	vec<int> path;
	int n;
	Diameter(int num): g(num) {
		ps.first = 0;
		ps.second = 0;
		n = num;
	}

	void edge(int a, int b) {
		g[a].pb(b);
		g[b].pb(a);
	}

	int longest(int a) {
		queue<pair<int, vec<int>>> keep;
		vec<int> hoge = {a};
		keep.push(mp(a, hoge));
		vec<int> dp(n, 0);

		pair<int, vec<int>> cur;
		while(!keep.empty()) {
			pair<int, vector<int>> get = keep.front();
			keep.pop();
			int cur_p = get.first;
			if (dp[cur_p]) continue;
			dp[cur_p] = 1;
			cur = get;
			rep(i, g[cur_p].size()) {
				int v = g[cur_p][i];
				vec<int> v_path = get.second;
				v_path.pb(v);

				keep.push(mp(v, v_path));
			}
		}

		path = cur.second;
		return cur.first;
	}

	vec<int> diameter(void) {
		ps.first = longest(0);
		ps.second = longest(ps.first);
		return path;
	}
};

ll solve(vec<int> cur_p, vec<vec<int>> g)
