#include <bits/stdc++.h>
using namespace std;

int n, colorfulness;
static vector<int> edges[100];

size_t leaves(int u, int v){
    vector<int> level[100];
    bool used[100];
    size_t count[100];
    for(int i=0;i<100;++i){ used[i] = false; count[i] = 0; }

    level[0].push_back(u);
    used[u] = true;
    level[0].push_back(v);
    used[v] = true;

    for(int i=0;level[i].size();++i){
        for(int v: level[i]){
            count[i] = max(count[i], edges[v].size() - 1);
            for(int to: edges[v]){
                if(used[to]) continue;
                used[to] = true;
                level[i+1].push_back(to);
            }
        }
    }
    size_t ret = 2;
    for(int i=0;count[i];++i) ret *= count[i];
    return ret;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    cin >> n;
    for(int i=1;i<n;++i){
        int a, b;
        cin >> a >> b;
        --a; --b;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    int u, v;
    queue<pair<int, int>> q;
    q.emplace(0, -1);
    while(!q.empty()){
        auto t = q.front();
        q.pop();
        u = t.first;
        for(auto to: edges[u]){
            if(to == t.second) continue;
            q.emplace(to, u);
        }
    }
    static int parent[100];
    parent[u] = -1;
    q.emplace(u, -1);
    while(!q.empty()){
        auto t = q.front();
        q.pop();
        v = t.first;
        for(auto to: edges[v]){
            if(to == t.second) continue;
            parent[to] = v;
            q.emplace(to, v);
        }
    }
    vector<int> path;
    path.push_back(v);
    while(path.back() != u){ path.push_back(parent[path.back()]); }
    colorfulness = (path.size() + 1) / 2;
    if(path.size() % 2 == 0){
        cout << colorfulness << " " << leaves(path[path.size() / 2], path[path.size() / 2 + 1]) << endl;
        return 0;
    }

    vector<int> level[100];
    static bool used[100];
    u = path[path.size()/2];
    level[0].push_back(u);
    used[u] = true;

    static size_t count[100];
    for(int i=0;level[i].size();++i){
        for(int v: level[i]){
            count[i] = max(count[i], edges[v].size() - 1);
            for(int to: edges[v]){
                if(used[to]) continue;
                used[to] = true;
                level[i+1].push_back(to);
            }
        }
    }
    if(path.size() & 1) ++count[0];
    size_t ans = 1;
    for(int i=0;count[i];++i) ans *= count[i];

    for(int v: edges[u]) ans = min(ans, leaves(u, v));
    cout << colorfulness << " " << ans << endl;

    return 0;
}

#include<bits/stdc++.h>
#define N 110
using namespace std;
vector<int> r[N];
int n,f[N],q[N],t,fa[N],sz[N],MX[N];
void dfs(int x){
	++f[x];sz[x]=0;
	for(int i=0,_E_=r[x].size();i<_E_;++i){
		int y=r[x][i];if(y==fa[x])continue;
		fa[y]=x;f[y]=f[x];++sz[x];dfs(y);
	}
}
void find(int nn){
	fa[1]=0;f[1]=0;dfs(1);
	int mx=0;
	for(int i=1;i<=nn;++i)if(f[i]>f[mx])mx=i;
	f[mx]=0;fa[mx]=0;dfs(mx);
	for(int i=1;i<=nn;++i)if(f[i]>f[mx])mx=i;
	t=0;for(;mx;mx=fa[mx])q[++t]=mx;
}
long long calc1(int nn){
	for(int i=1;i<=nn;++i)MX[i]=1;
	long long ans=1;
	int x=q[t+1>>1];
	fa[x]=0;f[x]=0;dfs(x);
	for(int i=1;i<=nn;++i)MX[f[i]]=max(MX[f[i]],sz[i]);
	for(int i=1;i<=nn;++i)ans*=MX[i];
	return ans;
}
long long calc2(int nn){
	for(int i=1;i<=nn;++i)MX[i]=1;
	int x=q[t>>1],y=q[t+2>>1];
	fa[x]=y;fa[y]=x;f[x]=f[y]=0;dfs(x);dfs(y);
	for(int i=1;i<=nn;++i)MX[f[i]]=max(MX[f[i]],sz[i]);
	long long ans=2;
	for(int i=1;i<=nn;++i)ans*=MX[i];
	return ans;
}
int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;++i)MX[i]=1;
	for(int i=1;i<n;++i){
		int x,y;scanf("%d %d",&x,&y);
		r[x].push_back(y);r[y].push_back(x);
	}
	find(n);int TT=t+1>>1;
	long long ans;
	if(t&1){
		ans=calc1(n);
		for(int i=1;i<=n;++i){
			r[i].push_back(n+1);
			r[n+1].push_back(i);
			find(n+1);
			ans=min(ans,(t&1)?calc1(n+1):calc2(n+1));
			r[i].pop_back();
			r[n+1].pop_back();
		}
	}else{
		ans=calc2(n);
	}
	printf("%d %lld",TT,ans);
}

