        g[b].push_back(a);
    }

    P ans = P(n, n);

    // 中心が1つ
    for(int i = 0; i < n; i++)
    {
        vector<int> d(n);
        vector<int> ord(n);
        for(int j = 0; j < n; j++)
        {
            d[j] = -1;
            ord[j] = 0;
        }
