        while(!que.empty())
        {
            int cand = que.front();
            que.pop();
            for(auto nx : g[cand])
            {
                if(d[nx] == -1)
                {
                    d[nx] = d[cand] + 1;
                    que.push(nx);
                    ord[cand]++;
                }
            }
        }
