                dmax = max(dmax, d[j]);
                ma[d[j]] = max(ma[d[j]], ord[j]);
            }
        }
        ll second = 1;
        for(int j = 0; j < n; j++)
        {
            if(ma[j] != 0)
            {
                second *= ma[j];
            }
        }
        ans = min(ans, P(dmax+1, second));
    }

    // 中心が2つ 
    for(int i = 0; i < n; i++)
    {
        for(auto tmp: g[i])
        {
            // tmp: もう一つの中心
            vector<int> d(n);
            vector<int> ord(n);
            for(int j = 0; j < n; j++)
            {
                d[j] = -1;
                ord[j] = 0;
            }
