                    {
                        d[nx] = d[cand] + 1;
                        que.push(nx);
                        ord[cand]++;
                    }
                }
            }
            // dごとのordmax
            vector<int> ma(n);
            int dmax = 0;
            for(int j = 0; j < n; j++)
            {
                if(d[j] != -1)
                {
                    dmax = max(dmax, d[j]);
                    ma[d[j]] = max(ma[d[j]], ord[j]);
                }
            }
            ll second = 2;
            for(int j = 0; j < n; j++)
            {
                if(ma[j] != 0)
                {
                    second *= ma[j];
                }
            }
            ans = min(ans, P(dmax+1, second));
        }
    }
    cout << ans.first << " " << ans.second << endl;
