        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    int u = 0;
    vector<int> dist(n, -1);
    dist[u] = 0;
    dfs1(u, -1, dist);
    for (int i = 0; i < n; i++) {
        if (dist[u] < dist[i]) {
            u = i;
        }
    }

    vector<int> dist2(n, -1);
    dist2[u] = 0;
    dfs1(u, -1, dist2);
    int v = u;
    for (int i = 0; i < n; i++) {
        if (dist2[v] < dist2[i]) {
            v = i;
        }
    }

    int ans1 = dist2[v] / 2 + 1;

    dist.assign(n, -1);
    dist[v] = 0;
    dfs1(v, -1, dist);

    vector<int> ce;
    for (int i = 0; i < n; i++) {
        if (dist2[i] == dist2[v] / 2) {
            ce.push_back(i);
            break;
        }
    }

    for (int i = 0; i < n; i++) {
        if (dist[i] == dist[u] / 2) {
            ce.push_back(i);
            break;
        }
    }

    vector<ll> num1(n, 1);
    dfs2(ce[0], ce[1], 0, num1);
    dfs2(ce[1], ce[0], 0, num1);
    ll ans2 = 1;
    for (int i = 0; i < n; i++) {
        ans2 *= num1[i];
    }

    if (dist2[v] % 2 == 0) {
        for (int nex : g[ce[0]]) {
            vector<ll> num2(n, 1);
            dfs2(ce[0], nex, 0, num2);
            dfs2(nex, ce[0], 0, num2);
            ll tmp = 1;
            for (int i = 0; i < n; i++) {
                tmp *= num2[i];
            }
            ans2 = min(ans2, tmp * 2);
        }
    } else {
        ans2 *= 2;
    }

    cout << ans1 << " " << ans2 << endl;
    return 0;
}

