#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int MAXN = 1e2 + 5;

int N;
vector <int> E[MAXN];
int dist[MAXN];
int mx[MAXN];

void add(int a, int b) {
	E[a].push_back(b);
	E[b].push_back(a);
}

void remove(int a, int b) {
	vector <int> nxt;
	for (auto it : E[a])
		if (it != b)
			nxt.push_back(it);
	E[a] = nxt;
}

void load() {
	scanf("%d", &N);
	for (int i = 1; i < N; i++) {
		int a, b;
		scanf("%d%d", &a, &b);
		add(a, b);
	}
}

int dfs(int x, int p) {
	int res = 0;
	for (auto it : E[x])
		if (it != p)
			res = max(res, dfs(it, x) + 1);
	return res;
}

void go(int x, int p, int d) {
	int ch = 0;
	for (auto it : E[x])
		if (it != p) {
			go(it, x, d + 1);
			ch++;
		}
	mx[d] = max(mx[d], ch);
}

ll calc(int root) {
	memset(mx, 0, sizeof mx);
	go(root, 0, 0);
	ll res = 1;
	for (int i = 0; i < MAXN; i++)
		if (mx[i])
			res *= mx[i];
	return res;
}

ll add_root(int a, int b) {
	remove(a, b);
	remove(b, a);
	add(N + 1, a);
	add(N + 1, b);
	ll res = calc(N + 1);
	remove(N + 1, a);
	remove(N + 1, b);
	remove(a, N + 1);
	remove(b, N + 1);
	add(a, b);
	return res;
}

void solve() {
	for (int i = 1; i <= N; i++)
		dist[i] = dfs(i, 0);

	int mn = *min_element(dist + 1, dist + N + 1);
	vector <int> centre;
	for (int i = 1; i <= N; i++)
		if (dist[i] == mn)
			centre.push_back(i);

	assert(centre.size() <= 2);

	ll sol = LLONG_MAX;
	if (centre.size() == 1) {
		sol = min(sol, calc(centre[0]));
		vector <int> adj = E[centre[0]];
		for (auto it : adj)
			sol = min(sol, add_root(centre[0], it));
	}
	else
		sol = min(sol, add_root(centre[0], centre[1]));

	printf("%d %lld\n", mn + (centre.size() == 1), sol);
}

int main() {
	load();
	solve();
	return 0;
}

