using namespace std;

typedef long long ll;

ll Solve(int u, int v, const vector<vector<int>>& g, const vector<int>& degree) {
  int n = g.size();
  vector<int> maxDegree(n);
  for (int i = 0; i < n; ++i) {
    int depth = min(g[i][u], g[i][v]);
    maxDegree[depth] = max(maxDegree[depth], degree[i]);
  }

  ll result = 2;
  if (u == v) {
    result = degree[u];
  }

  for (int depth = 1; depth < n; ++depth) {
    ll cur = maxDegree[depth];
    if (cur <= 1) continue;
    result *= cur - 1;
  }

  if (u != v && maxDegree[0] > 1) {
    result *= maxDegree[0] - 1;
  }
  return result;
}

int main()
{
  int n;
  cin >> n;

  const int inf = 1000;
  vector<vector<int>> g(n, vector<int>(n, inf));
  for (int i = 0; i < n; ++i) g[i][i] = 0;

  vector<int> degree(n);

  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    degree[a]++;
    degree[b]++;
    g[a][b] = 1;
    g[b][a] = 1;
  }

  for (int t = 0; t < n; ++t) {
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < n; ++j) {
        if (g[i][j] > g[i][t] + g[t][j]) {
          g[i][j] = g[i][t] + g[t][j];
        }
      }
    }
  }

  int d = 0;
  int x = -1;
  int y = -1;

  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      if (g[i][j] > d) {
        d = g[i][j];
        x = i;
        y = j;
      }
    }
  }

  int u = -1;
  int v = -1;
  for (int i = 0; i < n; ++i) {
    if (g[x][i] == d / 2 && g[i][y] == d - d / 2) {
      u = i;
    }
    if (g[x][i] == d - d / 2 && g[i][y] == d / 2) {
      v = i;
    }
  }

  ll result = Solve(u, v, g, degree);
  if (u == v) {
    for (int w = 0; w < n; ++w) {
      if (g[u][w] == 1) {
        result = min(result, Solve(u, w, g, degree));
      }
    }
  }

  cout << d / 2 + 1 << " " << result << endl;

  return 0;
}

