int n, deg[maxn + 3], son[maxn + 3], dep[maxn + 3], mx[maxn + 3];
vector<int> G[maxn + 3];
pair<int, ll> ans, res;

void dfs(int u, int pa = 0) {
	son[u] = 0;
	for (int i = 0, v; i < G[u].size(); i++) {
		v = G[u][i];
		if (v == pa) continue;
		dep[v] = dep[u] + 1;
		son[u]++;
		dfs(v, u);
	}
}

pair<int, ll> calc() {
	int x = 0;
	for (int i = 1; i <= n; i++) {
		x = max(x, dep[i]);
	}
	for (int i = 1; i <= x; i++) {
		mx[i] = 0;
	}
	int c = 0;
	for (int i = 1; i <= n; i++) {
		mx[dep[i]] = max(mx[dep[i]], son[i]);
		if (dep[i] == 1) c++;
	}
	ll y = c;
	for (int i = 1; i < x; i++) {
		y = min(inf, y * mx[i]);
	}
	return make_pair(x, y);
}

pair<int, ll> solve_1(int u) {
	dep[u] = 1;
	dfs(u);
	return calc();
}

pair<int, ll> solve_2(int u, int v) {
	dep[u] = dep[v] = 1;
	dfs(u, v), dfs(v, u);
	return calc();
}

void search(int u, int pa = 0) {
	for (int i = 0, v; i < G[u].size(); i++) {
		v = G[u][i];
		if (v == pa) continue;
		res = min(res, solve_2(u, v));
		search(v, u);
	}
}

pair<int, ll> solve() {
	res.first = maxn + 3, res.second = 0;
	for (int i = 1; i <= n; i++) {
		res = min(res, solve_1(i));
	}
	search(1);
	return res;
}

