int cir[maxn],ctp;

inline int bfs(int S)
{
	static int dis[maxn],pre[maxn];
	static queue<int>q;
	q.push(S);
	REP(i,1,n)dis[i]=n+1,pre[i]=0;
	dis[S]=0;
	while(!q.empty())
	{
		int u=q.front();q.pop();
		for(int v:ed[u])
		{
			if(dis[v]>dis[u]+1)
				dis[v]=dis[u]+1,pre[v]=u,q.push(v);
		}
	}
	int mx=0,mxid=0;
	REP(i,1,n)if(dis[i]>mx)mx=dis[i],mxid=i;
	ctp=0; for(int x=mxid;x;x=pre[x])cir[++ctp]=x;
	return mxid;
}

ll num;
int vis[maxn];

inline void doing()
{
	int S=bfs(1);
	bfs(S);
	int ans=ctp+1>>1;
	num=1ll<<60;
	if(~ctp&1)
	{
		int L=cir[ctp>>1],R=cir[ctp+2>>1];
		vis[L]=vis[R]=1;
		static int f[maxn]; memset(f,0,sizeof(int)*(n+1));
		REP(i,0,n)f[i]=1;
		int len=ctp>>1;
		function<void(int u,int fa,int dis)>dfs =[&](int u,int fa,int dis) {
			int son=0;
			for(int v:ed[u])
				if(v!=fa && !vis[v])
				{
					++son;
					dfs(v,u,dis+1);	
				}
			chkmax(f[dis],son);
		};
		dfs(L,0,1); dfs(R,0,1);
		ll res=1;
		REP(i,1,len)res*=f[i];
		res*=2;
		num=res;
	}else
	{
		static int f[maxn]; memset(f,0,sizeof(int)*(n+1));
		REP(i,0,n)f[i]=1;
		int len=ctp+1>>1;
		int RT=cir[ctp+1>>1];
		function<void(int u,int fa,int dis)>dfs =[&](int u,int fa,int dis) {
			int son=0;
			for(int v:ed[u])
				if(v!=fa && !vis[v])
				{
					++son;
					dfs(v,u,dis+1);	
				}
			chkmax(f[dis],son);
		};
		dfs(RT,0,1);
		ll res=1;
		REP(i,1,len)res*=f[i];
		chkmin(num,res);


		int L=RT,R;
		REP(i,0,SZ(ed[L])-1)
		{
			R=ed[L][i];
			REP(i,0,n)f[i]=1;
			len=ctp+1>>1;
			dfs(L,R,1); dfs(R,L,1);
			ll res=1;
			REP(i,1,len)res*=f[i];
			chkmin(num,res*2);
		}
	}
	printf("%d %lld\n",ans,num);
}

