				if (dis[j] > dis[i])num++;
			}
			if (!dis[i])m[dis[i]] = max(m[dis[i]], num * 2);
			else m[dis[i]] = max(m[dis[i]], num);
		}
		long long int bag = 1;
		for (auto i : m)bag *= (!i ? 1 : i);
		ans = min(ans, bag);
	}
	else {
		for (auto loop : edge[center[0]]) {
			vector<int>dis(N, MOD);
