            y = x ? i : 0, x = x ? x : i;

    int ans;
    if( !y )
    {
    	ans = calc_ans( x, 0 );
    	for( int i = front[x]; i; i = e[i].next )
    		ans = std::min( ans, calc_ans( x, e[i].v ) );
	}
