                dist[v] = dist[que[j]] + 1;
                deg[que[j]]++;
                que.emplace_back(v);
            }
            chmax(maxdeg[dist[que[j]]], deg[que[j]]);
            chmax(col, dist[que[j]]);
        }
        lint leaf = 1;
        for (int i = 0; i < n + 1; ++i) {
            if (maxdeg[i] != 0)
                leaf *= maxdeg[i];
        }
