inline void wk(int x,int y)
{
	rep(i,1,n) dep[i]=0,vis[i]=0,mx[i]=0;
	queue <int> q; q.push(x); q.push(y); vis[x]=1; vis[y]=1;
	while(!q.empty())
	{
		int u=q.front(); q.pop();
		for(int i=0;i<mp[u].size();i++)
		{
			int v=mp[u][i]; if(vis[v]) continue;
			dep[v]=dep[u]+1; vis[v]=1; q.push(v);
		}
	}
	rep(i,1,n) mx[dep[i]]=max(mx[dep[i]],(int)mp[i].size()-1);
	ll tmp=1,p2=0;
	if(y!=0) mx[dep[0]]=max(mp[x].size(),mp[y].size())-1;
	else mx[dep[0]]=mp[x].size();
	rep(i,0,n) if(mx[i]) tmp*=mx[i]; else break; if(y!=0) tmp*=2;
	rep(i,1,n) p2=max(p2,(ll)dep[i]); //cout<<x<<" "<<y<<" "<<p2<<" "<<tmp<<endl;
	if(a1==p2) a2=min(a2,tmp); else if(a1>p2) a1=p2,a2=tmp;
}

