const int MAXN = 110;

int n;
vector<int> v[MAXN];
pair<ull, ull> ans(MAXN, 0);

int u[MAXN], cnt[MAXN], most[MAXN];

void check(int r, int s)
{
	for (int i = 1; i <= n; ++ i)
	{
		u[i] = 0;
		cnt[i] = 0;
		most[i] = 0;
	}
	queue<int> q;
	int c = 1;
	if (s != -1)
	{
		q.push(r);
		q.push(s);
		u[r] = u[s] = 1;
	}
	else
	{
		q.push(r);
		u[r] = 1;
	}
	while (!q.empty())
	{
		int x = q.front();
		q.pop();
		for (auto y : v[x])
			if (!u[y])
			{
				u[y] = u[x]+1;
				cnt[x] ++;
				c = max(c, u[y]);
				q.push(y);
			}
	}
	for (int i = 1; i <= n; ++ i)
		most[u[i]] = max(most[u[i]], cnt[i]);
	ull tmp = (s == -1) ? 1 : 2;
	for (int i = 1; i < c; ++ i)
		tmp *= most[i];
	ans = min(ans, pair<ull, ull>(c, tmp));
}

