{

	n = inp();
	for (int i = 1; i < n; ++ i)
	{
		int x = inp();
		int y = inp();
		v[x].push_back(y);
		v[y].push_back(x);
	}
	for (int r = 1; r <= n; ++ r)
	{
		check(r, -1);
		for (auto s : v[r])
			check(r, s);
	}
	cout << ans.X << " " << ans.Y << endl;

	return 0;
}

