int dep[maxn], p[maxn];

void dfs(int v, int pr) {
  p[v] = pr;
  for (int i = 0; i < sz(g[v]); i++) {
    int u = g[v][i];
    if (u == pr) {
      continue;
    }
    dep[u] = dep[v] + 1;
    dfs(u, v);
  }
