long long get(long long res0) {
  long long res = res0;
  for (int d = 1;; d++) {
    int deg = 0;
    for (int i = 0; i < n; i++) {
      if (dep[i] == d) {
        deg = max(deg, sz(g[i]) - 1);
      }
    }
    if (!deg) {
      break;
    }
    res *= deg;
  }
  return res;
}

void solve() {
  if (n == 2) {
    printf("1 2\n");
    return;
  }
  dep[0] = 0;
  dfs(0, -1);
  int v0 = 0;
  for (int i = 1; i < n; i++) {
    if (dep[i] > dep[v0]) {
      v0 = i;
    }
