  dep[v0] = 0;
  dfs(v0, -1);
  int v1 = 0;
  for (int i = 1; i < n; i++) {
    if (dep[i] > dep[v1]) {
      v1 = i;
    }
  }
  int maxd = dep[v1] / 2 + 1;
  long long res;
  if (dep[v1] & 1) {
    int v = v1;
    for (int i = 0; i < dep[v1] / 2; i++) {
      v = p[v];
    }
    int u = p[v];
    dep[v] = 0;
    dfs(v, u);
    dep[u] = 0;
    dfs(u, v);
    res = 2 * (max(sz(g[v]), sz(g[u])) - 1);
    res = get(res);
  } else {
    int v = v1;
    for (int i = 0; i < dep[v1] / 2; i++) {
      v = p[v];
    }
    dep[v] = 0;
    dfs(v, -1);
