      dep[u] = 0;
      dfs(u, v);
      long long cur = 2 * (max(sz(g[v]), sz(g[u])) - 1);
      cur = get(cur);
      res = min(res, cur);
    }
  }
  printf("%d %lld\n", maxd, res);
}

