//deg, sum, cnt
tuple<int,int, int> calcMaxDegree(vector<int> &D, queue<int> &Q,int target, int flag){
  int deg = 0,sum = 0, cnt = 0;
  while(!Q.empty()){
    int pos = Q.front();
    int cost = D[pos];
    if(cost > target) break;

    if(cost == target) {
      Max(deg, (int)G[pos].size() - flag);
      sum += G[pos].size() - flag;
      cnt++;
    }

    Q.pop();

    for(int to:G[pos]){
      if(D[to] != -1) continue;
      D[to] = cost + 1;
      Q.push(to);
    }
  }
  return tie(deg, sum, cnt);
}


P solve(vector<int> start){
  vector<int> D(n,-1);
  queue<int> Q;
  for(int s:start){Q.push(s); D[s] = 0;}

  int col = 1, leaf = start.size();
  int flag = leaf != 1;

  for(int i=0;i<n;i++, flag = 1){
    int deg, sum, cnt; 
    tie(deg, sum, cnt) = calcMaxDegree(D, Q, i, flag);
    if(deg == 0) break;
    col++;
    leaf = leaf * deg;
  }
  return {col, leaf};
}

signed main(){
  cin.tie(0);
  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(12);

  cin>>n;
  G.resize(n);

  DiameterOfTree DoT(n);
  for(int i=1;i<n;i++){
    int a, b;
    cin>>a>>b; a--, b--;
    G[a].push_back(b);
    G[b].push_back(a);
    DoT.add_edge(a, b);
  }

  DoT.build();
  vector<int> start;
  auto path = DoT.getPath();
  start.push_back( path[DoT.length/2] );
  if(DoT.length % 2) start.push_back( path[DoT.length/2 + 1] );

  P a = solve(start);
  P b = P(INF,INF);
  if(start.size() == 1){
    int center = start[0];
    int center2 = 0, mn = INF;
    for(int to:G[center]){
      int diff = abs(G[center].size()-G[to].size());
      if(mn > diff) center2 = to, mn = diff;
    }
    start.push_back(center2);
    b = solve(start);
  }

  P ans = min(a, b);
  cout<<ans.first<<" "<<ans.second<<endl;
  return 0;
}

