int main()
{
    int n;
    cin >> n;
    vector<vector<int>> g(n);
    for(int i = 0; i < n-1; i++)
    {
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    P ans = P(n, n);

    // 中心が1つ
    for(int i = 0; i < n; i++)
    {
        vector<int> d(n);
        vector<int> ord(n);
        for(int j = 0; j < n; j++)
        {
            d[j] = -1;
            ord[j] = 0;
        }
        d[i] = 0;
        queue<int> que;
        que.push(i);

        while(!que.empty())
        {
            int cand = que.front();
            que.pop();
            for(auto nx : g[cand])
            {
                if(d[nx] == -1)
                {
                    d[nx] = d[cand] + 1;
                    que.push(nx);
                    ord[cand]++;
                }
            }
        }
        // dごとのordmax
        vector<int> ma(n);
        for(int j = 0; j < n; j++)
        {
            ma[d[j]] = max(ma[d[j]], ord[j]);
        }
        int first = 0;
        ll second = 1;
        for(int j = 0; j < n; j++)
        {
            if(ma[j] != 0)
            {
                first = j;
                second *= ma[j];
            }
        }
        ans = min(ans, P(first+2, second));
    }

    // 中心が2つ
    for(int i = 0; i < n; i++)
    {
        for(auto tmp: g[i])
        {
            // tmp: もう一つの中心
            vector<int> d(n);
            vector<int> ord(n);
            for(int j = 0; j < n; j++)
            {
                d[j] = -1;
                ord[j] = 0;
            }
            d[i] = 0;
            queue<int> que;
            que.push(i);
            d[tmp] = 0;
            que.push(tmp);

            while(!que.empty())
            {
                int cand = que.front();
                que.pop();
                for(auto nx : g[cand])
                {
                    if(d[nx] == -1)
                    {
                        d[nx] = d[cand] + 1;
                        que.push(nx);
                        ord[cand]++;
                    }
                }
            }
            // dごとのordmax
            vector<int> ma(n);
            for(int j = 0; j < n; j++)
            {
                ma[d[j]] = max(ma[d[j]], ord[j]);
            }
            int first = 0;
            ll second = 2;
            for(int j = 0; j < n; j++)
            {
                if(ma[j] != 0)
                {
                    first = j;
                    second *= ma[j];
                }
            }
            ans = min(ans, P(first+2, second));
        }
    }
    cout << ans.first << " " << ans.second << endl;
}

