int dep[MN], deg[MN], xdep;
void DFS(int u, int fz) {
	xdep = std::max(xdep, dep[u]);
	deg[dep[u]] = std::max(deg[dep[u]], (int)G[u].size() - (fz ? 1 : 0));
	for (auto v : G[u])
		if (v != fz)
			dep[v] = dep[u] + 1,
			DFS(v, u);
}

int main() {
	scanf("%d", &N), Ans.first = N + 1;
