		xdep = dep[i] = 1, DFS(i, 0);
		LL Sum = 1;
		for (int j = 1; j < xdep; ++j) Sum *= deg[j], deg[j] = 0;
		Ans = std::min(Ans, {xdep, Sum});
	}
