    dfs(1, 0, 1);

    int u = dim[mxlen];
    mxlen = 0;
    dfs(u, 0, 1);

    long long ans1 = (mxlen + 1) / 2, ans2;
    if (mxlen % 2 == 0) {
        dfs2(dim[mxlen / 2], dim[mxlen / 2 + 1], 0);
        dfs2(dim[mxlen / 2 + 1], dim[mxlen / 2], 0);
        ans2 = 2;
        for (int i = 0; mxd[i]; i++) {
            ans2 *= mxd[i];
        }
    } else {
        long long tmp = 1;
        int root = dim[mxlen / 2 + 1];
        dfs2(root, 0, 0);
        for (int i = 0; mxd[i]; i++) {
            tmp *= mxd[i];
        }
        for (int to: con[root]) {
            memset(mxd, 0, sizeof(mxd));
            dfs2(root, to, 0);
            dfs2(to, root, 0);
            long long x = 2;
            for (int i = 0; mxd[i]; i++) {
                x *= mxd[i];
            }
            if (x < tmp)
                tmp = x;
        }
        ans2 = tmp;
    }

    cout << ans1 << ' ' << ans2 << '\n';
}

