void check2(int v, int dist, int st) {
	vector<vector<ll>> cur;

	used[v] = 1;
	ll curD = d[st][v];

	if (st != v) vals[curD] = max(vals[curD], ll(gr[v].size()));


	for (auto to : gr[v]) {
