		for (int i = 0; i < vals.size(); i++) {
			if (c[i] != 0) c[i]--;
		}
		for (int i = 0; i < vals.size() - 1; i++) {
			if (c[i] != 0) cr *= c[i];
		}
		if (cr == 8) {
			cout << "";
		}
		ans = min(ans, cr * 2);
	}
}

