int N;
using Graph = vector< vector<int> >;

pair<int, int> solve(Graph &G, vector<int> roots) {
    vector<int> visited(N);
    for(auto x : roots) visited[x] = true;

    int sum = roots.size(), depth = 1;
    vector<int> cur = roots;
    for(; ; depth++) {
        /*
        fprintf(stderr, "cur: ");
        for(auto x : cur) cerr << x+1 << " ";
        cerr << endl;
        */

        int max_children = 0;
        vector<int> nxt;
        for(auto x : cur) {
            int cnt = 0;

            // fprintf(stderr, "vertex %lld: ", x+1);
            for(auto to : G[x]) {
                if(visited[to]) continue;
                visited[to] = true;
                // cerr << to + 1 << " ";
                cnt++;
                nxt.push_back(to);
            }
            // cerr << endl;
            chmax(max_children, cnt);
        }

        if(max_children == 0) break;
        sum *= max_children;
        swap(cur, nxt);
    }
    return make_pair(depth, sum);
}

signed main() {
