        G[v].push_back(u);
    }

    pii ans = make_pair(INF, INF);
    for(int i=0; i<N; i++) {
        // root is i
        if(G[i].size() < 2) continue;
        chmin(ans, solve(G, vector<int>{i}));

        for(auto to : G[i]) {
            int u = i, v = to;
            chmin(ans, solve(G, vector<int>{u, v}));
        }
    }
    printf("%lld %lld\n", ans.first, ans.second);
    return 0;
}

