const int MAXN = 105;
const int oo = 0x3f3f3f3f;

int N;

struct edge {
	int y, next;
}e[MAXN << 1];

int LINK[MAXN], len = 0, dis[MAXN], pre[MAXN];

inline void ins(int x, int y){
	e[++len].next = LINK[x]; LINK[x] = len;
	e[len].y = y;
}

inline void Ins(int x, int y){
	ins(x, y);
	ins(y, x);
}

deque<int> q;

int BFS(int ss){
	up (i, 1, N) dis[i] = oo;
	dis[ss] = 0; q.push_back(ss);
	while (!q.empty()) {
		int node = q.front(); q.pop_front();
		Auto (i, node) if (dis[e[i].y] > dis[node] + 1) {
			dis[e[i].y] = dis[node] + 1;
			pre[e[i].y] = node;
			q.push_back(e[i].y);
		}
	}
	int tt = ss;
	up (i, 1, N) if (dis[i] > dis[tt]) tt = i;
	return tt;
}

bool vis[MAXN];

int mx[MAXN];
pr w[MAXN];

void DFS(int node, int dep){
	int deg = 0; vis[node] = 1;
	Auto (i, node) if (!vis[e[i].y]) {
		deg++;
		DFS(e[i].y, dep + 1);
	}
	cmax(mx[dep], deg);
}

