int maxelement(int a[]) {
	int ans = 0,pos;
	rep(i, n) {
		ans = max(ans, a[i]);
		if (ans == a[i])pos = i;
	}
	return pos;
}

int solve(int dia) {
	int D = dia / 2;
	int pos;
	rep(i, n - 1) {
		if (d2[A[i]] > d2[B[i]])swap(A[i], B[i]);
		if (d2[A[i]] == D&&d1[B[i]] == D&& d2[A[i]] + d1[B[i]] + 1 == dia)pos = i;
	}
	fill(d3, d3 + n, -1);
	d3[A[pos]] = 0, d3[B[pos]] = 0;
	dfs2(A[pos], d3); dfs2(B[pos], d3);
	fill(r, r + n, 0);
	rep(i, n) {
		r[d3[i]] = max(r[d3[i]], (int)G[i].size() - 1);
	}
	int ans = 2;
	rep(i, D)ans *= r[i];
	return ans;
}

void reset(int n) {
	rep(i, n)d1[i] = d2[i] = 0;
}
