	cin >> n;
	rep(i, n - 1) {
		int a, b; cin >> a >> b;
		a--; b--;
		G[a].push_back(b);
		G[b].push_back(a);
		A[i] = a; B[i] = b;
	}

	dfs(0, -1, d1);
	int u = maxelement(d1);
	dfs(u, -1, d2);
	int X = maxelement(d2);
	d1[X] = 0;
	dfs(X, -1, d1);
	int D = d2[X] / 2+1;
	if (d2[X] & 1) {
		cout << D << ' ' << solve(d2[X])<< endl;
	}
	else {
		cout << D << ' ';
		int center;
		rep(i, n) {
			if (d2[i] + d1[i] == d2[X]&&d1[i]==d2[i])center = i;
		}

		int ans = 1;

		fill(d3, d3 + n, -1);
		d3[center] = 0;


		dfs2(center, d3);

		rep(i, n - 1) {
			if (d3[A[i]] > d3[B[i]])swap(A[i], B[i]);
			p[A[i]]++;
		}
		rep(i, n)r[d3[i]] = max(r[d3[i]], p[i]);

		rep(i, D-1)ans *= r[i];


		rep(i, n) {
			G[i].push_back(n);
			G[n].push_back(i);
			A[n] = n; B[n] = i;
			n++;
			reset(n);
			dfs(0, -1, d1);
			u = maxelement(d1);
			dfs(u, -1, d2);
			X = maxelement(d2);
			d1[X] = 0;
			dfs(X, -1, d1);
			ans = min(ans, solve(d2[X]));
			n--;

			G[i].pop_back();
			G[n].pop_back();
		}

		cout << ans << endl;
	}
}

