struct Node {
	int id;
	int color;
	int dist;
	bool visited;
	vector<int> nexts;
};

int N;
int dist;
vector<Node> nodes;
pair<int, int> ans;

int getFarest(int idx, vector<Node> &nodes) {
	dist = 0;
	rep(i, N) nodes[i].visited = false;
	queue<int> q;
	q.push(idx);
	nodes[idx].dist = 0;
	int last;
	while (!q.empty()) {
		int now = q.front(); q.pop();
		last = now;
		dist = max(dist, nodes[now].dist);
		nodes[now].visited = true;
		for (int next : nodes[now].nexts) {
			if (nodes[next].visited) continue;
			q.push(next);
			nodes[next].dist = nodes[now].dist + 1;
		}
	}
	return last;
}

pair<int, int> solve(vector<Node> nodes) {
	int N = nodes.size();

	int tmp = getFarest(0, nodes);
	getFarest(tmp, nodes);

	rep(i, N) {
		if (nodes[i].dist <= dist / 2) {
			nodes[i].color = nodes[i].dist;
		} else {
			nodes[i].color = dist - nodes[i].dist;
		}
	}

	map<int, int> m;
	rep(i, N) {
		int color = nodes[i].color;
		m[color] = max(m[color], (int) nodes[i].nexts.size());
	}

	int times = dist % 2 ? m[dist / 2] - 1 : m[dist / 2];

	int colors = dist / 2 + 1;
	int leafs = 0;

	itrep(it, m) {
		if (it->first == 0) continue;
		if (it->first == 1) {
			leafs += (it->second - 1) * times;
		} else {
			leafs += (it->second - 2) * times;
		}
	}

	pair<int, int> ret;
	ret.first = colors;
	ret.second = leafs;
	return ret;
}

