const int Maxn=105;
vector<int>e[Maxn],path;
pair<int,int>dfs(int x,int fa,int dis){
    pair<int,int>ret=make_pair(dis,x);
    for(int y:e[x]){
        if(y==fa)continue;
        pair<int,int>tmp=dfs(y,x,dis+1);
        ret=max(ret,tmp);
    }
    return ret;
}
int dfs1(int x,int fa,int dis=0){
    int ret=dis;
    for(int y:e[x]){
        if(y==fa)continue;
        ret=max(ret,dfs1(y,x,dis+1));
    }
    return ret;
}
bool dfs2(int x,int fa,int t){
    if(x==t)return path.push_back(x),true;
    for(int y:e[x]){
        if(y==fa)continue;
        if(dfs2(y,x,t))
            return path.push_back(x),true;
    }
    return false;
}
void dfs3(int x,int fa,int dis,int*f){
    int sz=0;
    for(int y:e[x]){
        if(y==fa)continue;
        sz++;
        dfs3(y,x,dis+1,f);
    }
    f[dis]=max(f[dis],sz);
}
ll solve(int ans,int x,int y){
    static int f[Maxn];
    fill(f,f+Maxn,1);
    dfs3(x,y,0,f);
    dfs3(y,x,0,f);
    ll ret=2;
    for(int i=!y;i<=ans;i++)ret*=f[i];
    return ret;
}
