    dfs2(a,0,b);
    ll cnt=(path.size()+1)/2,ans;
    if(path.size()&1){
        int x=path[path.size()/2];
        ans=solve(cnt,x,0);
        for(int y:e[x])
            if(dfs1(y,x)+dfs1(x,y)+2==path.size())
                ans=min(ans,solve(cnt,x,y));
    }else{
        for(int x=1;x<=n;x++)
            for(int y:e[x])
                if(dfs1(y,x)+dfs1(x,y)+2==path.size())
                    ans=min(ans,solve(cnt,x,y));
    }
