template<class T> void chmin(T &a,const T &b){if(a>b) a=b;}
template<class T> void chmax(T &a,const T &b){if(a<b) a=b;}

pair<int,int> findFar(int now,int par,vector<vector<int>> &g){
    pair<int,int> res=mkp(0,now);
    for(auto nex:g[now]){
        if(nex==par) continue;
        auto neco=findFar(nex,now,g);
        neco.first++;
        chmax(res,neco);
    }
    return res;
}

bool setPath(int now,int par,int goal,vector<int> &path,vector<vector<int>> &g){
    if(now==goal){
        path.push_back(now);
        return true;
    }
    for(auto nex:g[now]){
        if(nex==par) continue;
        if(setPath(nex,now,goal,path,g)){
            path.push_back(now);
            return true;
        }
    }
    return false;
}

vector<int> getDiameter(vector<vector<int>> &g){
    int N=g.size();
    int a=findFar(0,-1,g).second;
    int b=findFar(a,-1,g).second;
    vector<int> diam;
    setPath(a,-1,b,diam,g);
    return diam;
}

const ll INF=2e18;

pair<int,ll> calc(vector<int> &diam,vector<vector<int>> &g){
    int N=g.size();
    int M=diam.size();
    vector<int> dep(N,MOD);
    int sta=diam[M/2];
    int stb=sta;
    if(M%2==0) stb=diam[M/2-1];
    dep[sta]=0;dep[stb]=0;
    queue<int> Q;
    Q.push(sta);Q.push(stb);
    while(!Q.empty()){
        int now=Q.front();
        Q.pop();

        for(auto nex:g[now]){
            if(dep[nex]==MOD){
                dep[nex]=dep[now]+1;
                Q.push(nex);
            }
        }
    }

    int D=0;
    rep(i,N) chmax(D,dep[i]);
    vector<vector<int>> v(D+1);
    rep(i,N) v[dep[i]].push_back(i);

    vector<ll> deg(N,0);
    rep(i,N) deg[i]=g[i].size();

    ll prenum=0;
    for(int i=0;i<D;i++){
        ll madeg=1;
        for(auto j:v[i]) chmax(madeg,deg[j]);
        ll nexnum=0;
        for(auto j:v[i]) nexnum+=madeg-deg[j];
        nexnum+=prenum*(madeg-1);
        prenum=nexnum;
    }
    rep(i,N) if(dep[i]==D) prenum++;
    return mkp((M+1)/2,prenum);
}

pair<int,ll> solve(vector<vector<int>> &g){
    pair<int,ll> res=mkp(MOD,INF);
    vector<int> diam=getDiameter(g);
    /*for(auto v:diam) cout<<v+1<<" ";
    cout<<endl;*/
    int M=diam.size();
    int N=g.size();

    vector<int> leaf;
    rep(i,N) if(g[i].size()==1) leaf.push_back(i);

    for(int i=0;i<leaf.size();i++){
        for(int j=i+1;j<leaf.size();j++){
            vector<int> path;
            setPath(leaf[i],-1,leaf[j],path,g);
            int m=path.size();
            if(M>m){
                int n=N;
                int diff=M-m;
                g.resize(n+diff);
                int pre=leaf[j];
                for(int k=0;k<diff;k++){
                    path.push_back(n+k);
                    g[pre].push_back(n+k);
                    g[n+k].push_back(pre);
                    pre=n+k;
                }   
                vector<int> d=getDiameter(g);
                if(d.size()==M){
                    auto tmp=calc(path,g);
                    chmin(res,tmp);
                }
                g.resize(n);
                g[leaf[j]].pop_back();
            }else{
                auto tmp=calc(path,g);
                chmin(res,tmp);
            }
        }
    }
    return res;
}


