#include<bits/stdc++.h>
#define maxn 105
using namespace std;

struct Edge{
	int Next,To;
}e[maxn<<1];

int First[maxn];
int v[maxn];
int vis[maxn];
int s[maxn];
int n,x,y;
int tot;
int f;
int res,as=0x3f3f3f3f;
int ad=0x3f3f3f3f,dep;

int add_edge(int x,int y){
	tot++;
	e[tot].To=y;
	e[tot].Next=First[x];
	First[x]=tot;
}

void dfs(int x,int d){
	int num=0;

	for(int i=First[x];i!=-1;i=e[i].Next){
		int y=e[i].To;
		if(vis[y])continue;
		if(i==f||i==f+1)continue;
		num++;
		vis[y]=1;
		dfs(y,d+1);
		s[x]=max(s[x],s[y]);
	}
	s[x]*=num;
	if(!num){
		s[x]=1;
		dep=max(dep,d);
		return;
	}
}

int main(){
	memset(First,-1,sizeof(First));
	cin>>n;
	for(int i=1;i<n;i++){
		cin>>x>>y;
		add_edge(x,y);
		add_edge(y,x);
		v[x]++,v[y]++;
	}

	f=-1;
	for(int i=1;i<=n;i++){
		memset(vis,0,sizeof(vis));
		memset(s,0,sizeof(s));
		dep=0;
		dfs(i,1);
		res=s[i];
		if(v[i]==1)res++;
		//cout<<dep<<" "<<res<<endl;
		if(dep<ad){
			ad=dep;
			as=res;
		}
		else if(dep==ad){
			if(res<as)as=res;
		}
	}

	for(int i=1;i<=tot;i+=2){
		memset(vis,0,sizeof(vis));
		memset(s,0,sizeof(s));
		dep=0;
		f=i;
		add_edge(0,e[i].To);
		add_edge(0,e[i+1].To);
		dfs(0,0);
		tot-=2;
		First[0]=-1;
		res=s[0];
		//cout<<dep<<" "<<res<<endl;
		if(dep<ad){
			ad=dep;
			as=res;
		}
		else if(dep==ad){
			if(res<as)as=res;
		}
	}

	cout<<ad<<" "<<as;
}

