int n,u,v,depth[1100],fa[1100];
vector<int> G[1100];

int mx[1100],sz;
void dfs(int num,int f = -1){
	int cnt = 0;
	for(auto ct:G[num]){
		if(ct == f)continue;
		cnt++;
		fa[ct] = num;
		depth[ct] = depth[num]+1;
		dfs(ct,num);
	}
	mx[depth[num]] = max(mx[depth[num]],cnt);
}

ll calc1(int p){
	ll ans = 1;
	memset(mx,0,sizeof(mx));
	depth[p] = 0; dfs(p);
	for(int i=0;i<sz/2;i++) ans*=mx[i];
	return ans;
}
ll calc2(int u,int v){
	memset(mx,0,sizeof(mx));
	depth[u] = 0; dfs(u,v);
	depth[v] = 0; dfs(v,u);
	ll ans = 2;
	for(int i=0;i<sz/2-1;i++){
		ans*=mx[i];
	}
	return ans;
}
int main() {
	read(n);
	for(int i=1;i<n;i++){
		read(u);read(v);
		G[u].pb(v);
		G[v].pb(u);
	}
	dfs(1);
	int u = max_element(depth+1,depth+n+1)-depth;

	dfs(u);
	int v = max_element(depth+1,depth+n+1)-depth;
	vector<int> R;
	R.pb(v);
	while(v!=u){
		v = fa[v];
		R.pb(v);
	}
	sz = R.size();
	ll ans = 1e18;
	if(R.size()%2 == 1){
		int p = R[R.size()/2];
		ans = min(ans,calc1(p));
		sz+=1;
		for(auto ct:G[p]){
			ans = min(ans,calc2(p,ct));
		}
	}else{
		ans = calc2(R[R.size()/2],R[R.size()/2-1]);
	}
	cout<<(R.size()+1)/2<<' '<<ans<<endl;
	return 0;
}

#include <cstdio>
#include <vector>
#include <algorithm>

#define MAXN 109

struct myc {
    int x;
    long long y;
    inline bool operator < (const myc &u) const {
        if (x == u.x) return y < u.y;
        else return x < u.x;
    }
};

std::vector < int > g[MAXN];
int d[2][MAXN];
bool viz[MAXN];
int v[MAXN];
int cul[MAXN];
int urm[MAXN];
int t, r[2][MAXN];

void dfs(int x) {
    viz[x] = 1;
    for (auto &y : g[x]) {
        if (viz[y] == 0) {
            d[t][y] = d[t][x] + 1;
            urm[y] = x;
            dfs(y);
        }
    }
}

inline myc adevSolve() {
    int val = (v[0] + 1) / 2, p = 0, q = 1;
    long long cnt = 0, ans = r[0][0];
    while (q < val) {
        for (int i = 1; i <= r[p][0]; i++)
            cul[r[p][i]] = q;
        q++;
        int best = 0, sum = 0;
        for (int i = 1; i <= r[p][0]; i++) {
            int cat = 0;
            for (auto &x : g[r[p][i]])
                if (cul[x] == 0)
                    cat++, r[1 - p][++r[1 - p][0]] = x;
            best = std::max(best, cat);
            sum += cat;
        }

        cnt = (cnt + r[p][0]) * best - sum;
        ans = cnt + sum;

        r[p][0] = 0;
        p = 1 - p;
    }

    for (int i = 1; i <= r[p][0]; i++)
        cul[r[p][i]] = q;
    for (int i = 1; i <= r[p][0]; i++)
        for (auto &x : g[r[p][i]])
            if (cul[x] == 0)
                return {MAXN, 0};

    return {val, ans};
}

inline myc solve(int n) {
    for (int i = 1; i <= n; i++)
        viz[i] = 0;
    t = 0;
    d[0][1] = 0;
    dfs(1);
    int a = 1;
    for (int i = 2; i <= n; i++)
        if (d[0][i] > d[0][a])
            a = i;

    for (int i = 1; i <= n; i++)
        viz[i] = 0;
    t = 1;
    d[1][a] = 0;
    dfs(a);
    int b = 1;
    for (int i = 2; i <= n; i++)
        if (d[1][i] > d[1][b])
            b = i;

    v[0] = 0;
    while (b != a) {
        v[++v[0]] = b;
        b = urm[b];
    }
    v[++v[0]] = a;

    r[0][0] = r[1][0] = 0;
    for (int i = 1; i <= n; i++)
        cul[i] = 0;
    if (v[0] % 2 == 0) {
        r[0][++r[0][0]] = v[v[0] / 2 + 1];
        r[0][++r[0][0]] = v[v[0] / 2];
        return adevSolve();
    } else {
        r[0][++r[0][0]] = v[v[0] / 2 + 1];
        myc ans = adevSolve();
        for (auto &x : g[v[v[0] / 2] + 1]) {
            r[0][0] = r[1][0] = 0;
            for (int i = 1; i <= n; i++)
                cul[i] = 0;
            r[0][++r[0][0]] = v[v[0] / 2 + 1];
            r[0][++r[0][0]] = x;
            ans = std::min(ans, adevSolve());
        }
        return ans;
    }

    return {MAXN, 0};
}

int main() {
    int n;
    scanf("%d", &n);

    for (int i = 1; i < n; i++) {
        int x, y;
        scanf("%d%d", &x, &y);

        g[x].push_back(y);
        g[y].push_back(x);
    }

    myc ans = solve(n);

    printf("%d %lld\n", ans.x, ans.y);

