void reset() {
    maxdepth = 0;
    for (int i = 0; i < 2100; ++i) maxdeg[i] = 1;
}


void rec(int v, int p, int depth) {
    long long con = 0;
    for (auto e : G[v]) {
        if (e == p) continue;
        ++con;
        rec(e, v, depth+1);
    }
    chmax(maxdepth, depth);
    chmax(maxdeg[depth], con);
}

long long calc() {
    long long res = 1;
    for (int d = 0; d <= maxdepth; ++d) {
        res *= maxdeg[d];
        //cout << d << ": " << maxdeg[d] << endl;
    }
    return res;
}

