using namespace std;

vector<int> getDist(const vector<vector<int>>& g, int start){
    const int n = g.size();
    vector<int> res(n, -1);
    queue<int> qu; qu.push(start);
    res[start] = 0;
    while(!qu.empty()){
        int p = qu.front(); qu.pop();
        for(auto& t : g[p]){
            if(res[t] != -1) continue;
            res[t] = res[p] + 1;
            qu.push(t);
        }
    }
    return res;
}

long long check(const vector<vector<int>>& g, const vector<int>& start){
    auto cur = start;
    vector<int> check(g.size(), 0);
    for(auto& t : cur) check[t] = 1;
    long long res = 0;
    while(!cur.empty()){
        int maxDeg = 1;
        for(auto& t : cur) maxDeg = max<int>(maxDeg, g[t].size()-1);
        res *= maxDeg;
        vector<int> next;
        for(auto& t : cur){
            res += maxDeg - (g[t].size() - 1);
            for(auto& p : g[t]){
                if(check[p]) continue;
                check[p] = 1;
                next.push_back(p);
            }
        }
        cur = next;
    }
    return res;
}

