int find_len(int now, int fa)
{
	int ret = 1;
	for(int to : edge[now])
	{
		if(to == fa) continue;
		ret = max(ret, find_len(to, now) + 1);
	}
	return ret;
}

void find_max(int now, int fa, int dis)
{
	int tmp = 0;
	for(int to : edge[now])
	{
		if(to == fa) continue;
		tmp ++;
		find_max(to, now, dis + 1);
	}
	sum[dis] = max(sum[dis], tmp);
}

void get_ans()
{
	rep(i, 1, n - 1) if(find_len(e[i].fi, e[i].se) == maxx / 2 && find_len(e[i].se, e[i].fi) == maxx / 2)
	{
