		find_max(e[i].fi, e[i].se, 1), find_max(e[i].se, e[i].fi, 1);
		ll tmp = 2;
		rep(i, 1, maxx / 2 - 1)
		{
			if(linf / tmp < sum[i])
			{
				tmp = linf;
				break;
			}
			tmp = min(tmp * sum[i], linf);
		}
		ans = min(ans, tmp);
	}
}

