template <typename T>
void gi(T &ret) {
	ret = 0; char inp=gc(); int kl=1;
	while (inp<'0' || inp>'9') {if (inp=='-') kl=-1; inp=gc();}
	while ('0'<=inp && inp<='9') ret=(ret<<3)+(ret<<1)+(inp-'0'), inp=gc();
	if (kl<1) ret=-ret;
}

const int MAXN = 105;
int n, st, mks, ctr[2];
vi adj[MAXN];
vector<pii> opt;

ll ans = 0ll, mtp = 0ll;
int que[2][MAXN], qr[2];
bool vis[MAXN];

void getst (int now, int par, int l) {
	if (l>mks) {
		mks = l;
		st = now;
	}
	for (auto nex : adj[now]) {
		if (nex==par) continue;
		getst(nex,now,l+1);
	}
}

vi stk;
void getctr (int now, int par, int l) {
	stk.psb(now);
	if (l>mks) {
		mks = l;
		opt.clear();
	}
	if (l==mks) {
		if (l&1) {
			opt.psb({stk[l/2], -1});
			if (l>1) {
				opt.psb({stk[l/2], stk[(l/2)-1]});
				opt.psb({stk[l/2], stk[(l/2)+1]});
			}
		} else {
			opt.psb({stk[l/2], stk[(l/2)-1]});
		}
	}
	for (auto nex : adj[now]) {
		if (nex==par) continue;
		getctr(nex,now,l+1);
	}
	stk.ppb();
}

void init () {
	setnul(vis);
	qr[0] = qr[1] = 0;
	// printf ("ctr = %d %d\n", 
	que[0][qr[0]++] = ctr[0];
	vis[ctr[0]] = 1;
	if (ctr[1]!=-1) {
		que[0][qr[0]++] = ctr[1];
		vis[ctr[1]] = 1;
	}
}

int countdeg (int x) {
	int ret = 0;
	for (auto nex : adj[x])
		if (!vis[nex]) ret++;
	return ret;
}

void solve () {
	int ia = 0, ib = 1;
	while (1) {
		ia ^= 1; ib ^= 1;
		qr[ia] = 0;

		// printf ("stat : ");
		// for (int i=0; i<qr[ib]; i++)
		// 	printf ("%d ", que[ib][i]);
		// endln;


		int mc = 0;
		for (int i=0; i<qr[ib]; i++)
			mc = max(mc, countdeg(que[ib][i]));
		if (mc==0) {
			ans += (ll) qr[ib];
			return;
		}

		ans += mtp * (ll)(mc-1);

		for (int i=0; i<qr[ib]; i++) {
			int sls = mc-countdeg(que[ib][i]);
			mtp += (ll) sls;
			ans += (ll) sls;

			for (auto nex : adj[que[ib][i]]) {
				if (vis[nex]) continue;
				vis[nex] = 1;
				que[ia][qr[ia]++] = nex;
			}
		}

		assert (ans>=0ll);

		// printf ("ans = %lld\n", ans);
	}
}


int main() {
	gi(n);
	for (int i=1; i<n; i++) {
		int u,v; gi(u); gi(v);
		adj[u].psb(v);
		adj[v].psb(u);
	}
	mks = 0;
	getst(1,-1,1);
	mks = 0;
	getctr(st,-1,1);

	ll fin = infll;
	for (auto xx : opt) {
		ans = 0ll; mtp = 0ll;
		ctr[0] = xx.fi; ctr[1] = xx.se;
		init();
		solve();
		// printf ("ans = %lld\n",ans);
		fin = min(fin, ans);
	}

	printf ("%d %lld\n", (mks+1)/2, fin);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

namespace TYC
{
	typedef long long ll;
	const int N = 105;

	int n, dep[N], fa[N], deg[N], mxd[N], cnt[N];
	vector<int> E[N];

	void dfs(const int u, const int f)
	{
		dep[u] = dep[fa[u] = f] + 1;
		for (int v : E[u])
			if (v != f)
				dfs(v, u);
	}

	inline void add(const int u, const int v)
	{
		E[n].clear();
		E[n].push_back(u);
		E[n].push_back(v);
		E[u].erase(find(E[u].begin(), E[u].end(), v));
		E[v].erase(find(E[v].begin(), E[v].end(), u));
	}

	inline void restore(const int u, const int v)
	{
		E[n].clear();
		E[u].push_back(v);
		E[v].push_back(u);
	}

	ll solve(const int o)
	{
		dfs(o, 0);
		memset(cnt, 0, sizeof(int[n + 1]));
		memset(mxd, 0, sizeof(int[n + 1]));
		int len = 0;
		for (int i = 1; i <= n; i++)
		{
			len = max(len, dep[i]);
			mxd[dep[i]] = max(mxd[dep[i]], deg[i] - (i != o));
			cnt[dep[i]]++;
		}
		ll ans = 1;
		for (int i = len - 1; i; i--)
			ans = ans * mxd[i];
		return ans;
	}

	void work()
	{
		scanf("%d", &n);
		for (int i = 1, u, v; i < n; i++)
		{
			scanf("%d%d", &u, &v);
			deg[u]++, deg[v]++;
			E[u].push_back(v);
			E[v].push_back(u);
		}
		int s = 1, t = 1;
		dfs(1, 0);
		for (int i = 2; i <= n; i++)
			if (dep[s] < dep[i])
				s = i;
		dfs(s, 0);
		for (int i = 2; i <= n; i++)
			if (dep[t] < dep[i])
				t = i;
		int o = t;
		while (dep[o] > (dep[t] + 1) / 2)
			o = fa[o];
		printf("%d ", dep[o]);
		if (dep[t] & 1)
		{
			ll ans = solve(o);
			deg[++n] = 2;
			for (int v : E[o])
			{
				add(o, v);
				ans = min(ans, solve(n));
				restore(o, v);
			}
			printf("%lld\n", ans);
		}
		else
		{
			deg[++n] = 2;
			int p = t;
			while (fa[p] != o)
				p = fa[p];
			add(o, p);
			printf("%lld\n", solve(n));
		}
	}
}

int main()
{
	TYC::work();
	return 0;
}

