void solve() {
	cin >> n;
    g.assign(n, vector<int>());
    rep(i, n - 1) {
        int a, b; cin >> a >> b;
        -- a, -- b;
        g[a].pb(b);
        g[b].pb(a);
    }
    int cmi = inf, lmi = INF;
    //中心が1つ
    rep(i, n) {
        vector<int> d(n, inf);
        dfs(i, -1, 0, d);
        int ma = 0;
        rep(j, n) {
            chmax(ma, d[j]);
        }
        int cm = cmi;
        if(chmin(cmi, ma + 1)) {
            vector<int> cnt(cmi + 1, 0);
            cnt[0] = (int)g[i].size();
            rep(j, n) {
                if(j == i) continue;
                chmax(cnt[d[j]], (int)g[j].size() - 1);
            }
            int res = 1LL;
            for(int j = 0; j < ma; ++ j) {
                res *= cnt[j];
            }
            if(cm == ma + 1) chmin(lmi, res);
            else lmi = res;
        }
    }
    //中心が2つ
    rep(i, n) {
        for(int j: g[i]) {
            vector<int> d(n, inf);
            dfs(i, j, 0, d);
            dfs(j, i, 0, d);
            int ma = 0;
            rep(k, n) {
                chmax(ma, d[k]);
            }
            int cm = cmi;
            if(chmin(cmi, ma + 1)) {
                vector<int> cnt(cmi + 1, 0);
                cnt[0] = max((int)g[i].size() - 1, (int)g[j].size() - 1);
                rep(k, n) {
                    if(k == i || k == j) continue;
                    chmax(cnt[d[k]], (int)g[k].size() - 1);
                }
                int res = 2LL;
                for(int k = 0; k < ma; ++ k) {
                    res *= cnt[k];
                }
                if(cm == ma + 1) chmin(lmi, res);
                else lmi = res;
            }
        }
    }
