pair<int, ld> get(vector<int> vs) {
    memset(dis, 0x3f, sizeof(dis));
    queue<int> que;
    for(int i : vs) dis[i] = 0, que.push(i);
    int mx_dis = 0;
    while(!que.empty()) {
        int v = que.front(); que.pop();
        for(int nxt : G[v]) {
            if(dis[nxt] > dis[v] + 1) {
                dis[nxt] = dis[v] + 1;
                que.push(nxt);
            }
        }
    }
    for(int i = 0; i < n; i++) id[i] = i;
    sort(id, id + n, [](const int a, const int b) {
        return dis[a] > dis[b];
    });
    mx_dis = dis[id[0]] + 1;
    int r = 0;
    ld sz = 1;
    for(int i = 0; i < n; i = r) {
        while(r < n && dis[id[r]] == dis[id[i]]) r++;
        if(i == 0) continue;
        int mx_bc = 0;
        for(int j = i; j < r; j++) {
            int cnt = 0;
            for(int nxt : G[id[j]]) if(dis[nxt] > dis[id[j]]) cnt++;
            mx_bc = max(mx_bc, cnt);
        }
//        cout << dis[id[i]] << ", " << mx_bc << endl;
        sz = mx_bc * sz;
    }
    sz *= vs.size();
    return {mx_dis, sz};
}

