	REP(i,0,mx)has[i].clear();
	REP(i,1,n)has[dep[i]].PB(i);
	ll ans=1;
	RREP(i,mx-1,0){
		int mx2=0;
		for(auto x:has[i]){
			int t=0;
			for(auto v:G[x])if(dep[v]==i+1)t++;
