vector<int> adjlist[N];
int d[N];
int a[N], b[N];
int mx[N];
int n;
using namespace std;
queue<int> q;
void process(){
    memset(mx,0,sizeof(mx));
    while (q.size()){
        int u = q.front(); q.pop();
        for (auto v : adjlist[u]){
            if (d[v] == -1){
                d[v] = d[u]+1;
                mx[d[v]] = max(mx[d[v]],(int)adjlist[v].size()-1);
                q.push(v);
            }
        }
    }
}
int main(){
    scanf("%d",&n);
    if (n == 2){
        printf("1 2");
        return 0;
    }
    for (int i = 1; i < n; i++){
        scanf("%d%d",&a[i],&b[i]);
        adjlist[a[i]].push_back(b[i]);
        adjlist[b[i]].push_back(a[i]);
    }
    pair<int,ll> ans = {n,LLONG_MAX};
    for (int i = 1; i <= n; i++){
        memset(d,-1,sizeof(d));
        d[i] = 0;
        q.push(i);
        process();
        ll P = (int)adjlist[i].size();
        int dist;
        for (dist = 1; dist < n; dist++){
            if (mx[dist] == 0) break;
            if (LLONG_MAX/mx[dist] < P){
                P = LLONG_MAX;
            }
            else P *= mx[dist];
        }
        dist++;
        ans = min(ans,{dist,P});
    }
    for (int i = 1; i < n; i++){
        q.push(a[i]);
        q.push(b[i]);
        memset(d,-1,sizeof(d));
        d[a[i]] = d[b[i]] = 0;
        process();
        ll P = 2*(max((int)adjlist[a[i]].size(),(int)adjlist[b[i]].size())-1);
        int dist;
        for (dist = 1; dist < n; dist++){
            if (mx[dist] == 0) break;
            if (INF/mx[dist] < P){
                P = INF;
            }
            else P *= mx[dist];
        }
        dist++;
        //printf("%d %d %d %lld\n",a[i],b[i],dist,P);
        ans = min(ans,{dist,P});
    }
    printf("%d %lld\n",ans.first,ans.second);
}

