const int MAXN = 105;

int N;
int a[MAXN], b[MAXN];

struct node {
	int to, next;
} edge[MAXN*2];
int head[MAXN], top = 0, d[MAXN];
inline void push(int i, int j)
{ edge[++top] = (node) {j, head[i]}, head[i] = top; }

int ans;
long long tot = 0;

int depth[MAXN], max_deg[MAXN];

void dfs(int nd, int f, int flag = 0)
{
	max_deg[depth[nd]] = max(max_deg[depth[nd]], d[nd]-flag);
	for (int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (to == f) continue;
		depth[to] = depth[nd]+1;
		dfs(to, nd, 1);
	}
}

int main()
{
	scanf("%d", &N), ans = N;
	for (int i = 1; i < N; i++) {
		scanf("%d%d", &a[i], &b[i]), d[a[i]]++, d[b[i]]++;
		push(a[i], b[i]), push(b[i], a[i]);
	}
	for (int i = 1; i <= N; i++) {
		depth[i] = 0;
		memset(max_deg, 0, sizeof max_deg);
		dfs(i, 0, 0);
		long long cur_tot = 1;
		int cur_ans = 0;
		for (int j = 1; j <= N; j++)
			cur_ans = max(cur_ans, depth[j]);
		for (int j = 0; j < cur_ans; j++)
			cur_tot = cur_tot*max_deg[j];
		cur_ans++;
		if (cur_ans < ans) ans = cur_ans, tot = cur_tot;
		else if (cur_ans == ans) tot = min(tot, cur_tot);
	}
	for (int i = 1; i < N; i++) {
		int x = a[i], y = b[i];
		depth[x] = depth[y] = 0;
		memset(max_deg, 0, sizeof max_deg);
		dfs(x, y, 1), dfs(y, x, 1);
		long long cur_tot = 1;
		int cur_ans = 0;
		for (int j = 1; j <= N; j++)
			cur_ans = max(cur_ans, depth[j]);
		for (int j = 0; j < cur_ans; j++)
			cur_tot = cur_tot*max_deg[j];
		cur_tot *= 2;
		// cerr << x << " " << y << " " << cur_ans+1 << " " << cur_tot << endl;
		cur_ans++;
		if (cur_ans < ans) ans = cur_ans, tot = cur_tot;
		else if (cur_ans == ans) tot = min(tot, cur_tot);
	}
	cout << ans << " " << tot << endl;
	return 0;
}

