pair<ll, ll> solve(int center){
    memset(max_deg, 0, sizeof(max_deg));
    dfs(center, -1, 0);
    ll rez = 1;
    int i;
    for(i = 0; max_deg[i]; ++i)
        rez *= max(max_deg[i] - (i != 0), 1);
    return make_pair(i, rez); }

pair<ll, ll> solve(int x, int y){
    memset(max_deg, 0, sizeof(max_deg));
    vec[x].erase(y);
    vec[y].erase(x);


    dfs(x, -1, 0);
    dfs(y, -1, 0);

    ll rez = 1;
    int i;
    for(i = 0; max_deg[i]; ++i){
        rez *= max(max_deg[i] - (i != 0), 1); }

    vec[x].insert(y);
    vec[y].insert(x);

    return make_pair(i, 2 * rez); }

int dist(int x, int y){
    int rez = 0;
    for(auto z : vec[x])
        if(y != z)
            rez = max(rez, dist(z, x));
    return rez + 1; }

