int ans = 1e9;
ll ansv;
vector<int> g[maxn + 10];

void dfs(int p, int fa) {
	dep[p] = dep[fa] + 1;
	for (int i = 0; i < (int)g[p].size(); ++i) {
		int e = g[p][i];
		if (e != fa) dfs(e, p);
	}
}

bool getpath(int p, int fa, int od) {
	a[++acnt] = p;
	if (p == od) return 1;
	for (int i = 0; i < (int)g[p].size(); ++i) {
		int e = g[p][i];
		if (e != fa && getpath(e, p, od)) return 1;
	}
	--acnt; return 0;
}

void dfsdeg(int p, int fa, int dep) {
	int cnt = 0;
	for (int i = 0; i < (int)g[p].size(); ++i) {
		int e = g[p][i];
		if (e != fa) {
			dfsdeg(e, p, dep + 1); ++cnt;
		}
	}
	mx[dep] = max(mx[dep], cnt);
}

void solve() {
	dfs(1, 0);
	int x = max_element(dep + 1, dep + n + 1) - dep;
	dfs(x, 0);
	int y = max_element(dep + 1, dep + n + 1) - dep;
	acnt = 0;
	assert(getpath(x, 0, y));
	memset(mx, 0, sizeof mx);
	int now; ll tot = 1;
	if (acnt & 1) {
		dfsdeg(a[acnt / 2 + 1], 0, 0);
		now = acnt / 2 + 1;
	} else {
		mx[0] = 2;
		dfsdeg(a[acnt / 2], a[acnt / 2 + 1], 1);
		dfsdeg(a[acnt / 2 + 1], a[acnt / 2], 1);
		now = acnt / 2;
	}
	for (int i = 0; mx[i]; ++i) tot *= mx[i];
	if (now < ans) {
		ans = now; ansv = tot;
	} else if (now == ans && tot < ansv) ansv = tot;
}

