	vel dist = dis(st, way);
	while (dist[goal] > le) {
		rep(j, way[goal].size()) {
			if (dist[goal] > dist[way[goal][j]]) {
				goal = way[goal][j];
				break;
			}
		}
	}
	return goal;
}
