    while (1) {
        VI nex;
        long maxdeg = 1;
        for (auto j: cur) {
            if (!first) {
                maxdeg = max(maxdeg, long(adj[j].size() - 1));
            } else {
                first = false;
            }
            for (auto k: adj[j]) {
                if (!visited[k]) {
