int lca(int u,int v){
	if(h[u] > h[v])
		swap(u,v);
	for(int i = 19;i >= 0;i--){
		if(par[v][i] != -1 && h[par[v][i]] >= h[u])v = par[v][i];
	}
	if(u == v)return u;
	for(int i = 19;i >= 0;i--){
		if(par[v][i] != par[u][i])v = par[v][i],u = par[u][i];
	}
	return par[v][0];
}

int dst(int u,int v) {
	return h[u] + h[v] - 2 * h[lca(u,v)] + 1;
}

