vector< vector<int> > g;

void dfs1(int cur, int par, vector<int>& dist) {
    for (int nex : g[cur]) {
        if (nex == par) continue;
        if (dist[nex] == -1) {
            dist[nex] = dist[cur] + 1;
            dfs1(nex, cur, dist);
        }
    }
}

void dfs2(int cur, int par, int d, vector<ll>& num) {
    ll cnt = 0;
    for (int nex : g[cur]) {
        if (nex == par) continue;
        cnt++;
        dfs2(nex, cur, d + 1, num);
    }
    num[d] = max(num[d], cnt);
}

