    for(int i=1;i<=N;i++) r[i]=0;
    for(int d=dmin-1;d>=0;d--){
        for(int i=1;i<=N;i++){
            if(dist[center][i]!=d) continue;
            for(int j=1;j<=N;j++){
                if(edge[i][j]!=1 && dist[center][j]!=d+1) continue;
                r[i]+=prev;
            }
            pmax=max(r[i],pmax);
        }
        prev=pmax;
    }

    cout << (dmax+2)/2 << " " << r[center] << endl;
    return 0;
}

