		G[x[i]].pb(y[i]),G[y[i]].pb(x[i]);
	}
	int best=1<<30;
	ull leaf=LIM;
	for(int i=1;i<=n;++i)
	{
		memset(cnt,0,sizeof(cnt));
		dep[i]=1;
		dfs(i,-1);
		int m=0;
		for(int j=1;j<=n;++j)
		{
			chkmax(m,dep[j]);
			chkmax(cnt[dep[j]],(int)(G[j].size()-(i!=j)));
		}
		if(m>best)continue;
		ull t=LIM,lf=0;
		for(int j=1;j<m;++j)t/=cnt[j];
		if(!t)lf=LIM;
		else
		{
			lf=1;
			for(int j=1;j<m;++j)lf*=cnt[j];
			if(G[i].size()==1)++lf;
		}
		if(m<best || lf<leaf)best=m,leaf=lf;
	}
	for(int i=1;i<n;++i)
