			chkmax(m,dep[j]);
			chkmax(cnt[dep[j]],(int)G[j].size()-1);
		}
		if(m>best)continue;
		ull t=LIM/2,lf=0;
		for(int j=1;j<m;++j)t/=cnt[j];
