const int N = 105;

int n;
int mx[N];
int dis[N][N];
int diam;
int maxdeg[N];
vector <int> g[N];

void dfs(int at, int par, int dep){
	int child = 0;
	for(auto u : g[at]){
		if(u == par) continue;
		dfs(u, at, dep + 1);
		child += 1;
	}
	maxdeg[dep] = max(maxdeg[dep], child);
}

long long calc(){
	long long ans = 1LL;
	for(int i = 1; maxdeg[i]; ++i) ans *= maxdeg[i];
	return ans;
}

int main(){
	int x, y;
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i){
		for(int j = 1; j <= n; ++j){
			dis[i][j] = 1e9;
		}
		dis[i][i] = 0;
	}
	for(int i = 2; i <= n; ++i){
		scanf("%d %d", &x, &y);
		dis[x][y] = 1;
		dis[y][x] = 1;
		g[x].push_back(y);
		g[y].push_back(x);
	}
	for(int k = 1; k <= n; ++k){
		for(int i = 1; i <= n; ++i){
			for(int j = 1; j <= n; ++j){
				dis[i][j] = min(dis[i][j], dis[i][k] + dis[k][j]);
			}
		}
	}
	for(int i = 1; i <= n; ++i){
		for(int j = 1; j <= n; ++j){
			if(dis[i][j] > diam){
				diam = dis[i][j];
				x = i, y = j;
			}
		}
	}
	long long ans = LONG_LONG_MAX;
	if(diam % 2){
		int a, b;
		for(int i = 1; i <= n; ++i){
			for(int j = 1; j <= n; ++j){
				if(i == j) continue;
				if(dis[x][i] == dis[j][y] && dis[x][i] == diam / 2 && dis[i][j] == 1){
					a = i;
					b = j;
				}
			}
		}
		memset(maxdeg, 0, sizeof(maxdeg));
		dfs(a, b, 1);
		dfs(b, a, 1);
		ans = 2LL * calc();
	}
	else{
		int a, b;
		for(int i = 1; i <= n; ++i){
			if(dis[x][i] == dis[i][y] && dis[x][i] + dis[i][y] == diam){
				a = i, b = i;
			}
		}
		dfs(a, 0, 1);
		ans = calc();
		for(auto i : g[a]){
			memset(maxdeg, 0, sizeof(maxdeg));
			dfs(a, i, 1);
			dfs(i, a, 1);
			ans = min(ans, 2LL * calc());
		}
	}
	printf("%d %lld\n", (diam + 2) / 2, ans);
	return 0;
}

