vector<int> visit(const unordered_map<int, unordered_set<int>>& e, int v, int l)
{
	vector<int> r;
	for (int i : e.at(v))
		if (i != l)
		{
			const auto p = visit(e, i, v);
			if (r.size() < p.size())
				r = p;
		}
	r.push_back(v);
	return r;
}

void calc(const unordered_map<int, unordered_set<int>>& e, int v, int l, vector<int>& r, int d)
{
	r[d] = max(r[d], (int)e.at(v).size() - 1);
	for (int i : e.at(v))
		if (i != l)
			calc(e, i, v, r, d + 1);
}

