	}

	const auto p1 = visit(e, 0, -1);
	const auto p2 = visit(e, p1.front(), -1);

	const int d = p2.size();

	const int c1 = p2[p2.size() / 2];
	const int c2 = d % 2 ? c1 : p2[p2.size() / 2 - 1];

	ll mn = 1;

	vector<int> r((d + 1) / 2, 1);
	calc(e, c1, c2, r, 0);
	if (c1 != c2)
		calc(e, c2, c1, r, 0);
