void dfs(int now,int dist,int pre)
{
  int ada = 0;
  for (int j : adj[now])
  {
    if (forb[j] || j == pre) continue;
    ++ada;
    dfs(j, dist + 1, now);
  }
  // debug("%d %d %d %d\n",now,dist,pre,ada);
  MAX(depth[dist + 1], ada);
}

pair<int,LL> count(int x, int y)
{
  RESET(depth,0);
  RESET(forb,0);
  forb[x] = forb[y] = 1;
  dfs(x,0,-1);
  if (x != y) dfs(y,0,-1);
  pair<int,LL> res; res.se = (x != y ? 2 : 1);
  FORN(i,1,n)
  {
    if (depth[i] == 0) break;
    res.fi = i + 1;
    res.se *= depth[i];
  }
  return res;
}

