		dep.emplace_back(DFS(i), i);
	sort(all(dep));

	ll ans;
	if (dep[0].st < dep[1].st){
		int u = dep[0].nd;
		mark[u] = true;
		fill_n(son, n + 1, 1);
		DFS2(u);
		ans = getVal();
		for (auto &v: E[u]){
			mark[v] = true;
			fill_n(son, n + 1, 1);
			DFS2(u);
			DFS2(v);
			mark[v] = false;
			ans = min(ans, getVal() * 2);
		}
	}
	else{
		int u = dep[0].nd, v = dep[1].nd;
		mark[u] = mark[v] = true;
		fill_n(son, n + 1, 1);
		DFS2(u);
		DFS2(v);
		ans = getVal() * 2;
	}
	printf("%d %lld\n", dep[0].st + (dep[0].st != dep[1].st), ans);
	return 0;
}

