const int M = 128;
const LL inf = 1e18;

int n;
vector<int> V[M], V2[M];
LL res = inf, leaf = inf;
vector<PII> E;

void DFS(int v, int p)
{
  for (auto x : V[v])
  {
    if (x != p)
    {
      V2[v].PB(x);
      DFS(x, v);
    }
  }
}

void makeGraph(int a, int b)
{
  for (int i = 1; i <= n; i++)
  {
    V2[i].clear();
  }
  DFS(a, b);
  if (b != 0)
  {
    DFS(b, a);
  }
}

void solve(vector<int> X)
{
  LL depth = 1;
  LL curr = siz(X);
  while (true)
  {
    LL maxi = 0;
    vector<int> XX;
    for (auto x : X)
    {
      maxi = max(maxi, (LL)siz(V2[x]));
      for (auto xx : V2[x])
      {
        XX.PB(xx);
      }
    }
    if (maxi == 0)
    {
      break;
    }
    depth++;
    if ((LD)maxi * curr > inf)
    {
      return;
    }
    curr = maxi * curr;
    swap(X, XX);
  }
  //debug(depth, curr);
  if (res > depth || (res == depth && leaf > curr))
  {
    res = depth;
    leaf = curr;
  }
}

