    E.PB(MP(a, b));
  }
  for (int i = 1; i <= n; i++)
  {
    makeGraph(i, 0);
    vector<int> X;
    X.PB(i);
    solve(X);
  }
  for (auto p : E)
  {
    makeGraph(p.F, p.S);
    vector<int> X;
    X.PB(p.F);
    X.PB(p.S);
    //debug(X);
    solve(X);
  }
  printf("%lld %lld\n", res, leaf);
  return 0;
}

