const int MAX_N = 102;
vector<int> es[MAX_N];

vector<int> mergeVec(vi& x, vi& y) {
    reverse(all(x));
    reverse(all(y));
    int n = max(x.size(), y.size());
    vi ret(n);
    rep(i, x.size()) ret[i] = max(ret[i], x[i]);
    rep(i, y.size()) ret[i] = max(ret[i], y[i]);
    reverse(all(x));
    reverse(all(y));
    reverse(all(ret));
    return ret;
}

vector<int> memo[MAX_N][MAX_N];

vector<int> calc(int v, int par = MAX_N-1) {
    if(par != MAX_N-1 && es[v].size() == 1) {
        return vi{};
    }
    if(memo[v][par].size() > 0) return memo[v][par];
    vector<int> ret;
    for(int& to : es[v]) {
        if(par != to) {
            vector<int> tmp = calc(to, v);
            ret = mergeVec(ret, tmp);
        }
    }
    int k = es[v].size();
    if(par != MAX_N-1) --k;
    ret.push_back(k);
    return memo[v][par] = ret;
}

ll getLeaf(const vi& x) {
    ll ret = 1LL;
    rep(i, x.size()) {
        if(double(ret)*x[i] > 9e18) return -1;
        ret *= x[i];
    }
    return ret;
}

vector<int> getAns(const vi& x, const vi& y) {
    if(x.size() < y.size()) return x;
    if(x.size() > y.size()) return y;
    ll X = getLeaf(x);
    ll Y = getLeaf(y);
    if(X == -1) return y;
    if(Y == -1) return x;
    if(X < Y) return x;
    return y;
}


