    if (p == -1) d++;

    tot[l]++;
    deg[l] = max(deg[l], d);

    for (auto u : adj[s]){
        if (u != p){
            dfs(u, s, l + 1, deg, tot);
        }
    }
}

pii calc(vector<int> &deg, vector<int> &tot, bool edge){
    while (!tot.back()){
        assert(deg.back() == 0);

        tot.pop_back();
        deg.pop_back();
    }

    assert(deg.back() == 0);

    int A = tot.size();
    int64 X = 1;

    for (int i = 0; i + 1 < (int)deg.size(); ++i)
        X *= deg[i];

    if (edge)
        X *= 2;

    return {A, X};
}

pii solve_edge(int u, int v){
    vector<int> deg(n), tot(n);

    dfs(u, v, 0, deg, tot);
    dfs(v, u, 0, deg, tot);

    return calc(deg, tot, true);
}

pii solve_node(int u){
    vector<int> deg(n);
    vector<int> tot(n);

    dfs(u, -1, 0, deg, tot);

    return calc(deg, tot, false);
}

