void getst (int now, int par, int l) {
	if (l>mks) {
		mks = l;
		st = now;
	}
	for (auto nex : adj[now]) {
		if (nex==par) continue;
		getst(nex,now,l+1);
	}
}

vi stk;
void getctr (int now, int par, int l) {
	stk.psb(now);
	if (l>mks) {
		mks = l;
		opt.clear();
	}
	if (l==mks) {
		if (l&1) {
			ct = stk[l/2];
		} else {
			ctr[0] = stk[(l/2)];
			ctr[1] = stk[(l/2)-1];
		}
	}
	for (auto nex : adj[now]) {
		if (nex==par) continue;
		getctr(nex,now,l+1);
	}
	stk.ppb();
}

void init () {
	setnul(vis);
	qr[0] = qr[1] = 0;
	// printf ("ctr = %d %d\n", 
	que[0][qr[0]++] = ctr[0];
	vis[ctr[0]] = 1;
	if (ctr[1]!=-1) {
		que[0][qr[0]++] = ctr[1];
		vis[ctr[1]] = 1;
	}
}

int countdeg (int x) {
	int ret = 0;
	for (auto nex : adj[x])
		if (!vis[nex]) ret++;
	return ret;
}

void solve () {
	int ia = 0, ib = 1;
	while (1) {
		ia ^= 1; ib ^= 1;
		qr[ia] = 0;

		// printf ("stat : ");
		// for (int i=0; i<qr[ib]; i++)
		// 	printf ("%d ", que[ib][i]);
		// endln;


		int mc = 0;
		for (int i=0; i<qr[ib]; i++)
			mc = max(mc, countdeg(que[ib][i]));
		if (mc==0) {
			ans += (ll) qr[ib];
			return;
		}

		ans += mtp * (ll)(mc-1);

		for (int i=0; i<qr[ib]; i++) {
			int sls = mc-countdeg(que[ib][i]);
			mtp += (ll) sls;
			ans += (ll) sls;

			for (auto nex : adj[que[ib][i]]) {
				if (vis[nex]) continue;
				vis[nex] = 1;
				que[ia][qr[ia]++] = nex;
			}
		}

		assert (ans>=0ll);

		// printf ("ans = %lld\n", ans);
	}
}


