			for (auto it : path) {
				memset(cur_cnt, 0, sizeof(cur_cnt));
				calc(it);
				for (int k = 0; k < N; k++) {
					cnt[k] = max(cnt[k], cur_cnt[k]);
				}
			}
			int cntwka = 0;
			int mx_suff = 0;
			for (int k = N - 1; k >= 1; k--) {
				cntwka += max(0, cnt[k] - mx_suff);
				mx_suff = max(mx_suff, cnt[k]);
			}
			int t = 0;
			for (auto it : path) {
				int sub = 0;
				for (auto k : v[it]) {
					if (!bad[k]) {
						sub++;
					}
				}
				t = max(t, sub);
			}
			cntwka *= t * sz(path);
			if (ans > max_lvl + (sz(path) + 1) / 2) {
				ans = max_lvl + (sz(path) + 1) / 2;
				ans_cnt = cntwka;
			} else if (ans == max_lvl + (sz(path) + 1) / 2) {
				ans_cnt = min(ans_cnt, cntwka);
			}
		}
	}
	cout << ans << ' ' << ans_cnt;
	return 0;
}

