typedef long long int LL;
typedef pair<int, int > pii;
typedef vector<int > vi;

const int N = 101;

vi g[N];
int D[N];
pii E[N];

int getHeight(int c, int p, int d) {
  int mx = 0;
  int cnt = 0;
  rep(i,0,g[c].size()) {
    int u = g[c][i];
    if(u != p) {
      cnt++;
      mx = max(mx, 1 + getHeight(u, c, d + 1));
    }
  }
  D[d] = max(D[d], cnt);
  return mx;
}

int main() {
  int n;
  S(n);
  rep(i,0,n-1) {
    int u,v;
    S2(u,v);
    g[u].pb(v);
    g[v].pb(u);
    E[i] = mp(u, v);
  }

  int colors = n;
  LL leafs = 1e18;

  // process vertices.. 
  rep(i,1,n+1) {
    memset(D, 0, sizeof(D));
    int c = getHeight(i, -1, 0);
    if(c <= colors) {
      LL res = 1;
      rep(i,0,c+1) {
        res *= max(D[i], 1);
      }
      if(c < colors || (c == colors && res < leafs)) {
        leafs = res;
      }
      colors = c;
    }
  }

  // process edges
  rep(i,0,n-1) {
    memset(D, 0, sizeof(D));
    int u = E[i].FF;
    int v = E[i].SS;
    int c1 = getHeight(u, v, 0);
    int c2 = getHeight(v, u, 0);
    int c = max(c1, c2);
    D[0] = 2 * max(g[u].size() - 1, g[v].size() - 1);
    if(c <= colors) {
      LL res = 1;
      rep(i,0,c+1) {
        res *= max(D[i], 1);
      }
      if(c < colors || (c == colors && res < leafs)) {
        leafs = res;
      }
      colors = c;
    }
  }

  printf("%d %lld\n",colors + 1, leafs);
  return 0;
}

