		int l=0,r=0;
		d[q[r++]=s]=1,from[s]=f;
		for(int u;l<r;l++){
			int sn=0;u=q[l];
			for(auto v:e[u])
				if(v!=from[u]){
					d[q[r++]=v]=d[u]+1,from[v]=u;
					++sn;
				}
			mx[d[u]]=max(mx[d[u]],sn);
		}
	};
	bfs(1); int rt=max_element(d+1,d+n+1)-d;
	bfs(rt);int rt2=max_element(d+1,d+n+1)-d;
	for(int x=rt2;x;x=from[x])l[++cnt]=x;
	if(cnt%2==0){
		int A=l[cnt/2],B=l[cnt/2+1];
		bfs(A,B),bfs(B,A);
		X=cnt/2,Y=2;
		rep(i,1,X-1)Y*=mx[i];
	}
	else{
		X=(cnt+1)/2;
		rep(A,1,n)for(auto B:e[A]){
			fill(mx+1,mx+n+1,0);
			ll now=1;
			bfs(A,B);
			if(*max_element(d+1,d+n+1)>X)continue;
			bfs(B,A);
			if(*max_element(d+1,d+n+1)>X)continue;
			rep(i,1,X-1)now*=mx[i];
			Y=min(Y,now*2);
		}
		rep(A,1,n){
			fill(mx+1,mx+n+1,0);
			ll now=1;
			bfs(A);
			if(*max_element(d+1,d+n+1)>X)continue;
			rep(i,1,X-1)now*=mx[i];
			Y=min(Y,now);
		}
	}
	cout<<X<<" "<<Y<<endl;
	return 0;
}

