void makeTree(int v,int pre,Graph &g,Graph &t){
    //cerr<<v<<endl;
    for(int i=0;i<g[v].size();i++){
        if(g[v][i]!=pre){
            t[v].push_back(g[v][i]);
            makeTree(g[v][i],v,g,t);
        }
    }
}

pair<Int,Int> solve(vector<int> &vec,Graph& t){
    vector<int> newvec;
    Int dep=0;
    Int pat=vec.size();

    while(true){
        dep++;
        Int chi=0;
        for(int i=0;i<vec.size();i++){
            for(int j=0;j<t[vec[i]].size();j++){
                 newvec.push_back(t[vec[i]][j]);
            }
            chi=max(chi,Int(t[vec[i]].size()));
        }
        if(newvec.size()==0) break;
        pat*=chi;
        if(pat>1e20) return make_pair(Int(1e20),Int(1e20));
        vec=newvec;
        newvec=vector<int>();
    }
    return make_pair(dep,pat);
}



