typedef pair<int, int> P;

vector<int> E[200];

P far_v(int pre, int cur){
	P p;
	p.first = -1;
	p.second = cur;
	for(int i = 0; i < E[cur].size(); i++){
		if(E[cur][i] != pre){
			P p1 = far_v(cur, E[cur][i]);
			if(p1.first > p.first){
				p.first = p1.first;
				p.second = p1.second;
			}
		}
	}
	p.first++;
	return p;
}

void dist_v(int dist, int pre, int cur, int d[]){
	d[cur] = dist;
	for(int i = 0; i < E[cur].size(); i++){
		if(E[cur][i] != pre){
			dist_v(dist + 1, cur, E[cur][i], d);
		}
	}
}

