void ae(int a, int b)
{
	graph[a].push_back(b);
	graph[b].push_back(a);
}

pair<int, i64> best;
int branch[220];

void dfs(int p, int rt, int d)
{
	//printf("%d %d %d\n", p, rt, d);
	int deg = graph[p].size() - (rt == -1 ? 0 : 1);
	branch[d] = max(branch[d], deg);
	for (int q : graph[p]) if (q != rt) dfs(q, p, d + 1);
}

const i64 kMax = 0x7fffffffffffffffLL;

i64 sat_mul(i64 a, i64 b)
{
	if (a == 0 || b == 0) return 0;
	if (a < kMax / b) return a * b;
	return kMax;
}

void solve(int root)
{
	for (int i = 0; i < 2 * N; ++i) branch[i] = 0;
	dfs(root, -1, 0);

	i64 leaf = 1;
	int col = 0;
	for (int i = 0; i < 2 * N; ++i) {
		if (branch[i] > 0) {
			++col;
			leaf = sat_mul(leaf, branch[i]);
		}
	}

	best = min(best, { col / 2 + 1, leaf });
}

