using namespace std;

vector<vector<long long int>>path;

pair<long long int, long long int>recursive(set<long long int>used, set<long long int>now){
	if( now.size() == 0 ){
		return make_pair(0, 1);
	}
	set<long long int>next;
	long long int countmax = 1;
	for( auto s : now ){
		long long int count = 0;
		for( auto t : path[s] ){
			if( !used.count(t) ){
				next.insert(t);
				count++;
			}
		}
		countmax = max(count, countmax);
		used.insert(s);
	}
	auto ret = recursive(used, next);
	ret.first++;
	ret.second *= countmax;
	return ret;
}

int main(){
