using namespace std;

typedef unsigned long long LL;
typedef unsigned long long ULL;
typedef pair<int,int> PII;

#define REP(i,n) for(int i=0;i<(n);++i)
#define FOR(i,a,b) for (int i=(a); i<(b); ++i)
#define FORD(i,a,b) for (int i=(a)-1; i>=(b); --i)

#define pb push_back
#define mp make_pair
#define st first
#define nd second

const int MOD = 1000000007;

int N;
vector<int> adj[105];

int D[105];
void compute_distances(vector<int> r) {
  REP(i,N) D[i] = -1;

  queue<int> Q;
  for (int v: r) {
    Q.push(v);
    D[v] = 0;
  }
  while (!Q.empty()) {
    int v = Q.front();
    Q.pop();
    for (int u: adj[v]) if (D[u] == -1) {
      D[u] = D[v] + 1;
      Q.push(u);
    }
  }
}

pair<LL, LL> go() {
  compute_distances({0});
  int v = 0;
  REP(i,N) {
    if (D[i] > D[v]) v = i;
  }

  compute_distances({v});
  vector<int> D1(D, D+N);

  int u = 0;
  REP(i,N) if (D[i] > D[u]) u = i;
  int d = D[u];
  compute_distances({u});
  vector<int> D2(D, D+N);
  int K = ((d+1)/2);

  vector<int> roots;
  // REP(i,N) printf("!!%d %d %d %d\n", i, D1[i], D2[i], d);
  REP(i,N) if ((D2[i] == K || D2[i] == d-K) && D1[i] + D2[i] == d) roots.pb(i);
  compute_distances(roots);

  vector<vector<int>> by_distance(N+1);
  REP(i,N) by_distance[D[i]].pb(i);

  // REP(i,N+1) {
  //   if (!by_distance[i].empty()) printf("(%d) ", by_distance[i].size());
  // }
  // printf("\n");

  LL result = by_distance[0].size();
  int depth = 1;
  REP(i,N+1) {
    int m = 0;
    for (int v: by_distance[i]) {
      m = max(m, (int)adj[v].size() - (i > 0 ? 1 : (int)roots.size() - 1));
      // printf("?%d %d\n", v, (int)adj[v].size() - (i > 0 ? 1 : roots.size() - 1));
    }
    if (m == 0) break;
    depth = i + 2;
    // printf("M%d\n", m);
    result *= m;
  }

  return pair<LL,LL>{depth, result};
}

int main() {
  // ios_base::sync_with_stdio(0);

  scanf("%d", &N);
  REP(i,N-1) {
    int a, b;
    scanf("%d%d", &a, &b);
    --a, --b;
    adj[a].pb(b);
    adj[b].pb(a);
  }

  pair<LL, LL> res(~0ULL, ~0ULL);
  res = min(res, go());

  ++N;
  REP(i,N-1) {
    adj[i].pb(N-1);
    adj[N-1].pb(i);

    res = min(res, go());
    adj[i].pop_back();
    adj[N-1].pop_back();
  }

  printf("%lld %lld\n", res.st, res.nd);
}

