        vector<int> kek(n + 1), depth(n + 1);
        depth[r] = 1;
        kek[1] = g[r].size();
        queue<int> q;
        q.push(r);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int u : g[v]) {
                if (depth[u]) continue;
                depth[u] = depth[v] + 1;
                kek[depth[u]] = max<int>(kek[depth[u]], g[u].size());
                q.push(u);
            }
        }
        pair<int, ll> res{*max_element(depth.begin(), depth.end()), 1};
        for (int i = 1; i < res.first; i++) {
            res.second *= (i == 1 ? kek[i] : kek[i] - 1);
        }
        ans = min(ans, res);
    }

    for (int r1 = 1; r1 <= n; r1++) {
        for (int r2 : g[r1]) {
            vector<int> kek(n + 1), depth(n + 1);
            depth[r1] = depth[r2] = 1;
            kek[1] = max(g[r1].size(), g[r2].size()) * 2 - 2;
            queue<int> q;
            q.push(r1);
            q.push(r2);
            while (!q.empty()) {
                int v = q.front();
                q.pop();
                for (int u : g[v]) {
                    if (depth[u]) continue;
                    depth[u] = depth[v] + 1;
                    kek[depth[u]] = max<int>(kek[depth[u]], g[u].size());
                    q.push(u);
                }
            }
            pair<int, ll> res{*max_element(depth.begin(), depth.end()), 1};
            for (int i = 1; i < res.first; i++) {
                res.second *= (i == 1 ? kek[i] : kek[i] - 1);
            }
            ans = min(ans, res);
        }
    }

    cout << ans.first << ' ' << ans.second << endl;
    return 0;
}

