struct Node {
	int id;
	int color;
	int dist;
	bool visited;
	vector<int> nexts;
};

int N;
int dist;
vector<Node> nodes;
pair<int, int> ans;

int getFarest(int idx, vector<Node> &nodes) {
	dist = 0;
	rep(i, N) nodes[i].visited = false;
	queue<int> q;
	q.push(idx);
	nodes[idx].dist = 0;
	int last;
	while (!q.empty()) {
		int now = q.front(); q.pop();
		last = now;
		dist = max(dist, nodes[now].dist);
		nodes[now].visited = true;
		for (int next : nodes[now].nexts) {
			if (nodes[next].visited) continue;
			q.push(next);
			nodes[next].dist = nodes[now].dist + 1;
		}
	}
	return last;
}

vector<int> getPath(vector<Node> &nodes, int idx1, int idx2) {
	if (idx1 == idx2) return vector<int>(1, idx2);

	for (int next : nodes[idx1].nexts) {
		if (nodes[idx1].dist + 1 != nodes[next].dist) continue;
		vector<int> tmp = getPath(nodes, next, idx2);
		if (!tmp.empty()) {
			tmp.push_back(idx1);
			return tmp;
		}
	}

	return vector<int>();
}

void setColor(vector<Node> &nodes) {
	int N = nodes.size();

	int tmp = getFarest(0, nodes);
	int tmp2 = getFarest(tmp, nodes);

	vector<int> path = getPath(nodes, tmp, tmp2);

	int maxval = 0;
	queue<int> q;
	rep(i, N) nodes[i].color = -1;
	if (path.size() % 2) {
		int idx = path[path.size() / 2];
		q.push(idx);
		nodes[idx].color = 0;
	}
	else {
		int idx = path[path.size() / 2 - 1];
		q.push(idx);
		nodes[idx].color = 0;
		idx = path[path.size() / 2];
		q.push(idx);
		nodes[idx].color = 0;
	}
	while (!q.empty()) {
		int now = q.front(); q.pop();
		for (int next : nodes[now].nexts) {
			if (nodes[next].color != -1) continue;
			nodes[next].color = nodes[now].color + 1;
			q.push(next);
			maxval = max(maxval, nodes[now].color + 1);
		}
	}

	rep(i, N) {
		nodes[i].color = maxval - nodes[i].color;
	}
}

