			leafs = dist % 2 ? (it->second - 1) * 2 : it->second;
		} else {
			leafs *= it->second - 1;
		}
		//cerr << it->first << ": leafs=" << leafs << endl;
	}
	//cerr << "--" << endl;

	pair<int, int> ret;
	ret.first = colors;
	ret.second = leafs;
	return ret;
}

