}

pair<int, LL> solve() {
    vector<int> cand;
    int mx = 0;
    forn(i, n) {
        int cur = dfs(i, -1);
        if (cur > mx) {
            mx = cur;
            cand.clear();
        }
        if (cur == mx) {
            cand.pb(i);
        }
    }
    assert((int)cand.size() == 1 || (int)cand.size() == 2);
    mx.assign(101, 0);
    int sz = cand.size();
    forn(i, sz) {
        solve(cand[i], (sz == 1 ? -1 : cand[i ^ 1]), 0);
    }
    int res1 = 0;
    LL res2 = 1;
    forn(i, 101) if (mx[i] > 0) {
        res1++;
        res2 *= mx[i];
    }
    return mp(res1, res2);
}

int main() {
    scanf("%d", &n);
    forn(i, n - 1) {
        int from, to;
        scanf("%d%d", &from, &to), --from, --to;
        g[from].pb(to);
        g[to].pb(from);
    }
    auto ans = solve();
    ++n;
    forn(i, n - 1) {
        g[i].pb(n - 1);
        g[n - 1].pb(i);
        ans = min(ans, solve());
        g[i].pop_back();
        g[n - 1].pop_back();
    }
    cout << ans.first << ' ' << ans.second << endl;
    return 0;
}

#include <bits/stdc++.h>
