  }

  int mi = INF;
  vi argmi;
  REP(i, n) {
    int res = depth(i, -1, g);
    if(res < mi) {
      mi = res;
      argmi.clear();
      argmi.push_back(i);
    } else if(res == mi) {
      argmi.push_back(i);
    }
  }


  int r = -1;
  bool add = false;
  if(SZ(argmi) == 2) {
    add = true;
    r = n;
