        v[x].push_back(y);
        v[y].push_back(x);
    }

    long long k1 = solve();

    ++n;
    for(int i = 1; i < n; ++i)
    {
        v[i].push_back(n);
        v[n].push_back(i);

        long long kk = solve();
        if(kk > 0)
            k1 = min(k1, kk);

        v[i].pop_back();
        v[n].pop_back();
    }

    assert(ans > 1 && k1 > 1);

    cout << ans << ' ' << k1 << '\n';

    return 0;
}

