void dfs(int x){
	fore(i,x){
		if ( e[i].to == fa[x] ) continue;
		fa[e[i].to] = x , dth[e[i].to] = dth[x] + 1;
		dfs(e[i].to);
	}
}

void dfs(int x,int fa){
	fore(i,x){
		if ( e[i].to == fa ) continue;
		dth[e[i].to] = dth[x] + 1;
		dfs(e[i].to,x);
	}
}
bool legal(int x,int fa){
	rep(i,1,n) dth[i] = 0;
	dfs(x,fa);
	int mx = 0;
	rep(i,1,n) mx = max(mx,dth[i]);
	return mx == col - 2;
}
void init(){
	dfs(1);
	int rt = 0,x = 0;
	rep(i,1,n) if ( dth[rt] < dth[i] ) rt = i;
	rep(i,1,n) fa[i] = dth[i] = 0;
	dth[rt] = 1 , dfs(rt);
	rep(i,1,n) if ( dth[x] < dth[i] ) x = i;
	col = (dth[x] + 1) / 2;
	if ( dth[x] & 1 ){
		rep(i,1,col - 1) x = fa[x];
		dth[x] = 0 , dfs(x,0);
		rep(i,1,n) mx[dth[i]] = max(mx[dth[i]],deg[i] - 1);
		sum[col - 1] = 1;
		repd(i,col - 2,1){
			sum[i] = sum[i + 1] * mx[i];
