			if ( legal(e[i].to,x) ){
				int mid1 = x , mid2 = e[i].to;
				dth[mid1] = dth[mid2] = 0 , dfs(mid1,mid2) , dfs(mid2,mid1);
				rep(j,1,n) sum[j] = 0 , mx[j] = 0;
				rep(j,1,n) mx[dth[j]] = max(mx[dth[j]],deg[j] - 1);
				sum[col - 1] = 1;
				repd(j,col - 2,0){
					sum[j] = sum[j + 1] * mx[j];
				}
				num = min(num,2 * sum[0]);
			}
		}
	}
	else{
		int mid1,mid2;
		rep(i,1,col - 1) x = fa[x];
		mid1 = x , mid2 = fa[x];
		dth[mid1] = dth[mid2] = 0 , dfs(mid1,mid2) , dfs(mid2,mid1);
		rep(i,1,n) mx[dth[i]] = max(mx[dth[i]],deg[i] - 1);
		sum[col - 1] = 1;
		repd(i,col - 2,0){
			sum[i] = sum[i + 1] * mx[i];
		}
		num = 2 * sum[0];
	}
}
