const int MOD = 1e9 + 7;

const int N = 200;
int branch[N];
vector<int> a[N];
int maxdep;

void DFS(int u, int parent, int dep) {
  maxdep = max(maxdep, dep);
  int cnt = 0;
  for (auto& v : a[u]) {
    if (v == parent) continue;
    DFS(v, u, dep + 1);
    ++cnt;
  }
  branch[dep] = max(branch[dep], cnt);
}

ii e[N];

int main() {
  int n;
  scanf("%d", &n);
  vector<pair<int, int>> e;
  for (int i = 1; i < n; ++i) {
    int x, y;
    scanf("%d%d", &x, &y);
    --x; --y;
    e.push_back({x, y});
    a[x].push_back(y);
    a[y].push_back(x);
  }
  ii ret = {1LL << 60, 1LL << 60};
  for (int i = 0; i < n; ++i) {
    memset(branch, 0, sizeof(branch));
    maxdep = 0;
    DFS(i, -1, 0);
    int64 cur = 1;
    for (int i = 0; i < maxdep; ++i) {
      cur *= branch[i];
    }
    ret = min(ret, {maxdep, cur});
  }
  for (auto& it : e) {
    int x = it.first, y = it.second;
    memset(branch, 0, sizeof(branch));
    maxdep = 0;
    DFS(x, y, 0);
    DFS(y, x, 0);
    int64 cur = 2;
    for (int i = 0; i < maxdep; ++i) {
      cur *= branch[i];
    }
    ret = min(ret, {maxdep, cur});
  }
  printf("%lld %lld\n", ret.first + 1, ret.second);
  return 0;
}

