VI bfs(const VVI& es, int start) {
    const int n = len(es);
    VI pre(n, -1);
    queue<int> que;
    que.push(start), pre[start] = -2;
    int x = start;
    while (!que.empty()) {
        x = que.front(), que.pop();
        for (int y : es[x]) {
            if (pre[y] == -1) {
                pre[y] = x, que.push(y);
            }
        }
    }
    VI path;
    while (x >= 0) path.pb(x), x = pre[x];
    reverse(all(path));
    return path;
}

pair<int, LL> cal(const VVI& es, int x1, int x2 = -1) {
    VI maxd(1);
    const function<void(int, int, int)> dfs = [&](int x, int fa, int d) {
        if (d >= len(maxd)) maxd.pb(0);
        int cur = 0;
        for (int y : es[x]) {
            if (y != fa) {
                ++cur;
                dfs(y, x, d + 1);
            }
        }
        setmax(maxd[d], cur);
    };
    dfs(x1, x2, 0);
    if (x2 >= 0) dfs(x2, x1, 0);
    LL s = 1;
    // cout << x1 + 1 << " " << x2 + 1 << " " << maxd << endl;
    repn(i, len(maxd) - 1) s *= maxd[i];
    if (x2 >= 0) s *= 2;
    return {len(maxd), s};
}

int main() {
