    VVI es(n);
    repn(i, n - 1) {
        int a = IN - 1, b = IN - 1;
        es[a].pb(b), es[b].pb(a);
    }
    VI path = bfs(es, bfs(es, 0).back());
    pair<int, LL> ans;
    if (len(path) % 2 == 0) {
        int x = path[len(path) / 2 - 1], y = path[len(path) / 2];
        ans = cal(es, x, y);
        assert(ans.fi == len(path) / 2);
    } else {
        int x = path[len(path) / 2];
        ans = cal(es, x);
        for (int y : es[x]) setmin(ans, cal(es, x, y));
        assert(ans.fi == len(path) / 2 + 1);
    }
    cout << ans.fi << " " << ans.se << endl;

    return 0;
}

