int Compare(deque<int> A, deque<int> B) {
	int NA = A.size();
	int NB = B.size();
	if (NA > NB) return 1;
	if (NA < NB) return -1;
	rep1(i, NA) {
		if (A[NA - i] > B[NB - i]) return 1;
		if (A[NA - i] < B[NB - i]) return -1;
	}
	return 0;
}

void kakeru(deque<int> &A, ll B) {
	ll kari = 0;
	int N = A.size();
	rep(i, N) {
		kari += B * A[i];
		A[i] = kari % 10;
		kari /= 10;
	}
	while(kari) {
		A.pb(kari % 10);
		kari /= 10;
	}
}

