struct Graph{
    struct Node{
        vector<int> dests;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.dests); } }
    void addEdge(int from, int dest){
        nodes[from].dests.push_back(dest);
    }
    void addEdge2(int from, int dest){
        addEdge(from, dest);
        addEdge(dest, from);
    }
    void dfs(vector<int>& maxis, int idx, int from = -1, int depth = 0){
        int cnt = 0;
        for(int didx : nodes[idx].dests){
            if(didx == from){ continue; }
            dfs(maxis, didx, idx, depth + 1);
            cnt++;
        }
        if((int)maxis.size() <= depth){
            maxis.resize(depth + 1);
        }
        maxis[depth] = max(maxis[depth], cnt);
    }
};

