	template<typename T>
	inline bool read(T &x)
	{
		char c;
		bool f = false;
		x = 0;
		do
			c = getchar();
		while (c != EOF && c != '-' && !isdigit(c));
		if (c == EOF)
			return false;
		if (c == '-')
			f = true, c = getchar();
		do
			x = x * 10 + c - '0', c = getchar();
		while (isdigit(c));
		if (f)
			x = -x;
		return true;
	}
	template<typename T>
	inline void write(T x)
	{
		static char buf[20];
		char *pos = buf;
		if (x < 0)
			putchar('-'), x = -x;
		do
			*pos++ = x % 10 + '0';
		while (x /= 10);
		while (pos > buf)
			putchar(*--pos);
	}
	typedef long long ll;
	const int N = 110;
	int n, dep[N], dp[N], D, deg[N], pre[N], r, r2;
	ll ans;
	vector<int> g[N];
	void dfs1(const int u, const int f)
	{
		dp[u] = 1;
		for (auto v : g[u])
		{
			if (v == f)
				continue;
			dfs1(v, u);
			if (dp[u] + dp[v] > D)
				r = u, r2 = (dp[u] < dp[v] + 1 ? pre[u] : v), D = dp[u] + dp[v];
			if (dp[u] < dp[v] + 1)
				dp[u] = dp[v] + 1, pre[u] = v;
		}
	}
	void dfs2(const int u, const int f, const int d)
	{
		dep[u] = d;
		deg[u] = 0;
		for (auto v : g[u])
		{
			if (v == f)
				continue;
			++deg[u];
			dfs2(v, u, d + 1);
		}
	}
	ll solve(const int r1, const int r2)
	{
		static int mx[N];
		ll tmp = (r2 ? 2 : 1);
		memset(mx, 0, sizeof(mx));
		dfs2(r1, r2, 0);
		if (r2)
			dfs2(r2, r1, 0);
		for (int i = 1; i <= n; i++)
			mx[dep[i]] = max(mx[dep[i]], deg[i]);
		for (int i = 0; i <= n && mx[i]; i++)
			tmp *= mx[i];
		return tmp;
	}
	int work()
	{
		read(n);
		for (int i = 1; i < n; i++)
		{
			int a, b;
			read(a), read(b);
			g[a].push_back(b), g[b].push_back(a);
		}
		dfs1(1, 0);
		vector<int> d;
		while (r)
			d.push_back(r), r = pre[r];
		reverse(d.begin(), d.end());
		while (r2)
			d.push_back(r2), r2 = pre[r2];
		int rot1 = d[d.size() / 2], rot2 = (D & 1 ? 0 : d[d.size() / 2 - 1]);
		write((D + 1) / 2), putchar(' ');
		if (rot2)
			ans = solve(rot1, rot2);
		else
		{
			ans = solve(rot1, 0);
			for (auto v : g[rot1])
				ans = min(ans, solve(rot1, v));
		}
		write(ans);
		return 0;
	}
}
int main()
{
	return zyt::work();
}

