typedef lib::modnum<1000000007> mod_t;
typedef std::pair<std::int64_t, std::int64_t> int64pair;
typedef std::vector<std::set<int>> graph_t;
std::pair<int, int> distance_set(graph_t const& edge, std::vector<int>& dist, int now, int prev, int depth)
{
	dist[now] = depth;
	int longest = depth;
	int point = now;
	for (auto e : edge[now])
	{
		if (e == prev)
		{
			continue;
		}
		DEFINE_STRUCT2(len, p, distance_set(edge, dist, e, now, depth + 1));
		if (len > longest)
		{
			longest = len;
			point = p;
		}
	}
	return std::make_pair(longest, point);
}

std::int64_t calc_leave(graph_t const& edge, std::set<int>now, std::vector<int>& walked)
{
	if (now.size() == 0)
	{
		return 1;
	}
	std::int64_t max = 1;
	std::set<int> next;
	for (auto n : now)
	{
		std::int64_t count = 0;
		for (auto e : edge[n])
		{
			if (walked[e])
			{
				continue;
			}
			++count;
			next.emplace(e);
		}
		walked[n] = true;
		max = std::max(count, max);
	}
	return max * calc_leave(edge, next, walked);
}

void Main()
{
	int N;
	std::cin >> N;
	graph_t edge(N);
	for (int i : boost::irange(0, N - 1))
	{
		int a, b;
		std::cin >> a >> b;
		--a; --b;
		edge[a].emplace(b);
		edge[b].emplace(a);
	}
	std::vector<int> dist0(N);
	std::vector<int> dist1(N);
	std::vector<int> dist2(N);
	DEFINE_STRUCT2(len0, x, distance_set(edge, dist0, 0, -1, 0));
	DEFINE_STRUCT2(len1, y, distance_set(edge, dist1, x, -1, 0));
	DEFINE_STRUCT2(len2, z, distance_set(edge, dist2, y, -1, 0));
	std::set<int> center;
	for (int i : boost::irange(0, N))
	{
		if (std::abs(2 * dist1[i] - len1) <= 1 &&
			std::abs(2 * dist2[i] - len2) <= 1)
		{
			center.emplace(i);
		}
	}

	std::vector<int> walked(N);
	for (auto c : center)
	{
		walked[c] = true;
	}
	std::int64_t min = center.size() * calc_leave(edge, center, walked);

	if (center.size() == 1)
	{
		auto c = *center.begin();
		for (auto e : edge[c])
		{
			for (auto& v : walked)
			{
				v = false;
			}
			walked[c] = walked[e] = true;
			center.emplace(e);
			min = std::min(min, 2 * calc_leave(edge, center, walked));
			center.erase(e);
		}
	}
	out::write_line(len1 / 2 + 1, min);
}

