}

void pre(int x, int fa, int dep) {
	int cnt = 0;
	fore (e, x, y) if (y != fa) {
		pre(y, x, dep+1);
		++cnt;
	}
	ans[dep] = max(ans[dep], max(cnt, 1));
}

LL gao(int l) {
	LL res = 1;
	rep (i, 1, l) res = res * ans[i];
	return res;
}

