	if(l%2) {
		for(ll i=1;i<=n;i++) {
			n++;
			adj[i].push_back(n);
			adj[n].push_back(i);
			solve();
			adj[i].pop_back();
			adj[n].pop_back();
			n--;
		}
	}
	printf("%lld %lld\n",(l+1)/2,ans);
}

