vector<int> mergeVec(vi& x, vi& y) {
    reverse(all(x));
    reverse(all(y));
    int n = max(x.size(), y.size());
    vi ret(n);
    rep(i, x.size()) ret[i] = max(ret[i], x[i]);
    rep(i, y.size()) ret[i] = max(ret[i], y[i]);
    reverse(all(x));
    reverse(all(y));
    reverse(all(ret));
    return ret;
}

