    if(par != MAX_N-1) --k;
    ret.push_back(k);
    return memo[v][par] = ret;
}

ll getLeaf(const vi& x) {
    ll ret = 1LL;
    rep(i, x.size()) {
        if(double(ret)*x[i] > 9e18) return -1;
        ret *= x[i];
    }
    return ret;
}

vector<int> getAns(const vi& x, const vi& y) {
    if(x.size() < y.size()) return x;
    if(x.size() > y.size()) return y;
    ll X = getLeaf(x);
    ll Y = getLeaf(y);
    if(X == -1) return y;
    if(Y == -1) return x;
    if(X < Y) return x;
    return y;
}


