void ins(int u,int v){
	e[++cnt].to = v;e[cnt].nxt = fir[u];fir[u] = cnt;
	e[++cnt].to = u;e[cnt].nxt = fir[v];fir[v] = cnt;
}
int dpt[1010];
int mx,gen,ge;
bool ed[110][110];
void dfs(int q,int lst){
	dpt[q] = dpt[lst] + 1;
	if(dpt[q] > mx){
		mx = dpt[q];
		gen = q;
	}
	for(int i = fir[q];i;i = e[i].nxt){
		int j = e[i].to;
		if(j == lst) continue;
		dfs(j,q);
	}
}
li ans1,ans2;
int jl[1010],ct;
void dfs2(int q,int lst){
	jl[++ct] = q;
	for(int i = fir[q];i;i = e[i].nxt){
		int j = e[i].to;
		if(j == lst || dpt[j] != dpt[q] - 1) continue;
		dfs2(j,q);
	}
}
int sd[1010],sl[1010];
int mxas[1010];
void dfs3(int q,int lst){
	sd[q] = sd[lst] + 1;
	int ss = 0;
	for(int i = 1;i <= n;++i) if(ed[q][i]){
		if(i == lst) continue;
		++ss;
		dfs3(i,q);
	}
	sl[q] = ss;
}
