		//cout<<u<<" "<<v<<endl;
		ed[u][v] = ed[v][u] = 0;
		++n;
		ed[n][u] = ed[n][v] = ed[u][n] = ed[v][n] = 1;
		work(n);
		ans3 = ans2;
	}
	else{
		work(jl[mx + 1 >> 1]);
		ans3 = ans2;
		u = jl[mx + 1 >> 1];
		v = jl[(mx + 1) / 2 - 1];
		w = jl[(mx + 1) / 2 + 1];
		ed[u][v] = ed[v][u] = 0;
