		ans3 = min(ans3,ans2);
		ed[u][v] = ed[v][u] = 1;
		ed[u][w] = ed[w][u] = ed[n][v] = ed[v][n] = 0;
		ed[n][w] = ed[w][n] = 1;
		work(n);
		ans3 = min(ans3,ans2);
	} 
	cout<<ans1<<" "<<ans3<<endl;
	return 0;
}

