#define fastInp cin.tie(0); cout.tie(0); ios_base::sync_with_stdio(0);

vector<vector<ll>> gr;

const ll INF = 1e9 * 1e9;
ll d[200][200], par[200][200];
bool used[200];
vector<ll> vals;
ll ans = INF;

void check(int v, int st, bool fl = 0) {
	used[v] = 1;
	ll curD = d[st][v];

	if (v != st) {
		vals[curD] = max(vals[curD], ll(gr[v].size() - 1));
	}
	else {
		if (!fl) {
			vals[curD] = max(vals[curD], ll(gr[v].size()));
		}
		else {
			vals[curD] = max(vals[curD], ll(gr[v].size() - 1));
		}
	}

	for (auto to : gr[v]) {
		if (!used[to]) {
			check(to, st, fl);
		}
	}
}

vector<ll> sv;
void check2(int v, int dist, int st) {
	vector<vector<ll>> cur;

	used[v] = 1;
	ll curD = d[st][v];

	if (st != v) vals[curD] = max(vals[curD], ll(gr[v].size()));


	for (auto to : gr[v]) {
		if (!used[to]) {
			check2(to, dist, st);
		}
		if (v == st) {
			cur.push_back(vals);
			for (auto &cur : vals) cur = 0;
		}
	}

	for (int i = 0; i < cur.size(); i++) {
		vector<ll> c(vals.size());
		for (int t = 0; t < cur.size(); t++) {
			if (t != i) {
				for (int j = 0; j < vals.size() - 1; j++) c[j + 1] = max(c[j + 1], cur[t][j]);
			}
			else {
				for (int j = 0; j < vals.size(); j++) {
					c[j] = max(c[j], cur[t][j]);
				}
			}
		}

		ll cr = 1;
		for (int i = 0; i < vals.size(); i++) {
			if (c[i] != 0) c[i]--;
		}

		for (int i = 0; i < vals.size() - 1; i++) {
			if (c[i] != 0) cr *= c[i];
		}

		ans = min(ans, cr * 2);
	}
}

int main()
{
	fastInp;

	ll n;
	cin >> n;

	gr.resize(n);
	for (int i = 0; i < n - 1; i++) {
		ll u, v;
		cin >> u >> v;
		u--; v--;
		gr[u].push_back(v);
		gr[v].push_back(u);
	}

	ll dim = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) used[j] = 0;
		queue<ll> q;
		q.push(i);
		while (!q.empty()) {
			ll v = q.front();
			q.pop();
			used[v] = 1;
			for (auto to : gr[v]) {
				if (!used[to]) {
					d[i][to] = d[i][v] + 1;
					par[i][to] = v;
					used[to] = 1;
					q.push(to);
				}
			}
		}
		for (int j = 0; j < n; j++) dim = max(dim, d[i][j]);
	}

	vals.resize(dim + 1);

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			if (d[i][j] == dim) {
				vals.clear();
				vals.resize(dim + 1);
				for (int t = 0; t < n; t++) used[t] = 0;
				ll v = j;
				if (dim % 2 != 0) {
					ll ds = (dim - 1) / 2 + 1;
					while (d[i][v] != ds) {
						v = par[i][v];
					}
					ll u = par[i][v];
					used[u] = 1;
					used[v] = 1;
					check(u, u, 1);
					check(v, v, 1);
				}
				else {
					while (d[i][v] != dim / 2) {
						v = par[i][v];
					}
					check(v, v);
				}

				ll cur = 1;

				for (int i = 0; i < vals.size() - 1; i++) {
					if (vals[i] != 0) cur *= vals[i];
				}
				if (dim % 2 != 0) cur *= 2;
				ans = min(ans, cur);

				if (dim % 2 == 0) {
					sv.clear();
					sv.resize(dim + 1);
					for (int i = 0; i < vals.size(); i++) vals[i] = 0;
					for (int i = 0; i < n; i++) used[i] = 0;
					check2(v, dim, v);
				}
			}
		}
	}

	cout << (dim) / 2 + 1 << " " << ans;
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

int n, maxD, dmtr, rootA, rootB, nxtN, CF, leaves;
int mcal[105];
int dist[105];
vector<vector<int> > adj;

void diam(int u, int p, int d){
    if(d > maxD){
        nxtN = u;
        maxD = d;
    }
    dist[u] = d;
    for(int i = 0; i < adj[u].size(); i++){
        if(adj[u][i] == p) continue;
        diam(adj[u][i], u, d+1);
    }
}

int findRootS(int u, int p, int d){
    int md = d;
    for(int i = 0; i < adj[u].size(); i++){
        if(adj[u][i] == p) continue;
        md = max(md, findRootS(adj[u][i], u, d+1));
    }
   // printf("node %d is %d units from starting point", u, d);
    if(md == dmtr){
     //   printf("and it's a root\n");
        if(d == dmtr/2){
            rootA = u;
        }
        else if(d == dmtr/2 +1){
            rootB = u;
        }
    }
    //printf("\n");
    return md;
}

void findMCAL(int u, int p, int lvl){
   // printf("node %d is %d layer deeps and has %d non-parent chldren\n", u, lvl, adj[u].size() - 1);
    mcal[lvl] = max(mcal[lvl], int(adj[u].size() - 1));
    for(int i = 0; i < adj[u].size(); i++){
        if(adj[u][i] == p || adj[u][i] < 0) continue;
        findMCAL(adj[u][i], u, lvl+1);
    }
}

int findROOT(int u, int p, int d){
    int md = d;
    for(int i = 0; i < adj[u].size(); i++){
        if(adj[u][i] == p) continue;
        md = max(md, findROOT(adj[u][i], u, d+1));
    }
    if(md == dmtr){
        if(2*d == dmtr) rootA = u;
    }
    return md;
}

int main()
{
    int a, b;
    cin >> n;
    adj.resize(205);
    for(int i = 0; i < n-1; i++){
        cin >> a >> b; a--; b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    maxD = 0;
    diam(0, -1, 0);
    maxD = 0;
    diam(nxtN, -1, 0);
    dmtr = maxD;
    if(dmtr%2){ // 2 centers, divide tree in 2 and CF = dmtr/2 + 1
        CF = dmtr/2 + 1;
        findRootS(nxtN, -1, 0);
        for(int i = 0; i < adj[rootA].size(); i++) if(adj[rootA][i] == rootB) adj[rootA][i] = -1;
        for(int i = 0; i < adj[rootB].size(); i++) if(adj[rootB][i] == rootA) adj[rootB][i] = -1;

        findMCAL(rootA, -1, 0);
        findMCAL(rootB, -1, 0);

        leaves = 2;

        for(int i = 0; i < dmtr && mcal[i] > 0; i++){
            leaves*=mcal[i];
        }
        cout << CF << ' ' << leaves << endl;
        //mcal[0] = max(adj[rootA].size() - 1, adj[rootB].size() - 1);
    }
    else{ // either take the center OR try and take each neigbor of the vertex to make a pair (need to increase diameter by one
        int leafGuess = 1;
        findROOT(nxtN, -1, 0);
        CF = dmtr/2 + 1;
        findMCAL(rootA, -1, 0);
        mcal[0] = adj[rootA].size();
        for(int i = 0; i < dmtr && mcal[i] > 0; i++){
        //    printf("mcal at depth %d is %d\n", i, mcal[i]);
            leafGuess*=mcal[i];
        }
      //  printf("center is %d and leaf for it alone is %d\n", rootA, leafGuess);
        for(int i = 0; i < adj[rootA].size(); i++){
            int v = adj[rootA][i];
           // printf("trying to pair center with %d\n", v);
            for(int j = 0; j < adj[rootA].size(); j++) if(adj[rootA][j] == v) adj[rootA][j] = -1;
            for(int j = 0; j < adj[v].size(); j++) if(adj[v][j] == rootA) adj[v][j] = -1;



            memset(mcal, 0, sizeof mcal);

            findMCAL(rootA, -1, 0);
            findMCAL(v, -1, 0);

            leaves = 2;

            for(int i = 0; i < dmtr && mcal[i] > 0; i++){
             //   printf("mcal at depth %d is %d\n", i, mcal[i]);
                leaves*=mcal[i];
            }

            //printf("%d leaves needed for this pair\n", leaves);

            leafGuess = min(leafGuess, leaves);
            for(int j = 0; j < adj[rootA].size(); j++) if(adj[rootA][j] == -1) adj[rootA][j] = v;
            for(int j = 0; j < adj[v].size(); j++) if(adj[v][j] == -1) adj[v][j] = rootA;

        }
        cout << CF << ' ' << leafGuess << endl;
    }
    return 0;
}

