void dfs(int node, int d) {
	used[node] = true;
	int children = 0;
	for (int i : vec[node]) {
		if (now != -1) {
			if (node == a[now] && i == b[now])continue;
			if (node == b[now] && i == a[now])continue;
		}
		if (!used[i]) {
			children++;
			dfs(i, d + 1);
		}
	}
	chmax(c[d], children);
}
