template <typename T>
struct Tree{
  int n = 0;
  vector<vector<edge<T>>> edges;
  vector<T> dis;
  Tree(){}
  explicit Tree(int n): n(n){
    edges.resize(n);
    dis.resize(n);
  }
  void adde(int from, int to, T cost){
    edges[from].emplace_back(from, to, cost);
  }
  void dfs(int i){
    for(auto e: edges[i]){
      if(dis[e.to] == -1){
        dis[e.to] = dis[i] + e.w;
        dfs(e.to);
      }
    }
  }
  T diameter(){
    dis.assign(n, -1);
    dis[0] = 0;
    dfs(0);
    int at = 0;
    T maxi = -1;
    for(int i = 0; i < n; i++){
      if(maxi < dis[i]){
        maxi = dis[i];
        at = i;
      }
    }
    dis.assign(n, -1);
    dis[at] = 0;
    dfs(at);
    st = at;
    T res = -1;
    for(int i = 0; i < n; i++){
      if(res < dis[i]){
        res = dis[i];
        en = i;
      }
    }
    return res;
  }
};
vector<int> edges[101];

bool dfs(int i, int g, int p){
  path.pb(i);
  if(i == g)return true;
  for(auto e: edges[i]){
    if(e == p)continue;
    bool b = dfs(e, g, i);
    if(b)return true;
  }
  path.pop_back();
  return false;
}

struct ed{
  int i, p, h;
  ed(int i, int p, int h): i(i), p(p), h(h){}
};

ll calc(int u, int v){
  vector<ll> deg;
  queue<ed> q;
  q.push(ed(u, v, 0));
  q.push(ed(v, u, 0));
  while(!q.empty()){
    auto p = q.front(); q.pop();
    if(sz(deg) <= p.h)deg.pb(1);
    chmax(deg[p.h], (ll)sz(edges[p.i]) - 1);
    for(auto e: edges[p.i]){
      if(e == p.p)continue;
      q.push(ed(e, p.i, p.h + 1));
    }
  }
  ll res = 1;
  for(auto d: deg)res *= d;
  return res;
}

ll calc2(int u){
  vector<ll> deg;
  queue<ed> q;
  q.push(ed(u, -1, 0));
  while(!q.empty()){
    auto p = q.front(); q.pop();
    if(sz(deg) <= p.h)deg.pb(1);
    if(p.i != u)chmax(deg[p.h], (ll)sz(edges[p.i]) - 1);
    else chmax(deg[p.h], (ll)sz(edges[p.i]));
    for(auto e: edges[p.i]){
      if(e == p.p)continue;
      q.push(ed(e, p.i, p.h + 1));
    }
  }
  ll res = 1;
  for(auto d: deg)res *= d;
  return res;
}

