namespace A{
	int n;
	int dis[N];
	int findfar(int x,int pre=0,int d=0){
		dis[x]=d;
		int ans=x;
		for (auto y : e[x])
			if (y!=pre){
				int now=findfar(y,x,d+1);
				if (dis[now]>dis[ans])
					ans=now;
			}
		return ans;
	}
	int depth[N],fa[N];
	void dfs(int x,int pre=0,int d=0){
		depth[x]=d,fa[x]=pre;
		for (auto y : e[x])
			if (y!=pre)
				dfs(y,x,d+1);
	}
	int mx[N];
	void sv(int x,int pre,int d){
		int cnt=0;
		for (auto y : e[x])
			if (y!=pre){
				sv(y,x,d+1);
				cnt++;
			}
		mx[d]=max(mx[d],cnt);
	}
	piL solve(){
		int a=findfar(1);
		int b=findfar(a);
		dfs(a);
		int m=b;
		For(i,1,depth[b]/2)
			m=fa[m];
		clr(mx);
		LL ans=1;
		if (depth[b]&1){
			int x=m,y=fa[m];
			sv(x,y,0),sv(y,x,0);
			ans*=2;
		}
		else {
			int x=m;
			sv(x,0,0);
		}
		For(i,0,n)
			if (mx[i])
				ans*=mx[i];
		return mp(depth[b]/2+1,ans);
	}
}
