		G[y[i]].pb(x[i]);
	}
	rep(i, 1, n)
	{
		memset(dis, 0, sizeof(dis));
		memset(sz, 0, sizeof(sz));
		dis[i] = 1;
		dfs(i ,0);
		ll now = 0;
		rep(i, 1, n) now = max(now, dis[i]);
		ll tmp[N] = {0};
		rep(i, 1, n)
			tmp[dis[i]] = max(tmp[dis[i]], sz[i]);
		ll Tmp = 1;
		rep(i, 1, now - 1) Tmp *= tmp[i];
		if(now < ans) ans = now, res = Tmp;
		else if(now == ans) res = min(res ,Tmp);
	}
	rep(i, 1, n - 1)
	{
		memset(dis, 0, sizeof(dis));
		memset(sz, 0, sizeof(sz));
		dis[x[i]] = dis[y[i]] = 1;
		dfs(x[i], y[i]);
