const int maxn = 101, inf = 1e9;

int n;
vector<int> g[maxn];
int prev[maxn];
int st[maxn], top;
int deg[maxn];

int Find(int u) {
  queue<int> q;
  q.push(u);
  memset(prev, -1, sizeof prev);
  prev[u] = u;
  while (!q.empty()) {
    u = q.front();
    q.pop();
    for (int v : g[u]) {
      if (prev[v] == -1) {
        prev[v] = u;
        q.push(v);
      }
    }
  }
  return u;
}

void Dfs(int u, int p, int d = 0) {
  int cnt = 0;
  for (int v : g[u]) {
    if (v != p) {
      ++cnt;
      Dfs(v, u, d + 1);
    }
  }
  deg[d] = max(deg[d], cnt);
}

pair<int, unsigned long long> Solve(void) {
  int u = Find(0);
  int v = Find(u);
  top = 0;
  for (int k = v; k != u; k = prev[k]) {
    st[top++] = k;
  }
  st[top++] = u;
  memset(deg, 0, sizeof deg);
  if (top - 1 & 1) {
    int p1 = st[(top >> 1) - 1], p2 = st[top >> 1];
    Dfs(p1, p2);
    Dfs(p2, p1);
    int h = (top >> 1) - 1;
    unsigned long long ans = 1;
    for (int i = 0; i < h; ++i) {
      ans *= deg[i];
    }
    return {h + 1, ans << 1};
  } else {
    int p = st[top >> 1];
    Dfs(p, -1);
    int h = top >> 1;
    unsigned long long ans = 1;
    for (int i = 0; i < h; ++i) {
      ans *= deg[i];
    }
    return {h + 1, ans};
  }
}

