#include<bits/stdc++.h>
using namespace std;

using Graph = vector<vector<int>>;

using I = long long;
using P = pair<I, I>;
P ans(1e18, 1e18);

void solve(const auto& G, auto r) {
  vector<vector<I>> child;
  function<void(int, int, int)> dfs = [&](auto v, auto p, auto d) {
    if(child.size() <= d) child.emplace_back(0);
    if(v == r) child[d].emplace_back(G[v].size());
    else       child[d].emplace_back(G[v].size() - 1);
    for(auto nex: G[v]) if(nex!=p) dfs(nex, v, d+1);
  };
  dfs(r, r, 0);
  I res = 0;
  for(auto d=0; d<child.size(); ++d) {
    auto mx = *max_element(begin(child[d]), end(child[d]));
    if(d+1 < child.size()) {
      I sum = 0;
      for(auto i: child[d]) sum += mx - i;
      for(auto i=0; i<sum; ++i) child[d+1].emplace_back(0);
    } else {
      res = child[d].size();
    }
  }
  I c = child.size();
  if(c <  ans.first) ans = P(c, res);
  if(c == ans.first) ans.second = min(ans.second, res);
}

void solve(const auto& G, auto x, auto y) {
  vector<vector<I>> X, Y;
  function<void(int, int, int)> dfsX = [&](auto v, auto p, auto d) {
    if(X.size() <= d) X.emplace_back(0);
    X[d].emplace_back(G[v].size() - 1);
    for(auto nex: G[v]) if(nex!=p) dfsX(nex, v, d+1);
  };
  function<void(int, int, int)> dfsY = [&](auto v, auto p, auto d) {
    if(Y.size() <= d) Y.emplace_back(0);
    Y[d].emplace_back(G[v].size() - 1);
    for(auto nex: G[v]) if(nex!=p) dfsY(nex, v, d+1);
  };
  dfsX(x, y, 0);
  dfsY(y, x, 0);
  if(X.size() > Y.size()) swap(X, Y);
  while(X.size() != Y.size()) X.emplace_back(0);
  I res = 0;
  for(auto d=0; d<X.size(); ++d) {
    while(X[d].size() != Y[d].size()) {
      if(X[d].size() < Y[d].size()) X[d].emplace_back(0);
      else                          Y[d].emplace_back(0);
    }
    sort(begin(X[d]), end(X[d]));
    sort(begin(Y[d]), end(Y[d]));
    auto mx = max(X[d].back(), Y[d].back());
    if(d+1 < X.size()) {
      for(auto i=0; i<X[d].size(); ++i) {
        for(auto j=0; j<mx-X[d][i]; ++j) X[d+1].emplace_back(0);
        for(auto j=0; j<mx-Y[d][i]; ++j) Y[d+1].emplace_back(0);
      }
    } else {
      res = X[d].size() + Y[d].size();
    }
  }
  I c = X.size();
  if(c <  ans.first) ans = P(c, res);
  if(c == ans.first) ans.second = min(ans.second, res);
}

