		vec<int> next_p;
		rep(i, cur_p.size()) {
			rep(j, g[cur_p[i]].size()) {
				if (dp[g[cur_p[i]][j]]) continue;
				dp[g[cur_p[i]][j]] = 1;
				next_p.pb(g[cur_p[i]][j]);
			}
		}

		int Max = 1;
		rep(i, cur_p.size()) {
			int temp = (int)g[cur_p[i]].size() - 1;
			Max = Max < temp ? temp : Max;
		}
		// cout << Max << endl;
		ans *= Max;
		cur_p = next_p;
	}
	return ans;
}

