template <typename T> void chmax(T &a, T b) { a = max(a, b); }
vector<vector<int>> G;
int d[110][110];
void dfs(int i, int p, int r) {
    for (auto &e : G[i]) {
        if (e == p) {
            continue;
        }
        d[r][e] = d[r][i] + 1;
        dfs(e, i, r);
    }
}
int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    G.resize(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }
    int ma = 0, ss, t;
    for (int i = 0; i < n; i++) {
        d[i][i] = 0;
        dfs(i, -1, i);
        for (int j = 0; j < n; j++) {
            if (ma < d[i][j]) {
                ma = d[i][j];
                ss = i;
                t = j;
            }
        }
    }
    ma++;
    ll res = LINF;
    if (ma % 2 == 0) {
        int u = -1, v = -1;
        for (int i = 0; i < n; i++) {
            if (d[ss][i] + d[i][t] == ma - 1 &&
                abs(d[ss][i] - (ma - 1) / 2) <= 1) {
                if (u == -1) {
                    u = i;
                } else {
                    v = i;
                    break;
                }
            }
        }
        vector<int> c(n + 1);
        for (int i = 0; i < n; i++) {
            if (d[u][i] < d[v][i]) {
                chmax(c[d[u][i]], (int)G[i].size() - 1);
            } else {
                chmax(c[d[v][i]], (int)G[i].size() - 1);
            }
        }
        ll s = 1;
        for (int i = 0; i <= n; i++) {
            if (c[i] == 0) {
                break;
            }
            s *= c[i];
        }
        res = s * 2;
    } else {
        int p = -1;
        for (int i = 0; i < n; i++) {
            if (d[ss][i] + d[i][t] == ma - 1 && d[ss][i] * 2 == ma - 1) {
                p = i;
                break;
            }
        }
        vector<int> c(n + 1);
        for (int i = 0; i < n; i++) {
            if (i == p) {
                chmax(c[d[p][i]], (int)G[i].size());
            } else {
                chmax(c[d[p][i]], (int)G[i].size() - 1);
            }
        }
        ll s = 1;
        for (int i = 0; i <= n; i++) {
            if (c[i] == 0) {
                break;
            }
            s *= c[i];
        }
        res = s;
        for (int i = 0; i < n; i++) {
            if (d[p][i] != 1) {
                continue;
            }
            c.assign(n + 1, 0);
            for (int j = 0; j < n; j++) {
                if (d[p][j] < d[i][j]) {
                    chmax(c[d[p][j]], (int)G[j].size() - 1);
                } else {
                    chmax(c[d[i][i]], (int)G[j].size() - 1);
                }
            }
            s = 1;
            for (int j = 0; j <= n; j++) {
                if (c[j] == 0) {
                    break;
                }
                s *= c[j];
            }
            chmin(res, s * 2);
        }
    }
    cout << (ma + 1) / 2 << " " << res << endl;
}

