vector<int> bfs(const vector<vector<int>> &G, int s, int t = -1) {
    vector<int> ret(G.size(),-1);
    ret[s] = 0;
    if (t != -1) ret[t] = 0;
    queue<int> que;
    que.emplace(s);
    if (t != -1) {
        ret[t] = 0;
        que.emplace(t);
    }
    while (!que.empty()) {
        int v = que.front(); que.pop();
        for (auto nv : G[v]) {
            if (ret[nv] != -1) continue;
            ret[nv] = ret[v] + 1;
            que.emplace(nv);
        }
    }

    return ret;
}

const int MAX = 100;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin >> N;
    vector<vector<int>> G(N);
    rep(i,N-1) {
        int u,v; cin >> u >> v;
        --u; --v;
        G[u].emplace_back(v);
        G[v].emplace_back(u);
    }

    auto f=[&](int v) {
        auto dist = bfs(G,v);
        int color = *max_element(all(dist));
        color++;
        vector<int> L(MAX);
        rep(i,N) {
            if (i==v) chmax(L[dist[i]],(int)G[i].size());
            else chmax(L[dist[i]],(int)G[i].size()-1);
        }
        ll ret = 1;
        rep(i,MAX) {
            if (L[i]) ret *= L[i];
        }
        return pll(color,ret);
    };
    auto g=[&](int u, int v) {
        auto dist = bfs(G,u,v);
        int color = *max_element(all(dist));
        color++;
        vector<int> L(MAX);
        rep(i,N) {
            chmax(L[dist[i]],(int)G[i].size()-1);
        }
        ll ret = 2;
        rep(i,MAX) {
            if (L[i]) ret *= L[i];
        }
        return pll(color,ret);
    };

    ll color = 1e18, ans = 1e18;
    rep(i,N) {
        ll c,a;
        tie(c,a) = f(i);
        if (color > c) {
            color = c;
            ans = a;
        } else if (color == c) {
            chmin(ans,a);
        }
    }
    rep(v,N) {
        for (auto nv : G[v]) {
            ll c,a;
            tie(c,a) = g(v,nv);
            if (color > c) {
                color = c;
                ans = a;
            } else if (color == c) {
                chmin(ans,a);
            }    
        }
    }

    cout << color << " " << ans << ln;
}

