//    cout << "max_deg: " << max_deg << endl;
    deg *= max_deg;


    vector<int> n_src;
    for (int i = 0; i < src.size(); ++i) {
      int u = src[i];
      for (int j = 0; j < e[u].size(); ++j) {
        int v = e[u][j];
        if (vis[v]) continue;
        n_src.push_back(v); 
      }
    }

    src = n_src;
  }

  return deg;
