// import here

void dfs(LL node, LL parent, vector<vector<LL>>& edge, vector<LL>& ref_cnt, vector<LL>& max_child, LL depth){
    max_child[depth] = max(max_child[depth], ref_cnt[node]-1);
    for(LL next: edge[node]){
        if(next == parent) continue;
        dfs(next, node, edge, ref_cnt, max_child, depth+1);
    }
}


pair<LL,LL> solve(LL root, vector<LL>& ref_cnt, vector<vector<LL>>& edge){
    LL n = edge.size();
    vector<LL> max_child(n+1);
    dfs(root, root, edge, ref_cnt, max_child, 0);
    max_child[0] = ref_cnt[root];
    //cerr << max_child << endl;

    LL total_leaf = 1;
    LL max_depth = 0;
    for(LL n_child: max_child){
        if(n_child <= 0) break;
        total_leaf *= n_child;
        max_depth += 1;
    }

    return pair<LL, LL>(max_depth+1, total_leaf);
}


pair<LL,LL> solve2(LL root1, LL root2, vector<LL>& ref_cnt, vector<vector<LL>>& edge){
    LL n = edge.size();
    vector<LL> max_child(n+1);
    dfs(root1, root2, edge, ref_cnt, max_child, 0);
    dfs(root2, root1, edge, ref_cnt, max_child, 0);
    max_child[0] = max(ref_cnt[root1]-1, ref_cnt[root2] - 1);
    //cerr << max_child << endl;

    LL total_leaf = 1;
    LL max_depth = 0;
    for(LL n_child: max_child){
        if(n_child <= 0) break;
        total_leaf *= n_child;
        max_depth += 1;
    }

    return pair<LL, LL>(max_depth+1, total_leaf*2);
}


