	for (int i=0;i<len/2;i++)
		if (maxson[i]) ret = ret * (ll)maxson[i];
	link(c1,c2);
	return ret * 2;
}

ll solve2(int c)
{
	find(c);
	memset(maxson,0,sizeof(maxson));
	for (int i=1;i<=n;i++)
	{
		if (!d[i]) continue;
		maxson[d[i]] = max(maxson[d[i]],son[i]);
	}
	ll ret = 1;
	for (int i=0;i<len/2;i++) 
