llint deg[105];

void dfs(llint v, llint prev, llint d)
{
	dep = max(dep, d);
	deg[d] = max(deg[d], (llint)G[v].size()-1);
	for(llint i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		dfs(G[v][i], v, d+1);
	}
}

