			E[a].push_back(b);
			E[b].push_back(a);
		}
		UL r = 0;
		vector<UL> D(N);
		{
			vector<UL> L(N); rep(i, N) L[i] = E[i].size() - 1;
			queue<UL> Q;  rep(i, N) if (L[i] == 0) Q.push(i);
			while (Q.size()) {
				UL p = Q.front(); Q.pop();
				r = max(r, D[p]);
				for (UL e : E[p]) {
					if (L[e] == 0) continue;
					D[e] = max(D[e], D[p] + 1);
					L[e]--;
					if (L[e] != 0) continue;
					Q.push(e);
