void calc_depths(vvi &tree, int loc, int par, int dep, vi &mc) {
    int nc = 0;
    for (int nbr : tree[loc]) {
        if (nbr != par) {
            nc++;
            calc_depths(tree, nbr, loc, dep+1, mc);
        }
    }

    if (nc) {
        while (mc.size() <= dep) mc.push_back(0);
        mc[dep] = max(mc[dep], nc);
    }
}

