  while(!q.empty()) {
    int curr = q.front();
    ret = depth[curr];
    q.pop();
    int dd = 0;
    for(int out: edges[curr]) {
      if(depth[out] == 1e9) {
        depth[out] = 1 + depth[curr];
        dd++;
        q.push(out);
      }
    }
    degAtDepth[depth[curr]] = max(degAtDepth[depth[curr]], dd);
  }
  return ret;
}

pll solveEdge(int a, int b) {
  init({a, b});
  int below = bfs();
  ll numLeaves = 2;
  for(int i = 0; i < below; i++) {
    numLeaves *= degAtDepth[i];
  }
  return {below+1, numLeaves};
}

pll solveCenter(int k) {
  if(edges[k].size() == 1) return {1e18, 1e18};
  init({k});
  int below = bfs();
  ll numLeaves = 1;
  for(int i = 0; i < below; i++) {
    numLeaves *= degAtDepth[i];
  }
  return {below+1, numLeaves};
}

void solve() {
  cin >> n;
  if(n == 2) {
    cout << "1 2\n";
    return;
  }
  for(int i = 1; i < n; i++) {
    int a, b;
    cin >> a >> b;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }
  pll ret = {1e18, 1e18};
  for(int i = 1; i <= n; i++) {
    ret = min(ret, solveCenter(i));
  }
  for(int i = 1; i <= n; i++) {
    for(int out: edges[i]) {
      ret = min(ret, solveEdge(i, out));
    }
  }
  cout << ret.first << " " << ret.second << "\n";
}

