int main() {
	const auto n = IO.input<uint32>();
	Graph G(n);
	for (const auto i : irange<>(1, n)) {
		uint32 a, b;
		IO >> a >> b;
		--a;
		--b;
		G[a].emplace_back(b);
		G[b].emplace_back(a);
	}
	std::vector<uint32> dist(n, 10000);
	std::function<void(uint32, uint32)> cho = [&](uint32 v, uint32 now) {
		++now;
		for (const auto e : G[v])
			if (smini(dist[e], now))
				cho(e, now);
	};
	dist[0] = 0;
	cho(0, 0);
	const uint32 left = std::max_element(dist.begin(), dist.end())-dist.begin();
	std::fill(dist.begin(), dist.end(), 10000);
	dist[left] = 0;
	cho(left, 0);
	const uint32 right = std::max_element(dist.begin(), dist.end()) - dist.begin();
	const uint32 ans = (dist[right] / 2) + 1;
	uint32 mid1 = 10000, mid2=10000;
	{
		std::vector<char> exi(n, 0);
		exi[right] = 1;
		std::function<void(uint32, uint32)> cho1 = [&](uint32 v, uint32 prev) {
			for (const auto e : G[v])
				if (e != prev)
					cho1(e, v), exi[v] |= exi[e];
		};
		cho1(left, n);
		for (const auto i : irange<>(0, n))
			if (exi[i] && (dist[i] == dist[right] / 2 || dist[i] == (dist[right] + 1) / 2))
				if (mid1 == 10000)
					mid1 = i;
				else
					mid2 = i;
	}
	uint64 ansmin = UINT64_MAX;
	if (mid2 == 10000) {
		std::vector<uint64> maxdeg(n, 0);
		std::function<void(uint32, uint32,uint32)> dfs = [&](uint32 v, uint32 prev,uint32 d) {
			uint64 cnt = 0;
			for (const auto e : G[v])
				if (e != prev)
					++cnt, dfs(e, v, d + 1);
			smaxi(maxdeg[d], cnt);
		};
		dfs(mid1, n, 0);
		uint32 itr = 0;
		uint64 cur = 1;
		while (maxdeg[itr] != 0)
			cur *= maxdeg[itr], ++itr;
		smini(ansmin, cur);
		for (const auto e : G[mid1]) {
			std::fill(maxdeg.begin(), maxdeg.end(), 0);
			dfs(mid1, e, 0);
			dfs(e, mid1, 0);
			itr = 0;
			cur = 2;
			while (maxdeg[itr] != 0)
				cur *= maxdeg[itr], ++itr;
			smini(ansmin, cur);
		}
	}
	else {
		std::vector<uint64> maxdeg(n, 0);
		std::function<void(uint32, uint32, uint32)> dfs = [&](uint32 v, uint32 prev, uint32 d) {
			uint64 cnt = 0;
			for (const auto e : G[v])
				if (e != prev)
					++cnt, dfs(e, v, d + 1);
			smaxi(maxdeg[d], cnt);
		};
		dfs(mid1, mid2, 0);
		dfs(mid2, mid1, 0);
		uint32 itr = 0;
		uint64 cur = 2;
		while (maxdeg[itr] != 0)
			cur *= maxdeg[itr], ++itr;
		smini(ansmin, cur);
	}
	IO << ans << " " << ansmin << "\n";
	return 0;
}

