{
	for(R int i=0;i<Edge[x].size();i++)
	{
		int y=Edge[x][i];
		if(y==fx) continue;
		son[x]++;
		dep[y]=dep[x]+1;
		dfs1(y,x);
	}
}

int md[MAXN];

inline void cal()
{
	int maxd=0;
	for(R int i=1;i<=n;i++) maxd=max(maxd,dep[i]);
	memset(md,0,sizeof(md));
	ll cnt=0;
	for(R int i=1;i<=n;i++)
	{
		md[dep[i]]=max(md[dep[i]],son[i]);
		if(dep[i]==1) cnt++;
	}
	for(R int i=1;i<maxd;i++) cnt=cnt*md[i];
	if(maxd<ans1) ans1=maxd,ans2=inf;
	if(maxd==ans1&&cnt<ans2) ans2=cnt;
}

inline void solve1() 
{
	for(R int i=1;i<=n;i++)
	{
		memset(son,0,sizeof(son));
		dep[i]=1;
		dfs1(i,0);
		cal();
	}
}

inline void dfs2(int x,int fx)
{
	for(R int i=0;i<Edge[x].size();i++)
	{
		int y=Edge[x][i];
		if(y==fx) continue;
		memset(son,0,sizeof(son));
		dep[x]=dep[y]=1;
		dfs1(x,y);dfs1(y,x);
		cal();
		dfs2(y,x);
	}
}

inline void solve2() { dfs2(1,0); }

inline void work() { solve1(); solve2();}

