using namespace std;

typedef long long ll;
typedef pair <int,int> pii;
typedef pair <ll,ll> pll;

typedef vector <int> VI;
typedef vector <bool> VB;
typedef vector <pii> VP;
typedef vector <ll> VL;
typedef vector <pll> VPL;

typedef vector <VI> VVI;
typedef vector <VL> VVL;
typedef vector <VB> VVB;
typedef vector <VP> VVP;

const int MOD = 1000000007;
const int INF = 1000000001;
const ll LINF = 1000000000000000001LL;

void dfs(int v, int par, VVI &g, int d, VI &minDegAt, VI &maxDegAt) {
    if (SIZE(maxDegAt) == d) {
        minDegAt.pb(INF);
        maxDegAt.pb(0);
    }

    int deg = SIZE(g[v]) - (par != -1);

    minDegAt[d] = min(minDegAt[d], deg);
    maxDegAt[d] = max(maxDegAt[d], deg);

    for (int u : g[v]) if (u != par) {
        dfs(u, v, g, d + 1, minDegAt, maxDegAt);
    }
}

pll solve(int root, int n, VP &edges) {
    VVI g(n);
    for (auto &e : edges) {
        int u, v;
        tie(u, v) = e;

        g[u].pb(v);
        g[v].pb(u);
    }

    VI minDegAt, maxDegAt;
    dfs(root, -1, g, 0, minDegAt, maxDegAt);

    ll depth = SIZE(maxDegAt);
    ll leaves = 1;

    minDegAt.pop_back();
    maxDegAt.pop_back();

    FORDE(i,maxDegAt) {
        leaves *= maxDegAt[i];
    }

    return {depth, leaves};
}

