using namespace std;
using ll = unsigned long long;

const int INF = 1 << 25;

struct Graph {
    Graph(int N) : size(N) { path.resize(N); };
    void span(int u, int v) { path[u].push_back(v); }
    vector<int> operator[](int v) { return path[v]; };

    int size;
    vector<vector<int>> path;
};

int N;
Graph tree(0);

vector<int> bfs(vector<int> rs) {
    vector<int> dist(N, INF);
    queue<int> que;

    for (int r : rs) {
        dist[r] = 0;
        que.push(r);
    }

    while (!que.empty()) {
        int v = que.front();
        que.pop();

        for (int sv : tree[v]) {
            if (dist[sv] <= dist[v]) continue;
            dist[sv] = dist[v] + 1;
            que.push(sv);
        }
    }
    return dist;
}

tuple<int, int, int> diameter() {
    auto dist = bfs({0});
    int l = max_element(dist.begin(), dist.end()) - dist.begin();
    dist = bfs({l});
    int r = max_element(dist.begin(), dist.end()) - dist.begin();
    return make_tuple(dist[r], l, r);
}

// centerを根としたとき、必要な葉の数
ll leaf_num(vector<int> center) {
    auto dist = bfs(center);
    vector<ll> hie(N, 0);
    // 各深さでの、子の数の最大値

    for (int v = 0; v < N; ++v) {
        ll cnt = 0;
        for (int sv : tree[v]) {
            if (dist[sv] > dist[v]) ++cnt;
        }
        hie[dist[v]] = max(hie[dist[v]], cnt);
    }

    ll ret = center.size();
    for (int d = 0; d < N; ++d) {
        if (hie[d] == 0) break;
        ret *= hie[d];
    }
    return ret;
}

int main() {
    cin >> N;

    tree = Graph(N);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        tree.span(u, v);
        tree.span(v, u);
    }

    int D, l, r;  // 直径とその両端点
    tie(D, l, r) = diameter();
    cout << D / 2 + 1 << " ";

    // 両端点の距離から木の中心を求める
    auto ldist = bfs({l}), rdist = bfs({r});
    vector<int> center;
    for (int v = 0; v < N; ++v) {
        if (ldist[v] + rdist[v] == D && abs(ldist[v] - rdist[v]) <= 1) center.push_back(v);
    }

    ll ans = leaf_num(center);
    if (center.size() == 1) {
        // 中心が2つになるようにすると葉の数が減ることがある
        int c = center[0];
        for (int sv : tree[c]) {
            ans = min(ans, leaf_num({c, sv}));
        }
    }

    cout << ans << endl;
    return 0;
}

