const int INF = 1e9 + 7;

int n;
vector<int> G[105];
int ms[105];

int dfs(int v, int par, int dep)
{
	int ret = 0;
	ms[dep] = max(ms[dep], int(G[v].size()) - (par >= 1 ? 1 : 0));
	rep(i, G[v].size()) {
		int u = G[v][i];
		if(u == par) continue;
		ret = max(ret, dfs(u, v, dep + 1));
	}
	return ret + 1;
}

pair<LL, LL> solve_tp1(int v)
{
	rep(i, n) ms[i] = 1LL;
	int md = dfs(v, -1, 0);
	pair<LL, LL> cur = MP(md, 1LL);
	rep(i, md) cur.second *= ms[i];
	return cur;
}

pair<LL, LL> solve_tp2(int u, int v)
{
	rep(i, n) ms[i] = 1LL;
	int md = max(dfs(v, u, 0), dfs(u, v, 0));
	pair<LL, LL> cur = MP(md, 2LL);
	rep(i, md) cur.second *= ms[i];
	return cur;
}

