void diameter(int s, int f, int d) {
    if(edge_count[s] == 1 && f != s) {
        if(max_di < d) {
            max_di = d;
            max_path = path;
        }
        return;
    }
    for(int n : edges[s]) {
        if(n != f) {
            path.push_back(n);
            diameter(n, s, d+1);
            path.pop_back();
        }
    }
}

void calc_height(int s, int f, int h) {
    if(height[s] != 0) return;
    height[s] = h;
    for(int n : edges[s]) {
        if(n != f) {
            calc_height(n, s, h-1);
        }
    }
}


