typedef long long ll;

const ll INF = 10000000000000000;

struct Graph
{
    int n;
    vector<vector<int>> g;

    Graph(int n) : n(n){
        g.resize(n);
    }

    void init(int n_){
        n = n_;
        g.resize(n_);
    }

    void add_edge(int from, int to){
        g[from].push_back(to);
    }
};

struct Tree	//create tree(directed) from graph(undirected)
{
    int n;
    int root;
    int root2;
    vector<vector<int>> t;
    vector<int> par;
    vector<int> dpt;

    void init(Graph &g, int root_, int root2_ = -1){
        n = g.n;
        root = root_;
        root2 = root2_;
        t.resize(n);
        par.resize(n);
        dpt.resize(n);
        fill(dpt.begin(), dpt.end(), -1);
        queue<int> que;
        par[root] = -1;
        dpt[root] = 0;
        que.push(root);
        if(root2 != -1){
            par[root2] = -1;
            dpt[root2] = 0;
            que.push(root2);
        }
        while(que.size()){
            int pa = que.front();
            que.pop();
            for(int ch : g.g[pa]){
                if(dpt[ch] == -1){
                    t[pa].push_back(ch);
                    par[ch] = pa;
                    dpt[ch] = dpt[pa] + 1;
                    que.push(ch);
                }
            }
        }
    }

    Tree(){}

    Tree(Graph &g, int root_, int root2_ = -1){
        init(g, root_, root2_);
    }
};

