                int u = que[d % 2].front();
                que[d % 2].pop();
                r = max(r, (ll)t.t[u].size());
                for(int v : t.t[u]) que[(d + 1) % 2].push(v);
            }
            d++;
            if(r == 0) break;
            s *= r;
        }
        if(d == ans) l = min(l, s);
        if(d < ans) ans = d, l = s;
    }
    for(int i = 0; i < n - 1; i++){
