#include <bits/stdc++.h>
using namespace std;

int N;
#define MAXN 100
vector<int> A[MAXN];
int S, T, D, R;
int DS[MAXN], DT[MAXN];
int B[MAXN];
long long X;

pair<int, int> farthest(int v, int par) {
  pair<int, int> res = {0, v};
  for(int w : A[v]) {
    if(w == par) continue;
    auto q = farthest(w, v);
    res = max(res, {q.first + 1, q.second});
  }
  return res;
}
void dist(int d, int v, int par, int ds[MAXN]) {
  ds[v] = d;
  for(int w : A[v]) {
    if(w == par) continue;
    dist(d + 1, w, v, ds);
  }
}
void branch(int d, int v, int par) {
  B[d] = max(B[d], (int)A[v].size() - (par != -1));
  for(int w : A[v]) {
    if(w == par) continue;
    branch(d + 1, w, v);
  }
}
long long calc() {
  long long res = 1;
  for(int d = 0; d < R; ++d) {
    res *= B[d];
  }
  return res;
}

int main() {
  cin >> N;
  for(int i = 0; i < N - 1; ++i) {
    int a, b; cin >> a >> b; --a; --b;
    A[a].push_back(b); A[b].push_back(a);
  }
  S = farthest(0, -1).second;
  auto p = farthest(S, -1);
  T = p.second; D = p.first; R = D / 2;
  cout << R + 1 << " ";
  dist(0, S, -1, DS); dist(0, T, -1, DT);
  if(D % 2 == 0) {
    int c;
    for(int v = 0; v < N; ++v) {
      if(DS[v] == R && DT[v] == R) c = v;
    }
    branch(0, c, -1);
    long long res = calc();
    for(int cx : A[c]) {
      fill(B, B + R, 0);
      branch(0, c, cx); branch(0, cx, c);
      res = min(res, 2 * calc());
    }
    cout << res << endl;
  } else {
    int c0, c1;
    for(int v = 0; v < N; ++v) {
      if(DS[v] == R + 1 && DT[v] == R) c0 = v;
      if(DS[v] == R && DT[v] == R + 1) c1 = v;
    }
    branch(0, c0, c1); branch(0, c1, c0);
    cout << 2 * calc() << endl;
  }
  return 0;
}

