void solve() {
  for (int root = 0; root < n; ++root) {
    vector<int> dist(n, -1);
    vector<int> cnt(n, 0);
    queue<int> qu;
    P np(0, 1);
    dist[root] = 0;
    cnt[0] = g[root].size();
    qu.push(root);
    while (qu.size()) {
      int now = qu.front();
      qu.pop();
      cnt[dist[now]] = max(cnt[dist[now]], (int)g[now].size() - 1);
      np.first = dist[now] + 1;
      for (auto to : g[now])
        if (dist[to] == -1) {
          dist[to] = dist[now] + 1;
          qu.push(to);
        }
    }
    for (int i = np.first - 2; i >= 0; --i) {
      long long tmp = np.second * cnt[i];
      if (tmp < np.second || tmp >= inf) tmp = inf;
      np.second = tmp;
    }
    res = min(res, np);
  }
  for (int r1 = 0; r1 < n; ++r1)
    for (auto r2 : g[r1]) {
      vector<int> dist(n, -1);
      vector<int> cnt(n, 0);
      queue<int> qu;
      P np(0, 2);
      dist[r1] = dist[r2] = 0;
      qu.push(r1);
      qu.push(r2);
