        int now = qu.front();
        qu.pop();
        cnt[dist[now]] = max(cnt[dist[now]], (int)g[now].size() - 1);
        np.first = dist[now] + 1;
        for (auto to : g[now])
          if (dist[to] == -1) {
            dist[to] = dist[now] + 1;
            qu.push(to);
          }
      }
      for (int i = np.first - 2; i >= 0; --i) {
        long long tmp = np.second * cnt[i];
        if (tmp < np.second || tmp >= inf) tmp = inf;
        np.second = tmp;
      }
      res = min(res, np);
    }
}

