using namespace std;

int main() {
    int n; cin >> n;
    vector<vector<int> > adj(n);
    for (int i = 1; i < n; i++) {
        int u, v; cin >> u >> v;
        u--; v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    function<void(int, int, int, int*)> calc_depth = [&](int i, int p, int d, int *tbl) {
        tbl[i] = d;
        for (int j : adj[i]) {
            if (j != p) calc_depth(j, i, d+1, tbl);
        }
    };
    const int diam = [&]() {
        int depth[n];
        calc_depth(0, -1, 0, depth);
        int v = max_element(depth, depth+n) - depth;
        calc_depth(v, -1, 0, depth);
        return *max_element(depth, depth+n);
    }();
    const int mincol = diam / 2 + 1;
    long long ans = LONG_MAX;
    function<void(int, int, int, int*)> dfs = [&](int i, int p, int h, int *g) {
        int deg = p == -1 ? adj[i].size() : adj[i].size() - 1;
        g[h] = max(g[h], deg);
        for (int j : adj[i]) if (j != p) dfs(j, i, h+1, g);
    };
    for (int u = 0; u < n; u++) {
        // center = u
        int g[n], depth[n];
        fill(g, g+n, 0);
        calc_depth(u, -1, 0, depth);
        int maxd = *max_element(depth, depth+n);
        if (mincol == maxd + 1) {
            dfs(u, -1, 0, g);
            long long temp = 1;
            for (int i = 0; g[i] > 0; i++) temp *= g[i];
            ans = min(ans, temp);
            // cerr << u << ' ' << temp << endl;
        }
        for (int v : adj[u]) {
            // center u-v
            calc_depth(u, v, 0, depth);
            calc_depth(v, u, 0, depth);
            int maxd = *max_element(depth, depth+n);
            if (mincol == maxd + 1) {
                fill(g, g+n, 0);
                dfs(u, v, 0, g);
                dfs(v, u, 0, g);
                long long temp = 2;
                for (int i = 0; g[i] > 0; i++) temp *= g[i];
                ans = min(ans, temp);
                //cerr << u << ' ' << v << ' ' << temp << endl;
            }
        }
    }
    cout << mincol << ' ' << ans << endl;
}

