using namespace std;
typedef long long ll;
struct edge{
	int to, nxt;
}e[100005];
int h[100005], cnt; 
void addedge(int x, int y){
	cnt++; e[cnt].to = y; e[cnt].nxt = h[x]; h[x] = cnt;
	cnt++; e[cnt].to = x; e[cnt].nxt = h[y]; h[y] = cnt;
}
int dep[100005], mx[100005], m1;
void dfs(int x, int fa){
	dep[x] = dep[fa] + 1; m1 = max(m1, dep[x]);
	int ct = 0;
	for(int i = h[x]; i; i = e[i].nxt){
		if(e[i].to == fa) continue;
		ct ++;
		dfs(e[i].to, x);
	}
	mx[dep[x]] = max(mx[dep[x]], ct);
}

void dfs(int x, int cc, int fa){
	dep[x] = dep[fa] + 1; m1 = max(m1, dep[x]);
	int ct = 0;
	for(int i = h[x]; i; i = e[i].nxt){
		if(e[i].to == fa || e[i].to == cc) continue;
		ct ++;
		dfs(e[i].to, cc, x);
	}
	mx[dep[x]] = max(mx[dep[x]], ct);
}

