pair<ll, ll> solve(vector<vector<ll>> g, ll N, ll x, ll y) {
	vector<ll> col(N + 1,-1);
	col[x] = 1;
	col[y] = 1;
	queue<ll> q;
	q.push(x);
	q.push(y);

	ll ret1 = 1;

	while (!q.empty()) {
		ll v = q.front();
		q.pop();

		for (ll w : g[v]) {
			if (col[w] != -1) { continue; }
			col[w] = col[v] + 1;
			q.push(w);

			ret1 = max(ret1, col[w]);
		}
	}

	vector<ll> out(ret1 + 1,0);
	repn(v, N) {
		ll i = 0;
		for (ll w : g[v]) {
			if (col[w] > col[v]) { i++; }
		}

		out[col[v]] = max(out[col[v]], i);
	}

	ll ret2 = 1;
	if (x != y) { ret2 = 2; }
	repn(i, ret1 - 1) { ret2 *= out[i]; }

	return{ ret1,ret2 };
}



int main() {
	ll N;
	cin >> N;

	vector<vector<ll>> g;
	g.resize(N + 1);
	repn(i, N - 1) {
		ll a, b;
		cin >> a >> b;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	pair<ll, ll> ans = { INF,INF };

	repn(v, N) {
		ans = min(ans, solve(g, N, v, v));

		for (ll w : g[v]) {
			ans = min(ans, solve(g, N, v, w));
		}
	}

	cout << ans.first << " " << ans.second << endl;


	system("PAUSE");
}

