void bfs(int rt,int rt2) {
	memset(vis,0,sizeof(vis));
	memset(sz,0,sizeof(sz));
	queue<int> que;
	vis[rt]=1;
	d[rt]=0;
	fa[rt]=0;
	que.push(rt);
	if(rt2) {
		vis[rt2]=1;
		d[rt2]=0;
		fa[rt2]=0;
		que.push(rt2);
	}
	while(!que.empty()) {
		u=que.front();que.pop();
		for(int i=0;i<gg[u].size();i++) {
			v=gg[u][i];
			if(vis[v]) continue;
			d[v]=d[u]+1;
			vis[v]=1;
			fa[v]=u;
			sz[u]++;
			que.push(v);
		}
	}
}

int go_up(int u,int t) {
	while(t--) {
		u=fa[u];
	}
	return u;
}

LL cal(int u,int v) {
	bfs(u,v);
	memset(c,0,sizeof(c));
	for(int i=1;i<=n;i++) {
		c[d[i]+1]=max(c[d[i]+1],sz[i]);
	}
	LL res=1;
	c[0]=(v==0)?1:2;
	for(int i=0;i<=n;i++) {
		if(c[i]>0) res*=c[i];
	}
	return res;
}

