typedef long long int int64;


typedef long long ll;
const int BASE = 100000000;

struct BigInt
{
	vector <int> a;
	BigInt () : a() {}
	BigInt (ll x)
	{
		if (x == 0)
			a.push_back(0);
		while (x > 0)
		{
			a.push_back(x % BASE);
			x /= BASE;
		}
	}
	BigInt (int x)
	{
		if (x == 0)
			a.push_back(0);
		while (x > 0)
		{
			a.push_back(x % BASE);
			x /= BASE;
		}
	}
	BigInt operator * (int x)
	{
		BigInt res = BigInt();
		ll z = 0;
		for (int i = 0; i < (int)a.size() || z; i++)
		{
			res.a.push_back(0);
			ll nVal = z + (ll)(i < (int)a.size() ? a[i] : 0) * x;
			z = nVal / BASE;
			res.a[i] = nVal % BASE;
		}
		return res;
	}
	BigInt operator + (const BigInt &x)
	{
		BigInt res = BigInt();
		int z = 0;
		int mx = max((int)x.a.size(), (int)a.size());
		for (int i = 0; i < mx || z; i++)
		{
			if ((int)res.a.size() == i)
				res.a.push_back(0);
			res.a[i] = (i < (int)a.size() ? a[i] : 0) + (i < (int)x.a.size() ? x.a[i] : 0) + z;
			if (res.a[i] >= BASE)
			{
				z = 1;
				res.a[i] -= BASE;
			}
			else
				z = 0;
		}
		return res;
	}
	BigInt operator * (const BigInt &x)
	{
		BigInt res = BigInt();
		for (int i = 0; i < (int)a.size(); i++)
		{
			int z = 0;
			for (int s = 0; s < (int)x.a.size() || z; s++)
			{
				if (i + s == (int)res.a.size())
					res.a.push_back(0);
				ll curAdd = (ll)a[i] * (s < (int)x.a.size() ? x.a[s] : 0) + z;
				ll nVal = (curAdd + res.a[i + s]);
				z = nVal / BASE;
				res.a[i + s] = nVal % BASE;
			}
		}
		return res;
	}
	BigInt operator / (int x)
	{
		BigInt res = BigInt();
		res.a.resize(a.size());
		ll z = 0;
		for (int i = (int)a.size() - 1; i >= 0; i--)
		{
			res.a[i] = (a[i] + z * BASE) / x;
			z = (a[i] + z * BASE) % x;
		}
		while (res.a.back() == 0 && res.a.size() > 1)
			res.a.pop_back();
		return res;
	}
	BigInt div2()
	{
		BigInt res = BigInt();
		res.a.resize(a.size());
		int z = 0;
		for (int i = (int)a.size() - 1; i >= 0; i--)
		{
			res.a[i] = (z + a[i]) / 2;
			z = BASE * ((z + a[i]) & 1);
		}
		while (res.a.back() == 0 && res.a.size() > 1)
			res.a.pop_back();
		return res;
	}
	BigInt operator / (const BigInt &x)
	{
		BigInt l = BigInt(0);
		BigInt r = *this;
		BigInt one = BigInt(1);
		while (r - l > one)
		{
			BigInt m = (l + r).div2();
			if (m * x > *this)
				r = m;
			else
				l = m;
		}
		return l;
	}
	BigInt operator - (const BigInt &x)
	{
		BigInt res = BigInt();
		int z = 0;
		for (int i = 0; i < (int)a.size(); i++)
		{
			res.a.push_back(0);
			res.a[i] = a[i] - (i < (int)x.a.size() ? x.a[i] : 0) - z;
			if (res.a[i] < 0)
			{
				res.a[i] += BASE;
				z = 1;
			}
			else
				z = 0;
		}
		while (res.a.back() == 0 && res.a.size() > 1)
			res.a.pop_back();
		return res;
	}
	bool operator > (const BigInt &x) const
	{
		return x < *this;
	}
	bool operator < (const BigInt &x) const
	{
		if (a.size() != x.a.size())
			return a.size() < x.a.size();
		for (int i = (int)a.size() - 1; i >= 0; i--)
		{
			if (a[i] != x.a[i])
				return a[i] < x.a[i];
		}
		return false;
	}
	void print()
	{
		printf("%d", a[(int)a.size() - 1]);
		for (int i = (int)a.size() - 2; i >= 0; i--)
			printf("%08d", a[i]);
	}
};

BigInt myPow(BigInt a, int k)
{
	if (k == 0)
		return BigInt(1);
	if (k & 1)
		return myPow(a, k - 1) * a;
	else
	{
		BigInt t = myPow(a, k / 2);
		return t * t;
	}
}

const int N = 105;
