void dfs(int v, int p, int cd)
{
    par[v] = p;
    d[v] = cd;
    for (int to : g[v] )
    {
        if (to == p) continue;
        dfs(to, v, cd + 1);
    }
}

BigInt solve(vector <int> v, BigInt cnt)
{
 //   eprintf("----\n");
    vector <int> nv;
    int mx = 0;
    for (int x : v)
    {
        int cur = 0;
        for (int nx : g[x] )
        {
//            eprintf("%d -> %d\n", x, nx);
            if (nx == par[x] ) continue;
            cur++;
            nv.push_back(nx);
        }
        mx = max(mx, cur);
    }
    if (mx == 0) return BigInt(cnt);
    return solve(nv, cnt * BigInt(mx) );
}

