cat solve(auto & G, int col_min) {
	int N = G.size();
	int r[4];
	vector<int> dep[3];
	r[0] = 0;
	for(int k = 0; k < 3; k++) {
		dep[k].resize(N, -1);
		dep[k][r[k]] = 0;
		DFS(r[k], G, dep[k]);
		r[k+1] = -1;
		for(int i = 0; i < N; i++)
			if(r[k+1] == -1 || dep[k][i] > dep[k][r[k+1]]) r[k+1] = i;
	}
	if(col_min != dep[2][r[3]] / 2 + 1) return -1;
	int R = 0;
	for(int i = 0; i < N; i++) if(dep[2][i]+dep[1][i] == dep[2][r[3]])
		if(abs(dep[2][i]-dep[1][i]) <= 1) R = i;

	if(dep[2][r[3]]&1) {
		G.push_back(vector<int>(2));
		ALL_THE(G[R], it) if(dep[2][*it]+dep[1][*it] == dep[2][r[3]]) {
			if(abs(dep[2][*it]-dep[1][*it]) > 1) continue;
			G[N][0] = R;
			G[N][1] = *it;
			ALL_THE(G[*it], jt) if(*jt == R) {
				G[*it].erase(jt);
				break;
			}
			G[R].erase(it);
			break;
		}
		G[G[N][0]].push_back(N);
		G[G[N][1]].push_back(N);
		R = N;
		N++;
	}

	vector<int> depR(N, -1);
	depR[R] = 0;
	DFS(R, G, depR);

	vector<int> maxdeg(N+1, 0);
	for(int i = 0; i < N; i++) {
		if(i == R) maxdeg[depR[i]] = max(maxdeg[depR[i]], (int)G[i].size());
		else maxdeg[depR[i]] = max(maxdeg[depR[i]], (int)G[i].size() - 1);
	}

	unsigned long long ans = 1;
	for(int i = 0; i <= N; i++) if(maxdeg[i] > 0) {
		if(ans > ((1ULL<<63) - 1) / maxdeg[i]) return -1;
		ans *= (unsigned long long) maxdeg[i];
	}
//	cout << ans << "\n";
	return ans;
}

