int depth(int now, int prev, const vvi &g) {
  int ma = 0;
  for(auto &nxt: g[now]) {
    if(nxt == prev) continue;
    int res = depth(nxt, now, g);
    chmax(ma, res+1);
  }
  return ma;
}

void sch(int now, int prev, int depth, const vi &d, const vvi &g, vi &dma) {
  if(depth == 0) dma[0] = d[now];
  else chmax(dma[depth], d[now]-1);
  for(auto nxt: g[now]) {
    if(nxt == prev) continue;
    sch(nxt, now, depth+1, d, g, dma);
  }
}


