template<class T1, class T2> inline bool cmin(T1 &a, const T2 &b) {return b<a?(a=b, true):false;}
template<class T1, class T2> inline bool cmax(T1 &a, const T2 &b) {return a<b?(a=b, true):false;}
template<class Type> Type read() {
	Type a;
	bool b;
	unsigned char c;
	while(c=getchar()-48, (c>9)&(c!=253));
	for(a=(b=c==253)?0:c; (c=getchar()-48)<=9; a=a*10+c);
	return b?-a:a;
}
int (*rd)()=read<int>;

const int N=111;
int n, from[N], dis[N], maxdeg[N], queue[N], *qhead, *qtail;
std::vector<int> e[N];
int bfs(int src) {
	qhead=qtail=queue;
	memset(from+1, 0, n*sizeof(int));
	from[*qtail++=src]=-1;
	while(qhead!=qtail) {
		int u=*qhead++;
		for(int v: e[u]) if(from[v]==0) from[*qtail++=v]=u;
	}
	return qtail[-1];
}
s64 solve(int src1, int src2=-1) {
	s64 res=1;
	int maxdis;
	memset(dis+1, -1, n*sizeof(int));
	qhead=qtail=queue;
	dis[*qtail++=src1]=0;
	if(src2!=-1) dis[*qtail++=src2]=0;
	while(qhead!=qtail) {
		int u=*qhead++;
		for(int v: e[u]) if(dis[v]==-1) dis[*qtail++=v]=dis[u]+1;
	}
	maxdis=dis[qtail[-1]];
	memset(maxdeg, 0, (maxdis+1)*sizeof(int));
	for(int i=1; i<=n; ++i) cmax(maxdeg[dis[i]], e[i].size());
	if(src2==-1) ++maxdeg[0]; else ++res;
	for(int i=0; i<maxdis; ++i) res*=maxdeg[i]-1;
	return res;
}
int main() {
	s64 minleaf;
	std::vector<int> dia;
	n=rd();
	for(int i=1; i<n; ++i) {
		int a=rd(), b=rd();
		e[a].push_back(b);
		e[b].push_back(a);
	}
	for(int i=bfs(bfs(1)); i!=-1; i=from[i]) dia.push_back(i);
	if(dia.size()%2==0) {
		minleaf=solve(dia[dia.size()/2-1], dia[dia.size()/2]);
	} else {
		int u=dia[dia.size()/2];
		minleaf=solve(u);
		for(int v: e[u]) cmin(minleaf, solve(u, v));
	}
	printf("%d %lld\n", (int)(dia.size()+1)/2, minleaf);
	return 0;
}

