template<typename Cost>
std::vector<std::size_t> diameter(const cost_tree<Cost>& tree)
{
    const std::size_t sz = tree.size();
    std::vector<Cost> dist(sz, 0);
    std::vector<std::size_t> p(sz, sz);
    auto dfs = [&](auto&& self, const std::size_t s, const std::size_t prev) -> void {
        for (const auto& e : tree[s]) {
            if (e.to == prev) { continue; }
            dist[e.to] = dist[s] + e.cost, p[e.to] = s;
            self(self, e.to, s);
        }
    };
    dfs(dfs, 0, sz);
    std::size_t r = std::max_element(dist.begin(), dist.end()) - dist.begin();
    dist[r]       = 0, std::fill(p.begin(), p.end(), sz), dfs(dfs, r, sz);
    r             = std::max_element(dist.begin(), dist.end()) - dist.begin();
    std::vector<std::size_t> ans;
    for (; r != sz; r = p[r]) { ans.push_back(r); }
    return ans;
}
