        g.add_edge(n + i, u, true), g.add_edge(n + i, v, true);
    }
    const auto ds = diameter(g);
    usize c       = ds[ds.size() / 2];
    using pii     = std::pair<usize, ull>;
    pii min{inf_v<usize>, inf_v<ull>};
    auto f = [&](const usize c) {
        std::vector<ull> dmax(2 * n - 1, 1);
        usize dM = 0;
        auto dfs = [&, n](auto&& self, const usize s, const usize p, const usize d) -> void {
            chmax(dM, d), chmax(dmax[d], (ull)g[s].size() - (p == 2 * n - 1 ? 0 : 1));
            for (const usize to : g[s]) {
                if (to == p) { continue; }
                self(self, to, s, d + 1);
            }
        };
        dfs(dfs, c, 2 * n - 1, 0);
        ull ans = 1;
        for (usize i = 0; i < 2 * n - 1; i++) { ans *= dmax[i]; }
        chmin(min, {dM / 2 + 1, ans});
    };
    f(c);
    for (const usize to : g[c]) { f(to); }
    std::cout << min.first << " " << min.second << std::endl;
    return 0;
}

