const int base = 999983, mod = 1013095777;

pair<lint, lint> solve(int n, bool center_edge) {
  lint result_a = 0, result_b = center_edge ? 2 : 1;

  vector<pair<int, int>> dist_and_node(n);
  for (int i = 0; i < n; ++i)
    dist_and_node[i] = make_pair(dist[i], i);
  sort(dist_and_node.begin(), dist_and_node.end(), greater<pair<int, int>>());
  for (int j = 0, i = j; i < n; i = j) {
    while (j < n && dist_and_node[j].first == dist_and_node[i].first) ++j;

    ++result_a;

    int max_children_count = 0;
    for (int k = i; k < j; ++k) {
      int v = dist_and_node[k].second;
      int children_count = 0;
      for (int u : adj[v])
        if (dist[u] > dist[v])
          ++children_count;
      max_children_count = max(max_children_count, children_count);
    }

    if (max_children_count > 1) {
      if (max_children_count > LLONG_MAX / result_b)
        result_b = LLONG_MAX;
      else
        result_b *= max_children_count;
    }
  }

  return {result_a, result_b};
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    scanf("%d %d", &a, &b), --a, --b;
    adj[a].push_back(b);
    adj[b].push_back(a);
  }
  int diam_a;
  tie(ignore, diam_a) = dfs(0, -1, 0);
  int diam, diam_b;
  tie(diam, diam_b) = dfs(diam_a, -1, 0);
  pair<lint, lint> result;
  if (diam % 2 == 0) {
    int center = diam_b;
    for (int rep = 0; rep < diam / 2; ++rep)
      center = parent[center];
    dfs(center, -1, 0);
    result = solve(n, false);
    for (int u : adj[center]) {
      dfs(u, center, 0);
      dfs(center, u, 0);
      result = min(result, solve(n, true));
    }
  } else {
    int center_b = diam_b;
    for (int rep = 0; rep < (diam - 1) / 2; ++rep)
      center_b = parent[center_b];
    int center_a = parent[center_b];
    dfs(center_a, center_b, 0);
    dfs(center_b, center_a, 0);
    result = solve(n, true);
  }
  printf("%lld %lld\n", result.first, result.second);
  return 0;
}

