}edge[202020];
unsigned long long ans=-1;
void getmin(unsigned long long &now,unsigned long long v)
{
	if(now==-1)
		now=v;
	else
		now=min(now,v);
}
int first[101010],now;
void adde(int x,int y)
{
	now++;
	edge[now].to=y;
	edge[now].next=first[x];
	first[x]=now;
}
int dis[111];
int ma;
int fa1[111];
void work(int p,int fa)
{
	fa1[p]=fa;
	if(dis[p]>dis[ma])
		ma=p;
	for(int e=first[p];e;e=edge[e].next)
		if(edge[e].to!=fa)
		{
			dis[edge[e].to]=dis[p]+1;
			work(edge[e].to,p);
		}
}
int q[101010],qn;
void work1(int p)
{
	qn=0;
	while(p)
	{
		q[++qn]=p;
		p=fa1[p];
	}
}
int cnt[111];
int p1,p2;
void work2(int p,int fa)
{
	int nc=0;
	for(int e=first[p];e;e=edge[e].next)
		if(edge[e].to!=fa)
		{
			if(p==p1&&edge[e].to==p2)
				continue;
			if(p==p2&&edge[e].to==p1)
				continue;
			nc++;
			dis[edge[e].to]=dis[p]+1;
			work2(edge[e].to,p);
		}
	cnt[dis[p]]=max(cnt[dis[p]],nc);
}
int rt;
int ans1;
int tt;
void work3(int pp1,int pp2)
{
	p1=pp1;
	p2=pp2;
	first[rt]=0;
	adde(rt,p1);
	adde(rt,p2);
	dis[rt]=0;
	memset(cnt,0,sizeof(cnt));
	unsigned long long nans=1;
	work2(rt,0);
	for(int i=0;i<=ans1;i++)
		if(cnt[i])
			nans*=cnt[i];
	getmin(ans,nans);
}
int main()
{
	int n,x,y,mid;
	scanf("%d",&n);
	memset(first,0,sizeof(first));
	now=0;
	for(int i=1;i<n;i++)
	{
		scanf("%d%d",&x,&y);
		adde(x,y);
		adde(y,x);
	}
	dis[1]=0;
	ma=1;
	work(1,0);
	rt=ma;
	dis[rt]=0;
	work(rt,0);
	ans1=(dis[ma]+2)/2;
	work1(ma);
	rt=n+1;
	if(dis[ma]&1)
	{
		rt=n+1;
		work3(q[dis[ma]/2],q[dis[ma]/2+1]);
	}
	else
	{
		int h=q[dis[ma]/2+1];
		memset(cnt,0,sizeof(cnt));
		unsigned long long nans=1;
		dis[h]=0;
		work2(h,0);
		for(int i=0;i<=ans1;i++)
			if(cnt[i])
				nans*=cnt[i];
		getmin(ans,nans);
		for(int e=first[h];e;e=edge[e].next)
			work3(h,edge[e].to);
	}
	printf("%d %llu",ans1,ans);
	return 0;
}

