ll dfs1(ll w,ll p){
    ll ret=1;
    for(auto &I:edge[w]){
        if(I!=p){
            ret=max(ret,dfs1(I,w)+1);
        }
    }
    mx[w]=ret;
    return ret;
}

void dfs2(ll w,ll p,ll pn){
    pn++;
    mx[w]=max(mx[w],pn);
    pll mx1={pn,p};
    pll mx2={1,w};
    if(mx1<mx2){swap(mx1,mx2);}
    for(auto &I:edge[w]){
        if(I!=p){
            if(mx2<pll(mx[I]+1,I)){mx2={mx[I]+1,I};}
            if(mx2>mx1){swap(mx2,mx1);}
        }
    }
    for(auto &I:edge[w]){
        if(I!=p){
            if(I==mx1.S){dfs2(I,w,mx2.F);}
            else{dfs2(I,w,mx1.F);}
        }
    }
}

vector<vector<ll>> dp;

void dfs3(ll w,ll p,ll root,ll d){
    if(dp[root].size()==d){dp[root].push_back(1);}
    ll ch=0;
    for(auto &I:edge[w]){
        if(I!=p){
