using namespace std;

const int MaxN = 2e4 + 15;
const int MOD = 1e9 + 7;
const long long INF = 1e18;

int d[MaxN];
int parent[MaxN];
vector <int> v[MaxN];

int n;

void dfs(int x, int y, int p, int & r)
{
    d[x] = y;
    parent[x] = p;

    if(y > d[r])
        r = x;

    for(int to : v[x])
        if(to != p)
            dfs(to, y + 1, x, r);
}

vector <int> bfs[MaxN];

int end1, end2, dd;

 long long ans = 0;

 long long solve()
{
    memset(d, 0, sizeof(d));
    memset(parent, 0, sizeof(parent));
    for(int i = 0; i < MaxN ; ++i)
        bfs[i].clear();

    end1 = end2 = dd = 0;


    dfs(rand() % n + 1, 1, 0, end1);

    memset(d, 0, sizeof(d));
    memset(parent, 0, sizeof(parent));
    for(int i = 0; i < MaxN ; ++i)
        bfs[i].clear();

    dfs(end1, 1, 0, end2);

    dd = d[end2];

    if(!ans)
        ans = dd / 2 + dd % 2;
    else
        if(ans != dd / 2 + dd % 2)
            return 0;

    int x = end2;

    for(int i = 1; i < dd / 2 + dd % 2; ++i)
    {
        x = parent[x];
    }

    long long add = 0;

    for(int i = 1; i <= n; ++i)
        d[i] = MOD;

    bfs[0].push_back(x);
    d[x] = 0;

    if(dd % 2 == 0)
    {
        bfs[0].push_back(parent[x]);
        d[parent[x]] = 0;
    }

    int cntLast = 0;

    for(int step = 0; !bfs[step].empty(); ++step)
    {
        int mx = 0;

        long long sumCnt = 0;

        for(int x : bfs[step])
        {
            int cnt = 0;

            for(int to : v[x])
                if(d[to] == MOD)
                {
                    d[to] = d[x] + 1;
                    bfs[step + 1].push_back(to);
                    ++cnt;
                }

            mx = max(mx, cnt);
            sumCnt += cnt;
        }

        long long allCount = (bfs[step].size() + add) * mx;

        if(mx)
        {
            add = allCount - sumCnt;
        }
        cntLast = bfs[step].size();
    }

    return cntLast + add;
}

