int dfs(int v, int par) {
    int res = 0;
    for (int to : g[v]) if (to != par) {
        res = max(res, dfs(to, v) + 1);
    }
    return res;
}

vector<int> mx;

void solve(int v, int par, int dist) {
    int cnt = 0;
    for (int to : g[v]) if (to != par) {
        ++cnt;
        solve(to, v, dist + 1);
    }
    mx[dist] = max(mx, cnt);
}

pair<int, LL> solve() {
    vector<int> cand;
    int mx = 0;
    forn(i, n) {
        int cur = dfs(i, -1);
        if (cur > mx) {
            mx = cur;
            cand.clear();
        }
        if (cur == mx) {
            cand.pb(i);
        }
    }
    assert((int)cand.size() == 1 || (int)cand.size() == 2);
    mx.assign(101, 0);
    int sz = cand.size();
    forn(i, sz) {
        solve(cand[i], (sz == 1 ? -1 : cand[i ^ 1]), 0);
    }
    int res1 = 0;
    LL res2 = 1;
    forn(i, 101) if (mx[i] > 0) {
        res1++;
        res2 *= mx[i];
    }
    return mp(res1, res2);
}

