        g[from].pb(to);
        g[to].pb(from);
    }
    auto ans = solve();
    ++n;
    forn(i, n - 1) {
        g[i].pb(n - 1);
        g[n - 1].pb(i);
        ans = min(ans, solve());
        g[i].pop_back();
        g[n - 1].pop_back();
    }
    cout << ans.first << ' ' << ans.second << endl;
    return 0;
}

