typedef long long  LL;
struct edge{int s,t,n;}e[205];
int n,S,T,h[105],f[105],dep[105],ans1;
LL ans2;
vector <int> V[105];

void dfs(int x,int fa)
{
	f[x]=fa,dep[x]=dep[fa]+1;
	for (int i=h[x],y; y=e[i].t,i; i=e[i].n)
		if (y!=fa)  dfs(y,x);
}

LL calc()
{
	int md=0;  LL res=1;
	for (int i=1; i<=n; i++)  md=max(md,dep[i]);
	for (int i=1; i<=md; i++)  V[i].clear();
	for (int i=1; i<=n; i++)  V[dep[i]].push_back(i);
	for (int i=md-1,mx,cnt; i; i--)
		{
			mx=0;
			for (auto x:V[i])
				{
					cnt=0;
					for (int j=h[x],y; y=e[j].t,j; j=e[j].n)
						if (dep[y]==dep[x]+1)  cnt++;
					mx=max(mx,cnt);
				}
			res*=mx;
		}
	return res;
}

LL calc(int x)
{
	dfs(x,0);
	return calc();
}

LL calc(int x,int y)
{
	dep[x]=0,dfs(y,x),dep[y]=0,dfs(x,y),dep[y]=1;
	return calc()*2;
}

void work()
{
	scanf("%d",&n);
	for (int i=1,u,v,tot=0; i<n; i++)
		{
			scanf("%d %d",&u,&v);
			e[++tot]=(edge){u,v,h[u]},h[u]=tot;
			e[++tot]=(edge){v,u,h[v]},h[v]=tot;
		}
	dfs(1,0),S=1;
	for (int i=1; i<=n; i++)  if (dep[i]>dep[S])  S=i;
	dfs(S,0),T=S;
	for (int i=1; i<=n; i++)  if (dep[i]>dep[T])  T=i;
	ans1=(dep[T]+1)/2;
	if (dep[T]&1)
		{
			int x=T;
			while (dep[x]!=ans1)  x=f[x];
			ans2=calc(x);
			for (int i=h[x],y; y=e[i].t,i; i=e[i].n)  ans2=min(ans2,calc(x,y));
		}else
		{
			int x,y=T;
			while (dep[y]!=ans1+1)  y=f[y];
			x=f[y];
			ans2=calc(x,y);
		}
	printf("%d %lld",ans1,ans2);
}

