const int MAXN = 111;
int N;
VI G[MAXN];
int par[MAXN];
int depth[MAXN];
VI ord;

int bfs(int s) {
    memset(par, ~0, sizeof par);
    par[s] = s;
    depth[s] = 0;
    ord.clear();
    ord.push_back(s);
    REP (i_, N) {
	int v = ord[i_];
	EACH (e, G[v]) if (par[*e] == -1) {
	    par[*e] = v;
	    depth[*e] = depth[v]+1;
	    ord.push_back(*e);
	}
    }

    return max_element(depth, depth+N) - depth;
}

VI center;
VI B[MAXN];
LL bfs2() {
    REP (i, N) B[i].clear();
    memset(par, ~0, sizeof par);
    ord.clear();

    EACH (s, center) {
	par[*s] = *s;
	depth[*s] = 0;
	ord.push_back(*s);
    }
    if (center.size() == 2u) {
	par[center[0]] = center[1];
	par[center[1]] = center[0];
    }

    REP (i_, N) {
	int v = ord[i_];
	EACH (e, G[v]) if (*e != par[v]) {
	    par[*e] = v;
	    depth[*e] = depth[v]+1;
	    ord.push_back(*e);
	}
    }

    REP (i_, N) {
	int v = ord[i_];
	B[depth[v]].push_back(v);
    }
    int max_depth = *max_element(depth, depth+N);

    LL leaves = 1;
    for (int d=max_depth-1; d>=0; d--) {
	int max_degree = 0;
	int sub = 1;
	if (d == 0 && center.size() == 1u) {
	    sub = 0;
	}

	EACH (e, B[d]) {
	    amax(max_degree, (int)G[*e].size() - sub);
	}

	leaves *= max_degree;
    }

    if (center.size() == 2u) leaves *= 2;

    return leaves;
}


void MAIN() {
    scanf("%d", &N);
    REP (i, N-1) {
	int x, y;
	scanf("%d%d", &x, &y);
	x--; y--;
	G[x].push_back(y);
	G[y].push_back(x);
    }


    int x = bfs(0);
    int y = bfs(x);
    int max_depth = depth[y];

    int core = -1;
    int cur = y;
    while (1) {
	if ((max_depth+1) / 2 == depth[cur]) {
	    core = cur;
	}
	cur = par[cur];
	if (cur == x) break;
    }

    LL ans = 1LL<<60;

    if (max_depth % 2 == 1) {
	center.push_back(core);
	center.push_back(par[core]);
	LL tmp = bfs2();
	amin(ans, tmp);
    } else {
	center.push_back(core);
	LL tmp = bfs2();
	amin(ans, tmp);
	center.push_back(-1);
	EACH (e, G[core]) {
	    center.back() = *e;
	    tmp = bfs2();
	    amin(ans, tmp);
	}
    }

    printf("%d %lld\n", (max_depth+2)/2, ans);
}

int main() {
    int TC = 1;
//    scanf("%d", &TC);
    REP (tc, TC) MAIN();
    return 0;
}

