template <typename T>
void gi(T &ret) {
	ret = 0; char inp=gc(); int kl=1;
	while (inp<'0' || inp>'9') {if (inp=='-') kl=-1; inp=gc();}
	while ('0'<=inp && inp<='9') ret=(ret<<3)+(ret<<1)+(inp-'0'), inp=gc();
	if (kl<1) ret=-ret;
}

const int MAXN = 105;
int n, st, mks, ctr[2];
vi adj[MAXN];
vector<pii> opt;

ll ans = 0ll, mtp = 0ll;
int que[2][MAXN], qr[2], ct;
bool vis[MAXN];

void getst (int now, int par, int l) {
	if (l>mks) {
		mks = l;
		st = now;
	}
	for (auto nex : adj[now]) {
		if (nex==par) continue;
		getst(nex,now,l+1);
	}
}

vi stk;
void getctr (int now, int par, int l) {
	stk.psb(now);
	if (l>mks) {
		mks = l;
		opt.clear();
	}
	if (l==mks) {
		if (l&1) {
			ct = stk[l/2];
		} else {
			ctr[0] = stk[(l/2)];
			ctr[1] = stk[(l/2)-1];
		}
	}
	for (auto nex : adj[now]) {
		if (nex==par) continue;
		getctr(nex,now,l+1);
	}
	stk.ppb();
}

void init () {
	setnul(vis);
	qr[0] = qr[1] = 0;
	// printf ("ctr = %d %d\n", 
	que[0][qr[0]++] = ctr[0];
	vis[ctr[0]] = 1;
	if (ctr[1]!=-1) {
		que[0][qr[0]++] = ctr[1];
		vis[ctr[1]] = 1;
	}
}

int countdeg (int x) {
	int ret = 0;
	for (auto nex : adj[x])
		if (!vis[nex]) ret++;
	return ret;
}

void solve () {
	int ia = 0, ib = 1;
	mtp = (ll) qr[0];
	ans = (ll) qr[0];

	while (1) {
		ia ^= 1; ib ^= 1;
		qr[ia] = 0;

		// printf ("stat : ");
		// for (int i=0; i<qr[ib]; i++)
		// 	printf ("%d ", que[ib][i]);
		// endln;


		int mc = 0;
		for (int i=0; i<qr[ib]; i++)
			mc = max(mc, countdeg(que[ib][i]));
		if (mc==0) return;

		ans += mtp * (ll)(mc-1);
		// printf ("mtp = %lld, ans = %lld\n", mtp, ans);

		for (int i=0; i<qr[ib]; i++) {
			mtp += (ll) (mc-1);

			for (auto nex : adj[que[ib][i]]) {
				if (vis[nex]) continue;
				vis[nex] = 1;
				que[ia][qr[ia]++] = nex;
			}
		}

		assert (ans>=0ll);

		// printf ("ans = %lld\n", ans);
	}
}


int main() {
	gi(n);
	for (int i=1; i<n; i++) {
		int u,v; gi(u); gi(v);
		adj[u].psb(v);
		adj[v].psb(u);
	}
	mks = 0;
	getst(1,-1,1);
	mks = 0;
	getctr(st,-1,1);

	if (!(mks&1)) {
		opt.psb({ctr[0], ctr[1]});
	} else {
		opt.psb({ct,-1});
		for (auto xx : adj[ct])
			opt.psb({ct,xx});
	}

	ll fin = infll;
	for (auto xx : opt) {
		ans = 0ll; mtp = 0ll;
		ctr[0] = xx.fi; ctr[1] = xx.se;
		init();
		solve();
		// printf ("ans = %lld\n",ans);
		fin = min(fin, ans);
	}

	printf ("%d %lld\n", (mks+1)/2, fin);
	return 0;
}

