		I(v, b) {
			ll cnt = 0;
			I(to, a[v]) {
				if (to != p[v])
					++cnt;
			}
			new_copies += (mxcnt - cnt);
		}
		new_copies += copies * mxcnt;
		copies = new_copies;
		swap(b, c);
	}
	return mp(ansx, ans);
}

