            for (auto v : G[u]) if (dep[v] > dep[u]) 
                B.push_back(v);
        }
        if (!t) return nw;
        if (1e18 / t < nw) return 1e18;
        nw *= t;
    }
}

inline LL work2(int A, int B) {
    int nw = n + 1;
    for (auto &v : G[A]) if (v == B) { v = nw; break; }
