vector<int> dpt(200, 0);

void dfs2(int N, vector<vector<int>> &G, vector<bool> &vis, int s, int depth){
    if(vis[s]) return;
    vis[s] = true;
    int cnt = 0;
    for(int t : G[s]){
        if(!vis[t]) cnt++;
        dfs2(N, G, vis, t, depth+1);
    }
    dpt[depth] = max(dpt[depth], cnt);
}

void dfs3(int N, vector<vector<int>> &G, vector<bool> &vis, int s, int depth, int c2){
    if(vis[s]) return;
    vis[s] = true;
    int cnt = 0;
    for(int t : G[s]){
        if(t == c2) continue;
        if(!vis[t]) cnt++;
        dfs3(N, G, vis, t, depth+1, c2);
    }
    dpt[depth] = max(dpt[depth], cnt);
}


pair<int, long long> solve(int N, vector<vector<int>> &G, int c){
    fill(dpt.begin(), dpt.end(), 0);
    vector<bool> vis(N, false);
    dfs2(N, G, vis, c, 0);
    long long ans = 1;
    for(int i=0; i<200; i++)
        if(dpt[i] != 0) ans *= dpt[i];

    int d = 0;
    for(int i=0; i<200; i++)
        if(dpt[i] != 0) d = max(d, i+2);
    return make_pair(d, ans);
}

pair<int, long long> solve(int N, vector<vector<int>> &G, int c1, int c2){
    fill(dpt.begin(), dpt.end(), 0);
    vector<bool> vis(N, false);
    dfs3(N, G, vis, c1, 0, c2);
    dfs3(N, G, vis, c2, 0, c1);
    long long ans = 1;
    for(int i=0; i<200; i++)
        if(dpt[i] != 0) ans *= dpt[i];
    int d = 0;
    for(int i=0; i<200; i++)
        if(dpt[i] != 0) d = max(d, i+2);

    return make_pair(d, 2*ans);
}

