Int color = INF, leaf = LINF;

void dfs(Int x, Int last = -1, Int dep = 0){
  if(last == -1 && dep == 0)maxdeg[dep] = max(maxdeg[dep], (Int)edge[x].size());
  else maxdeg[dep] = max(maxdeg[dep], (Int)edge[x].size() - 1);
  for(Int to:edge[x]){
    if(to == last)continue;
    dfs(to, x, dep+1);
  }
}

void go(Int l){
  Int c = 0;
  while(maxdeg[c] != 0)c++;
  for(Int i = 0;i < c;i++){
    l *= maxdeg[i];
  }
  if(c < color){
    leaf =l;
    color = c;
  }
  if(c == color){
    leaf = min(l, leaf);
  }
}

