  }
  for(Int i = 0;i < n;i++){
    for(Int to:edge[i]){
      fill(maxdeg, maxdeg + 108, 0);
      dfs(i, to);
      dfs(to, i);
      go(2);
    }
    fill(maxdeg, maxdeg + 108, 0);
    dfs(i);
    go(1);
  }
  cout << color + 1 << " " << leaf << endl;
  return 0;
}

