int been[MaxN], dep[MaxN];
int downDeg[MaxN];
int maxDegOnDepth[MaxN];

void dfs(int node, int depth){

  // 'been' already taken care of
  dep[node] = depth;

  for (auto v: adj[node]){

    if (!been[v]){
      been[v] = 1;
      downDeg[node]++;
      dfs(v, depth + 1);
    }
  }

  maxDegOnDepth[dep[node]] = max( maxDegOnDepth[dep[node]], downDeg[node] );

}


pair<ll, ll> solveCenterNode(int start){

  memset(been, 0, sizeof been);
  memset(dep, -1, sizeof dep);
  memset(downDeg, 0, sizeof downDeg);
  memset(maxDegOnDepth, -1, sizeof maxDegOnDepth);

  been[start] = 1;
  dfs(start, 0);

  int colorful = -1;
  ll numCurLeaves = 1;

  for (int i = 0; i < N + 4; i++){

    if (maxDegOnDepth[i] == 0){
      colorful = i + 1;    
      break;
    }

    numCurLeaves *= (ll)maxDegOnDepth[i];  
  }

  return {colorful, numCurLeaves};
}

pair<ll, ll> solveCenterEdge(pair<int, int> edge){

  memset(been, 0, sizeof been);
  memset(dep, -1, sizeof dep);
  memset(downDeg, 0, sizeof downDeg);
  memset(maxDegOnDepth, -1, sizeof maxDegOnDepth);

  been[edge.first] = 1;
  been[edge.second] = 1;
  dfs(edge.first, 0);
  dfs(edge.second, 0);

  int colorful = -1;
  ll numCurLeaves = 1;

  for (int i = 0; i < N + 4; i++){

    if (maxDegOnDepth[i] == 0){ //mutna linijica
      colorful = i + 1;    
      break;
    }

    numCurLeaves *= (ll)maxDegOnDepth[i];  
  }

  return {colorful, numCurLeaves * 2};
}

void solve() {

  ll minCol = 1e7;
  ll maxLeaves = -1;

  for(int i = 1; i <= N; i++){
    auto ans = solveCenterNode(i);
    if (ans.first < minCol){
      minCol = ans.first;
      maxLeaves = ans.second;
    }
    else if (ans.first == minCol){
      maxLeaves = min(maxLeaves, ans.second);
    }
  }

  for (auto edge: edges){
    auto ans = solveCenterEdge(edge);
    if (ans.first < minCol){
      minCol = ans.first;
      maxLeaves = ans.second;
    }
    else if (ans.first == minCol){
      maxLeaves = min(maxLeaves, ans.second);
    }
  }

  cout<<minCol<<" "<<maxLeaves<<endl;
}

