template<typename A, typename B>inline void chmin(A &a, B b){if(a > b) a = b;}
template<typename A, typename B>inline void chmax(A &a, B b){if(a < b) a = b;}

int32 N;
vector<int32> G[101];

PII calc(int32 v1, int32 v2){
	vector<int32> out(N+1, 0);
	vector<int32> leaf(N+1, 0);
	vector<int32> d(N+1, INF);
	d[v1] = d[v2] = 0;
	int32 maxd = 0;
	function<void(int32, int32, int32)> dfs = [&](int32 v, int32 p, int32 dd){
		d[v] = dd;
		maxd = max(maxd, dd);
		if(G[v].size() == (v != p)){
			chmax(leaf[dd], 1);
			chmax(out[dd], 0);
			return;
		}
		chmax(out[dd], G[v].size()-(v != p));
		REP(i, G[v].size()){
			if(G[v][i] == p) continue;
			dfs(G[v][i], v, dd+1);
			chmax(leaf[dd], leaf[dd+1]*out[dd]);
		}
	};
	dfs(v1, v2, 0);
	dfs(v2, v1, 0);
	int32 res = 0;
	res = leaf[0]*(v1 != v2 ? 2 : 1);
	return PII(maxd, res);
}

