int main(){
  int N;
  cin >> N;
  vector<vector<int>> G(N);
  for(int i = 0; i < N-1; ++i){
    int a,b;
    cin >> a >> b;
    --a,--b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  int ans = 0;
  for(int i = 0; i < N; ++i){
    ans = max(ans,dfs(G,i,-1));
  }
  int d = (ans+1)/2;
  vector<int> C;
  for(int i = 0; i < N; ++i){
    if(dfs(G,i,-1) != d) continue;
    C.push_back(i);
  }
  long long l = LLINF;
  if(C.size() == 2) l = solve(G,C);
  else{
    l = min(l,solve(G,C));
    int c = C[0];
    //cerr << "c = " << c << endl;
    for(auto c_ : G[c]){
      if(dfs(G,c_,-1) != d+1) continue;
