ll find_len(ll now, ll fa)
{
	ll ret = 1;
	for(ll to : edge[now])
	{
		if(to == fa) continue;
		ret = max(ret, find_len(to, now) + 1);
	}
	return ret;
}

void find_max(ll now, ll fa, ll dis)
{
	ll tmp = 0;
	for(ll to : edge[now])
	{
		if(to == fa) continue;
		tmp ++;
		find_max(to, now, dis + 1);
	}
	sum[dis] = max(sum[dis], tmp);
}

