int calc(int dia) {
	int d = dia / 2;
	int epos;
	rep(i, n - 1) {
		if (d1[A[i]] > d1[B[i]])swap(A[i], B[i]);
		if (d1[A[i]] == d&&d1[B[i]] == d + 1 && d1[A[i]] + d2[B[i]] + 1 == dia) {
			epos = i; break;
		}
	}
	fill(d3, d3 + n, -1);
	d3[A[epos]] = d3[B[epos]] = 0;
	dfs2(A[epos]); dfs2(B[epos]);

	fill(r, r + n, 0);
	rep(i, n) {
		r[d3[i]] = max(r[d3[i]], (int)G[i].size() - 1);
	}

	int res = 2;
	rep(i, d)res *= r[i];
