struct Graph {
    Graph(int N) : size(N) { path.resize(N); };
    void span(int u, int v) { path[u].push_back(v); }
    vector<int> adj(int v) { return path[v]; };

    int size;
    vector<vector<int>> path;
};

int N;
Graph tree(0);

vector<int> bfs(vector<int> rs) {
    vector<int> dist(N, INF);
    queue<int> que;

    for (int r : rs) {
        dist[r] = 0;
        que.push(r);
    }

    while (!que.empty()) {
        int v = que.front();
        que.pop();

        for (int sv : tree.adj(v)) {
            if (dist[sv] <= dist[v]) continue;
            dist[sv] = dist[v] + 1;
            que.push(sv);
        }
    }
    return dist;
}

tuple<int, int, int> diameter() {
    auto dist = bfs({0});
    int l = max_element(dist.begin(), dist.end()) - dist.begin();
    dist = bfs({l});
    int r = max_element(dist.begin(), dist.end()) - dist.begin();
    return make_tuple(dist[r], l, r);
}

ll leaf_num(vector<int> center) {
    auto dist = bfs(center);
    vector<ll> hie(N, 0);

    for (int v = 0; v < N; ++v) {
        ll cnt = 0;
        for (int sv : tree.adj(v)) {
            if (dist[sv] > dist[v]) ++cnt;
        }
        hie[dist[v]] = max(hie[dist[v]], cnt);
    }

    ll ret = center.size();
    for (int d = 0; d < N; ++d) {
        if (hie[d] == 0) break;
        ret *= hie[d];
    }
    return ret;
}

int main() {
    cin >> N;

    tree = Graph(N);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        tree.span(u, v);
        tree.span(v, u);
    }

    int D, l, r;
    tie(D, l, r) = diameter();
    cout << D / 2 + 1 << " ";

    auto ldist = bfs({l}), rdist = bfs({r});
    vector<int> center;
    for (int v = 0; v < N; ++v) {
        if (ldist[v] + rdist[v] == D && abs(ldist[v] - rdist[v]) <= 1) center.push_back(v);
    }

    ll ans = leaf_num(center);
    if (center.size() == 1) {
        int c = center[0];
        for (int sv : tree.adj(c)) {
            ans = min(ans, leaf_num({c, sv}));
        }
    }

    cout << ans << endl;
    return 0;
}

