#include "bits/stdc++.h"
using namespace std;
typedef long long li;

const li mod = 1e9 + 7;

vector<vector<li>> nexts;

struct dfsresult {
    li depth;
    li node;
};

dfsresult dfs(li pos, li parent) {
    dfsresult result;
    result.depth = 0;
    result.node = pos;

    for (auto &&next  : nexts[pos]) {
        if (next == parent) {
            continue;
        }
        auto subres = dfs(next, pos);
        subres.depth += 1;
        if (subres.depth > result.depth) {
            result = subres;
        }
    }
    return result;
}

li distance(li pos, li dest, li parent) {
    if (pos == dest) {
        return 0;
    }

    li ans = 999;
    for (auto &&next : nexts[pos]) {
        if (next == parent) {
            continue;
        }
        ans = min(ans, distance(next, dest, pos) + 1);
    }
    return ans;
}

vector<li> dfs2(li pos, li parent) {
    vector<li> ret;
    li cnt = 0;
    for (auto &&next : nexts[pos]) {
        if (next == parent) {
            continue;
        }
        cnt++;
        auto subret = dfs2(next, pos);
        if (subret.size() > ret.size()) {
            swap(subret, ret);
        }
        for (int i = ret.size() - subret.size(); i < ret.size(); ++i) {
            ret[i] = max(ret[i], subret[i]);
        }
    }
    if (cnt) {
        ret.push_back(cnt);
    }
    return ret;
}

li calc(li x, li y) {
    auto ret1 = dfs2(x, y);
    auto ret2 = dfs2(y, x);
    if (ret2.size() > ret1.size()) {
        swap(ret1, ret2);
    }
    li ret = 2;
    for (int i = 0; i < ret1.size(); ++i) {
        if (i + (li)ret2.size() - (li)ret1.size() >= 0) {
            ret *= max(ret1[i], ret2[i + (li)ret2.size() - (li)ret1.size()]);
        } else {
            ret *= ret1[i];
        }
    }
    return ret;
}

