using namespace std;
const int maxn=100100;
int Max(int x,int y){
	return x>y?x:y;
}
void chkmax(int &x,int y){
	x=x>y?x:y;
}
void chkmin(int &x,int y){
	x=x<y?x:y;
}
void chkmin(long long &x,long long y){
	x=x<y?x:y;
}
int n;
int beg[maxn],tto[maxn<<1],nex[maxn<<1],e;
void putin(int s,int t){
	tto[++e]=t;
	nex[e]=beg[s];
	beg[s]=e;
}
int len1[maxn],len2[maxn];
void updata(int u,int v){
	if(v>len1[u]){
		len2[u]=len1[u];
		len1[u]=v;
	}
	else if(v>len2[u])
		len2[u]=v;
}
void get_maxlen(int u,int fa){
	len1[u]=len2[u]=0;
	for(int i=beg[u];i;i=nex[i]){
		if(tto[i]==fa) continue;
		get_maxlen(tto[i],u);
		updata(u,len1[tto[i]]+1);
	}
}
void find_dis(int u,int fa,int l){
	updata(u,l);
	for(int i=beg[u];i;i=nex[i]){
		if(tto[i]==fa) continue;
		if(len1[tto[i]]+1==len1[u])
			find_dis(tto[i],u,len2[u]+1);
		else
			find_dis(tto[i],u,len1[u]+1);
	}
}
int dep[maxn];
void get_dep(int u){
	for(int i=beg[u];i;i=nex[i]){
		if(dep[tto[i]]) continue;
		dep[tto[i]]=dep[u]+1;
		get_dep(tto[i]);
	}
}
int mxd[maxn],d[maxn];
long long solve(int rt1,int rt2,int ans1){
	for(int i=1;i<=n;i++)
		dep[i]=0,mxd[i]=0;
	dep[rt1]=dep[rt2]=1;
	for(int i=1;i<=n;i++)
		if(dep[i]==1)
			get_dep(i);
	for(int i=1;i<=n;i++){
		if(dep[i]==1&&rt2==0)
			chkmax(mxd[dep[i]],d[i]);
		else
			chkmax(mxd[dep[i]],d[i]-1);
	}
	long long ans2=rt2==0?1:2;
	for(int i=1;i<=ans1/2;i++)
		ans2=ans2*mxd[i];
	return ans2;
}
int main(){
	int s,t;
	scanf("%d",&n);
	for(int i=1;i<n;i++){
		scanf("%d%d",&s,&t);
		d[s]++,d[t]++;
		putin(s,t);
		putin(t,s);
	}
	get_maxlen(1,-1);
	find_dis(1,-1,0);
	int ans1=0;
	for(int i=1;i<=n;i++)
		chkmax(ans1,len1[i]+len2[i]);
	long long ans2;
	if(ans1%2==1){
		int rt1=0,rt2=0;
		for(int i=1;i<=n;i++){
			if(len1[i]==(ans1+1)/2){
				if(!rt1) rt1=i;
				else rt2=i;
			}
		}
		ans2=solve(rt1,rt2,ans1);
	}
	else{
		int rt;
		for(int i=1;i<=n;i++)
			if(len1[i]==ans1/2)
				rt=i;
		ans2=solve(rt,0,ans1);
		for(int i=beg[rt];i;i=nex[i])
			chkmin(ans2,solve(rt,tto[i],ans1));
	}
	printf("%d %lld\n",ans1/2+1,ans2);
	return 0;
}

