using namespace std;

long long N, A[109], B[109], dist[109][109], P[109], dp[109]; bool used[109]; vector<int>x[109], y[109], z[109], w[109];

void dfs(int pos, int dep) {
	dp[pos] = dep;
	for (int i = 0; i < x[pos].size(); i++) {
		if (used[x[pos][i]] == true || dp[x[pos][i]] >= 0) continue;
		w[pos].push_back(x[pos][i]);
		dfs(x[pos][i], dep + 1);
	}
}

long long solve(vector<int>vec) {
	for (int i = 1; i <= N; i++) { used[i] = false; dp[i] = -1; y[i].clear(); w[i].clear(); }
	for (int i = 0; i < vec.size(); i++) used[vec[i]] = true;
	for (int i = 0; i < vec.size(); i++) {
		dfs(vec[i], 0);
	}
	for (int i = 1; i <= N; i++) y[dp[i]].push_back(i);
	long long ret = 1;
	for (int i = 0; i <= N; i++) {
		long long maxn = 0;
		for (int j = 0; j < y[i].size(); j++) maxn = max(maxn, (long long)w[y[i][j]].size());
		if (maxn >= 1) ret *= maxn;
	}
	ret *= vec.size();
	return ret;
}

int main() {
	cin >> N;
	for (int i = 1; i <= N - 1; i++) {
		cin >> A[i] >> B[i];
		x[A[i]].push_back(B[i]);
		x[B[i]].push_back(A[i]);
	}
	for (int i = 1; i <= N; i++) { for (int j = 1; j <= N; j++) dist[i][j] = (1 << 30); dist[i][i] = 0; }
	for (int i = 1; i <= N - 1; i++) { dist[A[i]][B[i]] = 1; dist[B[i]][A[i]] = 1; }
	for (int k = 1; k <= N; k++) { for (int i = 1; i <= N; i++) { for (int j = 1; j <= N; j++) dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]); } }

	long long minx = (1 << 30), maxn = 0;
	for (int i = 1; i <= N; i++) {
		long long R = 0; for (int j = 1; j <= N; j++) R = max(R, dist[i][j]);
		P[i] = R; z[P[i]].push_back(i);
		minx = min(minx, P[i]);
		maxn = max(maxn, P[i]);
	}
	long long G = solve(z[minx]);
	if (z[minx].size() == 1) {
		int pos = z[minx][0];
		for (int i = 0; i < x[pos].size(); i++) {
			vector<int>T = { pos,x[pos][i] };
			G = min(G, solve(T));
		}
	}
	cout << maxn - minx + 1 << " " << G << endl;
	return 0;
}

