//            min_leaf = min(cal_leaf(edge[hen]), min_leaf);
//        }
//    }
    rep(i, 0, hei.size()) {
        if (hei[i] == min_h) {
            min_leaf = min(cal_leaf(edge[i]), min_leaf);
        }
    }
    return pair<int, ll>(min_h, min_leaf);
}

