    for (int x : adjl[node]){
        if (x==parent) continue;
        auto thing = furthest(x,node);
        ans = max(ans,{thing.first+1,thing.second});
    }
    return ans;
}

void dfs(int node, int parent){
    for (int x : adjl[node]){
        if (x==parent) continue;
        if (dist[x]==-1 || dist[x]>dist[node]+1){
            dist[x] = dist[node]+1;
            dfs(x,node);
        }

    }
}

