void relax(vector<int> diam, vector<vector<int>> g, int &ans) {
    int n = (int)g.size();
    vector<int> used(n);
    vector<int> mxbh(n);
    vector<int> cnth(n);
    function<void(int,int)> dfs = [&](int cur, int ch) {
        used[cur] = 1;
        int cnt = 0;
        for (auto t : g[cur]) {
            if (!used[t]) {
                dfs(t, ch + 1);
                cnt++;
            }
        }
        cnth[ch]++;
        mxbh[ch] = max(mxbh[ch], cnt);
    };
    if ((int)diam.size() % 2 == 1) {
        dfs(diam[(int)diam.size() / 2], 0);
    } else {
        int p = (int)diam.size() / 2;
        used[diam[p]] = 1;
        used[diam[p - 1]] = 1;
        dfs(diam[p], 0);
        dfs(diam[p - 1], 0);
    }
    int cur = 1;
    for (int i = 0; i < n; i++) {
        cur *= max((int)1, mxbh[i]);
    }
    if ((int)diam.size() % 2 == 0) {
        cur *= 2;
    }
    ans = min(ans, cur);
}

vector<int> path(int n, vector<vector<int>> g, int a, int b) {
    vector<int> ps(n);
    vector<int> used(n);
    function<void(int, int)> dfs = [&](int cur, int p) {
        ps[cur] = p;
        used[cur] = 1;
        for (auto t : g[cur]) {
            if (!used[t]) {
                dfs(t, cur);
            }
        } 
    };
    dfs(a, -1);
    vector<int> ans;
    int cur = b;
    while (cur != -1) {
        ans.push_back(cur);
        cur = ps[cur];
    }
    return ans;
}

void try_path(vector<int> path, vector<vector<int>> g, int &ans) {
    // cerr << "trying " << endl;
    // for (auto t : path) {
    //     cerr << t + 1 << ' ';
    // }
    // cerr << endl;
    int n = (int)g.size();
    g.push_back(vector<int> ());
    relax(path, g, ans);
    if (path.size() % 2 == 1) {
        {
            path.insert(path.begin(), n);
            g[n].push_back(path[1]);
            g[path[1]].push_back(n);
            relax(path, g, ans);
            g[n].pop_back();
            g[path[1]].pop_back();
            path.erase(path.begin());
        }
        {
            path.push_back(n);
            g[path[(int)path.size() - 2]].push_back(n);
            g[n].push_back(path[(int)path.size() - 2]);
            relax(path, g, ans);
            g[n].pop_back();
            g[path[(int)path.size() - 2]].pop_back();
            path.pop_back();
        }

    }
}

