template<class T> void chmin(T &a,const T &b){if(a>b) a=b;}
template<class T> void chmax(T &a,const T &b){if(a<b) a=b;}

pair<int,int> findFar(int now,int par,vector<vector<int>> &g){
    pair<int,int> res=mkp(0,now);
    for(auto nex:g[now]){
        if(nex==par) continue;
        auto neco=findFar(nex,now,g);
        neco.first++;
        chmax(res,neco);
    }
    return res;
}

bool setPath(int now,int par,int goal,vector<int> &path,vector<vector<int>> &g){
    if(now==goal){
        path.push_back(now);
        return true;
    }
    for(auto nex:g[now]){
        if(nex==par) continue;
        if(setPath(nex,now,goal,path,g)){
            path.push_back(now);
            return true;
        }
    }
    return false;
}

vector<int> getDiameter(vector<vector<int>> &g,bool flag){
    int N=g.size();
    int a=findFar(0,-1,g).second;
    int b=findFar(a,-1,g).second;
    vector<int> diam;
    setPath(a,-1,b,diam,g);
    if(flag){
        int c,d;
        tie(c,d)=findFar(N-1,-1,g);
        if(c+1==diam.size()){
            diam.clear();
            setPath(d,-1,N-1,diam,g);
        }
    }
    return diam;
}

pair<int,ll> ans;
const ll INF=2e18;

pair<int,ll> solve(vector<vector<int>> &g,bool flag){
    vector<int> diam=getDiameter(g,flag);
    /*for(auto v:diam) cout<<v+1<<" ";
    cout<<endl;*/
    int M=diam.size();
    int N=g.size();
    if((M+1)/2>ans.first||M==0) return mkp(MOD,INF);

    vector<int> dep(N,MOD);
    int sta=diam[M/2],stb=sta;
    if(M%2==0) stb=diam[M/2-1];
    dep[sta]=0;dep[stb]=0;
    queue<int> Q;
    Q.push(sta);Q.push(stb);
    while(!Q.empty()){
        int now=Q.front();
        Q.pop();

        for(auto nex:g[now]){
            if(dep[nex]==MOD){
                dep[nex]=dep[now]+1;
                Q.push(nex);
            }
        }
    }

    int D=0;
    rep(i,N) chmax(D,dep[i]);
    vector<vector<int>> v(D+1);
    rep(i,N) v[dep[i]].push_back(i);

    vector<int> deg(N,0);
    rep(i,N) deg[i]=g[i].size();

    ll prenum=0;
    for(int i=0;i<D;i++){
        int madeg=1;
        for(int j=0;j<v[i].size();j++) chmax(madeg,deg[v[i][j]]);
        ll nexnum=0;
        for(auto j:v[i]) nexnum+=madeg-deg[j];
        if(prenum>0&&(madeg-1)>INF/prenum) return mkp(MOD,INF);
        nexnum+=prenum*(madeg-1);
        prenum=nexnum;
        if(prenum>ans.second) return mkp(MOD,INF);
    }
    rep(i,N) if(dep[i]==D) prenum++;
    return mkp((M+1)/2,prenum);
}


