struct dijkstra {

	ll N;
	vector<vector<edge>> g;
	ll s;

	vector<ll> ans;

	dijkstra(ll N0, ll s, vector<vector<edge>> g0) {//頂点数、始点、グラフ(頂点は1indexか0index)
		N = N0;
		g = g0;

		ans.assign(N + 1, INF);


		priority_queue<pair<ll, ll>> q;//(-キョリ、頂点)

		ans[s] = 0;
		q.push({ 0,s });

		while (!q.empty()) {
			auto x = q.top();
			q.pop();

			ll dis = -x.first;
			ll v = x.second;

			if (dis > ans[v]) { continue; }


			for (edge e : g[v]) {
				ll w = e.to;
				if (dis + e.d < ans[w]) {
					ans[w] = dis + e.d;
					q.push({ -ans[w], w });
				}
			}


		}
	}

	ll d(ll t) {//sからtまでの最短距離を出力
		return ans[t];
	}

};

pair<ll,ll> solve(ll N, vector<vector<edge>> g) {
	dijkstra dij(N, 1, g);

	ll d = 0;
	ll s = 0;
	repn(i, N) {
		if (dij.ans[i] > d) { d = dij.ans[i]; s = i; }
	}

	dijkstra dijs(N, s, g);
	d = 0;
	ll t = 0;
	repn(i, N) {
		if (dijs.ans[i] > d) { d = dijs.ans[i]; t = i; }
	}
	dijkstra dijt(N, t, g);


	ll diam = dijs.ans[t];
	ll ret1 = (diam + 2) / 2;

	//cout << diam <<" "<<ret1<< endl;

	vector<ll> col(N + 1);

	repn(i, N) {
		ll x = dijs.ans[i];
		ll y = dijt.ans[i];
		ll z = (x + y - diam) / 2;
		col[i] = 1 + min(x - z, y - z) - z;
		//cout << col[i]<<endl;
	}

	vector<ll> out(ret1 + 1, 0);
	repn(i, N) {
		ll v = 0;
		for (edge e : g[i]) {
			if (col[e.to] < col[i]) { v++; }
		}

		out[col[i]] = max(out[col[i]], v);
	}

	ll ret2 = 1;
	if (diam % 2 == 1) { ret2 = 2; }
	for (ll i = 2; i <= ret1; i++) { ret2 *= out[i];}

	return { ret1,ret2 };

}



int main() {
	ll N;
	cin >> N;

	vector<vector<edge>> g;
	g.resize(N + 1);
	repn(i, N - 1) {
		ll a, b;
		cin >> a >> b;
		g[a].push_back({ i,a,b,1 });
		g[b].push_back({ i,b,a,1 });
	}

	pair<ll, ll> ans = solve(N, g);

	repn(i, N) {
		vector<vector<edge>> h = g;
		h.resize(N + 2);
		h[i].push_back({ 0,i,N + 1,1 });
		h[N + 1].push_back({ 0,N + 1,i,1 });
		ans = min(ans, solve(N + 1, h));
	}

	cout << ans.first << " " << ans.second << endl;


	system("PAUSE");
}

