struct P{
	int col,lef;
};
bool operator <(P a,P b){
	if(a.col==b.col) return a.lef<b.lef;
	return a.col<b.col;
}
struct edge{
	int k,next;
}e[200005];
int n,home[100005],cnt=-1,E[105][2],fa[100005],tot;
void add(int x,int y){
	cnt++;
	e[cnt].k=y;
	e[cnt].next=home[x];
	home[x]=cnt;
}
void init(int k,int F){
	fa[k]=F;
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F)
		init(e[i].k,k);
}
int q[100005];
P bfs(int x,int y,int op){
	int tou=0,wei=1,k;
	P ans;
	ans.col=0;
	q[0]=x;
	if(op) q[wei++]=y;
	while(tou<wei){
		int o=tou,mx=0;
		tou=wei;
		ans.lef=tou-o;
		ans.col++;
		for(int i=o;i<tou;i++){
			int g=0;
			for(int p=home[q[i]];~p;p=e[p].next) if(e[p].k!=fa[q[i]]) g++;
			mx=max(mx,g);
		}
		for(int i=o;i<tou;i++){
			int g=0;
			for(int p=home[q[i]];~p;p=e[p].next) if(e[p].k!=fa[q[i]]) g++;
			while(g<mx) fa[++n]=q[i],g++,add(q[i],n);
			for(int p=home[q[i]];~p;p=e[p].next) if(e[p].k!=fa[q[i]]) q[wei++]=e[p].k;
		}
	}
	return ans;
}
int main(){
	memset(home,-1,sizeof(home));
	scanf("%d",&n);
	for(int i=1,x,y;i<n;i++){
		scanf("%d%d",&x,&y);
		E[i][0]=x;E[i][1]=y;
	}
	tot=n;
	P ans;ans.col=1e9;ans.lef=0;
	for(int i=1;i<=tot;i++){
		memset(home,-1,sizeof(home));
		cnt=-1;
		for(int p=1;p<tot;p++) add(E[p][0],E[p][1]),add(E[p][1],E[p][0]);
		n=tot;
		init(i,0);
		P t=bfs(i,0,0);
		ans=min(ans,t);
	}
	for(int i=1;i<=tot;i++){
		memset(home,-1,sizeof(home));
		cnt=-1;
		for(int p=1;p<tot;p++) add(E[p][0],E[p][1]),add(E[p][1],E[p][0]);
		n=tot;
		for(int p=home[i];~p;p=e[p].next) if(e[p].k>i){
			init(e[p].k,i);
			init(i,e[p].k);
			P t=bfs(i,e[p].k,1);
			ans=min(ans,t);
		}
	}
	printf("%d %d",ans.col,ans.lef);
	return 0;
}

