void dfs(int u, int p, int d) {
    parent[u] = p;
    deepest = max(deepest, MP(d, u));
    for (int v : adj[u]) {
        if (v != p) dfs(v, u, d+1);
    }
}

VI branches;

void dfs2(int u, int p, int d) {
    int b = 0;
    for (int v: adj[u]) {
        if (v != p) {
            b++;
            dfs2(v, u, d+1);
        }
    }
    branches[d] = max(branches[d], b);
}

int main() {
    int N;
    RI(N);
    adj.resize(N+1);
    parent.resize(N+1);
    REP(i, N-1) {
        DRI(a, b);
        adj[a].PB(b);
        adj[b].PB(a);
    }
    dfs(1, 0, 0);
    int a = deepest.Y;
    deepest = MP(-1, 0);
    dfs(a, 0, 0);
    int d = deepest.X, b = deepest.Y, m = b;
    REP(i, (d-1)/2) {
        m = parent[m];
    }
    LL ans = LLONG_MAX;
    auto update = [&ans](LL prod) {
        for (int br : branches) {
            if (br == 0) break;
            prod *= br;
        }
        ans = min(ans, prod);
    };
    branches = VI(N+1);
    dfs2(m, parent[m], 0);
    dfs2(parent[m], m, 0);
    update(2);
    if(d % 2 == 0) {
        branches = VI(N+1);
        dfs2(parent[m], 0, 0);
        update(1);
        branches = VI(N+1);
        dfs2(parent[m], parent[parent[m]], 0);
        dfs2(parent[parent[m]], parent[m], 0);
        update(2);
    }
    printf("%d %lld\n", d/2 + 1, ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int Maxn = 105;
const ll Inf = 9000000000000000007ll;

int n;
vector <int> neigh[Maxn];
int mxL;
ll dp[Maxn][Maxn];
ll global[Maxn];
ll res = Inf;
ll cand;
int best = Maxn;

void Clear()
{
	mxL = 0;
	fill((ll*)dp, (ll*)dp + Maxn * Maxn, 0);
	cand = 0;
}

void Level(int v, int p, int lvl)
{
	mxL = max(mxL, lvl);
	for (int i = 0; i < neigh[v].size(); i++) {
		int u = neigh[v][i];
		if (u == p) continue;
		Level(u, v, lvl + 1);
	}
}

void Solve(int v, int p, int lvl)
{
	dp[v][lvl] = 1;
	for (int i = 0; i < neigh[v].size(); i++) {
		int u = neigh[v][i];
		if (u == p) continue;
		Solve(u, v, lvl + 1);
		for (int j = lvl + 1; j <= mxL; j++)
			dp[v][j] = max(dp[v][j], dp[u][j]);
	}
	int has = int(neigh[v].size()) - (p != 0);
	if (has) dp[v][lvl + 1] = has;
	for (int i = 0; i < neigh[v].size(); i++) {
		int u = neigh[v][i];
		if (u == p) continue;
	}
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i < n; i++) {
		int a, b; scanf("%d %d", &a, &b);
		neigh[a].push_back(b);
		neigh[b].push_back(a);
	}
	for (int i = 1; i <= n; i++) {
		Clear();
		Level(i, 0, 1);
		Solve(i, 0, 1);
		cand = 1;
		for (int j = 1; j <= mxL; j++)
			cand *= dp[i][j];
		if (mxL < best || mxL == best && cand < res) {
			best = mxL; res = cand;
		}
	}
	for (int i = 1; i <= n; i++)
		for (int j = 0; j < neigh[i].size(); j++) {
			int u = neigh[i][j];
			if (i < u) {
				Clear();
				Level(i, u, 1); Level(u, i, 1);
				Solve(i, u, 1); Solve(u, i, 1);
				for (int k = 1; k <= mxL; k++)
					global[k] = max(dp[i][k], dp[u][k]);
				global[1] = 2;
				cand = 1;
				for (int k = 1; k <= mxL; k++)
					cand *= global[k];
				if (mxL < best || mxL == best && cand < res) {
					best = mxL; res = cand;
				}
			}
		}
	cout << best << " " << res << endl;
	return 0;
}

