	LL mx=0,sum=0;
	for(int k=head[j];k;k=e[k].nex){
	  int v=e[k].to;
	  if(dep[v]==dep[j]+1) mx=max(mx,f[v]),sum++;
	}
	if(sum==0) f[j]=1;
	else f[j]=mx*sum;
	Max=max(Max,f[j]);
      }
    for(int j=1;j<=n;j++)
      if(dep[j]==i) f[j]=Max;
      }
  return mk(Dep,f[x]);
