  memset(f,0,sizeof(f));
  for(int i=Dep;i>0;i--){
    LL Max=0;
    for(int j=1;j<=n;j++)
      if(dep[j]==i){
	LL mx=0,sum=0;
	for(int k=head[j];k;k=e[k].nex){
	  int v=e[k].to;
	  if(dep[v]==dep[j]+1) mx=max(mx,f[v]),sum++;
	}
	if(sum==0) f[j]=1;
	else f[j]=mx*sum;
	Max=max(Max,f[j]);
      }
    for(int j=1;j<=n;j++)
      if(dep[j]==i) f[j]=Max;
  }
  return mk(Dep,2ll*max(f[u],f[v]));
}
inline P Min(P a,P b){
  if(a.first<b.first) return a;
  else if(a.first>b.first) return b;
  else if(a.second<b.second) return a;
  else return b;
}
