void gogo(int v, int p, int h) {
	int cnt = 0;
	for (int u: eds[v])
		if (u != p)
			++cnt;
	mx[h] = max(mx[h], ll(cnt));
	for (int u: eds[v]) {
		if (u != p)
			gogo(u, v, h + 1);
	}
}

