		return -1;
	}
	else {
		gogo(st[d / 2], st[d / 2 + 1], 0);
		gogo(st[d / 2 + 1], st[d / 2], 0);
		ll ans = 1;
		for (int i = 0; i < d / 2; ++i) {
			ans = (ans * mx[i]);
		}
		return ans * 2;
	}
}

