					depth[G[vs[i]][j]]=depth[vs[i]]+1;
					par[G[vs[i]][j]]=vs[i];
					looked[G[vs[i]][j]]=1;
					++cnt;
				}
			}
			num[vs[i]]=cnt;
		}
		vs.swap(nx);
	}
}

