const int INF = 1.01e9;

pair<int, ll> solve(vector<pair<int, int>> ed) {
    int n = ed.size() + 1;

    vector<vector<int>> e(n + 1);
    for (auto o : ed) {
        e[o.first].push_back(o.second);
        e[o.second].push_back(o.first);
    }

    vector<int> d(n + 1, -1);
    vector<int> pr(n + 1);
    function<void(int, int, int)> dfs1 = [&](int v, int h, int p) {
        if (d[v] != -1) return;
        d[v] = h;
        pr[v] = p;
        for (int to : e[v]) {
            dfs1(to, h + 1, v);
        }
    };

    int diam = -1, root = -1;
    for (int i = 0; i < n; i++) {
        d.assign(n + 1, -1);
        dfs1(i, 0, -1);
        int j = max_element(d.begin(), d.end()) - d.begin();
        if (diam < d[j]) {
            diam = d[j];
            root = i;
        }
    }
    d.assign(n + 1, -1);
    dfs1(root, 0, -1);
    int j = max_element(d.begin(), d.end()) - d.begin();

    vector<int> vct;
    for (int cur = j; cur != -1; cur = pr[cur]) vct.push_back(cur);

    pair<int, ll> ans = make_pair(INF, INF);

    auto solve = [&](int root, int sub) {
        d.assign(n + 1, -1);
        dfs1(root, 0, -1);

        vector<int> vct(n);
        iota(vct.begin(), vct.end(), 0);
        sort(vct.begin(), vct.end(), [&](int i, int j) {
            return d[i] > d[j];
        });

        vector<ll> dp(n);
        vector<vector<int>> mx(n, vector<int>(n, 0));
        for (int v : vct) {
            vector<int> cur(n);
            for (int to : e[v]) {
                if (d[to] > d[v]) {
                    cur[d[to]]++;
                }
            }
            for (int j = 0; j < n; j++) {
                mx[d[v]][j] = max(mx[d[v]][j], cur[j]);
            }
        }

        dp[d[vct[0]]] = 1;
        for (int i = d[vct[0]] - 1; i >= 0; i--) {
            for (int j = 0; j < n; j++) {
                dp[i] += dp[j] * mx[i][j];
            }
        }

        int res = d[vct[0]] + 1;
        res -= sub;
        ans = min(ans, make_pair(res, dp[0]));
    };

    auto addEdge = [&](int u, int v) {
        e[u].erase(find(e[u].begin(), e[u].end(), v));
        e[v].erase(find(e[v].begin(), e[v].end(), u));

        e[u].push_back(n);
        e[n].push_back(u);
        e[v].push_back(n);
        e[n].push_back(v);
        n++;
        solve(n-1, 1);
        n--;
        e[u].pop_back();
        e[v].pop_back();
        e[n].pop_back();
        e[n].pop_back();

        e[u].push_back(v);
        e[v].push_back(u);
    };

    if (vct.size() % 2 == 0) {
        addEdge(vct[vct.size() / 2], vct[vct.size() / 2 - 1]);
    } else {
        solve(vct[vct.size() / 2], 0);
        solve(vct[vct.size() / 2 + 1], 0);
        int vv = vct[vct.size() / 2];
        for (int to : e[vv]) {
            addEdge(vv, to);
        }
    }


    return ans;
};

