class DiameterOfTree{
public:
  typedef pair<int,int> P;
  int V;
  vector<vector<P> > G;
  vector<int> nodeCost;
  int start, end, length;
  int ok;
  DiameterOfTree():V(-1){}
  DiameterOfTree(int V):V(V),G(V),nodeCost(V, 0),ok(false){};

  void add_edge(int a,int b,int c = 1){
    assert(a < V && b < V);
    assert(a >= 0 && b >= 0);
    G[a].push_back(P(b,c));
    G[b].push_back(P(a,c));
  }

  void dfs(int pos,int pre = -1,int len = 0){
    if(pre == -1) start = pos, length = -1;
    len += nodeCost[pos];    
    if(len > length) length = len, end = pos;
    for(P p:G[pos]) if(p.first != pre) dfs(p.first, pos, len+p.second);
  }

  //O(V + E);
  vector<int> getPath(){
    assert(ok);
    vector<int> res;
    function<int(int,int)> dfs=[&](int pos,int pre){
      if(pos == end) {res.push_back(end); return 1;}
      for(P p:G[pos]){
        int to = p.first;
        if(to != pre && dfs(to, pos)){res.push_back(pos); return 1;}
      }
      return 0;
    };
    dfs(start, -1);
    return res;
  }

  //O(V + E);
  void build(int start=0){
    ok = true;
    assert(start < V);
    dfs(start);
    dfs(end);
  }
};


int n;
vector<vector<int> > G;

//deg, sum, cnt
tuple<int,int, int> calcMaxDegree(vector<int> &D, queue<int> &Q,int target, int flag){
  int deg = 0,sum = 0, cnt = 0;
  while(!Q.empty()){
    int pos = Q.front();
    int cost = D[pos];
    if(cost > target) break;

    if(cost == target) {
      Max(deg, (int)G[pos].size() - flag);
      sum += G[pos].size() - flag;
      cnt++;
    }

    Q.pop();

    for(int to:G[pos]){
      if(D[to] != -1) continue;
      D[to] = cost + 1;
      Q.push(to);
    }
  }
  return tie(deg, sum, cnt);
}


P solve(vector<int> start){
  vector<int> D(n,-1);
  queue<int> Q;
  for(int s:start){Q.push(s); D[s] = 0;}

  int col = 1, leaf = start.size();
  int flag = leaf != 1;

  for(int i=0;i<n;i++, flag = 1){
    int deg, sum, cnt; 
    tie(deg, sum, cnt) = calcMaxDegree(D, Q, i, flag);
    if(deg == 0) break;
    col++;
    leaf = leaf * deg;
  }
  return {col, leaf};
}

signed main(){
  cin.tie(0);
  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(12);

  cin>>n;
  G.resize(n);

  DiameterOfTree DoT(n);
  for(int i=1;i<n;i++){
    int a, b;
    cin>>a>>b; a--, b--;
    G[a].push_back(b);
    G[b].push_back(a);
    DoT.add_edge(a, b);
  }

  DoT.build();
  vector<int> start;
  auto path = DoT.getPath();
  start.push_back( path[DoT.length/2] );
  if(DoT.length % 2) start.push_back( path[DoT.length/2 + 1] );
  assert(start.size() == 2);
  P a = solve(start);
  P b = P(INF,INF);
  if(start.size() == 1){
    int center = start[0];
    int center2 = 0, mx = -1;
    for(int to:G[center]) if(mx < (int)G[to].size()) center2 = to, mx = G[to].size();
    start.push_back(center2);
    b = solve(start);
  }

  P ans = min(a, b);
  cout<<ans.first<<" "<<ans.second<<endl;
  return 0;
}

