typedef long long ll;
const int maxn = 200;
int n, dep[maxn + 10];
int a[maxn + 10], acnt, mx[maxn + 10];
int ans = 1e9;
ll ansv;
vector<int> g[maxn + 10];

void dfs(int p, int fa) {
	dep[p] = dep[fa] + 1;
	for (int i = 0; i < (int)g[p].size(); ++i) {
		int e = g[p][i];
		if (e != fa) dfs(e, p);
	}
}

bool getpath(int p, int fa, int od) {
	a[++acnt] = p;
	if (p == od) return 1;
	for (int i = 0; i < (int)g[p].size(); ++i) {
		int e = g[p][i];
		if (e != fa && getpath(e, p, od)) return 1;
	}
	--acnt; return 0;
}

void dfsdeg(int p, int fa, int dep) {
	int cnt = 0;
	for (int i = 0; i < (int)g[p].size(); ++i) {
		int e = g[p][i];
		if (e != fa) {
			dfsdeg(e, p, dep + 1); ++cnt;
		}
	}
	mx[dep] = max(mx[dep], cnt);
}

void solve() {
	dfs(1, 0);
	int x = max_element(dep + 1, dep + n + 1) - dep;
	dfs(x, 0);
	int y = max_element(dep + 1, dep + n + 1) - dep;
	acnt = 0;
	assert(getpath(x, 0, y));
	memset(mx, 0, sizeof mx);
	int now = 1; ll tot = 1;
	if (acnt & 1) {
		dfsdeg(a[acnt / 2 + 1], 0, 0);
	} else {
		mx[0] = 2;
		dfsdeg(a[acnt / 2], a[acnt / 2 + 1], 1);
		dfsdeg(a[acnt / 2 + 1], a[acnt / 2], 1);
		--now;
	}
	for (int i = 0; mx[i]; ++i) {
		tot *= mx[i]; ++now;
	}
	if (now < ans) {
		ans = now; ansv = tot;
	} else if (now == ans && tot < ansv) ansv = tot;
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i < n; ++i) {
		int l, r; scanf("%d%d", &l, &r);
		g[l].push_back(r); g[r].push_back(l);
	}
	solve();
	++n;
	for (int i = 1; i < n; ++i) {
		g[n].push_back(i);
		g[i].push_back(n);
		solve();
		g[n].pop_back(); g[i].pop_back();
	}
	printf("%d %lld", ans, ansv);
}

