ll dfs(ll pos, ll par, ll dpt, P cent) {
	ll sum=0;
	ll ret=dpt;
	REP(i,(ll)adj[pos].size()) {
		if(adj[pos][i]==par) continue;
		if(adj[pos][i]==cent.first||adj[pos][i]==cent.second) continue;
		sum++;
		ret=max(ret,dfs(adj[pos][i],pos,dpt+1,cent));
	}
	maxdeg[dpt]=max(maxdeg[dpt],sum);
	return ret;
}

