using namespace std;

char buf[1000000], *p1 = buf, *p2 = buf;
inline char gc() {
  if (p1 == p2) p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin);
  return p1 == p2 ? EOF : *(p1++);
}
template <class T> inline void read(T &n) {
  n = 0; RI ch = gc(), f;
  while ((ch < '0' || ch > '9') && (ch != '-')) ch = gc();
  f = (ch == '-' ? ch = gc(), -1 : 1);
  while (ch >= '0' && ch <= '9') n = n * 10 + (ch ^ 48), ch = gc();
  n *= f;
}

int const MAXN = 105;
struct Edges { int to, next; } e[MAXN * 2];
int head[MAXN], tot;
int dep[MAXN], Maxson[MAXN];

inline void addedge(int from, int to) {
  e[++tot] = (Edges){to, head[from]};
  head[from] = tot;
  e[++tot] = (Edges){from, head[to]};
  head[to] = tot;
}

void Dfs(int now, int fa, int d) {
  int cnt = 0;
  dep[now] = d;
  for (RI i = head[now]; i; i = e[i].next)
    if (e[i].to != fa)
      Dfs(e[i].to, now, d + 1), ++cnt;
  Maxson[dep[now]] = max(Maxson[dep[now]], cnt);
}

