  LL ans1 = 0x7f7f7f7f7f7f7f7f, ans2 = 0x7f7f7f7f7f7f7f7f;
  for (RI i = 1; i <= n; ++i) {
    memset(Maxson, 0, sizeof(Maxson));
    Dfs(i, 0, 1);
    LL Leaf = 1, Maxdep = 1;
    for (RI j = 1; j <= n; ++j)
      if (Maxson[j]) Leaf *= Maxson[j], Maxdep = j + 1;
      else break;
    if (Maxdep < ans1) ans1 = Maxdep, ans2 = Leaf;
    if (Maxdep == ans1) ans2 = min(ans2, Leaf);
  }
  for (RI i = 1; i <= n; ++i)
    for (RI j = head[i]; j; j = e[j].next) {
      memset(Maxson, 0, sizeof(Maxson));
      Dfs(i, e[j].to, 1), Dfs(e[j].to, i, 1);
      LL Leaf = 2, Maxdep = 1;
      for (RI k = 1; k <= n; ++k)
        if (Maxson[k]) Leaf *= Maxson[k], Maxdep = k + 1;
        else break;
      if (Maxdep < ans1) ans1 = Maxdep, ans2 = Leaf;
      if (Maxdep == ans1) ans2 = min(ans2, Leaf);
    }
  printf("%lld %lld\n", ans1, ans2);

  cerr << (double)(clock()) / CLOCKS_PER_SEC * 1000 << "ms" << endl;

  return 0;
}

