inline void up(int &x, int y) { x = max(x, y); }

int dp(int v, int p = 0){
	int an = 1;
	f(i, 0, tr[v].size()){
		int u = tr[v][i];
		if (u == p)continue;
		an = max(an, 1 + dp(u, v));
	}
	return an;
}

void as(int v, bool ff = false, int p = 0, int dp = 0){
	if (ff && dp == 0)up(mxs[dp], (int)tr[v].size());
	else up(mxs[dp], (int)tr[v].size() - 1);
	f(i, 0, tr[v].size()){
		int u = tr[v][i];
		if (u == p)continue;
		as(u, ff, v, dp + 1);
	}
}

ll sn(){
	f(i, 0, n)mxs[i] = 0;
	ll an = 1;
	as(r[0], true);
	f(i, 0, mx - 1)an *= mxs[i];
	return an;
}

ll db(int a, int b){
	f(i, 0, n)mxs[i] = 0;
	ll an = 2;
	as(a, false, b);
	as(b, false, a);
	int lm = mx;
	if ((int)r.size() == 2)--lm;
	f(i, 0, lm - 1)an *= mxs[i];
	return an;
}

