	for (int i = 0; i < (int)vec[v].size(); i++) {
		if (vec[v][i] == p)continue;
		pair<int, int> q = dfs(vec[v][i], v);
		if (ma < q.first)ma = q.first, k = q.second;
	}
	return make_pair(ma + 1, k);
}

void dfs2(int v, int p, int k) {
	int cnt = 0;
	for (int i = 0; i < (int)vec[v].size(); i++) {
