LL n,tot,dep,ans1,ans2,head[N],x[N],y[N],f[N],g[N],d[N];
struct edge{LL v,nxt;}e[N];

void add(LL x,LL y){e[++tot].v=y; e[tot].nxt=head[x]; head[x]=tot;}

void dfs(LL u,LL fa){
	LL num=0; dep=max(dep,d[u]);
	for (LL i=head[u],v;i;i=e[i].nxt)
		if ((v=e[i].v)!=fa){d[v]=d[u]+1; dfs(v,u); ++num;}
	++f[d[u]]; g[d[u]]=max(g[d[u]],num);
}

