	for (LL i=1;i<=n;++i){
		memset(f,0,sizeof f); memset(g,0,sizeof g);
		dep=0; d[i]=1; dfs(i,0);
		if (dep>n/2+2) continue;
		for (LL j=n;j;--j)
			if (g[j]&&g[j+1]) g[j]=g[j]*g[j+1];
		if (dep<ans1){ans1=dep; ans2=g[1];}
