#include <iostream>
#include <algorithm>
#include <vector>
#include <map>
using namespace std;

int n;
vector<int> G[100];

int DFS(int from, int prev) {
  int mx = 0;
  for (int to : G[from]) {
    if (to == prev) continue;
    mx = max(mx, DFS(to, from) + 1); 
  }
  return mx;
}

vector<int> centers() {
  map<int, vector<int>> mp;
  for (int i = 0; i < n; ++i) {
    int dist = DFS(i, -1);
    mp[dist].push_back(i);
  }
  cout << mp.begin()->first + (mp.begin()->second.size() == 1) << ' ';
  return mp.begin()->second;
}

int D[100];
int C[100];
void cat(int from, int prev, int depth) {
  D[from] = depth;
  int cnt = 0;
  for (int to : G[from]) {
    if (to == prev) continue;
    ++cnt;
    cat(to, from, depth + 1);
  }
  C[from] = cnt;
}

long sub(vector<int> cs) {
  if (cs.size() == 1) {
    cat(cs[0], -1, 0);
  } else {
    cat(cs[0], cs[1], 0);
    cat(cs[1], cs[0], 0);
  }
  map<int, int> mp;
  for (int i = 0; i < n; ++i) {
    mp[D[i]] = max(mp[D[i]], C[i]);
  }

  long ans = 1;
  for (auto p : mp) {
    ans *= p.second == 0 ? 1 : p.second;
  }
  return ans * cs.size();
}

int main() {
  cin >> n;
  for (int i = 1; i < n; ++i) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  vector<int> cs = centers();

  long ans;
  if (cs.size() == 1) {
    ans = sub(cs);
    for (int to : G[cs[0]]) {
      vector<int> v(cs);
      v.push_back(to);
      ans = min(ans, sub(v));
    }
  } else {
    ans = sub(cs);
  }
  cout << ans << endl;
}

