void bfs(vector<vector<int>> connect, int n, vector<int> v, vector<int> &dist)
{
    vector<int> search, new_search;
    int t;
    fill(dist.begin(), dist.end(), -1);
    t = 0;
    search = v;

    for (int i : v)
    {
        dist[i] = t;
    }

    while (!search.empty())
    {
        t++;
        for (auto i : search)
        {
            for (auto j : connect[i])
                if (dist[j] == -1)
                {
                    new_search.push_back(j);
                    dist[j] = t;
                }
        }

        search.clear();
        search = new_search;
        new_search.clear();
    }
}

ll bfs2(vector<vector<int>> connect, int n, vector<int> degree, vector<int> v)
{
    ll ret = v.size();
    vector<int> search, new_search;
    int t, check[n];
    fill(check, check + n, 0);

    search = v;

    for (int i : v)
    {
        check[i]++;
    }

    while (!search.empty())
    {
        t = 0;
        for (auto i : search)
        {
            if (ret > 1)
                t = max(degree[i] - 1, t);
            else
                t = degree[i];

            for (auto j : connect[i])
                if (!check[j])
                {
                    new_search.push_back(j);
                    check[j]++;
                }
        }

        if (t)
            ret *= t;

        search.clear();
        search = new_search;
        new_search.clear();
    }
    return ret;
}

