signed main() {
  cin.tie(0);
  ios::sync_with_stdio(0);
  int N;
  cin >> N;
  vector<int> tree[2 * N];
  int dummy = N;
  for (int i = 0; i < N - 1; i++) {
    int a, b;
    cin >> a >> b;
    a--, b--;
    int mid = dummy++;
    tree[a].push_back(mid);
    tree[mid].push_back(a);
    tree[b].push_back(mid);
    tree[mid].push_back(b);
  }
  auto solve = [&](int center) {
    long long depth = 1, leaves = tree[center].size();
    bool used[dummy];
    fill(used, used + dummy, false);
    used[center] = true;
    vector<int> vs;
    for (int v : tree[center]) vs.push_back(v);
    while (!vs.empty()) {
      depth++;
      vector<int> next;
      long long deg = 1;
      for (int v : vs) {
        used[v] = true;
        for (int u : tree[v])
          if (!used[u]) {
            next.push_back(u);
          }
        deg = max(deg, (long long)tree[v].size() - 1);
      }
      leaves *= deg;
      vs.swap(next);
    }
    return make_pair((depth + 1) / 2, leaves);
  };
  long long color = LLONG_MAX, leaves = 0;
  for (int i = 0; i < dummy; i++) {
    if (tree[i].size() == 1) continue;
    auto [c, l] = solve(i);
    // debug(i);
    // debug(c);
    // debug(l);
    // cerr << "\n";
    if (color > c) {
      color = c;
      leaves = l;
    } else if (color == c && leaves > l) {
      leaves = l;
    }
  }
  cout << color << " " << leaves << '\n';
  return 0;
}

