  }
  i64 y = g[u].size();
  for (i64 i = 1; i < n; ++i) {
    if (deg[i] >= 2) y *= deg[i] - 1;
  }
  return y;
}

i64 f(i64 u, i64 v) {
  auto z = g;
  z[u].erase(find(begin(z[u]), end(z[u]), v));
  z[v].erase(find(begin(z[v]), end(z[v]), u));
  z[u].push_back(0);
  z[v].push_back(0);
  z[0].push_back(u);
  z[0].push_back(v);
  return h(z, 0);
}

int main() {
  cin >> n;
  init_n(g, n + 2);
  for (i64 i = 0; i < n - 1; ++i) {
    i64 u, v; cin >> u >> v;
    g[u].push_back(v);
    g[v].push_back(u);
  }

  vector<pair<i64, i64>> dg;
  for (i64 u = 1; u <= n; ++u) {
    dg.emplace_back(far(u, -1), u);
  }
  sort(begin(dg), end(dg));

  i64 y = 0, rad = dg[0].first, col, c = dg[0].second, c2 = dg[1].second;
  if (dg[0].first == dg[1].first) {
    col = rad;
    y = f(c, c2);
  } else {
    col = rad + 1;
    y = h(g, c);
    for (i64 v : g[c]) {
      y = min(y, f(c, v));
    }
  }

  cout << col << ' ' << y << '\n';
  return 0;
}

