const ull INF = (1ull << 63) + 500;

ull mul(ull a, ull b) {
    if  (a >= INF || b >= INF) {
        return INF;
    }
    ull c = a * b;
    if  (c >= INF || c / a != b || INF / a + 1 < b) {
        return INF;
    }
    return c;
}

ull go(const vector<pii>& vers, ull ones) {
    int mx = 0;
    vector<pii> nvers;
    int sum_degs = 0;
    for (const auto& ver : vers) {
        int cur = 0;
        for (int to : g[ver.fst]) {
            if  (to != ver.snd) {
                ++cur; 
                nvers.pb(mp(to, ver.fst));
            }
        }
        mx = max(mx, cur);
        sum_degs += cur;
    }
    if  (mx == 0) {
        assert(nvers.empty());
        return ones + sz(vers);
    }
    ull nxt = mul(ones + sz(vers), mx);
    if  (nxt >= INF) {
        return INF;
    }
    nxt -= sum_degs;
    return go(nvers, nxt);
}

int go_par(int v, int cnt) {
    assert(v != -1);
    if  (cnt == 0) {
        return v;
    }
    return go_par(par[v], cnt - 1);
}

pair<int, ull> solve_old() {
    par.assign(n, -1);
    int a = most_from(0).fst;
    int b, diam;
    tie(b, diam) = most_from(a);

    eprintf("a = %d, b = %d, diam = %d\n", a + 1, b + 1, diam);

    const int colors = (diam + 1 + 1) / 2;

    int bb = go_par(b, diam / 2);
    int aa = go_par(b, (diam + 1) / 2);

    ull cnt = 0;
    if  (aa == bb) {
        cnt = go(vector<pii>{{aa, -1}}, 0ll);
    } else {
        cnt = go(vector<pii>{{aa, bb}, {bb, aa}}, 0ll);
    }

    eprintf("aa = %d, bb = %d, cnt = %llu\n", aa + 1, bb + 1, cnt);
    return mp(colors, cnt);
}

void solve() {
    pair<int, ull> ans(n + 10, 0);
    ans = min(ans, solve_old());
    forn(v, n) {
        if  (sz(g[v]) == 1) {
            int nv = n++;
            g[v].pb(nv);
            g.pb({});
            g[nv].pb(v);

            eprintf("\nattach %d to %d\n", nv + 1, v + 1);

            auto cur = solve_old();
            ans = min(ans, cur);

            --n;
            g.pop_back();
            g[v].pop_back();
        }
    }

    cout << ans.fst << " " << ans.snd << endl;
}

