using namespace std;
typedef long long ll;
const ll N = 105, inf = 9e18;

ll n, l, d[N], d2[N], mx[N], ans = inf;

vector<ll> adj[N], p;

void getd (ll D[], ll C, ll P) {
	D[C] = D[P] + 1;
	for(auto &T : adj[C]) {
		if(T == P) continue;
		getd(D, T, C);
	}
}

pair<ll,ll> mxd (ll I) {
	getd(d, I, 0);
	pair<ll,ll> R = {-1, -1};
	for(ll i=1;i<=n;i++) {
		R = max(R, {d[i], i});
	}
	return R;
}

bool getp (ll C, ll P, ll O) {
	if(C == O) {
		p.push_back(C);
		return true;
	}
	for(auto &T : adj[C]) {
		if(T == P) continue;
		if(getp(T, C, O)) {
			p.push_back(C);
			return true;
		}
	}
	return false;
}

void solve () {
	ll A = mxd(1).Y, B = mxd(A).Y;
	p.clear();
	getp(A, 0, B);
	getd(d, p[(int)p.size()/2], 0);
	getd(d2, p[((int)p.size()-1)/2], 0);
	fill(mx+1, mx+1+n, 0);
	for(ll i=1;i<=n;i++) {
		ll I = min(d[i],d2[i]);
		mx[I] = max(mx[I],(ll)adj[i].size());
	}
	ll T;
	if((int)p.size()%2) T = mx[1];
	else T = (mx[1]-1)*2;
	for(ll i=2;i<((int)p.size()+1)/2;i++) {
		T *= mx[i] - 1;
	}
	ans = min(ans, T);
}

int main()
{
	scanf("%lld",&n);
	if(n == 2) {puts("1 2"); return 0;}
	for(ll i=1;i<n;i++) {
		ll A, B;
		scanf("%lld%lld",&A,&B);
		adj[A].push_back(B);
		adj[B].push_back(A);
	}
	l = mxd(mxd(1).Y).X;
	solve();
	if(l%2) {
		for(ll i=1;i<=n;i++) {
			if(mxd(i).X != l) continue;
			n++;
			adj[i].push_back(n);
			adj[n].push_back(i);
			solve();
			adj[i].pop_back();
			adj[n].pop_back();
			n--;
		}
	}
	printf("%lld %lld\n",(l+1)/2,ans);
}

