void get_out(int s, int ignore, int out[100])
{
	if (s < 0) return;

	bool flg[100] = {};
	queue<int> q;
	q.push(s);
	flg[s] = true;

	int loop = 0;
	while (q.size() > 0)
	{
		int q_cnt = q.size();
		REP(i, q_cnt)
		{
			int n = q.front();
			q.pop();
			int l_size = 0;
			for (int l : link[n])
			{
				if (!flg[l] && l != ignore)
				{
					l_size++;
				}
			}
			out[loop] = MAX(out[loop], l_size);
			for (int a : link[n])
			{
				if (!flg[a] && a != ignore)
				{
					flg[a] = true;
					q.push(a);
				}
			}
		}
		loop++;
	}
}

