{
	int a_out[100] = {};
	int b_out[100] = {};
	get_out(a, b, a_out);
	get_out(b, a, b_out);
	int ret = 1;
	for (int i = 0; i < N; i++)
	{
		int a = MAX(a_out[i], 1);
		int b = MAX(b_out[i], 1);
		int c = MAX(a, b);
		ret *= c;
	}
	return ret;
}

