int main() {
    int N;
    RI(N);
    adj.resize(N+1);
    parent.resize(N+1);
    height.resize(N+1);
    REP(i, N-1) {
        DRI(a, b);
        adj[a].PB(b);
        adj[b].PB(a);
    }
    dfs(1, 0, 0);
    int a = deepest.Y;
    deepest = MP(-1, 0);
    dfs(a, 0, 0);
    int d = deepest.X, b = deepest.Y, m = b;
    REP(i, (d-1)/2) {
        // One before the centroid
        m = parent[m];
    }
    unsigned long long ans = ULLONG_MAX;
    auto update = [&ans](unsigned long long prod) {
        for (int br : branches) {
            if (br == 0) break;
            prod *= br;
        }
        ans = min(ans, prod);
    };
    if (d % 2) {
        branches = VI(N+1);
        dfs2(m, parent[m], 0);
        dfs2(parent[m], m, 0);
        update(2);
    } else {
        branches = VI(N+1);
        m = parent[m];
        dfs2(m, 0, 0);
        update(1);

        dfs3(m, 0);
        for (int ch : adj[m]) {
            if (height[ch] == height[m] - 1) {
                branches = VI(N+1);
                dfs2(m, ch, 0);
                dfs2(ch, m, 0);
                update(2);
            }
        }
    }
    printf("%d %llu\n", d/2 + 1, ans);
    return 0;
}

