int mxdeg[MAXN],mxdep;

void go(int at,int par,int dep) {
	mxdep=max(dep,mxdep);
	int deg=SZ(adj[at])-(par==-1?0:1);
	mxdeg[dep]=max(mxdeg[dep],deg);
	REPSZ(i,adj[at]) {
		int to=adj[at][i]; if(to==par) continue;
		go(to,at,dep+1);
	}
}

pair<int,ll> calc(int a,int b) {
	//printf("solve(%d",a+1); if(b!=-1) printf(",%d",b+1); printf("):"); REPE(i,mxdep) printf(" %d",mxdeg[i]); puts("");
	ll nleaf=b==-1?1:2; REP(i,mxdep) nleaf*=mxdeg[i];
	return MP(mxdep+1,nleaf);
}

pair<int,ll> solve(int a) {
	mxdep=0; memset(mxdeg,0,sizeof(mxdeg));
	go(a,-1,0);
	return calc(a,-1);
}

pair<int,ll> solve(int a,int b) {
	mxdep=0; memset(mxdeg,0,sizeof(mxdeg));
	go(a,b,0);
	go(b,a,0);
	return calc(a,b);
}

