using namespace std;
queue<int> q;
void process(){
    memset(mx,0,sizeof(mx));
    while (q.size()){
        int u = q.front(); q.pop();
        for (auto v : adjlist[u]){
            if (d[v] == -1){
                d[v] = d[u]+1;
                mx[d[v]] = max(mx[d[v]],(int)adjlist[v].size()-1);
                q.push(v);
            }
        }
    }
}
