int g(int x, int p){
    int r = 1;
    for(int i : e[x]) if(i != p) r = max(r, g(i, x) + 1);
    return r;
}

void h(int x, int p, int d){
    l[d] = max(l[d], int(e[x].size()) - (!!p));
    for(int i : e[x]) if(i != p) h(i, x, d + 1);
}

ll f(int x, int y){
    ll t = 1 + (!!y);
    h(x, y, 0);
    if(y) h(y, x, 0);
    for(int i = 0; l[i]; i++){
        t *= l[i];
        l[i] = 0;
    }
    return t;
}

