    max_deg[lvl] = max(max_deg[lvl], (int) adj[vertex].size() - 1);
  }

  for (int nxt : adj[vertex]) {
    if (nxt != parent) {
      calc_max_deg(nxt, vertex, lvl + 1);
    }
  }
}

