		g[b].push_back(a);
		edge[i]=PII(a,b);
	}
	PLL ans=PLL(INF, INF);
	REP(i,n)
	{
		vector<int> child(n);
		function<void(int,int,int)> dfs=[&](int v,int pv, int dep)
		{
			if(pv==-1)
			chmax(child[dep], (int)(g[v].size()));
			else
			chmax(child[dep], (int)(g[v].size()-1));
			for(auto&& e:g[v])
			{
				if(e==pv) continue;
				dfs(e, v, dep+1);
			}
		};
		dfs(i,-1,0);

		LL s=1,d=0;
		REP(i,n)
		{
			if(child[i]==0)
				break;
			d=i;
			s*=child[i];
		}
		chmin(ans, PLL(d+2,s));
	}
	REP(i,n-1)
	{
		vector<int> child(n);
		function<void(int,int,int)> dfs=[&](int v,int pv, int dep)
		{
			chmax(child[dep], (int)(g[v].size()-1));
			for(auto&& e:g[v])
			{
				if(e==pv) continue;
				dfs(e, v, dep+1);
			}
		};
		dfs(edge[i].first,edge[i].second,0);
		dfs(edge[i].second,edge[i].first,0);

		LL s=2,d=0;
		REP(i,n)
		{
			if(child[i]==0)
				break;
			d=i;
			s*=child[i];
		}
		chmin(ans, PLL(d+2,s));
	}
	print(ans.first, ans.second);
}

