const int64_t inf = (1LL << 60);

int maxChildren_[100];
vector<int> g_[100];
int depth_;

void DFS(int u, int par, int dep) {
    depth_ = max(depth_, dep);

    int num = 0;
    for (int to : g_[u]) {
        if (to == par) continue;
        num++;
        DFS(to, u, dep + 1);
    }
    maxChildren_[dep] = max(maxChildren_[dep], num);
}

int64_t countLeaves() {
    int64_t num = 1;
    for (int dep = depth_ - 1; dep >= 0; dep--) {
        num = min(inf, num * maxChildren_[dep]);
    }
    return num;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;

    vector<int> a(n - 1), b(n - 1);
    repeat (i, n - 1) {
        cin >> a[i] >> b[i];
        a[i]--; b[i]--;

        g_[a[i]].push_back(b[i]);
        g_[b[i]].push_back(a[i]);
    }

    int64_t colorful = n,
            numLeaves = n;
    repeat (u, n) {
        memset(maxChildren_, 0, sizeof(maxChildren_));
        depth_ = 0;

        DFS(u, -1, 0);

        if (depth_ + 1 > colorful) continue;
        // 葉の数を数える
        int64_t num = countLeaves();

        if (depth_ + 1 == colorful and num < numLeaves) numLeaves = num;
        if (depth_ + 1 < colorful) {
            colorful = depth_ + 1;
            numLeaves = num;
        }
    }

    repeat (i, n - 1) {
        memset(maxChildren_, 0, sizeof(maxChildren_));
        depth_ = 0;

        DFS(a[i], b[i], 0);
        DFS(b[i], a[i], 0);

        if (depth_ + 1 > colorful) continue;

        int64_t num = 2 * countLeaves();

        if (depth_ + 1 == colorful and num < numLeaves) numLeaves = num;
        if (depth_ + 1 < colorful) {
            colorful = depth_ + 1;
            numLeaves = num;
        }
    }

