int a[123],b[123],dv[123],d[123],p[123],cnt[123];
std::vector<int> g[123];
std::queue<int> que;

P bfs(void){
	int u,v,j,i,m=0;
	ll ret = 1ll;
	std::fill(cnt,cnt+123,0);
	while(!que.empty()){
		u = que.front();
		que.pop(); i = 0;
		m = std::max(m,d[u]);
		for(j=(g[u].l_ength()-1); j>=0; --j){
			v = g[u][j];
			if(v==p[u]){
				continue;
			}
			p[v] = u;
			d[v] = d[u] + 1; ++i;
			que.push(v);
		}
		cnt[d[u]] = std::max(cnt[d[u]],i);
	}
	for(i=0; i<m; ++i){
		ret *= cnt[i];
	}
	return P(m+1,ret);
}

