int dmin[MAXN];
int mradius;

int radius (int cloc)
{
    int ans = 0;
    for (int i = 0; i < N; i++)
        ans = max (ans, edge[i][cloc]);
    return ans;
}

long long v;

void flood (int cloc, int last, int cdist)
{
    int deg = 0;
    for (int i = 0; i < N; i++)
        if (edge[i][cloc] == 1)
            deg++;

    if (cloc != last)
        deg--;

    dmin[cdist] = max (dmin[cdist], deg);
    for (int i = 0; i < N; i++)
    {
        if (edge[i][cloc] == 1 && i != last)
        {
            flood (i, cloc, cdist + 1);
        }
    }
}

long long get_res (int x, int y)
{
    for (int i = 0; i < MAXN; i++)
        dmin[i] = 0;
    flood (x, y, 0);
    flood (y, x, 0);

    long long ans = 1;
    for (int i = 0; i < mradius - 1; i++)
        ans *= dmin[i];
    return ans;
}

