    for(int i=0;i<leaf.size();i++){
        for(int j=i+1;j<leaf.size();j++){
            vector<int> path;
            setPath(leaf[j],-1,leaf[i],path,g);
            int m=path.size();
            if(M>m){
                int n=N;
                int diff=M-m;
                g.resize(n+diff);
                int pre=leaf[j];
                for(int k=0;k<diff;k++){
                    path.push_back(n+k);
                    g[pre].push_back(n+k);
                    g[n+k].push_back(pre);
                    pre=n+k;
                }   
                vector<int> d=getDiameter(g);
                if(d.size()==M){
                    auto tmp=calc(path,g);
                    chmin(res,tmp);
                }
                g.resize(n);
                g[leaf[j]].pop_back();

                g.resize(n+diff);
                pre=leaf[i];
                reverse(path.begin(),path.end());
                for(int k=0;k<diff;k++){
                    path.push_back(n+k);
                    g[pre].push_back(n+k);
                    g[n+k].push_back(pre);
                    pre=n+k;
                }   
                d=getDiameter(g);
                if(d.size()==M){
                    auto tmp=calc(path,g);
                    chmin(res,tmp);
                }
                g.resize(n);
                g[leaf[i]].pop_back();
            }else{
                auto tmp=calc(path,g);
                chmin(res,tmp);
            }
