    vector<int> vct;
    for (int cur = j; cur != -1; cur = pr[cur]) vct.push_back(cur);*/

    pair<int, ll> ans = make_pair(INF, INF);

    auto solve = [&](int root, int sub) {
        d.assign(n + 1, -1);
        dfs1(root, 0, -1);

        vector<int> vct(n);
        iota(vct.begin(), vct.end(), 0);
        sort(vct.begin(), vct.end(), [&](int i, int j) {
            return d[i] > d[j];
        });

        vector<ll> dp(n);
        vector<vector<int>> mx(n, vector<int>(n, 0));
        for (int v : vct) {
            vector<int> cur(n);
            for (int to : e[v]) {
                if (d[to] > d[v]) {
                    cur[d[to]]++;
                }
            }
            for (int j = 0; j < n; j++) {
                mx[d[v]][j] = max(mx[d[v]][j], cur[j]);
            }
        }

        dp[d[vct[0]]] = 1;
        for (int i = d[vct[0]] - 1; i >= 0; i--) {
            for (int j = 0; j < n; j++) {
                dp[i] += dp[j] * mx[i][j];
            }
        }

        int res = d[vct[0]] + 1;
        res -= sub;
        ans = min(ans, make_pair(res, dp[0]));
    };

    auto addEdge = [&](int u, int v) {
        e[u].erase(find(e[u].begin(), e[u].end(), v));
        e[v].erase(find(e[v].begin(), e[v].end(), u));

        e[u].push_back(n);
        e[n].push_back(u);
        e[v].push_back(n);
        e[n].push_back(v);
        n++;
        solve(n-1, 1);
        n--;
        e[u].pop_back();
        e[v].pop_back();
        e[n].pop_back();
        e[n].pop_back();

        e[u].push_back(v);
        e[v].push_back(u);
    };

    for (int i = 0; i < n; i++) solve(i, 0);
    for (int i = 0; i < n; i++) for (int to : e[i]) addEdge(i, to);


    return ans;
};

