template<class T> void ReadInteger(T & x) {
    x = 0;
    int f = 1, ch = getchar();
    while(ch < '0' || ch > '9') {
        if(ch == '-') f = -1;
        ch = getchar();
    }
    while(ch >= '0' && ch <= '9') {
        x = x * 10 - '0' + ch;
        ch = getchar();
    }
    x *= f;
}

typedef long long LL;

int N;
int head[205], ecnt;
queue< pair<int, int> > q;

struct edge {
    int to, nex;
};
edge G[205];
inline void addedge(int u, int v) {
    G[ecnt] = (edge) {v, head[u]};
    head[u] = ecnt++;
    G[ecnt] = (edge) {u, head[v]};
    head[v] = ecnt++;
}

int dep[205], anc[205], d;
void DFS(int u, int step) {
    dep[u] = step;
    if(step > dep[d]) d = u;
    for(int i = head[u]; ~ i; i = G[i].nex) {
        int v = G[i].to;
        if(v != anc[u]) {
            anc[v] = u;
            DFS(v, step + 1);
        }
    }
}

int cnt[205], vis[205];
LL BFS(int st, int f) {
    memset(cnt, 0, sizeof(cnt));
    memset(vis, 0, sizeof(vis));
    q.push(make_pair(st, 1)), cnt[1]++, vis[st] = 1;
    if(anc[st] && f) q.push(make_pair(anc[st], 1)), cnt[1]++, vis[ anc[st] ] = 1;
    while(!q.empty()) {
        int u = q.front().first;
        int d = q.front().second;
        vis[u] = 1;
        q.pop();
        int deg = 0;
        for(int i = head[u]; ~ i; i = G[i].nex) {
            int v = G[i].to;
            if(!vis[v]) {
                q.push(make_pair(v, d + 1));
                deg++;
            }
        }
        cnt[d + 1] = max(cnt[d + 1], deg);
    }
    /*cout << "DEBUG " << st << ' ' << anc[st] << endl;*/
    long long res = 1;
    for(int i = 1; i <= N; i++) if(cnt[i]) {
        /*cout << i << ' ' << cnt[i] << endl;*/
        res *= cnt[i];
    }
    return res;
}

void Solve() {
    DFS(1, 1);
    memset(anc, 0, sizeof(anc));
    DFS(d, 1);
    long long ans;
    if(~ dep[d] & 1) {
        int u = d;
        for(int i = 1; i <= dep[d] / 2; i++) u = anc[u];
        ans = BFS(u, 1);
    }
    else {
        int u = d;
        for(int i = 1; i < dep[d] / 2; i++) u = anc[u];
        ans = min(BFS(anc[u], 0), min(BFS(u, 1), BFS(anc[u], 1)));
    }
    printf("%d %lld\n", (dep[d] + 1) >> 1, ans);
}
int main() {
    ReadInteger(N);
    memset(head, -1, sizeof(head));
    for(int i = 1; i < N; i++) {
        int u, v;
        ReadInteger(u);
        ReadInteger(v);
        addedge(u, v);
    }
    Solve();
    return 0;
}

#include <bits/stdc++.h>
