typedef long long ll;
const int BASE = 100000000;

struct BigInt
{
	vector <int> a;
	BigInt () : a() {}
	BigInt (ll x)
	{
		if (x == 0)
			a.push_back(0);
		while (x > 0)
		{
			a.push_back(x % BASE);
			x /= BASE;
		}
	}
	BigInt (int x)
	{
		if (x == 0)
			a.push_back(0);
		while (x > 0)
		{
			a.push_back(x % BASE);
			x /= BASE;
		}
	}
	BigInt operator * (int x)
	{
		BigInt res = BigInt();
		ll z = 0;
		for (int i = 0; i < (int)a.size() || z; i++)
		{
			res.a.push_back(0);
			ll nVal = z + (ll)(i < (int)a.size() ? a[i] : 0) * x;
			z = nVal / BASE;
			res.a[i] = nVal % BASE;
		}
        while ((int) res.a.size() > 0 && res.a.back() == 0)
            res.a.pop_back();
		return res;
	}
    BigInt operator + (const BigInt &x)
	{
		BigInt res = BigInt();
		int z = 0;
		int mx = max((int)x.a.size(), (int)a.size());
		for (int i = 0; i < mx || z; i++)
		{
			if ((int)res.a.size() == i)
				res.a.push_back(0);
			res.a[i] = (i < (int)a.size() ? a[i] : 0) + (i < (int)x.a.size() ? x.a[i] : 0) + z;
			if (res.a[i] >= BASE)
			{
				z = 1;
				res.a[i] -= BASE;
			}
			else
				z = 0;
		}
		return res;
	}
	bool operator > (const BigInt &x) const
	{
		return x < *this;
	}
	bool operator < (const BigInt &x) const
	{
		if (a.size() != x.a.size())
			return a.size() < x.a.size();
		for (int i = (int)a.size() - 1; i >= 0; i--)
		{
			if (a[i] != x.a[i])
				return a[i] < x.a[i];
		}
		return false;
	}
	void print()
	{
        while ((int) a.size() > 0 && a.back() == 0) a.pop_back();
		printf("%d", a[(int)a.size() - 1]);
		for (int i = (int)a.size() - 2; i >= 0; i--)
			printf("%08d", a[i]);
	}
};


const int N = 105;
vector <int> g[N];
int d[N], par[N];

void dfs(int v, int p, int cd)
{
    par[v] = p;
    d[v] = cd;
    for (int to : g[v] )
    {
        if (to == p) continue;
        dfs(to, v, cd + 1);
    }
}

BigInt solve(vector <int> v, BigInt cnt, bool fl = false)
{
 //   eprintf("----\n");
    vector <int> nv;
    int mx = 0, cz = 0;
    for (int x : v)
    {
        int cur = 0;
        for (int nx : g[x] )
        {
            if (nx == par[x] ) continue;
            if (g[nx].size() == 1 && fl)
            {
                cz++;
                continue;
            }
            cur++;
            nv.push_back(nx);
        }
        mx = max(mx, cur);
    }
    eprintf("fl = %d, cz = %d\n", fl, cz);
    if (mx == 0) return BigInt(cnt) + BigInt(cz);
    if (fl)
        return solve(nv, mx) + BigInt(cz);
    return solve(nv, cnt * mx);
}

