inline void addEdge(int x, int y) {
  nxt[cnt] = pre[x];
  ++d[to[pre[x] = cnt++] = y];
  nxt[cnt] = pre[y];
  ++d[to[pre[y] = cnt++] = x];
}

inline int readInt() {
  int ans = 0, c, f = 1;
  while (!isdigit(c = getchar()))
    if (c == '-') f *= -1;
  do ans = ans * 10 + c - '0';
  while (isdigit(c = getchar()));
  return ans * f;
}

int n;
int ans1;
LL ans2;

void Calc(int x, int y = -1) {
  static bool vis[N];
  static int _p[2][N];
  memset(vis, 0, sizeof vis);
  int *p = _p[0], *p2 = _p[1];
  int m = 0, m2 = 0;
  vis[p[m++] = x] = true;
  if (y >= 0) vis[p[m++] = y] = true;
  LL ans = m;
  int len = 0;
  while (m > 0) {
    ++len;
    int k = 1;
    m2 = 0;
    for (int i = 0; i < m; ++i) {
      int z = p[i], t = 0;
      for (int j = pre[z]; j >= 0; j = nxt[j])
        if (!vis[to[j]])
          ++t, vis[p2[m2++] = to[j]] = true;
      k = std::max(k, t);
    }
    std::swap(p2, p);
    m = m2;
    ans *= k;
  }
  if (ans1 > len || (ans1 == len && ans2 > ans)) {
    ans1 = len;
    ans2 = ans;
  }
}

int main() {
  n = readInt();
  memset(pre, -1, sizeof pre);
  for (int i = 1; i < n; ++i)
    addEdge(readInt(), readInt());
  ans2 = ans1 = n;
  for (int x = 1; x <= n; ++x) {
    Calc(x);
    for (int i = pre[x]; i >= 0; i = nxt[i])
      if (to[i] > x)
        Calc(x, to[i]);
  }
  printf("%d %lld\n", ans1, ans2);
  return 0;
}

