using namespace std;

const int N = 105;
const long long inf = 8e18;

inline long long mul(long long x, long long y) {
  if (inf / x < y) return inf;
  else return x * y;
}

vector<int> g[N];

int dist[N];
int mx[N];
int n;

pair<int, long long> Solve(const vector<int> &a) {
  memset(dist, -1, sizeof dist);
  memset(mx, 0, sizeof mx);
  queue<int> que;
  for (int x : a) {
    dist[x] = 0;
    que.push(x);
    mx[0] = max(mx[0], (int) g[x].size() - (a.size() == 2));
  }
  int dep = 0;
  while (!que.empty()) {
    int v = que.front();
    que.pop();
    for (int to : g[v]) {
      if (dist[to] == -1) {
        dist[to] = dist[v] + 1;
        dep = max(dep, dist[to]);
        mx[dist[to]] = max(mx[dist[to]], (int) g[to].size() - 1);
        que.push(to);
      }
    }
  }
  long long res = (int) a.size();
  for (int i = 0; i < dep; i++) {
    res = mul(res, mx[i]);
  }
  return {dep, res};
}

