  for (int i = 1; i < n; ++i) {
    int a, b;
    scanf("%d%d", &a, &b);
    --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  pair<int, __int128> ans = Solve();
  for (int i = 0; i < n; ++i) {
    g[i].push_back(n);
    g[n].push_back(i);
    ans = min(ans, Solve());
    g[i].pop_back();
    g[n].pop_back();
  }
  printf("%d %lld\n", ans.first, (long long)ans.second);
  return 0;
}

