int d[1000];

void dfs(int v, int p, int dep, const vvi& g) {
  d[v] = dep;
  assert(v < g.size());
  for (int nv : g[v]) {
    if (nv == p) continue;
    dfs(nv, v, dep + 1, g);
  }
}

int solve(const vvi & g, int root) {
  dfs(root, -1, 0, g);
  vl sz(g.size());
  for (int t = g.size() - 1; t >= 0; --t) {
    int maxdeg = -1;
    for (int i = 0; i < (int)g.size(); ++i) if (d[i] == t) {
      maxdeg = max(maxdeg, (int)g[i].size());
    }
    if (t) --maxdeg;
    if (maxdeg < 0) continue;
    sz[t] = sz[t + 1] * maxdeg;
    if (maxdeg == 0) {
      sz[t]++;
    }
  }
  return sz[0];
}

