	for (int u:v[node])
	{
		if (u!=p)
		ret=max(ret,get(u,node));
	}
	ret.first++;
	return ret;
}
bool dfs(int node,int p,int e)
{
	if (node==e)
	{
		d.push_back(node);
		return 1;
	}
	for (int u:v[node])
	{
		if (u!=p && dfs(u,node,e))
		{
			d.push_back(node);
			return 1;
		}
	}
	return 0;
}
void go(int node,int p,int dep)
{
	int c=0;
	for (int u:v[node])
	{
		if (u!=p)
		{
			c++;
			go(u,node,dep+1);
		}
	}
	mx[dep]=max(mx[dep],c);
}
long long calc(int h)
{
	long long l=1;
	for (int i=0;i<h-1;i++)
	l*=mx[i];
	return l;
}
