void rec(int c, int p, int d = 0){
	depth[c] = d;
	vs[d].pb(c);
	for(int i : e[c]) if(i != p) rec(i, c, d + 1);
}
pi dia(int c, int p, int d = 0){
	depth[c] = d;
	pi f(0, c);
	for(int i : e[c]) if(i != p){
		pi x = dia(i, c, d + 1);
		if(f.first <= x.first) f = pi(x.first + 1, x.second);
	}
	return f;
}
pair<int, ll> solve(bool twice){
	ll ans = 0, size = 0;
	for(int i = (int)vs.size() - 2; i >= 0; i--){

		int mxc = 0, add = 0;
		for(int j : vs[i]){
			int cnt = 0;
			for(int k : e[j]) if(depth[k] == depth[j] + 1) cnt++;
			mxc = max(mxc, cnt);
		}
		if(i + 2 == vs.size()) size = 1;
		size = size * mxc;
		if(i == 0) ans = size;
	}
	if(twice) ans *= 2;

	for(auto &i : vs) i.clear();

	return pair<int, ll>(vs.size(), ans);
}
