vector<int> vertexs[200];
int distances[2000];
void dfs(int now, int back) {
	REP(q, vertexs[now].size()) {
		int go = vertexs[now][q];
		if (go == back) continue;
		distances[go] = distances[now] + 1;
		dfs(go, now);
	}
}
long long visited[2000] = {};
long long bobo[2000];
long long solve(long long a, long long b) {
	for (int i = 0; i < 2000; ++i) {
		visited[i] = 0;
		distances[i] = 0;
		bobo[i] = 0;
	}
	dfs(a, b);
	dfs(b, a);
	for (int i = 0;vertexs[i].size() != 0; ++i) {
		int hoge = 0;
		if (a != b||distances[i] !=0) {
			hoge = 1;
		}
		bobo[distances[i]] = max(bobo[distances[i]], (long long)vertexs[i].size() - hoge);
	}
	long long ans = 1;
	for (int i = 0; bobo[i] != 0; ++i) {
		if (ans >= 2e18/bobo[i]) {
			ans = 2e18;
		}
		else {
			ans *= bobo[i];
		}
	}
	if (a != b) {
		ans *= 2LL;
	}
	return ans;
}
