void dfs0(int v, int p) {
  par[v] = p;
  if (p == 0) h[v] = 0;
  else h[v] = h[p] + 1;

  for (auto u : G[v]) {
    if (u != p) dfs0(u, v);
  }
}

int znajdzNajdalszy() {
  int maxi = -1;
  for (int i = 1; i <= n; ++i) maxi = max(maxi, h[i]);
  for (int i = 1; i <= n; ++i) if (h[i] == maxi) return i;
  return 0;
}

vector <int> dp[N + 7];

void licz(int v, int p) {
  int sz = 1;

  for (auto u : G[v]) {
    if (u != p) {
      licz(u, v);
      sz = max(sz, 1 + (int) dp[u].size()); 
    }
  }

  dp[v].clear();
  dp[v].resize(sz, 0);

  for (auto u : G[v]) {
    if (u != p) {
      for (int i = 0; i < (int) dp[u].size(); ++i) {
        dp[v][i + 1] = max(dp[v][i + 1], dp[u][i]);
      }
    }
  }

  dp[v][0] = (int) G[v].size();
  if (p != 0) dp[v][0]--;
  if ((int) G[v].size() == 1) dp[v][0] = 1;
}

void usun(int u, int v) {
  G[u].erase(find(G[u].begin(), G[u].end(), v));
  G[v].erase(find(G[v].begin(), G[v].end(), u));
}

unsigned long long jebaj1(int v) {
  licz(v, 0);
  /*cout << "korzen = " << v << endl;
  for (int i = 1; i <= max(n, v); ++i) {
    cout << "i = " << i << ": ";
    for (auto u : dp[i]) cout << u << ' ';
    cout << endl;
  }*/
  unsigned long long res = 1;
  for (auto u : dp[v]) res *= u;
  return res;
}

unsigned long long jebaj2(int u, int v) {
  //cout << "usuwamy " << u << ' ' << v << endl;
  usun(u, v);

  G[n + 1].push_back(u);
  G[u].push_back(n + 1);

  G[n + 1].push_back(v);
  G[v].push_back(n + 1);

  unsigned long long res = jebaj1(n + 1);

  usun(n + 1, v);
  usun(n + 1, u);

  G[u].push_back(v);
  G[v].push_back(u);

  return res;
}

