    for (int d: range(0, N)) {
      for (int u: group[d]) {
        for (int v: graph[u]) {
          if (chmin(dist[v], d + 1)) {
            group[d + 1].push_back(v);
          }
        }
      }
    }
    return group;
  };
  auto solve = [&](const std::vector<std::vector<int>> &group) {
    int dist = 0;
    unsigned long long leaves = [&] {
      if (group[0].size() == 1) {
        return degree[group[0][0]];
      }
      else {
        return 2 * std::max(degree[group[0][0]] - 1, degree[group[0][1]] - 1);
      }
    }();
    for (int d: range(1, N)) {
      if (group[d].empty()) {
        break;
      }
      chmax(dist, d + 1);
      int max = 0;
      for (int u: group[d]) {
        chmax(max, degree[u]);
      }
      leaves *= std::max(1, max - 1);
    }
    return std::make_pair(dist, leaves);
  };
  std::pair<int, unsigned long long> ans(std::numeric_limits<int>::max(), std::numeric_limits<unsigned long long>::max());
  for (int u: range(0, N)) {
    chmin(ans, solve(bfs(u)));
  }
  for (auto e: range(0, N - 1)) {
    chmin(ans, solve(bfs(A[e], B[e])));
  }
  std::cout << ans.first << ' ' << ans.second << '\n';
}

