long long int INF = 1000000000000000000LL; // 10^18

typedef pair<int, int> P;

vector<int> E[200];

P far_v(int pre, int cur){
	P p;
	p.first = -1;
	p.second = cur;
	for(int i = 0; i < E[cur].size(); i++){
		if(E[cur][i] != pre){
			P p1 = far_v(cur, E[cur][i]);
			if(p1.first > p.first){
				p.first = p1.first;
				p.second = p1.second;
			}
		}
	}
	p.first++;
	return p;
}

void dist_v(int dist, int pre, int cur, int d[]){
	d[cur] = dist;
	for(int i = 0; i < E[cur].size(); i++){
		if(E[cur][i] != pre){
			dist_v(dist + 1, cur, E[cur][i], d);
		}
	}
}

int main(){

	int N;
	cin >> N;

	for(int i = 0; i < N - 1; i++){
		int u, v;
		cin >> u >> v;
		u--;
		v--;
		E[u].push_back(v);
		E[v].push_back(u);
	}

	P p = far_v(-1, 0);
	int Ru1 = p.second;
	p = far_v(-1, Ru1);
	int D = p.first;
	int Ru2 = p.second;

	int d1[200] = {};
	int d2[200] = {};

	dist_v(0, -1, Ru1, d1);
	dist_v(0, -1, Ru2, d2);

	int cent;
	vector<int> u_can;
	if(D % 2 == 0){
		for(int i = 0; i < N; i++){
			if(d1[i] + d2[i] == D && d1[i] == d2[i]){
				cent = i;
			}
		}
		u_can.push_back(cent);
		for(int i = 0; i < E[cent].size(); i++){
			u_can.push_back(E[cent][i]);
		}
	}else{
		for(int i = 0; i < N; i++){
			if(d1[i] + d2[i] == D && (d1[i] - d2[i]) * (d1[i] - d2[i]) == 1){
				u_can.push_back(i);
			}
		}

		cent = u_can[1];
		u_can.pop_back();
	}

	long long int ans = INF;
	for(int loop = 0; loop < u_can.size(); loop++){
		int v2 = u_can[loop];

		int du[200] = {};
		int dv[200] = {};

		dist_v(0, -1, cent, du);
		dist_v(0, -1, v2, dv);

		long long int v_dist[200] = {};
		for(int i = 0; i < N; i++){
			int ret = min(du[i], dv[i]);
			v_dist[ret] = max(v_dist[ret], (long long int)E[i].size());
		}

		long long int cnt = 1;
		for(int i = 0; i < N; i++){
			cnt *= max(1LL, v_dist[i] - 1);
		}
		if(cent != v2){
			cnt *= 2;
		}
		if(cent == v2){
			cnt /= v_dist[0] - 1;
			cnt *= v_dist[0];
		}
		ans = min(ans, cnt);
	}
	cout << D / 2 + 1 << " " << ans << endl;

	return 0;
}

