struct tree{
    size_t n,r,md;
    vector<vector<int>> e;
    vector<int> pa,d,sz;
    explicit tree(int n):n(n),e(n){}
    void built(bool f=true){
        static int a,b;
        fr(i,n-1){
            cin>>a>>b;
            if(f) --a,--b;
            add(a,b);
        }
    }
    void pbuilt(bool f=true){
        static int a;
        Fr(i,n-1){
            cin>>a;
            if(f) --a;
            add(a,i,false);
        }
    }
    void add(int a,int b,bool f=true){
        e[a].emplace_back(b);
        if(f) e[b].emplace_back(a);
    }
    void r_dfs(int i,int p=-1,int D=0){
        pa[i]=p;d[i]=D;md=max(md,(size_t)D);++D;
        for(auto j:e[i]) if(j!=p) r_dfs(j,i,D),sz[i]+=sz[j];
    }
    void r_i(int r_){
        pa.resize(n);d.resize(n);sz.resize(n,1),r=r_;md=0;
        r_dfs(r);
    }
};

void cent_dfs(tree&t,vector<int>&path,pair<int,int>&ans,int&D,int i,int pa=-1){
    path.push_back(i);
    if(path.size()>D){
        D=path.size();
        ans=make_pair(path[(D-1)/2],path[D/2]);
    }
    for(auto&j:t.e[i]) if(j!=pa) cent_dfs(t,path,ans,D,j,i);
    path.pop_back();
}
int DD{};
pair<int,int> cent(tree&t){
    int n=t.n;
    int D=-1,DL=-1;
    stack<pair<int,int>> q;
    t.r_i(0);
    fr(i,n) if(D<t.d[i]) D=t.d[i],DL=i;
    t.pa.assign(n,0);
    t.sz.clear();
    t.d.assign(n,0);
    pair<int,int> ans(-1,-1);
    vector<int> path;
    D=0;
    cent_dfs(t,path,ans,D,DL);
    DD=D;
    return ans;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n;
    cin>>n;
    tree t(n);
    t.built();
    auto cen=cent(t);
    vector<int> bra(DD/2+1,1);
    bool f=cen.first==cen.second;
    struct dfs{
        int i,pa,d;
    };
    stack<dfs> st;
    if(f) st.push(dfs{cen.first,-1,0});
    else{
        st.push(dfs{cen.first,cen.second,1});
        st.push(dfs{cen.second,cen.first,1});
        bra[0]=2;
    }
    while(!st.empty()){
        auto D=st.top();st.pop();
        chmax(bra[D.d],t.e[D.i].size()-(D.pa!=-1));
        for(auto&j:t.e[D.i]) if(j!=D.pa) st.push(dfs{j,D.i,D.d+1});
    }
    ll ans{1};
    for(auto&i:bra) ans*=i;
    if(f){
        for(auto&i:t.e[cen.first]){
            bra.assign((DD+1)/2+1,1);
            st.push(dfs{cen.first,i,1});
            st.push(dfs{i,cen.first,1});
            bra[0]=2;
            while(!st.empty()){
                auto D=st.top();st.pop();
                chmax(bra[D.d],t.e[D.i].size()-(D.pa!=-1));
                for(auto&j:t.e[D.i]) if(j!=D.pa) st.push(dfs{j,D.i,D.d+1});
            }
            ll tmp{1};
            for(auto&I:bra) tmp*=I;
            chmin(ans,tmp);
        }
    }
    cout<<(DD+1)/2<<" "<<ans<<endl;
}

