const int N = 105;
vector <int> g[N];
int d[N], par[N];

void dfs(int v, int p, int cd)
{
    par[v] = p;
    d[v] = cd;
    for (int to : g[v] )
    {
        if (to == p) continue;
        dfs(to, v, cd + 1);
    }
}

long long solve(vector <int> v, long long cnt)
{
 //   eprintf("----\n");
    vector <int> nv;
    int mx = 0;
    for (int x : v)
    {
        int cur = 0;
        for (int nx : g[x] )
        {
//            eprintf("%d -> %d\n", x, nx);
            if (nx == par[x] ) continue;
            cur++;
            nv.push_back(nx);
        }
        mx = max(mx, cur);
    }
    if (mx == 0) return (long long)(cnt);
    return solve(nv, cnt * mx);
}

