template <class T, class U>
inline bool chmin(T& lhs, const U& rhs) {
  if (lhs > rhs) {
    lhs = rhs;
    return true;
  }
  return false;
}

template <class T, class U>
inline bool chmax(T& lhs, const U& rhs) {
  if (lhs < rhs) {
    lhs = rhs;
    return true;
  }
  return false;
}

// [l, r) from l to r
struct range {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { ++i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr range(int l_, int r_): l(l_), r(std::max<int>(l_, r_)) { }
  constexpr itr begin() const { return l; }
  constexpr itr end() const { return r; }
};

// [l, r) from r to l
struct revrange {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { --i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr r, l;
  constexpr revrange(int l_, int r_): l(l_ - 1), r(std::max<int>(l_, r_) - 1) { }
  constexpr itr begin() const { return r; }
  constexpr itr end() const { return l; }
};

int main() {
  int N;
  std::cin >> N;
  std::vector<int> A(N - 1), B(N - 1);
  std::vector<std::vector<int>> graph(N);
  std::vector<int> degree(N);
  for (int i: range(0, N - 1)) {
    int a, b;
    std::cin >> a >> b;
    --a; --b;
    graph[a].push_back(b);
    graph[b].push_back(a);
    ++degree[a];
    ++degree[b];
    A[i] = a;
    B[i] = b;
  }
  auto bfs = [&](int u1, int u2 = -1) {
    std::vector<std::vector<int>> group(N);
    std::vector<int> dist(N, std::numeric_limits<int>::max());
    dist[u1] = 0;
    group[dist[u1]].push_back(u1);
    if (u2 != -1) {
      dist[u2] = 0;
      group[dist[u2]].push_back(u2);
    }
    for (int d: range(0, N)) {
      for (int u: group[d]) {
        for (int v: graph[u]) {
          if (chmin(dist[v], d + 1)) {
            group[d + 1].push_back(v);
          }
        }
      }
    }
    return group;
  };
  auto solve = [&](const std::vector<std::vector<int>> &group) {
    int dist = 1;
    unsigned long long leaves = [&] {
      if (group[0].size() == 1) {
        return std::max(degree[group[0][0]], 2);
      }
      else {
        return 2 * std::max({ degree[group[0][0]] - 1, degree[group[0][1]] - 1, 1 });
      }
    }();
    for (int d: range(1, N)) {
      if (group[d].empty()) {
        break;
      }
      chmax(dist, d + 1);
      int max = 0;
      for (int u: group[d]) {
        chmax(max, degree[u]);
      }
      leaves *= std::max(1, max - 1);
    }
    return std::make_pair(dist, leaves);
  };
  std::pair<int, unsigned long long> ans(std::numeric_limits<int>::max(), std::numeric_limits<unsigned long long>::max());
  for (int u: range(0, N)) {
    chmin(ans, solve(bfs(u)));
  }
  for (auto e: range(0, N - 1)) {
    chmin(ans, solve(bfs(A[e], B[e])));
  }
  std::cout << ans.first << ' ' << ans.second << '\n';
}

