const int N = 200 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;
const int M = 998244353;

int n;
int deg[N];
vector<int> g[N];

bool read() {
    if (!(cin >> n))
        return false;

    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        g[u - 1].emplace_back(v - 1);
        g[v - 1].emplace_back(u - 1);
    }

    return true;
}

vector<int> dfs_d(int v, int pr, vector<int> path) {
    path.emplace_back(v);
    auto res = path;

    for (auto to : g[v])
        if (to != pr) {
            auto ret = dfs_d(to, v, path);

            if (ret.size() > res.size())
                res = ret;
        }

    return res;
}

void dfs(int v, int pr, int h = 0) {
    deg[h] = max(deg[h], (int) g[v].size() - (pr != -1));

    for (auto to : g[v])
        if (to != pr)
            dfs(to, v, h + 1);
}

void solve() {
    auto D = dfs_d(dfs_d(0, -1, vector<int>()).back(), -1, vector<int>());
    cout << (1 + D.size()) / 2 << ' ';

    if (D.size() % 2 == 0) {
        dfs(D[D.size() / 2 - 1], D[D.size() / 2]);
        dfs(D[D.size() / 2], D[D.size() / 2 - 1]);
        auto ans = 2ll;

        for (int i = 0; i < D.size() / 2 - 1; ++i)
            ans *= deg[i];

        cout << ans << endl;
    } else {
        auto v = D[D.size() / 2];
        dfs(v, -1);
        auto ans = 1ll;

        for (int i = 0; i < D.size() / 2; ++i)
            ans *= deg[i];

        for (const auto& u : g[v]) {
            fill(deg, deg + n, 0);
            auto cur = 2ll;
            dfs(u, v);
            dfs(v, u);

            for (int i = 0; i < D.size() / 2; ++i)
                cur *= deg[i];

            if (cur != 0)
                ans = min(ans, cur);
        }

        cout << ans << endl;
    }
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

