void solve(){
    i64 N;
    cin >> N;

    vector<vector<int>> tree(N);
    vector<int> a(N-1),b(N-1);
    rep(i,0,N-1){
        cin >> a[i] >> b[i];
        --a[i];
        --b[i];
        tree[a[i]].push_back(b[i]);
        tree[b[i]].push_back(a[i]);
    }

    static i64 height[128][128];
    static i64 depth[100][100][101];
    fill_n((i64*)height,128*128,-1);
    fill_n((i64*)depth,100*100*101,0);

    function<i64(int,int)> calc_height=[&](int u,int p){
        i64& res=height[u][p];
        if(res!=-1) return res;
        res=1;
        rep(i,0,tree[u].size()){
            if(tree[u][i]==p) continue;
            res=max(res,calc_height(tree[u][i],u)+1);
        }
        return res;
    };

    function<void(int,int)> calc_depth=[&](int u,int p){
        if(depth[u][p][0]!=0) return;
        depth[u][p][0]=tree[u].size()-1;
        for(int v:tree[u]){
            if(v==p) continue;
            calc_depth(v,u);
            rep(i,0,101){
                if(depth[v][u][i]==0) break;
                depth[u][p][i+1]=max(depth[u][p][i+1],depth[v][u][i]);
            }
        }
    };

    pair<i64,i64> ans(inf64,inf64);
    rep(i,0,N-1){
        int x=a[i],y=b[i];
        i64 max_height=max(calc_height(x,y),calc_height(y,x));
        calc_depth(x,y);
        calc_depth(y,x);

        i64 r=1;
        rep(j,0,101){
            if(depth[x][y][j]==0 and depth[y][x][j]==0) break;
            r*=max(depth[x][y][j],depth[y][x][j]);
        }
        pair<i64,i64> tmp(max_height,r*2);
        ans=min(ans,tmp);
    }

    rep(x,0,N){
        i64 max_height=0;
        vector<i64> depthx(101);
        rep(j,0,tree[x].size()){
            max_height=max(max_height,calc_height(tree[x][j],x)+1);
            calc_depth(tree[x][j],x);
            rep(k,0,100) depthx[k+1]=max(depthx[k+1],depth[tree[x][j]][x][k]);
        }
        i64 r=1;
        rep(k,0,101){
            if(depthx[k]==0) continue;
            r*=depthx[k];
        }
        pair<i64,i64> tmp(max_height,r*tree[x].size());
        ans=min(ans,tmp);
    }

    cout << ans.first << " " << ans.second << endl;
}

