const int maxn = 1e5+9;
const ll mod = 1e9+7;

vector <int> g[maxn], vec, tmp, ans;
int deg[maxn];
bool vis[maxn];

int dfs (int v, int parent = -1) {
	int mx = 0;
	for (auto u : g[v]) {
		if (u == parent) continue;
		mx = max(mx, dfs(u, v) + 1);
	}
	return mx;
}

ll cal () {
	while (vec.size()) {
		tmp.clear();
		int mx = 0;
		for (auto v : vec) {
			mx = max(mx, deg[v]);
			for (auto u : g[v]) {
				if (vis[u]) continue;
				vis[u] = true;
				deg[u]--;
				tmp.push_back(u);
			}
		}
		vec = tmp;
		if (mx) ans.push_back(mx);
	}
	ll res = 1;
	for (auto x : ans)
		res *= x;
	return res;
}

void setdeg (int n) {
	for (int i = 0; i < n; i++) deg[i] = g[i].size();
}

