			vec.push_back(i);
	}
	ll res = 0;
	if (vec.size() == 2) {
		setdeg(n);
		ans.push_back(2);
		vis[vec[0]] = true; vis[vec[1]] = true;
		deg[vec[0]]--; deg[vec[1]]--;
		res = cal();
