	}
	else {
		int v = vec[0];
		setdeg(n);
		res = cal();
		for (auto u : g[v]) {
			setdeg(n);
			memset(vis, 0, sizeof vis);
			vec.clear(); ans.clear();
			vec.push_back(v); vec.push_back(u);
			ans.push_back(2);
			vis[v] = vis[u] = true;
			deg[v]--; deg[u]--;
			res = min(res, cal());
		}
		cout << mn + 1 << " " << res << "\n";
	}
