const int MAX_N = 2010;
const int MAX_M = 2010;

double x[MAX_M];
double p[MAX_M];
double log_fact[MAX_N];

double R[MAX_N][MAX_M];
double T[MAX_N][MAX_M];

int main2() {
  CLR(R, 0);
  CLR(T, 0);

  int N = nextInt();
  int M = nextInt();
  double Q = nextInt();
  REP(j, M) {
    x[j] = nextInt();
    p[j] = nextInt() / Q;
  }

  for (int i = 0; i <= N; i++) R[i][0] = 1.0;
  double pl = 0;
  for (int j = 1; j <= M; j++) {
    pl += p[j-1];
    for (int i = 0; i < N; i++) {
      R[i][j] = (i-1 >= 0 ? R[i-1][j] : 0) + exp(log(pl) * i + log(1.0 - pl) * (N-i) + log_fact[N] - log_fact[i] - log_fact[N-i]);
    }
    R[N][j] = 0;
  }
  REP(i, N) {
    for (int j = 1; j <= M; j++) {
      T[i][j] = R[i][j-1] - R[i][j];
    }
  }
  double ans = 0;
  REP(i, N) {
    double t = 0;
    for (int j = 1; j <= M; j++) t += abs(x[0] - x[j-1]) * T[i][j];
    double val = t;

    double eff = 0;
    for (int j = 1; j <= M; j++) eff -= T[i][j];

    for (int j = 2; j <= M; j++) {
      eff += 2 * T[i][j-1];
      t += (x[j-1] - x[j-2]) * eff;
      chmin(val, t);
    }
    ans += val;
  }

  printf("%.10f\n", ans);
  return 0;
}

