PLL calc(ll start1, ll start2 = -1) {
    bool used[100] = {};
    queue<ll> que;
    used[start1] = true;
    que.push(start1);
    if(start2 != -1) {
        used[start2] = true;
        que.push(start2);
    }

    ll depth = 0;
    ll mul = que.size();
    while(que.size()) {
        depth++;
        queue<ll> nxtq;
        ll max_ch = 0;
        ll node_cnt = que.size();
        while(que.size()) {
            ll cur = que.front();
            que.pop();
            ll ch_cnt = 0;
            for(ll nxt : edges[cur]) {
                if(used[nxt]) continue;
                nxtq.push(nxt);
                ch_cnt++;
                used[nxt] = true;
            }
            chmax(max_ch, ch_cnt);
        }
        mul *= max<ll>(1, max_ch);
        que = move(nxtq);
    }
    DEBUG(make_tuple(start1, start2, depth, mul));
    return PLL(depth, mul);
}

