vel par;
int root(int ser) {
	if (par[ser] == -1) { return ser; }
	int ans = root(par[ser]);
	par[ser] = ans;
	return ans;
}
bool marge(pin a) {
	int x = root(a.first);
	int y = root(a.second);
	if (x != y) { par[x] = y; }
	return x != y;
}
int gcd(int a, int b) {
	if (a < b) { swap(a, b); }
	if (b == 0) { return a; }
	return gcd(b, a%b);
}
int ru(int a, int r) {
	if (r == 0) { return 1; }
	int ans = ru(a, r / 2);
	ans *= ans; ans %= p;
	if (r % 2 == 1) { ans *= a; ans %= p; }
	return ans;
}
int inv(int a) {
	return ru(a, p - 2);
}
void make_kai() {
	rep(i, 1000006) { kai[i + 1] = (kai[i] * (i + 1)) % p; }
	rep(i, 1000007) { ink[i] = inv(kai[i]); }
}
int com(int n, int r) {
	int ans = kai[n] * ink[r];
	ans %= p;
	return ans;
}
pin most_far(int now, int back, vvel &way) {
	pin ans = mkp(0, now);
	rep(i, way[now].size()) {
		int nex = way[now][i];
		if (nex != back) {
			pin y = most_far(nex, now, way); y.first++;
			if (now == 0) {
				now = 0;
			}
			if (ans.first < y.first) { ans = y; }
		}
	}
	return ans;
}
int fid(int han, int now,int goal,vvel &way) {
	queue<int> q;
	vel dist(way.size(), -1); dist[now] = 0;
	q.push(now);
	while (!q.empty()) {
		int st = q.front(); q.pop();
		rep(i, way[st].size()) {
			int to = way[st][i];
			if (dist[to] == -1) {
				dist[to] = dist[st] + 1;
				q.push(to);
			}
		}
	}
	while (dist[goal] > han) {
		rep(j, way[goal].size()) {
			if (dist[goal] > dist[way[goal][j]]) {
				goal = way[goal][j]; break;
			}
		}
	}
	return goal;
}
