typedef long long ll;
typedef pair<ll, ll> pll;

vector <ll> V[111];
ll K[111], D[111], Q[111];
ll n, f, r;
pll ans;

void bfs(ll p)
{
	ll i;
	pll ret;

	f = r = 0;

	for(i=1;i<=n;i++){
		K[i] = D[i] = 0;
	}

	Q[++f] = p;
	D[p] = 1;
	K[1] = V[p].size();

	for(;r<f;){
		p = Q[++r];
		for(auto t: V[p]){
			if(!D[t]){
				Q[++f] = t;
				D[t] = D[p] + 1;
				K[D[t]] = max(K[D[t]], (ll)V[t].size() - 1);
			}
		}
	}

	ret = pll(D[p], 1);

	for(i=1;i<ret.first;i++){
		ret.second *= K[i];
	}

	ans = min(ans, ret);
}

void bfs(ll p, ll q)
{
	ll i;
	pll ret;

	f = r = 0;

	for(i=1;i<=n;i++){
		K[i] = D[i] = 0;
	}

	Q[++f] = p, Q[++f] = q;
	D[p] = D[q] = 1;
	K[1] = max((ll)V[p].size(), (ll)V[q].size()) - 1;

	for(;r<f;){
		p = Q[++r];
		for(auto t: V[p]){
			if(!D[t]){
				Q[++f] = t;
				D[t] = D[p] + 1;
				K[D[t]] = max(K[D[t]], (ll)V[t].size() - 1);
			}
		}
	}

	ret = pll(D[p], 2);

	for(i=1;i<ret.first;i++){
		ret.second *= K[i];
	}

	ans = min(ans, ret);
}

int main()
{
