using namespace std;
typedef long long li;

const li mod = 1e9 + 7;

vector<vector<li>> nexts;

struct dfsresult {
    li depth;
    li node;
};

dfsresult dfs(li pos, li parent) {
    dfsresult result;
    result.depth = 0;
    result.node = pos;

    for (auto &&next  : nexts[pos]) {
        if (next == parent) {
            continue;
        }
        auto subres = dfs(next, pos);
        subres.depth += 1;
        if (subres.depth > result.depth) {
            result = subres;
        }
    }
    return result;
}

li distance(li pos, li dest, li parent) {
    if (pos == dest) {
        return 0;
    }

    li ans = 999;
    for (auto &&next : nexts[pos]) {
        if (next == parent) {
            continue;
        }
        ans = min(ans, distance(next, dest, pos) + 1);
    }
    return ans;
}

vector<li> dfs2(li pos, li parent) {
    vector<li> ret;
    li cnt = 0;
    for (auto &&next : nexts[pos]) {
        if (next == parent) {
            continue;
        }
        cnt++;
        auto subret = dfs2(next, pos);
        if (subret.size() > ret.size()) {
            swap(subret, ret);
        }
        for (int i = ret.size() - subret.size(); i < ret.size(); ++i) {
            ret[i] = max(ret[i], subret[i]);
        }
    }
    if (cnt) {
        ret.push_back(cnt);
    }
    return ret;
}

li calc(li x, li y) {
    auto ret1 = dfs2(x, y);
    auto ret2 = dfs2(y, x);
    li ret = 2;
    for (int i = 0; i < ret1.size(); ++i) {
        ret *= ret1[i];
    }
    return ret;
}

int main() {
    li n;
    cin >> n;
    nexts = vector<vector<li>>(n);
    for (int i = 0; i < n - 1; ++i) {
        li fr, to;
        cin >> fr >> to;
        fr--; to--;
        nexts[fr].push_back(to);
        nexts[to].push_back(fr);
    }

    li dix = dfs(0, -1).node;
    auto ddd = dfs(dix, -1);
    li diy = ddd.node;
    li diameter = ddd.depth;

    li color = 1 + diameter / 2;

    vector<li> centers;
    for (int i = 0; i < n; ++i) {
        if (abs(distance(dix, i, -1) - distance(diy, i, -1)) <= 1) {
            centers.push_back(i);
        }
    }

    li ans = 1LL << 62;
    if (centers.size() == 1) {
        vector<vector<li>> rets;
        for (auto &&next  : nexts[centers[0]]) {
            auto ret1 = dfs2(next, centers[0]);
            while (ret1.size() * 2 < diameter) {
                ret1.insert(ret1.begin(), 1);
            }
            rets.push_back(ret1);
            ans = min(ans, calc(next, centers[0]));
        }
        li tans = nexts[centers[0]].size();
        for (int i = 0; i < diameter / 2; ++i) {
