vector<int> g[MAXN]; 
int deep[MAXN];
int prs[MAXN];
int deeps[MAXN];
int need[MAXN];


void dfs(int u, int pr = -1) {
    for (auto h: g[u]) {
        if (h != pr) {
            deep[h] = deep[u] + 1;
            prs[h] = u;
            dfs(h, u);
        }
    }
}


void dfs1(int u, int pr = -1) {
    chkmax(need[deeps[u]], sz(g[u]) - 1);
    if (pr == -1) {
        chkmax(need[deeps[u]], sz(g[u]));
    }
    for (auto h: g[u]) {
        if (h != pr) {
            deeps[h] = deeps[u] + 1;
            dfs1(h, u);
        }
    }
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);
    //read(FILENAME);
    cin >> n;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        g[a].pb(b);
        g[b].pb(a);
    }
    dfs(0);
    int pos = 0;
    for (int i = 1; i < n; i++) {
        if (deep[pos] < deep[i]) {
            pos = i;
        }
    }
    deep[pos] = 0;
    prs[pos] = -1;
    dfs(pos);
    int pos1 = 0;
    for (int i = 1; i < n; i++) {
        if (deep[pos1] < deep[i]) {
            pos1 = i;
        }
    }
    vector<int> gs;
    while (pos1 != -1) {
        gs.pb(pos1);
        pos1 = prs[pos1];
    }
    reverse(all(gs));
    //cout << sz(gs) << endl;
    int len = (sz(gs) + 1) / 2;
    cout << len << ' ';
    if (sz(gs) % 2 == 1) {
        long long ans1 = 1e18;
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < n; i++) {
                need[i] = 0;
                deeps[i] = 0;
            }
            dfs1(j); 
            //cout << gs[sz(gs) / 2] + 1 << endl;
            long long ans = 1;
          //  cout << "opa" << endl;
            for (int i = 0; i < n; i++) {
                if (need[i] == 0) continue;
                //cout << need[i] << endl; 
                ans *= need[i];
                if (ans > 1e18) {
                    break;
                }
            }
            chkmin(ans1, ans);
        }
        cout << ans1 << endl;
    } else {
        dfs1(gs[sz(gs) / 2], gs[sz(gs) / 2 - 1]);
        dfs1(gs[sz(gs) / 2 - 1], gs[sz(gs) / 2]);
        long long ans = 1;
        for (int i = 0; i < len - 1; i++) {
            ans *= need[i];
        }
        ans *= 2;
        cout << ans << endl;
    }
    return 0;
}

