const int M = 107;
const int ROOT = 13;

int n;
vector<int> g[M];
bool u[M];
int d[M], d2[M], d1[M];

void read() {
  cin >> n;
  for (int i = 0; i < n - 1; ++i) {
    int u, v;
    cin >> u >> v;
    --u, --v;
    g[u].push_back(v);
    g[v].push_back(u);
  }
}

void dfs(int v, int x, int *d) {
  u[v] = true;
  d[v] = x;

  for (int to : g[v])
    if (!u[to]) {
      dfs(to, x + 1, d);
    }
}

ll check(vector<int> x) {
  //assert(x.size() == 2);
  //cerr << x[0] + 1 << " " << x[1] + 1 << endl;

  fill(u, u + n, false);

  for (int v : x) {
    u[v] = true;
  }

  for (int v : x) {
    dfs(v, 0, d);
  }

  ll prod = 1;

  vector<ll> mx(M, 1);
  for (int v = 0; v < n; ++v) {
    ll cnt = 0;
    for (int to : g[v])
      if (d[to] == d[v] + 1)
        ++cnt;
    mx[d[v]] = max(mx[d[v]], cnt);
  }

  for (ll x : mx)
    prod *= x;

  if (x.size() == 2)
    prod *= 2;

  return prod;
}

void kill() {
  int s1 = ROOT % n;
  dfs(s1, 0, d);


  s1 = max_element(d, d + n) - d;

  fill(u, u + n, false);
  dfs(s1, 0, d1);


  int s2 = max_element(d1, d1 + n) - d1;

  fill(u, u + n, false);
  dfs(s2, 0, d2);

  int D = *max_element(d1, d1 + n);


  ll prod = 2e18;

  if (D % 2 == 0) {
    vector<int> x;
    for (int i = 0; i < n; ++i)
      if (d1[i] == D / 2 && d2[i] == D / 2) {
        x.push_back(i);
      }

    assert(x.size() == 1);
    prod = check(x);

    for (int to : g[x[0]]) {
      prod = min(prod, check({x[0], to}));
    }
  } else {
    vector<int> x;
    for (int i = 0; i < n; ++i)
      if (d1[i] + d2[i] == D && min(d1[i], d2[i]) >= D / 2)
        x.push_back(i);
    prod = check(x);
  }

  cout << (D + 2) / 2 << " " << prod << "\n";
}

