        rep(j, n) {
            chmax(ma, d[j]);
        }
        int cm = cmi;
        if(chmin(cmi, ma + 1)) {
            vector<int> cnt(cmi + 1, 0);
            cnt[0] = (int)g[i].size();
            rep(j, n) {
                if(j == i) continue;
                chmax(cnt[d[j]], (int)g[j].size() - 1);
            }
            int res = 1LL;
            for(int j = 0; j < ma; ++ j) {
                res *= cnt[j];
            }
            if(cm == ma + 1) chmin(lmi, res);
            else lmi = res;
        }
    }
    //中心が2つ
    rep(i, n) {
        for(int j: g[i]) {
            vector<int> d(n, inf);
            dfs(i, j, 0, d);
            dfs(j, i, 0, d);
            int ma = 0;
            rep(k, n) {
                chmax(ma, d[k]);
