                rep(k, n) {
                    if(k == i || k == j) continue;
                    chmax(cnt[d[k]], (int)g[k].size() - 1);
                }
                int res = 2LL;
                for(int k = 0; k < ma; ++ k) {
                    res *= cnt[k];
                }
                if(cm == ma + 1) chmin(lmi, res);
                else lmi = res;
            }
        }
    }
    cout << cmi << " " << lmi << endl;
}

