template<class T> void ReadInteger(T & x) {
    x = 0;
    int f = 1, ch = getchar();
    while(ch < '0' || ch > '9') {
        if(ch == '-') f = -1;
        ch = getchar();
    }
    while(ch >= '0' && ch <= '9') {
