typedef long long LL;

const LL inf = 1LL << 60;
int N;
int head[205], ecnt;
queue< pair<int, int> > q;

struct edge {
    int to, nex;
};
edge G[205];
inline void addedge(int u, int v) {
    G[ecnt] = (edge) {v, head[u]};
    head[u] = ecnt++;
    G[ecnt] = (edge) {u, head[v]};
    head[v] = ecnt++;
}

int dep[205], anc[205], d;
void DFS(int u, int step) {
    dep[u] = step;
    if(step > dep[d]) d = u;
    for(int i = head[u]; ~ i; i = G[i].nex) {
        int v = G[i].to;
        if(v != anc[u]) {
            anc[v] = u;
            DFS(v, step + 1);
        }
    }
}

int cnt[205], vis[205];
LL BFS(int st, int f) {
    if(!st) return inf;
    if(f && !anc[st]) return inf;
    memset(cnt, 0, sizeof(cnt));
    memset(vis, 0, sizeof(vis));
    q.push(make_pair(st, 1)), cnt[1]++, vis[st] = 1;
    if(f) q.push(make_pair(anc[st], 1)), cnt[1]++, vis[ anc[st] ] = 1;
    while(!q.empty()) {
        int u = q.front().first;
        int d = q.front().second;
        vis[u] = 1;
        q.pop();
        int deg = 0;
        for(int i = head[u]; ~ i; i = G[i].nex) {
            int v = G[i].to;
            if(!vis[v]) {
                q.push(make_pair(v, d + 1));
                deg++;
            }
        }
        cnt[d + 1] = max(cnt[d + 1], deg);
    }
    /*cout << "DEBUG " << st << ' ' << anc[st] << endl;*/
    long long res = 1;
    for(int i = 1; i <= N; i++) if(cnt[i]) {
        /*cout << i << ' ' << cnt[i] << endl;*/
        res *= cnt[i];
        if(i > (dep[d] + 1) / 2) return inf;
    }
    return res;
}

void Solve() {
    DFS(1, 1);
    memset(anc, 0, sizeof(anc));
    DFS(d, 1);
    long long ans = inf;
    for(int i = 1; i <= N; i++) ans = min(ans, BFS(i, 0));
    for(int i = 1; i <= N; i++) ans = min(ans, BFS(i, 1));
    printf("%d %lld\n", (dep[d] + 1) >> 1, ans);
}
int main() {
    ReadInteger(N);
    memset(head, -1, sizeof(head));
    for(int i = 1; i < N; i++) {
        int u, v;
        ReadInteger(u);
        ReadInteger(v);
        addedge(u, v);
    }
    Solve();
    return 0;
}

