    level[0].push_back(v);
    used[v] = true;

    for(col=0;level[col].size();++col){
        for(int v: level[col]){
            count[col] = max(count[col], edges[v].size() - 1);
            for(int to: edges[v]){
                if(used[to]) continue;
                used[to] = true;
                level[col+1].push_back(to);
            }
        }
    }
    size_t ret = 2;
    for(int i=0;count[i];++i) ret *= count[i];
    return {col, ret};
}
