        if (to != root)
            dfs(to, node, d + 1);
}

void get_way(int node, int root, int dest) {
    aux.pb(node);

    if (node == dest) way = aux;
    for (auto to : list[node])
        if (to != root)
            get_way(to, node, dest);

    aux.pop_back();
}

ll check(ll n1, ll n2 = 0) {
    int i, j;

    memset(us, 0, sizeof(us));
    memset(maxi, 0, sizeof(maxi));
    Q.push(mp(n1, 0));
    if (n2 != 0) Q.push(mp(n2, 0));
    us[n1] = us[n2] = true;

    while (!Q.empty()) {
        int act = Q.front().first;
        int lvl = Q.front().second;
        Q.pop();

        int down = 0;
        for (auto to : list[act]) {
            if (us[to]) continue;
            down++;
            Q.push(mp(to, lvl + 1));
            us[to] = true;
        }

        maxi[lvl + 1] = max(maxi[lvl + 1], down);
    }

    ll ans = 1;
    for (i = 1; maxi[i] > 0; i++)
        ans *= 1LL * maxi[i];

    return ans * (n2 != 0 ? 2 : 1);
}

void solve() {
    int sz = way.size();
    int R;
    colors = (sz + 1) / 2;

    if (sz % 2 == 0) {
        leaves = check(way[(sz / 2) - 1], way[sz / 2]);
