vector<int> Diameter_path(int n){
    if(n==1)return vector<int> {0};
    auto farthest=[&](int start){
        vector<int> depth(n);
        function<void(int,int,int)>get_depth=[&](int u,int prev,int d){
            depth[u]=d;
            for(auto v:G[u]){
                if(v!=prev){
                    get_depth(v,u,d+1);
                }
            }
        };
        get_depth(start,-1,0);
        int maxd=0;
        int res=0;
        rep(i,n){
            if(depth[i]>maxd){
                maxd=depth[i];res=i;
            }
        }
        return res;
    };
    int s=farthest(1);
    int t=farthest(s);
    vector<int> diameter_path;
    function<void(int,int,vector<int>&)> construct=[&](int u,int prev,vector<int> &path){
        if(u==t){
            diameter_path=path;
            return;
        }
        for(auto v:G[u])if(v!=prev){
            path.push_back(v);
            construct(v,u,path);
            path.pop_back();
        }
    };
    vector<int> tmp;tmp.pb(s);
    construct(s,-1,tmp);
    return diameter_path;
}


