int dfs1(int v, int p) {
    int ans = 0;
    for (int c : adj[v])
        if (c != p)
            ans = max(ans, dfs1(c, v) + 1);
    return ans;
}
void dfs2(int v, int p, int d) {
    maxdeg[d] = max(maxdeg[d], (int) adj[v].size());
    for (int c : adj[v])
        if (c != p)
            dfs2(c, v, d + 1);
}

pair<int, long> solve(int n) {
    if (n == 2)
        return make_pair(1, 2L);

    for (int i = 0; i < n; i++)
        dist[i] = dfs1(i, -1);

    int *c1 = min_element(dist, dist + n);
    int *c2 = find(c1 + 1, dist + n, *c1);

    fill_n(maxdeg, n, 0);

    if (c2 == dist + n) {
        dfs2(c1 - dist, -1, 0);
        long ans = maxdeg[0];
        for (int i = 1; i < *c1; i++)
            ans *= maxdeg[i] - 1;

        for (int v : adj[c1 - dist]) {
            fill_n(maxdeg, n, 0);
            dfs2(c1 - dist, v, 0);
            dfs2(v, c1 - dist, 0);
            long ans2 = 2 * (maxdeg[0] - 1);
            for (int i = 1; i < *c1; i++)
                ans2 *= maxdeg[i] - 1;
            ans = min(ans, ans2);
        }

        return make_pair(*c1 + 1, ans);
    } else {
        dfs2(c1 - dist, c2 - dist, 0);
        dfs2(c2 - dist, c1 - dist, 0);

        long ans = 2 * (maxdeg[0] - 1);
        for (int i = 1; i < *c1 - 1; i++)
            ans *= maxdeg[i] - 1;
        return make_pair(*c1, ans);
    }
}

