using Edges = vector<int>;
using Graph = vector<Edges>;

void add_edge(Graph &g, int s, int t) {
  g[s].push_back(t);
  g[t].push_back(s);
}

void bfs(const Graph &g, vector<ll> &d, int s) {
  int n = g.size();
  queue<ll> q;
  q.push(s);
  d.assign(n, INF);
  d[s] = 0;
  while(!q.empty()) {
    ll i = q.front();
    q.pop();
    for (ll j : g[i]) {
      if (d[j] > d[i] + 1) {
        d[j] = d[i] + 1;
        q.push(j);
      }
    }
  }
}

void bfs2(const Graph &g, vector<ll> &dim, int s1, int s2) {
  int n = g.size();
  queue<ll> q;
  q.push(s1);
  q.push(s2);
  vector<ll> d(n, INF);
  d[s1] = 0;
  d[s2] = 0;
  while(!q.empty()) {
    ll i = q.front();
    q.pop();
    for (ll j : g[i]) {
      if (d[j] > d[i] + 1) {
        d[j] = d[i] + 1;
        q.push(j);
      }
    }
  }
  REP(i,n) dim[d[i]] = max(dim[d[i]], (ll)g[i].size()-1);
}

