    --a;--b;
    add_edge(g, a, b);
  }
  ll mx = 0;
  vector<ll> ecc(n, 0);
  REP(i,n) {
    vector<ll> dist(n);
    bfs(g, dist, i);
    REP(j,n) {
      ecc[j] = max(ecc[j], dist[j]);
      mx = max(mx, dist[j]);
    }
  }
  vector<ll> dim(n, 1);
  ll c = 0;
  REP(i,n) {
    if (ecc[i] != mx / 2) {
      dim[ecc[i]] = max(dim[ecc[i]], (ll)g[i].size()-1);
    } else {
      dim[ecc[i]] = max(dim[ecc[i]], (ll)g[i].size());
      c = i;
    }
  }
  ll mul = ((mx % 2) == 1) ? 2 : 1;
  REP(i,n) mul *= dim[i];
  if ((mx % 2) == 0) {
