    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vector<vector<int>> g(n);
    vector<int> sz(n);
    for (int i = 0; i + 1 < n; i++) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
        sz[a]++;
        sz[b]++;
    }
    vector<int> lf;
    for (int i = 0; i < n; i++) {
        if (sz[i] == 1) {
            lf.push_back(i);
        }
    }
    vector<vector<int>> pathes;
    int d = 0;
    for (int i = 0; i < (int)lf.size(); i++) {
        for (int j = i + 1; j < (int)lf.size(); j++) {
            vector<int> p = path(n, g, lf[i], lf[j]);
            d = max(d, (int)p.size());
            pathes.push_back(p);
        }
    }
    int ans = INF;
    for (auto t : pathes) {
        if ((int)t.size() == d) {
            try_path(t, g, ans);
        }
    }
    cout << (d + 1) / 2 << ' ' << ans << endl;
