const int maxn = 100;

int n;
vector<int> g[maxn];
int prev[maxn];

int Find(int u) {
  memset(prev, -1, sizeof prev);
  queue<int> q;
  q.push(u);
  prev[u] = u;
  while (!q.empty()) {
    u = q.front();
    q.pop();
    for (int v : g[u]) {
      if (prev[v] == -1) {
        prev[v] = u;
        q.push(v);
      }
    }
  }
  return u;
}

int d[maxn];

void Dfs(int u, int p, int dep = 0) {
  int cnt = 0;
  for (int v : g[u]) {
    if (v == p) continue;
    Dfs(v, u, dep + 1);
    ++cnt;
  }
  d[dep] = max(d[dep], cnt);
}

int st[maxn], top;

int main(void) {
  scanf("%d", &n);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    scanf("%d%d", &a, &b);
    --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  int u = Find(0);
  int v = Find(u);
  for (int k = v; k != u; k = prev[k]) {
    st[top++] = k;
  }
  st[top++] = u;
  if (top & 1) {
    int c = st[top >> 1], h = top >> 1;
    long long ans = 1;
    Dfs(c, -1);
    for (int i = 0; i < h; ++i) {
      ans *= d[i];
    }
    for (int c2 : g[c]) {
      memset(d, 0, sizeof d);
      Dfs(c, c2);
      Dfs(c2, c);
      long long res = 2;
      for (int i = 0; i < h; ++i) {
        res *= d[i];
      }
      ans = min(ans, res);
    }
    printf("%d %lld\n", h + 1, ans);
  } else {
    int c1 = st[(top >> 1) - 1], c2 = st[top >> 1], h = (top >> 1) - 1;
    long long ans = 2;
    Dfs(c1, c2);
    Dfs(c2, c1);
    for (int i = 0; i < h; ++i) {
      ans *= d[i];
    }
    printf("%d %lld\n", h + 1, ans);
  }
  return 0;
}

