void solve(){
    i64 N;
    cin >> N;

    vector<vector<int>> tree(N);
    vector<int> a(N-1),b(N-1);
    rep(i,0,N-1){
        cin >> a[i] >> b[i];
        --a[i];
        --b[i];
        tree[a[i]].push_back(b[i]);
        tree[b[i]].push_back(a[i]);
    }

    static i64 height[128][128];
    static i64 leaf[128][128];
    fill_n((i64*)height,128*128,-1);
    fill_n((i64*)leaf,128*128,-1);

    function<i64(int,int)> calc_height=[&](int u,int p){
        i64& res=height[u][p];
        if(res!=-1) return res;
        res=1;
        rep(i,0,tree[u].size()){
            if(tree[u][i]==p) continue;
            res=max(res,calc_height(tree[u][i],u)+1);
        }
        return res;
    };

    function<i64(int,int)> calc_leaf=[&](int u,int p){
        i64& res=leaf[u][p];
        if(res!=-1) return res;
        if(tree[u].size()==1) return res=i64(1);
        res=0;
        rep(i,0,tree[u].size()){
            if(tree[u][i]==p) continue;
            res+=calc_leaf(tree[u][i],u);
        }
        return res;
    };

    pair<i64,i64> ans(inf64,inf64);
    rep(i,0,N-1){
        int x=a[i],y=b[i];
        i64 max_height=1,max_leaf=1;
        {
            rep(j,0,tree[x].size()){
                if(tree[x][j]==y) continue;
                max_height=max(max_height,calc_height(tree[x][j],x)+1);
                max_leaf=max(max_leaf,calc_leaf(tree[x][j],x));
            }
        }
        {
            rep(j,0,tree[y].size()){
                if(tree[y][j]==x) continue;
                max_height=max(max_height,calc_height(tree[y][j],y)+1);
                max_leaf=max(max_leaf,calc_leaf(tree[y][j],y));
            }
        }
        pair<i64,i64> tmp(max_height,max_leaf*max<i64>({(i64)tree[x].size()-1,(i64)tree[y].size()-1,(i64)1})*2);
        ans=min(ans,tmp);
    }

    rep(x,0,N){
        if(tree[x].size()>1){
            i64 max_height=0,max_leaf=0;
            rep(j,0,tree[x].size()){
                max_height=max(max_height,calc_height(tree[x][j],x)+1);
                max_leaf=max(max_leaf,calc_leaf(tree[x][j],x));
            }
            pair<i64,i64> tmp(max_height,max_leaf*tree[x].size());
            ans=min(ans,tmp);
        }else{
            pair<i64,i64> tmp(calc_height(tree[x][0],x)+1,calc_leaf(tree[x][0],x)*2);
            ans=min(ans,tmp);
        }
    }

    cout << ans.first << " " << ans.second << endl;
}

