typedef long long ll;
const int maxn = 200;
int n, dep[maxn + 10];
int a[maxn + 10], acnt, mx[maxn + 10];
int ans = 1e9;
ll ansv;
vector<int> g[maxn + 10];

void dfs(int p, int fa) {
	dep[p] = dep[fa] + 1;
	for (int i = 0; i < (int)g[p].size(); ++i) {
		int e = g[p][i];
		if (e != fa) dfs(e, p);
	}
}

bool getpath(int p, int fa, int od) {
	a[++acnt] = p;
	if (p == od) return 1;
	for (int i = 0; i < (int)g[p].size(); ++i) {
		int e = g[p][i];
		if (e != fa && getpath(e, p, od)) return 1;
	}
	--acnt; return 0;
}

void dfsdeg(int p, int fa, int dep) {
	int cnt = 0;
	for (int i = 0; i < (int)g[p].size(); ++i) {
		int e = g[p][i];
		if (e != fa) {
			dfsdeg(e, p, dep + 1); ++cnt;
		}
	}
	mx[dep] = max(mx[dep], cnt);
}

void solvep(int p) {
	int now = 1; ll tot = 1;
	memset(mx, 0, sizeof mx);
	dfsdeg(p, 0, 0);
	for (int i = 0; mx[i]; ++i) {
		tot *= mx[i]; ++now;
	}
	if (now < ans) {
		ans = now; ansv = tot;
	} else if (now == ans && tot < ansv) ansv = tot;
}

void solvee(int x, int y) {
	int now = 1; ll tot = 2;
	memset(mx, 0, sizeof mx);
	dfsdeg(x, y, 0); dfsdeg(y, x, 0);
	for (int i = 0; mx[i]; ++i) {
		tot *= mx[i]; ++now;
	}
	if (now < ans) {
		ans = now; ansv = tot;
	} else if (now == ans && tot < ansv) ansv = tot;
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i < n; ++i) {
		int l, r; scanf("%d%d", &l, &r);
		g[l].push_back(r); g[r].push_back(l);
	}
	for (int i = 1; i <= n; ++i)
	solvep(i);
	for (int i = 1; i <= n; ++i)
		for (int j = 0; j < (int)g[i].size(); ++j)
			solvee(i, g[i][j]);
	printf("%d %lld", ans, ansv);
}

#include <iostream>
