using ll = long long;

#define MIN(a, b) (((a) < (b)) ? (a) : (b))
#define MAX(a, b) (((a) < (b)) ? (b) : (a))

int const nmax = 100;
std::vector<int> g[1 + nmax];

std::pair<int,int> dfs(int node, int parent){
  std::pair<int,int> sol(0, node);
  for(int h = 0; h < g[node].size(); h++) {
    int to = g[node][h];
    if(to != parent) {
      std::pair<int,int> sol2 = dfs(to, node);
      sol2.first++;
      sol = std::max(sol, sol2);
    }
  }
  return sol;
}

void mark(int node, int parent, std::vector<int> &dist) {
  for(int h = 0; h < g[node].size(); h++) {
    int to = g[node][h];
    if(to != parent) {
      dist[to] = dist[node] + 1;
      mark(to, node, dist);
    }
  }
}

std::pair<ll,ll> solve_specific(int mid, int mid2, int total, int n) {
  std::vector<int> _count(1 + n);
  std::vector<int> new_dist(1 + n), new_dist2(1 + n);
  mark(mid, 0, new_dist);
  mark(mid2, 0, new_dist2);

  ll result = 1;
  if(mid != mid2)
    result = 2;

  for(int i = 1;i <= n; i++) {
    if(new_dist[i] <= new_dist2[i]) {
      int sum = 0;
      for(int h = 0; h < g[i].size(); h++){
        int to = g[i][h];
        if(new_dist[to] == new_dist[i] + 1)
          sum++;
      }
      _count[new_dist[i]] = std::max(_count[new_dist[i]], sum);
    } else { 
      int sum = 0;
      for(int h = 0; h < g[i].size(); h++){
        int to = g[i][h];
        if(new_dist2[to] == new_dist2[i] + 1)
          sum++;
      }
      _count[new_dist2[i]] = std::max(_count[new_dist2[i]], sum);
    }
  }
  if(mid != mid2)
    _count[0]--; 

  for(int i = 0;i < n; i++)
    if(0 < _count[i])
      result = result * _count[i];
  return {total / 2 + 1, result};
}

std::pair<ll, ll> solve(int from, int to, int n) {
  std::vector<int> dist(1 + n), dist2(1 + n);
  mark(from, 0, dist);
  mark(to, 0, dist2);
  int total = dist[to];

  int mid = 0, mid2 = 0;
  for(int i = 1;i <= n; i++)
    if(dist[i] + dist2[i] == total){
      if(dist[i] == dist2[i])
        mid = mid2 = i;
      else if(dist[i] + 1 == dist2[i])
        mid = i;
      else if(dist2[i] + 1 == dist[i])
        mid2 = i;
    }
  if(mid != mid2)
    return solve_specific(mid, mid2, total, n);
  else {
    std::pair<ll, ll> sol = solve_specific(mid, mid, total, n);
    for(int h = 0; h < g[mid].size(); h++) {
      int to = g[mid][h];
      sol = std::min(sol, solve_specific(mid, to, total, n));
    }
    return sol;
  }
}

int main() {
  int n;
  std::cin >> n;
  for(int i = 1;i < n; i++) {
    int x, y;
    std::cin >> x >> y;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  int from = dfs(1, 0).second;
  int to = dfs(from, 0).second;
  std::pair<ll, ll> sol = solve(from, to, n);
  std::cout << sol.first << " " << sol.second;
  return 0;
}

