void dfs(int v, int d){
    used[v] = true;
    dist[v] = d;
    for(int i = 0; i < G[v].size(); i++){
        if(!used[G[v][i]]){
            p[G[v][i]] = v;
            dfs(G[v][i], d+1);            
        }
    }
}

void dfs1(int v, int d){
    //cout << v << endl;
    used[v] = true;
    dist[v] = d;
    int cnt = 0;
    for(int i = 0; i < G[v].size(); i++){
        if(!used[G[v][i]]){
            p[G[v][i]] = v;
            dfs1(G[v][i], d+1);
            cnt++;          
        }
    }
    c[d] = max(c[d], (ll)cnt);
}

vector<int> r;

ll calc(){
    clear();
    dfs(0, 0);
    clear();
    int dist_max = -1;
    int end;
    for(int i = 0; i < N; i++){
        if(dist[i] > dist_max){
            end = i;
            dist_max = dist[i];
        }
    }
    clear();
    p[end] = end;
    dfs(end, 0);
    dist_max = -1;
    for(int i = 0; i < N; i++){
        if(dist[i] > dist_max){
            end = i;
            dist_max = dist[i];
        }
    }
    int tmp = end;
    while(p[tmp] != tmp){
        r.push_back(tmp);
        tmp = p[tmp];
    }
    r.push_back(tmp);
    int s = r.size();
    for(int i = 0; i < N; i++) dist[i] = -1;
    if(s%2 == 0){
        dist[r[s/2-1]] = 1;
        dist[r[s/2]] = 1;
        c[0] = 2;
        clear();
        used[r[s/2-1]] = true;
        used[r[s/2]] = true;
        dfs1(r[s/2-1], 1);
        dfs1(r[s/2], 1);
    }else{
        dist[r[s/2]] = 0;
        clear();
        dfs1(r[s/2], 0);
    }
    ll ans = 1;
    for(int i = 0; i < s/2; i++) {
        ans *= c[i];
    }
    return ans;
}

