    ans = tmp;
    int s = r.size();
    r.clear();
    for(int i = 0; i < N; i++) c[i] = 0;
    for(int i = 0; i < N; i++) {
        if(G[i].size() == 1) isLeaf[i] = true;
    }
    int N_ = N;
    N++;
    bool updated = false;
    if(s%2 == 1){
        for(int i = 0; i < N_; i++){
            if(!isLeaf[i]) continue;
            G[i].push_back(N_);
            G[N_].push_back(i);
            tmp = calc();
            if(tmp < ans) {
                ans = tmp;
                if(!updated) s++;
            }
            G[i].pop_back();
            G[N_].pop_back();
            r.clear();
            for(int i = 0; i < N; i++) c[i] = 0;
        }
    }
    cout <<(s+1)/2 << ' ' << ans << endl;
}

