namespace hh
{
	typedef long long ll;
	typedef std::pair<ll,ll> pii;
	const int N=105;

	int begin[N],next[N*2],to[N*2];

	int n,e;

	void add(int x,int y,bool k=1)
	{
		to[++e]=y;
		next[e]=begin[x];
		begin[x]=e;
		if(k)add(y,x,0);
	}
	void initialize()
	{
		scanf("%d",&n);
		for(int i=1,u,v;i<n;i++)
			scanf("%d%d",&u,&v),add(u,v);
	}

	int fa[N];

	pii dfs(int p,int h=0)
	{
		fa[p]=h;

		pii ret(0,p);

		for(int i=begin[p],q;i;i=next[i])
			if((q=to[i])!=h)
			{
				pii tmp=dfs(q,p);
				tmp.x++;
				ret=std::max(tmp,ret);
			}
		return ret;
	}

	int maxd[N],tot;

	void DFS(int p,int h=0,int dis=0)
	{
		tot=std::max(tot,dis);

		int deg=0;
		for(int i=begin[p],q;i;i=next[i])
			if((q=to[i])!=h)DFS(q,p,dis+1),deg++;
		maxd[dis]=std::max(maxd[dis],deg);
	}

	pii calc_point(int p)
	{
		memset(maxd,0,sizeof(maxd)),tot=0;
		DFS(p);
		ll pi=1;
		for(int i=0;i<tot;i++)pi*=maxd[i];
		return pii(tot+1,pi);
	}
	pii calc_edge(int u,int v)
	{
		memset(maxd,0,sizeof(maxd)),tot=0;
		DFS(u,v),DFS(v,u);
		ll pi=2;
		for(int i=0;i<tot;i++)pi*=maxd[i];
		return pii(tot+1,pi);
	}

	void solve()
	{
		initialize();

		pii ans(23333,23333);

		for(int p=1;p<=n;p++)
			ans=std::min(ans,calc_point(p));
		for(int p=1;p<=n;p++)
			for(int i=begin[p],q;i;i=next[i])
				if((q=to[i])<p)ans=std::min(ans,calc_edge(p,q));

		printf("%lld %lld\n",ans.x,ans.y);
	}
}


