class Solver {
   public:
    int n;
    vector<vector<int>> t;
    Solver(LL n) : n(n), t(2 * n - 1){};
    void add_edge(int a, int b, int v) {
        t[a].push_back(v);
        t[v].push_back(a);
        t[v].push_back(b);
        t[b].push_back(v);
    }
    pair<LL, LL> calc(int r) {
        vector<LL> maxc((LL)t.size()), dep((LL)t.size(), -1);
        queue<int> Q;
        Q.push(r);
        dep[r] = 0;
        LL ret = 0;
        while (!Q.empty()) {
            int now = Q.front();
            Q.pop();
            for (auto x : t[now]) {
                if (dep[x] == -1) {
                    dep[x] = dep[now] + 1;
                    Q.push(x);
                }
            }
            ret = max(ret, dep[now] + 1);
            LL cnt_child =
                (now == r ? (LL)t[now].size() : (LL)t[now].size() - 1);
            maxc[dep[now]] = max(maxc[dep[now]], cnt_child);
        }
        LL ret2 = 1;
        for (int i = 0; i < ret - 1; ++i) {
            ret2 *= maxc[i];
        }
        DBG(r, ret, ret2, maxc)
        return {(ret + 1) / 2, ret2};
    }
    void solve() {
        for (int i = 0; i < n - 1; ++i) {
            int a, b;
