ll solve(ll v1, ll v2, const Graph &G){
    vector<ll> dist(n, INF);
    if(v1==v2){
        dfs2(v1, -1, 0, G, dist);
    }else{
        dfs2(v1, -1, 1, G, dist);
        dfs2(v2, -1, 1, G, dist);
    }

    ll D = -1;
    REP(i, n) chmax(D, dist[i]);
    vector<vector<ll>> V(D+1);
    REP(i, n){
        V[dist[i]].push_back(i);
    }

    vector<ll> kazu(n, 0);
    REP(j, V[D].size()){
        kazu[V[D][j]] = 1;
    }

    for(int i=D-1;i>=0;i--){
        REP(j, V[i+1].size()){
            ll ver = V[i+1][j];
            REP(k, G[ver].size()){
                ll next = G[ver][k];
                if(dist[next] == dist[ver]-1){
                    kazu[next] += kazu[ver];
                }
            }
        }            

        ll ma = 0;
        REP(j, V[i].size()){
            chmax(ma, kazu[V[i][j]]);
        }
        REP(j, V[i].size()){
            kazu[V[i][j]] = ma;
        }
    }

    ll res = 0;
    for(auto v: V[1]) res += kazu[v];
    return res;
