class Diameter
{
public:
	vec<vec<int>> g;
	pair<int, int> ps;
	vec<int> path;
	int n;
	Diameter(int num): g(num) {
		ps.first = 0;
		ps.second = 0;
		n = num;
	}

	void edge(int a, int b) {
		g[a].pb(b);
		g[b].pb(a);
	}

	int longest(int a) {
		queue<pair<int, vec<int>>> keep;
		vec<int> hoge = {a};
		keep.push(mp(a, hoge));
		vec<int> dp(n, 0);

		pair<int, vec<int>> cur;
		while(!keep.empty()) {
			pair<int, vector<int>> get = keep.front();
			keep.pop();
			int cur_p = get.first;
			if (dp[cur_p]) continue;
			dp[cur_p] = 1;
			cur = get;
			rep(i, g[cur_p].size()) {
				int v = g[cur_p][i];
				vec<int> v_path = get.second;
				v_path.pb(v);

				keep.push(mp(v, v_path));
			}
		}

		path = cur.second;
		return cur.first;
	}

	vec<int> diameter(void) {
		ps.first = longest(0);
		ps.second = longest(ps.first);
		return path;
	}
};

ll solve(vec<int> cur_p, vec<vec<int>> g)
{
	vec<int> dp(g.size(), 0);
	ll ans;
	rep(i, cur_p.size()) dp[cur_p[i]] = 1;

	if (cur_p.size() == 1) {
		int c = cur_p[0];
		ans = (ll)g[c].size();;
		vec<int> next_p;
		rep(i, g[c].size()) {
			next_p.pb(g[c][i]);
		}
		cur_p = next_p;
	} else ans = 2;

	while(cur_p.size()) {
		vec<int> next_p;
		rep(i, cur_p.size()) {
			rep(j, g[cur_p[i]].size()) {
				if (dp[g[cur_p[i]][j]]) continue;
				dp[g[cur_p[i]][j]] = 1;
				next_p.pb(g[cur_p[i]][j]);
			}
		}

		int Max = 1;
		rep(i, cur_p.size()) {
			int temp = (int)g[cur_p[i]].size() - 1;
			Max = Max < temp ? temp : Max;
		}
		// cout << Max << endl;
		ans *= Max;
		cur_p = next_p;
	}
	return ans;
}

