	if (l % 2 == 0) {
		vec<int> cur_p = {path[l / 2 - 1], path[l / 2]};
		ans = solve(cur_p, d.g);
	} else {
		vec<int> cur_p1 = {path[l / 2]};
		ll ans1 = solve(cur_p1, d.g);
		// cout << endl;
		vec<int> cur_p2 = {path[l / 2 - 1], path[l / 2]};
		ll ans2 = solve(cur_p2, d.g);
		// cout << endl;
		vec<int> cur_p3 = {path[l / 2 + 1], path[l / 2]};
