void calc(int now,int fa){
	int D=0;
	dep[now]=dep[fa]+1;
	for (int i=H[now];i;i=E[i].nxt){
		if (E[i].to==fa) continue;
		D++;
		calc(E[i].to,now);
	}
	DD[dep[now]]=std::max(DD[dep[now]],D);
}

