int n,head[MAX],cnt=0,deg[MAX];
struct edge{
	int next,to;
}a[MAX<<1];
void add(int x,int y)
{
	a[++cnt].next=head[x];
	a[cnt].to=y;
	head[x]=cnt;
	deg[y]++;
}
int mxdeg[MAX],dep[MAX],ans1=INF;
long long ans2;
queue<int> q;
void solve(int x,int y)
{
	int mxdep=0;
	long long mxv;
	for(int i=1;i<=n;i++)
		mxdeg[i]=0,dep[i]=0;
	q.push(x),dep[x]=1;
	if(y) q.push(y),dep[y]=1;
	while(!q.empty())
	{
		int u=q.front();
		q.pop();
		mxdeg[dep[u]]=max(mxdeg[dep[u]],deg[u]);
		mxdep=max(mxdep,dep[u]);
		for(int i=head[u];i;i=a[i].next)
