  }

  //pair<int,ll> ans=solve(g);
  ans=mkp(N+1,0);
  ans=solve(g);
  g.resize(N+1);
  //cout<<ans.first<<" "<<ans.second<<endl;
  for(int i=0;i<N;i++){
      g[i].push_back(N);
