i64 far(i64 u, i64 p) {
  i64 d = 0;
  for (i64 v : g[u]) {
    if (v != p) d = max(d, 1 + far(v, u));
  }
  return d;
}

template<class G>
void dfs(const G& g, i64 u, i64 p, vector<i64>& a) {
  for (i64 v : g[u]) {
    if (v != p) {
      a[v] = a[u] + 1;
      dfs(g, v, u, a);
    }
  }
}

template<class G>
i64 h(const G& g, i64 u) {
  vector<i64> a(n + 1), deg(n + 1);
  dfs(g, u, -1, a);
  for (i64 u = 1; u <= n; ++u) {
    deg[a[u]] = max(deg[a[u]], i64(g[u].size()));
  }
  i64 y = g[u].size();
  for (i64 i = 0; i < n; ++i) {
    if (deg[i] >= 2) y *= deg[i] - 1;
  }
  return y;
}

i64 f(i64 u, i64 v) {
  auto z = g;
  z[u].erase(find(begin(z[u]), end(z[u]), v));
  z[v].erase(find(begin(z[v]), end(z[v]), u));
  z[u].push_back(0);
  z[v].push_back(0);
  z[0].push_back(u);
  z[0].push_back(v);
  return h(z, 0);
}

