    fill_n((i64*)leaf,128*128,-1);

    function<i64(int,int)> calc_height=[&](int u,int p){
        i64& res=height[u][p];
        if(res!=-1) return res;
        res=1;
        rep(i,0,tree[u].size()){
            if(tree[u][i]==p) continue;
            res=max(res,calc_height(tree[u][i],u)+1);
        }
        return res;
    };

    function<i64(int,int)> calc_leaf=[&](int u,int p){
        i64& res=leaf[u][p];
        if(res!=-1) return res;
        if(tree[u].size()==1) return res=i64(1);
        res=0;
        rep(i,0,tree[u].size()){
            if(tree[u][i]==p) continue;
            res+=calc_leaf(tree[u][i],u);
        }
        return res;
    };

    pair<i64,i64> ans(inf64,inf64);
    rep(i,0,N-1){
        int x=a[i],y=b[i];
        i64 max_height=1,max_leaf=1;
        {
            rep(j,0,tree[x].size()){
                if(tree[x][j]==y) continue;
                max_height=max(max_height,calc_height(tree[x][j],x)+1);
                max_leaf=max(max_leaf,calc_leaf(tree[x][j],x));
            }
        }
        {
            rep(j,0,tree[y].size()){
                if(tree[y][j]==x) continue;
                max_height=max(max_height,calc_height(tree[y][j],y)+1);
                max_leaf=max(max_leaf,calc_leaf(tree[y][j],y));
            }
        }
        pair<i64,i64> tmp(max_height,max_leaf*max<i64>({(i64)tree[x].size()-1,(i64)tree[y].size(),(i64)1})*2);
        ans=min(ans,tmp);
    }

    rep(i,0,N){
        int x=i;
        if(tree[x].size()==1) continue;
        i64 max_height=0,max_leaf=0;
        rep(j,0,tree[x].size()){
            max_height=max(max_height,calc_height(tree[x][j],x)+1);
            max_leaf=max(max_leaf,calc_leaf(tree[x][j],x));
        }
        pair<i64,i64> tmp(max_height,max_leaf*tree[x].size());
        ans=min(ans,tmp);
    }

    cout << ans.first << " " << ans.second << endl;
}

