	if(n == 1) {puts("1 1"); return 0;}
	if(n == 2) {puts("1 2"); return 0;}
	for(ll i=1;i<n;i++) {
		ll A, B;
		scanf("%lld%lld",&A,&B);
		adj[A].push_back(B);
		adj[B].push_back(A);
	}
	l = mxd(mxd(1).Y).X;
	solve();
	if(l%2) {
		for(ll i=1;i<=n;i++) {
			n++;
			adj[i].push_back(n);
			adj[n].push_back(i);
			solve();
			adj[i].pop_back();
			adj[n].pop_back();
			n--;
		}
	}
	printf("%lld %lld\n",(l+1)/2,ans);
}

