		DFS(r[k], G, dep[k]);
		r[k+1] = -1;
		for(int i = 0; i < N; i++)
			if(r[k+1] == -1 || dep[k][i] > dep[k][r[k+1]]) r[k+1] = i;
	}
	int col_min = dep[2][r[3]] / 2 + 1;

