#include<bits/stdc++.h>
#define ll unsigned long long
#define N 505
using namespace std;
int a[N],head[N],vet[N<<1],Next[N<<1],num;
int Max[N],x,y,n,Maxdpt,vis[N];
ll ans1,ans2;
void add(int x,int y){
	Next[++num]=head[x];
	head[x]=num;
	vet[num]=y;
}
bool find(int v,int u,int last){
	if (v==u){
		a[++num]=v;
		return 1;
	}
	for (int i=head[v];i;i=Next[i]){
		if (vet[i]==last) continue;
		if (find(vet[i],u,v)){
			a[++num]=v;
			return 1;
		}
	}
	return 0;
}
void dfs(int x,int last,int dpt){
	Maxdpt=max(Maxdpt,dpt);
	int tot=0;
	for (int i=head[x];i;i=Next[i]){
		if (vis[vet[i]]||vet[i]==last) continue;
		tot++;
		dfs(vet[i],x,dpt+1);
	}
	Max[dpt]=max(Max[dpt],tot);
}
void dfs1(int x,int last,int dpt){
	Maxdpt=max(Maxdpt,dpt);
	int tot=0;
	for (int i=head[x];i;i=Next[i]){
		if (vis[vet[i]]||vet[i]==last) continue;
		dfs(vet[i],x,dpt+1);
	}
	if (tot==0) ans2++;
}
int main(){
	scanf("%d",&n);
	for (int i=1;i<n;i++){
		scanf("%d%d",&x,&y);
		add(x,y);
		add(y,x);
	}
	ll res1=(1ll<<64)-1,res2=(1ll<<64)-1;
	for (int v=1;v<n;v++)
	for (int u=v+1;u<=n;u++){
		num=0;
		ans1=0,ans2=2;
		find(v,u,0);
		for (int i=1;i<=n;i++) vis[i]=0;
		for (int i=1;i<=num;i++) vis[a[i]]=1;
		for (int i=1;i<=n+1;i++) Max[i]=0;
		Maxdpt=0;
		dfs(v,0,1);
		dfs(u,0,1);
		ans1+=Maxdpt; 
		for (int i=1;i<Maxdpt;i++) ans2*=Max[i];
		for (int i=2;i<=num/2;i++){
			for (int i=1;i<=n+1;i++) Max[i]=0;
			Maxdpt=0;
			dfs(a[i],0,1);
			dfs(a[num-i+1],0,1);
			ans1+=Maxdpt;
			ll tmp=2;
			for (int i=1;i<Maxdpt;i++) tmp*=Max[i];
			if (Maxdpt>1) ans2+=tmp;
		}
		if (num%2==1){
			Maxdpt=0;
			dfs1(a[num/2+1],0,1);
			if (Maxdpt==1) ans2--;
			ans1+=Maxdpt;
		}
		if (ans1<res1||ans1==res1&&ans2<res2){
			res1=ans1;
			res2=ans2;
		}
	}
	cout<<res1<<' '<<res2<<endl;
}

