void dfs(int u, int p, int d, VI &D) {
	D[u] = d;
	for (int v : adj[u]) {
		if (v == p) continue;
		dfs(v, u, d+1, D);
	}
}
struct State {
	vector<int> curr;
	int others;
};

Long getLeaves(VI roots) {
	VI VIS(adj.size() , 0);
	Long shadows = 0;
	while(roots.size()) {
		vector<int> nr;
		for (int u : roots) VIS[u] = 1;
		VI NC;
		for (int u : roots) {
			int nc = 0;
			for (int v : adj[u]) {
				if (!VIS[v]) {
					nr.push_back(v);
					nc++;
				}
			}
			NC.push_back(nc);
		}
		int m = *max_element(NC.begin(), NC.end());
		int sum = 0;
		for (int n : NC) {
			sum += n;
		}
		if (nr.size() == 0) {
			shadows = shadows + roots.size();
		} else {
			shadows = shadows * m + NC.size() * m - sum;
		}
		roots = nr;
	}
	return shadows;
}

