		adj[u].push_back(v);
		adj[v].push_back(u);
	}
	VI D0(N);
	dfs(0, -1, 0, D0);
	int p1 = max_element(D0.begin(), D0.end()) - D0.begin();
	VI D1(N);
	dfs(p1, -1, 0, D1);
	int p2 = max_element(D1.begin(), D1.end()) - D1.begin();
	VI D2(N);
	dfs(p2, -1, 0, D2);
	IL = VI(N);
	vector<int> roots;
	int mi = 1000000000;
	for (int i = 0; i < N; ++i) {
		int t = max(D1[i], D2[i]);
		if ( t < mi ) {
			roots.clear();
			roots.push_back(i);
			mi = t;
		} else if(t == mi) {
			roots.push_back(i);
		}
	}
	if (roots.size() == 2) {
		cout << mi << " " << getLeaves(roots) << endl;
	} else {
		Long minLeaves = 1000000000000000000LL;
		for(int v : adj[roots[0]]) {
			VI tr = roots;
			tr.push_back(v);
			minLeaves = min(minLeaves, getLeaves(tr));
		}
		cout << mi + 1 << " " << minLeaves << endl;
	}


}

#include <cstdio>
