using namespace std;

int a[100][100];
int b[100];
vector <int> v[100];

vector <int> merge(vector <int> &v, vector <int> &w) {
    int i;
    vector <int> z = v;

    for (i = 0; i < w.size(); i++) {
        if (i < v.size()) {
            z[i] = max(z[i], w[i]);
        } else {
            z.push_back(w[i]);
        }
    }

    return z;
}

vector <int> dfs(int x, int y) {
    int f = 0, i;
    vector <int> w;

    for (i = 0; i < v[x].size(); i++) {
        if (v[x][i] == y) {
            f = 1;
            continue;
        }

        vector <int> z = dfs(v[x][i], x);
        w = merge(w, z);
    }

    if (v[x].size() != f) w.insert(w.begin(), v[x].size() - f);

    return w;
}

long long calc(int x, int y) {
    int i;
    long long ans = 2;
    vector <int> z1 = dfs(x, y);
    vector <int> z2 = dfs(y, x);
    vector <int> z = merge(z1, z2);

    for (i = 0; i < z.size(); i++) ans *= z[i];

    return ans;
}

long long calc2(int x) {
    int i;
    long long ans = 1;
    vector <int> z = dfs(x, -1);

    for (i = 0; i < z.size(); i++) ans *= z[i];

    return ans;
}

int main() {
    int n, i, j, k;
    long long ans1, ans2;
    vector <int> w;

    scanf("%d", &n);

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (i == j) {
                a[i][j] = 0;
            } else {
                a[i][j] = 1e9;
            }
        }
    }

    for (i = 0; i < n - 1; i++) {
        int x, y;

        scanf("%d %d", &x, &y);

        x--;
        y--;

        a[x][y] = a[y][x] = 1;
        v[x].push_back(y);
        v[y].push_back(x);
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            for (k = 0; k < n; k++) {
                a[j][k] = min(a[j][k], a[j][i] + a[i][k]);
            }
        }
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) b[i] = max(b[i], a[i][j]);
    }

    w.push_back(0);
    for (i = 1; i < n; i++) {
        if (b[i] < b[w[0]]) {
            w.clear();
            w.push_back(i);
        } else if (b[i] == b[w[0]]) {
            w.push_back(i);
        }
    }

    if (w.size() == 1) {
        ans1 = b[w[0]] + 1;
        ans2 = calc2(w[0]);

        for (i = 0; i < v[w[0]].size(); i++) ans2 = min(ans2, calc(w[0], v[w[0]][i]));
    } else {
        ans1 = b[w[0]];
        ans2 = calc(w[0], w[1]);
    }

    printf("%lld %lld\n", ans1, ans2);

    return 0;
}

