#define V vector
vel dis(int mid1, vvel &way) {
	int n = way.size();
	vel dist(n, -1); dist[mid1] = 0;
	queue<int> q;
	q.push(mid1);
	while (!q.empty()) {
		int st = q.front(); q.pop();
		rep(i, way[st].size()) {
			int to = way[st][i];
			if (dist[to] == -1) {
				dist[to] = dist[st] + 1;
				q.push(to);
			}
		}
	}
	return dist;
}
pin most_far(int now,int n,vvel &way) {
	vel dist1 = dis(now,way);
	pin ans = mkp(-1, 0);
	rep(i, n) {
		if (dist1[i] > ans.first) { ans = mkp(dist1[i], i); }
	}
	return ans;
}
int fid(int le,int st,int goal,vvel &way) {
	vel dist = dis(st, way);
	while (dist[goal] > le) {
		rep(j, way[goal].size()) {
			if (dist[goal] > dist[way[goal][j]]) {
				goal = way[goal][j];
				break;
			}
		}
	}
	return goal;
}
