const long long mod = 1000000007;

const int mxN = 110;

vector<int> tree[mxN];
int par[mxN][20];
int h[mxN];

pair<int,int> up(pair<int,int> c) {return {c.first+1,c.second};}

pair<int,int> di(int v,int p = -1) {
	pair<int,int> res = {1,v};
	for(auto u : tree[v]) if(p != u) res = max(res,up(di(u,v)));
	return res;
}

void dfs(int v = 0,int p = -1){
	h[v] = (p==-1?0:h[p]+1);
	par[v][0] = p;
	for(int i = 1;par[v][i-1] != -1;i++)
		par[v][i] = par[par[v][i-1]][i-1];
	for(auto u : tree[v]){
		if(u != p)
			dfs(u,v);
	}
}
int lca(int u,int v){
	if(h[u] > h[v])
		swap(u,v);
	for(int i = 19;i >= 0;i--){
		if(par[v][i] != -1 && h[par[v][i]] >= h[u])v = par[v][i];
	}
	if(u == v)return u;
	for(int i = 19;i >= 0;i--){
		if(par[v][i] != par[u][i])v = par[v][i],u = par[u][i];
	}
	return par[v][0];
}

int dst(int u,int v) {
	return h[u] + h[v] - 2 * h[lca(u,v)] + 1;
}

size_t mx[mxN];
void get(int u,int p = -1,int at = 0) {
	for(auto v : tree[u]) if(v != p) get(v,u,at+1);
	mx[at] = max(mx[at],tree[u].size() - (p != -1));
}

int N;
long long solve(int d) {
	int u,v;
	u = di(0).second;
	v = di(u).second;
	memset(par,-1,sizeof par);
	dfs();
	if((d+1)/2 != (dst(u,v)+1)/2) return LLONG_MAX;
	d = dst(u,v);
	for(int i = 0;i < N;i++) {
		if(dst(u,i)<<1 == d + 1 && dst(v,i)<<1 == d + 1) {
			long long res = 1;
			get(i);
			for(int j = 0;j * 2 + 2 < d;j++) res *= mx[j];
			return res;
		}
	}
	assert(!(d&1));
	long long res = LLONG_MAX;
	for(int i = 0;i <= N;i++) {
		for(auto j : tree[i]) {
			int a = di(i,j).first;
			int b = di(j,i).first;
			if(a == b && b + a == d) {
				long long cur = 1;
				get(i,j);
				get(j,i);
				for(int at = 0;at * 2 + 2 < d;at++) cur *= mx[at];
				res = min(res,2*cur);
			}
		}
	}
	return res;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	int u,v;
	cin>>N;
	for(int i = 1;i < N;i++) {
		cin>>u>>v;
		u--,v--;
		tree[u].push_back(v);
		tree[v].push_back(u);
	}
	u = di(0).second;
	v = di(u).second;
	memset(par,-1,sizeof par);
	dfs();
	int d = dst(u,v);
	long long res = solve(d);
	for(int i = 0;i < N;i++) {
		tree[i].push_back(N);
		tree[N].push_back(i);
		res = min(res,solve(d));
		cerr<<i<<' '<<res<<'\n';
		tree[i].pop_back();
		tree[N].clear();
	}
	cout<<(d+1)/2<<' '<<res<<'\n';
	return 0;
}

