ll Max(size_t a, size_t b)
{
	if (a > b) return (ll)a;
	return (ll)b;
}

ll min3(ll a, ll b, ll c)
{
	if (a < b && a < c) return a;
	if (b < c) return b;
	return c;
}

class Diameter
{
public:
	vec<vec<int>> g;
	pair<int, int> ps;
	vec<int> path;
	int n;
	Diameter(int num): g(num) {
		ps.first = 0;
		ps.second = 0;
		n = num;
	}

	void edge(int a, int b) {
		g[a].pb(b);
		g[b].pb(a);
	}

	int longest(int a) {
		queue<pair<int, vec<int>>> keep;
		vec<int> hoge = {a};
		keep.push(mp(a, hoge));
		vec<int> dp(n, 0);

		pair<int, vec<int>> cur;
		while(!keep.empty()) {
			pair<int, vector<int>> get = keep.front();
			keep.pop();
			int cur_p = get.first;
			if (dp[cur_p]) continue;
			dp[cur_p] = 1;
			cur = get;
			rep(i, g[cur_p].size()) {
				int v = g[cur_p][i];
				vec<int> v_path = get.second;
				v_path.pb(v);

				keep.push(mp(v, v_path));
			}
		}

		path = cur.second;
		return cur.first;
	}

	vec<int> diameter(void) {
		ps.first = longest(0);
		ps.second = longest(ps.first);
		return path;
	}
};

int main(void)
{
	int n;
	cin >> n;
	Diameter d(n);
	rep(i, n - 1) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		d.edge(a, b);
	}

	vec<int> path = d.diameter();

	int l = (int)path.size();
	ll ans = 1;
	if (l % 2 == 0) {
		rep(i, l / 2) {
			if (!i) continue;
			ans *= Max(d.g[path[i]].size() - 1, d.g[path[l - 1 - i]].size() - 1);
		}
		ans *= 2;
	} else {
		ll ans1 = 1;
		ll ans2 = 1;
		ll ans3 = 1;
		vec<int> path2 = path;
		vec<int> path3 = path;
		path2.pb(n);
		path3.insert(path3.begin(), n);

		rep(i, l / 2) {
			if (!i) continue;
			ans1 *= Max(d.g[path[i]].size() - 1, d.g[path[l - 1 - i]].size() - 1);
		}
		ans1 *= (int)d.g[path[l / 2]].size();
		rep(i, l / 2 + 1) {
			if (!i) continue;
			ans2 *= Max(d.g[path2[i]].size() - 1, d.g[path2[l - i]].size() - 1);
			ans3 *= Max(d.g[path3[i]].size() - 1, d.g[path3[l - i]].size() - 1);
		}
		ans2 *= 2;
		ans3 *= 2;

		ans = min3(ans1, ans2, ans3);
	}

	cout << (l + 1) / 2 << " " << ans << endl;
	return 0;
}

