int solve(int dia) {
	int D = dia / 2;
	int pos;
	rep(i, n - 1) {
		if (d2[A[i]] > d2[B[i]])swap(A[i], B[i]);
		if (d2[A[i]] == D&&d2[B[i]] == D + 1 && d2[A[i]] + d1[B[i]] + 1 == dia)pos = i;
	}

