#define MAXN 109

struct myc {
    int x;
    long long y;
    inline bool operator < (const myc &u) const {
        if (x == u.x) return y < u.y;
        else return x < u.x;
    }
};

std::vector < int > g[MAXN];
int d[2][MAXN];
bool viz[MAXN];
int v[MAXN];
int cul[MAXN];
int urm[MAXN];
int t, r[2][MAXN];

void dfs(int x) {
    viz[x] = 1;
    for (auto &y : g[x]) {
        if (viz[y] == 0) {
            d[t][y] = d[t][x] + 1;
            urm[y] = x;
            dfs(y);
        }
    }
}

inline myc solve(int n) {
    for (int i = 1; i <= n; i++)
        viz[i] = 0;
    t = 0;
    d[0][1] = 0;
    dfs(1);
    int a = 1;
    for (int i = 2; i <= n; i++)
        if (d[0][i] > d[0][a])
            a = i;

    for (int i = 1; i <= n; i++)
        viz[i] = 0;
    t = 1;
    d[1][a] = 0;
    dfs(a);
    int b = 1;
    for (int i = 2; i <= n; i++)
        if (d[1][i] > d[1][b])
            b = i;

    v[0] = 0;
    while (b != a) {
        v[++v[0]] = b;
        b = urm[b];
    }
    v[++v[0]] = a;

    r[0][0] = r[1][0] = 0;
    for (int i = 1; i <= n; i++)
        cul[i] = 0;
    if (v[0] % 2 == 1)
        r[0][++r[0][0]] = v[v[0] / 2 + 1];
    else
        r[0][++r[0][0]] = v[v[0] / 2], r[0][++r[0][0]] = v[v[0] / 2 + 1];

    int val = (v[0] + 1) / 2, p = 0, q = 1;
    long long cnt = 0, ans = r[0][0];
    while (q < val) {
        for (int i = 1; i <= r[p][0]; i++)
            cul[r[p][i]] = q;
        q++;
        int best = 0, sum = 0;
        for (int i = 1; i <= r[p][0]; i++) {
            int cat = 0;
            for (auto &x : g[r[p][i]])
                if (cul[x] == 0)
                    cat++, r[1 - p][++r[1 - p][0]] = x;
            best = std::max(best, cat);
            sum += cat;
        }

        cnt = (cnt + r[p][0]) * best;
        ans = cnt;
        cnt -= sum;
        ans = cnt + sum;
        if (ans < 0)
            while(1);

        r[p][0] = 0;
        p = 1 - p;
    }

    return {val, ans};
}

int main() {
    int n;
    scanf("%d", &n);

    for (int i = 1; i < n; i++) {
