    myc ans = solve(n);
    for (int i = 1; i <= n; i++) {
        g[i].push_back(n + 1);
        g[n + 1].push_back(i);
        myc sol = solve(n + 1);
        if (sol < ans)
            ans = sol;
        g[n + 1].clear();
        g[i].pop_back();
    }

    printf("%d %lld\n", ans.x, ans.y);

    return 0;
}

