	MaxLeafCount[u] = 1;
	for(int i = 0; i < g[u].size(); i++)
	{
		int v = g[u][i];
		if(v != p)
		{
			dfs(v , u , depth + 1);
			MaxLeafCount[u] = max(MaxLeafCount[u] , MaxLeafCount[v]);
		}
	}
	MaxLeafCount[u] = (g[u].size() - 1) * MaxLeafCount[u];
}
