void dfs(int v, int p)
{
	for (auto e : go[v])
	{
		if (e == p)
			continue;
		d[e] = d[v] + 1;
		par[e] = v;
		dfs(e, v);
	}
}

ull calc_for(int e, int pe)
{
	vector<int> maxs(n, 1);
	d[e] = 0;
	dfs(e, pe);
	d[pe] = 0;
	dfs(pe, e);
	for (int i = 0; i < n; ++i)
		maxs[d[i]] = max(maxs[d[i]], (int)go[i].size() - 1);
	ull res = 2;
	for (auto t : maxs)
		res *= t;
	return res;
}

void solve()
{
	scanf("%d", &n);
	for (int i = 0; i < n - 1; ++i)
	{
		int a, b;
		scanf("%d%d", &a, &b);
		--a, --b;
		go[a].push_back(b);
		go[b].push_back(a);
	}
	dfs(0, -1);
	int root = max_element(d, d + n) - d;
	d[root] = 0;
	dfs(root, -1);
	int e = max_element(d, d + n) - d;
	int maxd = d[e];
	while ((d[e] - 1) * 2 >= maxd)
		e = par[e];
	ull res = 1;
	vector<int> maxs(n, 1);
	if (maxd % 2 == 0)
	{
		d[e] = 0;
		dfs(e, -1);
		maxs[0] = go[e].size();
		for (int i = 0; i < n; ++i)
			maxs[d[i]] = max(maxs[d[i]], (int)go[i].size() - 1);
		for (auto t : maxs)
			res *= t;
		for (auto t : go[e])
			res = min(res, calc_for(e, t));
	}
	else
		res = calc_for(e, par[e]);
	printf("%d %lld\n", maxd / 2 + 1, res);
}

