using namespace std;
typedef long long ll;
typedef double dbl;
const int INF = 1.01e9;

pair<int, ll> solve(vector<pair<int, int>> ed) {
    int n = ed.size() + 1;

    vector<vector<int>> e(n + 1);
    for (auto o : ed) {
        e[o.first].push_back(o.second);
        e[o.second].push_back(o.first);
    }

    vector<int> d(n + 1, -1);
    vector<int> pr(n + 1);
    function<void(int, int, int)> dfs1 = [&](int v, int h, int p) {
        if (d[v] != -1) return;
        d[v] = h;
        pr[v] = p;
        for (int to : e[v]) {
            dfs1(to, h + 1, v);
        }
    };

    pair<int, ll> ans = make_pair(INF, INF);

    auto solve = [&](int root, int sub) {
        d.assign(n, -1);
        dfs1(root, 0, -1);

        vector<int> vct(n);
        iota(vct.begin(), vct.end(), 0);
        sort(vct.begin(), vct.end(), [&](int i, int j) {
            return d[i] > d[j];
        });

        vector<ll> dp(n);
        vector<int> mx(n, 1);
        ll prod = 1;
        for (int v : vct) {
            int cnt = 0;
            for (int to : e[v]) {
                if (d[to] > d[v]) {
                    assert(d[to] == d[v] + 1);
                    cnt++;
                }
            }
            mx[d[v]] = max(mx[d[v]], cnt);
        }
        for (int i = 0; i < n; i++) prod *= mx[i];

        int res = d[vct[0]] + 1;
        res -= sub;
        ans = min(ans, make_pair(res, prod));
    };

    auto addEdge = [&](int u, int v) {
        e[u].erase(find(e[u].begin(), e[u].end(), v));
        e[v].erase(find(e[v].begin(), e[v].end(), u));

        e[u].push_back(n);
        e[n].push_back(u);
        e[v].push_back(n);
        e[n].push_back(v);
        n++;
        solve(n-1, 1);
        n--;
        e[u].pop_back();
        e[v].pop_back();
        e[n].pop_back();
        e[n].pop_back();

        e[u].push_back(v);
        e[v].push_back(u);
    };

    for (int i = 0; i < n; i++) if (e[i].size() != 1) solve(i, 0);
    for (int i = 0; i < n; i++) for (int to : e[i]) addEdge(i, to);


    return ans;
};

