		}
		if (diam<=col){
			map<int,ll> mp,mp2;
			REP(v,V){
				if (dist[0][v]==diam){
					mp[v]=1;
				}
			}
			REP(i,diam){
				for(auto ite:mp){
					REP(i,(int)G[ite.first].size()){
						if (dist[0][G[ite.first][i]]<dist[0][ite.first]){
							mp2[G[ite.first][i]]+=ite.second;
