        G[a].push_back(b);
        G[b].push_back(a);
    }

    auto [p, q] = tree_diameter(G);
    ll d = q.first;
    ll u = p.second;
    ll v = q.second;

    vector<ll> path;
    get_diameter_vertices(G, u, -1, v, path);

    ll ans1, ans2 = INF;

    ans1 = d/2 + 1;

    if(d%2){
        chmin(ans2, solve(path[d/2], path[d/2+1], G));
    }else{
        ll center = path[d/2];
        chmin(ans2, solve(center, center, G));
        for(auto v: G[center]){
            chmin(ans2, solve(center, v, G));
        }
    } 

    cout << ans1 << " " << ans2 << endl;
    return 0;
}

