vi diameter(vvi g){
    ll n=g.size();
    vi dis(n,inf);
    queue<ll> q;
    q.emplace(0);
    dis[0]=0;
    while(!q.empty()){
        auto t=q.front();q.pop();
        for(ll x:g[t]){
            if(chmin(dis[x],dis[t]+1))q.emplace(x);
        }
    }
    P far=P(-1,-1);
    rep(i,n)chmax(far,P(dis[i],i));
    dis=vi(n,inf);
    ll ne=far.se;
    dis[ne]=0;
    q.emplace(ne);
    vi par(n,-1);
    while(!q.empty()){
        auto i=q.front();q.pop();
        for(ll x:g[i])if(x!=par[i]){
            dis[x]=dis[i]+1;q.emplace(x);par[x]=i;
        }
    }
    far=P(-1,-1);
    rep(i,n)chmax(far,P(dis[i],i));
    ll w=far.se;
    vi res;
    while(w!=ne){
        res.pb(w);
        w=par[w];
    }
    res.pb(ne);
    return res;
}
ll solve(vvi g,vi dp,ll t){
    ll n=g.size();
    ll res=dp.size();
    vb used(n,false);
    for(ll x:dp)used[x]=true;
    ll c=0;
    while(true){
        vi ndp;
        ll ma=0;
        c++;
        for(ll i:dp){
            ll cnt=0;
            for(ll x:g[i])if(!used[x]){
                used[x]=true;
                cnt++;
                ndp.pb(x);
            }
            chmax(ma,cnt);
        }
        if(ma==0)break;
        res*=ma;
        dp=ndp;
    }
    if(c==t)return res;
    return inf;
}
