int n,d[105],dep[105],maxd[105];
vector<int> G[105];
pll ans;
void add(int x,int y)
{
	G[x].push_back(y);G[y].push_back(x);
	d[x]++,d[y]++;
}
int bfs(int x,int y)
{
	int maxx=0;
	memset(dep,0,sizeof(dep));
	memset(maxd,0,sizeof(maxd));
	queue<int> q;
	dep[x]=1,dep[y]=1;
	q.push(x);if(y) q.push(y);
	while(!q.empty())
	{
		int u=q.front();
		q.pop();
		maxd[dep[u]]=max(maxd[dep[u]],d[u]);
		maxx=max(maxx,dep[u]);
		int sz=G[u].size();
		for(int i=0;i<sz;i++)
		{
			int nx=G[u][i];
			if(!dep[nx]) dep[nx]=dep[u]+1,q.push(nx);
		}
	}
	return maxx;
}
void Solve(int x,int y)
{
	pll s;
	s.first=bfs(x,y);s.second=maxd[1]-(y!=0);
	for(int i=2;i<=n;i++)
	{
		if(maxd[i]==1) break;
		s.second=s.second*(maxd[i]-1);
	}
	if(y) s.second*=2;
	ans=min(ans,s);
}
