				ile++;
		mapa[odl[i]]=max(mapa[odl[i]], ile);
	}
	//~ debug() << range(res+1, res+1+n);
	//~ debug() << mapa;
	for (auto i : mapa)
		if (i.second)
			ret*=i.second;

	return {naj, ret*wek.size()};
