struct edge{ll to;};
struct graph{
    ll N;
    vector<vector<edge> > G;
    vector<bool> used;
    vector<ll> A;

    graph(ll n): N(n), G(N), used(N,false), A(N,0) {}

    void ade(ll s, ll t){
        G[s].emplace_back((edge){t});
        G[t].emplace_back((edge){s}); //無向ならON
    }

    void dfs(ll v=0, ll p=0){
        used[v]=true;
        ll ct=0;
        for(auto E : G[v]){
            if(!used[E.to]){
                dfs(E.to,p+1);
                ++ct;
            }
        }
        maxi(A[p+1],ct);
    }

    P gon(ll v){
        rep(i,N) used[i]=false;
        rep(i,N) A[i]=0;
        dfs(v);
        ll huka=1,ha=1;
        reps(i,1,N){
            if(A[i]==0) break;
            ++huka;
            ha*=A[i];
        }
        return {huka,ha};
    }

    P goe(ll v, ll v2){
        rep(i,N) used[i]=false;
        rep(i,N) A[i]=0;
        used[v]=true;
        used[v2]=true;
        dfs(v);
        dfs(v2);
        ll huka=1,ha=2;
        reps(i,1,N){
            if(A[i]==0) break;
            ++huka;
            ha*=A[i];
        }
        return {huka,ha};
    }
};
//--MAIN-----------------------------------
void Main() {
    ll N;
    cin>>N;
    graph g(N);
    vector<P> kore;
    rep(i,N-1){
        ll a,b; cin>>a>>b; --a,--b;
        kore.emplace_back(a,b);
        g.ade(a,b);
    }
    ll ans0=INF2,ans1=INF2;
    rep(i,N){
        P pa=g.gon(i);
        if(mini(ans0,pa.first)) ans1=pa.second;
        else if(ans0==pa.first) mini(ans1,pa.second);
    }
    rep(i,N-1){
        P pa=g.goe(kore[i].first, kore[i].second);
        if(mini(ans0,pa.first)) ans1=pa.second;
        else if(ans0==pa.first) mini(ans1,pa.second);
    }
    cout<< ans0 SP ans1 <<"\n";
}

