#include <bits/stdc++.h>

const int N = 200;
const int INF = 1<<30;

inline int read()
{
	char c = getchar(); int f = 1, x = 0;
	while( c < '0' || c>'9' ) { if(c == '-') f = -1;  c = getchar(); }
	while( c >= '0'&&c<='9' ) { x = x * 10 + c - '0'; c = getchar(); }
	return f * x;
}

int tot = 0, front[N];

struct tEdge {
    int v, next;
} e[N<<1];

inline void add_edge( int u, int v ) {
    e[++tot] = { v, front[u] }; front[u] = tot;
    e[++tot] = { u, front[v] }; front[v] = tot; 
}

int n, m = INF, max_dep[N];

inline int find_max_dep( int u, int fa )
{
    int ret = 0;

    for( int i = front[u]; i; i = e[i].next ) 
    {
        int v = e[i].v;
        if( v == fa ) continue;

        ret = std::max( ret, find_max_dep( v, u ) );
    }

    return ret + 1;
}

int sum[N];

inline int find_leaves( int u, int fa, int dep )
{
    int now_sum = 0;

    for( int i = front[u]; i; i = e[i].next )
    {
        int v = e[i].v;
        if( v == fa ) continue;

        find_leaves( v, u, dep + 1 );
        now_sum ++;
    } 

    sum[dep] = std::max( sum[dep], now_sum );
}

inline int calc_ans( int u, int v )
{
	int ret = 0;
	if( !v )
	{
    	for( int i = front[u]; i; i = e[i].next )
        	find_leaves( e[i].v, u, 1 ), ret ++;

    	for( int i = 1; sum[i]; i ++ )
	        ret *= sum[i], sum[i] = 0;

    	return ret;
	}

    ret = 2;
    find_leaves( u, v, 1 );
    find_leaves( v, u, 1 );

	for( int i = 1; sum[i]; i ++)
		ret *= sum[i], sum[i] = 0;
	return ret;
}

int main()
{
    memset( max_dep, 0, sizeof( max_dep ) ); 

    n = read();
    for( int i = 1; i < n; i ++ )
        add_edge( read(), read() );

    int x = 0, y = 0;
    for( int i = 1; i <= n; i ++ )
        max_dep[i] = find_max_dep( i, 0 ),
        m = std::min( m, max_dep[i] );

    for( int i = 1; i <= n; i ++ )
        if( max_dep[i] == m ) 
            y = x ? i : 0, x = x ? x : i;

    int ans;
    if( !y )
    {
    	ans = calc_ans( x, 0 );
    	for( int i = front[x]; i; i = e[i].next )
    		ans = std::min( ans, calc_ans( x, e[i].v ) );
	}
	else ans = calc_ans( x, y );

    printf( "%d %d\n", m - ( !!y ), ans );

    return 0;
}

