ll ans = INF;

void check(int v, int st, bool fl = 0) {
	used[v] = 1;
	ll curD = d[st][v];

	if (v != st) {
		vals[curD] = max(vals[curD], ll(gr[v].size() - 1));
	}
	else {
		if (!fl) {
			vals[curD] = max(vals[curD], ll(gr[v].size()));
		}
		else {
			vals[curD] = max(vals[curD], ll(gr[v].size() - 1));
		}
	}

	for (auto to : gr[v]) {
		if (!used[to]) {
			check(to, st, fl);
		}
	}
}

vector<ll> sv;
void check2(int v, int dist, int st) {
	vector<vector<ll>> cur;

	used[v] = 1;
	ll curD = d[st][v];
	if (curD == dist) return;

	if (st != v) vals[curD] = max(vals[curD], ll(gr[v].size()));


	for (auto to : gr[v]) {
		if (!used[to]) {
			check2(to, dist, st);
		}
		if (v == st) {
			cur.push_back(vals);
			for (auto &cur : vals) cur = 0;
		}
	}

	for (int i = 0; i < cur.size(); i++) {
		vector<ll> c(vals.size());
		for (int t = 0; t < cur.size(); t++) {
			if (t != i) {
				for (int j = 0; j < vals.size(); j++) c[j] = max(c[j], cur[t][j]);
			}
			else {
				for (int j = 0; j < vals.size(); j++) {
					if (j > 0) c[j - 1] = max(c[j - 1], cur[t][j]);
				}
			}
		}

		ll cr = 1;
		c[0] = max(c[0], ll(gr[0].size() - 1));
		for (int i = 0; i < vals.size(); i++) {
			if (c[i] != 0) c[i]--;
		}
		for (int i = 0; i < vals.size() - 1; i++) {
			if (c[i] != 0) cr *= c[i];
		}
		if (cr == 8) {
			cout << "";
		}
		ans = min(ans, cr * 2);
	}
}

