		gr[u].push_back(v);
		gr[v].push_back(u);
	}

	ll dim = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) used[j] = 0;
		queue<ll> q;
		q.push(i);
		while (!q.empty()) {
			ll v = q.front();
			q.pop();
			used[v] = 1;
			for (auto to : gr[v]) {
				if (!used[to]) {
					d[i][to] = d[i][v] + 1;
					par[i][to] = v;
					used[to] = 1;
					q.push(to);
				}
			}
		}
		for (int j = 0; j < n; j++) dim = max(dim, d[i][j]);
	}

	vals.resize(dim + 1);

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			if (d[i][j] == dim) {
				vals.clear();
				vals.resize(dim + 1);
				for (int t = 0; t < n; t++) used[t] = 0;
				ll v = j;
				if (dim % 2 != 0) {
					ll ds = (dim - 1) / 2 + 1;
					while (d[i][v] != ds) {
						v = par[i][v];
					}
					ll u = par[i][v];
					used[u] = 1;
					used[v] = 1;
					check(u, u, 1);
					check(v, v, 1);
				}
				else {
					while (d[i][v] != dim / 2) {
						v = par[i][v];
					}
					check(v, v);
				}

				ll cur = 1;

				for (int i = 0; i < vals.size() - 1; i++) {
					if (vals[i] != 0) cur *= vals[i];
				}
				if (dim % 2 != 0) cur *= 2;
				ans = min(ans, cur);

				if (dim % 2 == 0) {
					sv.clear();
					sv.resize(dim + 1);
					for (int i = 0; i < n; i++) used[i] = 0;
					check2(v, dim, v);
				}
			}
		}
	}

	cout << (dim) / 2 + 1 << " " << ans;
	return 0;
}

