    while (233) {
        swap(A, B), B.clear(); int t = 0;
        for (auto u : A) {
            t = max((int)G[u].size() - 1, t);
            for (auto v : G[u]) if (dep[v] > dep[u]) 
                B.push_back(v);
        }
        if (!t) return nw;
        nw *= t;
    }
}

inline int work2(int A, int B) {
    int nw = n + 1;
    for (auto &v : G[A]) if (v == B) { v = nw; break; }
    for (auto &v : G[B]) if (v == A) { v = nw; break; }
