			v=gg[u][i];
			if(vis[v]) continue;
			d[v]=d[u]+1;
			vis[v]=1;
			fa[v]=u;
			sz[u]++;
			que.push(v);
		}
	}
}

int go_up(int u,int t) {
	while(t--) {
		u=fa[u];
	}
	return u;
}

LL cal(int u,int v) {
	bfs(u,v);
	memset(c,0,sizeof(c));
	for(int i=1;i<=n;i++) {
		c[d[i]+1]=max(c[d[i]+1],sz[i]);
	}
	LL res=1;
	c[0]=(v==0)?1:2;
	for(int i=0;i<=n;i++) {
		if(c[i]>0) res*=c[i];
	}
	return res;
}

void solve() {
	bfs(1,0);
	int a1=1,a2;
	for(int i=1;i<=n;i++) {
		if(d[i]>d[a1]) {
			a1=i;
		}
	}
	bfs(a1,0);
	a2=a1;
	for(int i=1;i<=n;i++) {
		if(d[i]>d[a2]) {
			a2=i;
		}
	}
	int ans1=(d[a2]+2)/2;
	LL ans2=INF;
	if(d[a2]&1) {
		int f1=go_up(a2,d[a2]/2);
		int f2=fa[f1];
		ans2=min(ans2,cal(f1,f2));
	}
	else {
		int f=go_up(a2,d[a2]/2);
		ans2=min(ans2,cal(f,0));
		for(int i=0;i<gg[f].size();i++) {
			u=gg[f][i];
			ans2=min(ans2,cal(f,u));
		}
	}
	printf("%d %lld\n",ans1,ans2);
}

