using namespace std;

typedef long long i64;

vector <int> adia[1010];
int lvl[1010];

void dfs(int nod, int tata, int l)
{
    int fii = 0;

    for (auto i : adia[nod]) {
        if (i != tata) {
            fii++;
            dfs(i, nod, l + 1);
        }
    }
    lvl[l] = max(lvl[l], fii);
}

pair <int, i64> solve(int nod1, int nod2 = 0)
{
    memset(lvl, 0, sizeof lvl);
    if (nod2 == 0)
        dfs(nod1, 0, 1);
    else {
        dfs(nod1, nod2, 1);
        dfs(nod2, nod1, 1);
    }
    int h = 0;
    i64 niv = 1 + (nod2 != 0);
    int nivmod = niv;

    for (int i = 1; lvl[i]; i++) {
        h = i;
        niv *= lvl[i];
        nivmod = 1LL * nivmod * lvl[i] % mod;
    }

    if (niv % mod != nivmod)
        return { 1e9, 1e9 };
    return { h + 1, niv };
}

