ll calc(int v) {
    ll cur = sz(a[v]);
    q[0].pb(v);
    memset(use, 0, sizeof(use));
    use[v] = 1;    
    for (int i = 0; ; ++i) {
        int i0 = (i & 1), i1 = (i0 ^ 1);
        if (q[i0].empty()) {
            break;
        }
        int mx = 0;
        for (int from: q[i0]) {
            for (int to: a[from]) {
                if (use[to])
                    continue;
                //debug(to);
                umx(mx, sz(a[to]) - 1);
                q[i1].pb(to);
                use[to] = 1;                                
            }
        }
