pa<int, ll> solve() {
    forn(i, n) {
        dfs(i, -1, 0, i);
    }
    int globmin = 1e9, globmax = -1;
    int mini = -1;
    forn(i, n) {
        int maxx = -1;
        forn(j, n) {
            umx(maxx, d[i][j]);
        }
        if (umn(globmin, maxx)) {
            mini = i;
        }
        umx(globmax, maxx);
    }
    if (2 * globmin != globmax) {
        int v = -1;
        forn(i, sz(a[mini])) {
            int to = a[mini][i];
            int maxx = -1;
            forn(j, n) {
                umx(maxx, d[to][j]);
            }
            if (maxx == globmin) {
                v = to;
                break;
            }
        }
        assert(v >= 0);
        a[n].pb(v);
        a[n].pb(mini);
        a[v].pb(n);
        a[mini].pb(n);
        del(mini, v);
        del(v, mini);
        //debug(mt(v, mini));
        mini = n;
        n++;
    }
    q[0].clear();
    q[1].clear();
    return mp(globmax / 2 + 1, calc(mini));
}

