int dfs ( int now, int nf )
{
	int ans = 1;
	for ( int i = la[now]; ~i; i = edge[i].last ) if ( edge[i].v ^ nf ) ans = max ( ans, dfs ( edge[i].v, now ) + 1 );
	return ans;
