LL getval ()
{
	lp ( i, 1, MAXN ) q[i].clear ();
	INIT ( vis, false );
	for ( auto x : q[0] ) vis[x] = true;

	LL nc = q[0].size ();
	int v, size, nd;
	lp ( i, 0, n ) {
		if ( q[i].empty () ) break;
		int size = q[i].size ();
		lp ( j, 0, size ) {
			deg[j] = 0;
			int u = q[i][j];
			for ( int e = la[u]; ~e; e = edge[e].last ) {
				if ( !vis[v = edge[e].v] ) {
					q[i + 1].push_back ( v );
					vis[v] = true;
					++deg[j];
				}
			}
		}
		nd = *max_element ( deg, deg + size );
		if ( !nd ) break;
		nc *= nd;
	}

	return nc;
}

