vector<int>E[110];
void DFS(int a, int pp) {
	for (auto &x : E[a]) {
		if (x == pp)continue;
		Dep[x] = Dep[a] + 1;
		DFS(x, a);
	}
}
void Do1(int a, int r) {
	if (rr < r)return;
	if (rr > r) {
		rr = r, res = -1;
	}
	Dep[a] = 0;
	DFS(a, 0);
	int i;
	for (i = 0; i <= n; i++)MM[i] = 0;
	for (i = 1; i <= n; i++) {
		MM[Dep[i]] = max(MM[Dep[i]], (int)E[i].size());
	}
	long long c = 1;
	for (i = n; i >= 0; i--) {
		if (!MM[i])continue;
		if (i)MM[i]--;
		if(MM[i])c = c*MM[i];
	}
	if (res == -1 || res > c)res = c;
}
void Del(int a, int b) {
	int i;
	for (i = 0; i < E[a].size(); i++) {
		if (E[a][i] == b) {
			swap(E[a][i], E[a][E[a].size() - 1]);
			E[a].pop_back();
			break;
		}
	}
}
void Add(int a, int b) {
	E[a].push_back(b);
	E[b].push_back(a);
}
void Do2(int a, int b, int r) {
	Del(a, b);
	Del(b, a);
	n++;
	chk = 1;
	Add(a, n);
	Add(b, n);
	Do1(n, r);
	Del(a, n);
	Del(n, a);
	Del(b, n);
	Del(n, b);
	n--;
	Add(a, b);
}
