using namespace std;
using ll = long long;
using pll = pair<ll, ll>;
static const int INF = 1000000000;

pll solve(int a, int b, const vector<vector<int>>& g){
	const int n = g.size();
	vector<int> d(n, INF);
	queue<int> q;
	q.push(a);
	d[a] = 0;
	if(a != b){
		q.push(b);
		d[b] = 0;
	}
	while(!q.empty()){
		const int u = q.front();
		q.pop();
		for(const auto v : g[u]){
			if(d[v] >= INF){
				d[v] = d[u] + 1;
				q.push(v);
			}
		}
	}
	vector<vector<int>> h(n);
	int max_color = 0;
	for(int i = 0; i < n; ++i){
		h[d[i]].push_back(i);
		max_color = max(max_color, d[i]);
	}
	ll n_leaves = 1;
	for(int i = max_color - 1; i >= 0; --i){
		ll max_deg = 0;
		for(const int u : h[i]){
			ll deg = 0;
			for(const int v : g[u]){
				if(d[v] > d[u]){ ++deg; }
			}
			max_deg = max(max_deg, deg);
		}
		n_leaves = max_deg * n_leaves;
	}
	if(a == b){
		return pll(max_color + 1, n_leaves);
	}else{
		return pll(max_color + 1, n_leaves * 2);
	}
}

int main(){
	ios_base::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<vector<int>> conn(n);
	for(int i = 1; i < n; ++i){
		int a, b;
		cin >> a >> b;
		--a; --b;
		conn[a].push_back(b);
		conn[b].push_back(a);
	}
	pll answer(INF, 0);
	for(int u = 0; u < n; ++u){
		answer = min(answer, solve(u, u, conn));
		for(const auto v : conn[u]){
			if(u < v){ answer = min(answer, solve(u, v, conn)); }
		}
	}
	cout << answer.first << " " << answer.second << endl;
	return 0;
}

