					depth[G[vs[i]][j]]=depth[vs[i]]+1;
					par[G[vs[i]][j]]=vs[i];
					looked[G[vs[i]][j]]=1;
					++cnt;
				}
			}
			num[vs[i]]=cnt;
		}
		vs.swap(nx);
	}
}

ll count_leaves(){
	for(int i=0; i<60; ++i) nmx[i]=1;
	for(int i=1; i<=N; ++i){
		nmx[depth[i]]=max(nmx[depth[i]], num[i]);
	}
	ll res=1;
	for(int i=0; i<60; ++i) res *= nmx[i];
	return res;
}

