const int Max_N(105);
typedef long long int LL;

int N, Head[Max_N], Total, To[Max_N << 1], Next[Max_N << 1], Deg[Max_N], Max[Max_N], Ans1;
LL Cnt[Max_N], Sum[Max_N], Ans2;

inline void Add_Edge(int s, int t)
{
	++Total, To[Total] = t, Next[Total] = Head[s], Head[s] = Total;
}

void dfs(int u, int fa, int dep)
{
	Ans1 = max(Ans1, dep);
	for (int i = Head[u], v;i;i = Next[i])
		if ((v = To[i]) != fa)
			dfs(v, u, dep + 1);
}

void arrange(int u, int fa, int dep)
{
	Max[dep] = max(Max[dep], Deg[u]), ++Cnt[dep], Sum[dep] += Deg[u];
	for (int i = Head[u], v;i;i = Next[i])
		if ((v = To[i]) != fa)
			arrange(v, u, dep + 1);
}

void prepare()
{
	memset(Sum, 0, sizeof(Sum)), memset(Max, 0, sizeof(Max)), memset(Cnt, 0, sizeof(Cnt));
}

void work()
{
	if (Cnt[(Ans1 + 1) / 2 + 1])
		return;
	for (int i = 1;i <= (Ans1 + 1) / 2 - 1;++i)
	{
		LL t = Cnt[i] * Max[i] - Sum[i];
		Cnt[i + 1] += t, Sum[i + 1] += t;
	}
	Ans2 = min(Ans2, Cnt[(Ans1 + 1) / 2]);
}

