	for (int u = 1;u <= N;++u)
		for (int i = Head[u], v;i;i = Next[i])
			v = To[i], prepare(), arrange(u, v, 1), arrange(v, u, 1), work();
	for (int u = 1;u <= N;++u)
		prepare(), arrange(u, -1, 1), work();
	printf("%lld", Ans2);
	return 0;
}

