void chemthan() {
    cin >> n;
    FOR(i, 0, n - 1) {
        int u, v; cin >> u >> v; u--, v--;
        adj[u].pb(v), adj[v].pb(u);
    }
    pair<long long, long long> best = mp(LINF, LINF);
    FOR(u, 0, n) {
        FOR(i, 0, n) g[i].clear();
        dfs(u, -1, 0);
        long long sum = 0, leaves = 1;
        FORd(i, n, 0) {
            int mx = 0;
            for (int v : g[i]) {
                if (i) {
                    chkmax(mx, sz(adj[v]) - 1);
                }
                else {
                    chkmax(mx, sz(adj[v]));
                }
            }
            if (mx) {
                sum += 1;
                leaves *= mx;
            }
        }
        sum++;
        chkmin(best, mp(sum, leaves));
    }
    FOR(u, 0, n) {
        for (int v : adj[u]) {
            FOR(i, 0, n) g[i].clear();
            dfs(u, v, 0), dfs(v, u, 0);
            long long sum = 0, leaves = 1;
            vi vals;
            FORd(i, n, 0) {
                int mx = 0;
                for (int v : g[i]) {
                    chkmax(mx, sz(adj[v]) - 1);
                }
                vals.pb(mx);
                if (mx) {
                    sum += 1;
                    leaves *= mx;
                }
            }
            sum++;
            leaves *= 2;
            chkmin(best, mp(sum, leaves));
        }
    }
    cout << best.fi << " " << best.se << "\n";
}

