#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int maxn = 1010;

vector<int> g[maxn];
int n;
int d[maxn], father[maxn], maxson[maxn], son[maxn];
int s,t,len;

void link(int u, int v) { g[u].push_back(v); g[v].push_back(u); }

void del(int u, int v)
{
	for (int i=0;i<g[u].size();i++)
		if (g[u][i] == v) g[u].erase(g[u].begin()+i);
	for (int i=0;i<g[v].size();i++)
		if (g[v][i] == u) g[v].erase(g[v].begin()+i);
}

int find(int ss)
{
	queue<int> que;
	int maxd = 0, maxu;
	while (!que.empty()) que.pop();
	for (int i=0;i<=n;i++) d[i] = 0, son[i] = 0;
	que.push(ss);
	while (!que.empty())
	{
		int u = que.front();
		if (d[u] > maxd) { maxd = d[u]; maxu = u; }
		que.pop();
		for (auto v:g[u])
		{
			if (d[v] || v == ss) continue;
			son[u]++;
			d[v] = d[u] + 1;
			father[v] = u;
			que.push(v);
		}
	}
	return maxu;
}


int findd()
{
	s = find(1);
	t = find(s);
	return d[t];
}

ll solve1(int c1, int c2)
{
	del(c1,c2);
	find(c1);
	memset(maxson,0,sizeof(maxson));
	for (int i=1;i<=n;i++)
	{
		if (!d[i] && i != c1) continue;
		maxson[d[i]] = max(maxson[d[i]],son[i]);
	}
	find(c2);
	for (int i=1;i<=n;i++)
	{
		if (!d[i] && i != c2) continue;
		maxson[d[i]] = max(maxson[d[i]],son[i]);
	}
	ll ret = 1;
	for (int i=0;i<=len/2;i++)
		if (maxson[i]) ret = ret * (ll)maxson[i];
	link(c1,c2);
	return ret * 2LL;
}

ll solve2(int c)
{
	find(c);
	memset(maxson,0,sizeof(maxson));
	for (int i=1;i<=n;i++)
	{
		if (!d[i] && i != c) continue;
		maxson[d[i]] = max(maxson[d[i]],son[i]);
	}
	ll ret = 1;
	for (int i=0;i<=len/2;i++) 
		if (maxson[i]) ret = ret * (ll)maxson[i];
	return ret;
}

int main()
{
	//freopen("D.in","r",stdin);
	cin >> n;
	for (int i=1;i<n;i++)
	{
		int u,v;
		cin >> u >> v;
		link(u,v);
	}
	len = findd();
	ll ans;
	if (len % 2 == 1)
	{
		for (int i=1;i<=len/2;i++) t = father[t];
		ans = solve1(t,father[t]);
	}
	else
	{
		for (int i=1;i<=len/2;i++) t = father[t];
		ans = solve2(t);
		len++;
		for (auto v : g[t])
		{
			ans = min(ans,solve1(t,v));
		}
	}

	cout << len/2 + 1 << " " << ans << endl;
	return 0;
}

