#define Foreachson(i , x) for(int i = fir[x];i;i = ne[i])

int dis[N][N] , fa[N][N];

void get(int x , int f , int no) {
  fa[no][x] = f;
  Foreachson(i , x) {
    if(to[i] != f)
      dis[no][to[i]] = dis[no][x] + 1 ,
	get(to[i] , x , no);
  }
}

vector <int> Dia;

bool vis[N];

void dfs(int x , int f) {
  int now = 0;
  Foreachson(i , x) {
    int V = to[i];
    if(vis[V] || V == f) continue;
    ++ now;
    dep[V] = dep[x] + 1;
    dfs(V , x);
  }
  Max[dep[x]] = max(Max[dep[x]] , now);
}

void init(void) {
  for(int i = 0;i <= n;++ i) Max[i] = 0 , dep[i] = 0;
  memset(vis , 0 , sizeof(vis));
}

long long calc(int x , int y) {
  init();
  vis[x] = vis[y] = 1;
  dfs(x , 0);
  dfs(y , 0);
  long long ans = 1;
  for(int i = 0;i <= n;++ i) ans *= max(Max[i] , 1);
  return ans * 2;
}

