  long long res = 1;
  for(int i = 0;i <= n;++ i) {
    res *= max(Max[i] , 1);
  }
  ans = min(ans , res);
  Foreachson(i , now) {
    int V = to[i];
    ans = min(ans , calc(V , now));
  }
  return ans;
}

