//!  88   88   88 88.  .88 88 88    88  !//
//!  dP   dP   dP '88888P8 dP dP    dP  !//
//!=====================================!//
int main()
{
    using LL = __int128_t;
    const int N = read<int>();
    Graph G(2 * N - 1);
    for (int i = 0, a, b; i < N - 1; i++) { std::cin >> a >> b, a--, b--, G.addEdge(N + i, a, true), G.addEdge(N + i, b, true); }
    SHOW(G);
    using P = std::pair<int, LL>;
    P ans = {2 * N, LL(0)};
    for (int i = 0; i < 2 * N - 1; i++) {
        std::vector<int> D(2 * N - 1, 0);
        int depth = 0;
        auto dfs = [&](auto&& self, const int s, const int p, const int d) -> void {
            chmax(depth, d + 1);
            int c = 0;
            for (const int to : G[s]) {
                if (to == p) { continue; }
                self(self, to, s, d + 1), c++;
            }
            chmax(D[d], c);
        };
        dfs(dfs, i, -1, 0);
        LL c = 1;
        for (int i = 0; i < 2 * N - 1; i++) {
            if (D[i] == 0) { break; }
            c *= D[i];
        }
        SHOW(i, D);
        chmin(ans, P{(depth + 1) / 2, c});
    }
    std::cout << ans.first << " " << (ll)(ans.second) << std::endl;
    return 0;
}

