int get_max_depth(const vector<int>& max_children) {
    int max_depth = 0;
    for (int i = 0; i < max_children.size(); ++i) {
        assert(i < max_children.size());
        if (max_children[i] != -1) {
            max_depth = i;
        }
    }
    return max_depth;
}

ll count_leaves(const vector<int>& max_children) {
    const int max_depth = get_max_depth(max_children);
    ll leaves = 1;
    for (int depth; depth < max_depth; ++depth) {
        assert(depth < max_children.size());
        leaves *= max_children[depth];
    }
    return leaves;
}

