const int N = 107;
int n, d[N], f[N], ans;
vi e[N];

void dfs(int x) {
	for (int y : e[x])
		if (y != f[x]) f[y] = x, d[y] = d[x] + 1, dfs(y);
}

inline ll calc(int x) {
	d[x] = 1, f[x] = 0, dfs(x);
	static int c[N];
	for (int i = 1; i <= ans; i++) c[i] = 0;
	for (int i = 1; i <= n; i++)
		c[d[i]] = max(c[d[i]], (int)e[i].size());
	ll ret = e[x].size();
	for (int i = 2; i < ans; i++) ret *= c[i] - 1;
	return ret;
}

inline ll calc(int x, int y) {
	d[x] = 1, f[x] = y, dfs(x);
	d[y] = 1, f[y] = x, dfs(y);
	static int c[N];
	for (int i = 1; i <= ans; i++) c[i] = 0;
	for (int i = 1; i <= n; i++)
		c[d[i]] = max(c[d[i]], (int)e[i].size()); 
	ll ret = 1;
	for (int i = 1; i < ans; i++) ret *= c[i] - 1;
	return ret * 2;
}

int main() {
	rd(n);
	for (int i = 1, x, y; i < n; i++)
		rd(x, y), e[x].pb(y), e[y].pb(x);
	d[1] = 1, f[1] = 0, dfs(1);
	int x = max_element(d + 1, d + n + 1) - d;
	d[x] = 1, f[x] = 0, dfs(x);
	int y = max_element(d + 1, d + n + 1) - d;
	int c = d[y];
	if (c & 1) {
		ans = (d[y] + 1) / 2;
		while (d[y] != ans) y = f[y];
		x = y;
		ll now = calc(x);
		for (int y : e[x])
			now = min(now, calc(x, y));
		print((ll)ans, now);
	} else {
		ans = d[y] / 2;
		while (d[y] != ans + 1) y = f[y];
		x = f[y];
		print((ll)ans, calc(x, y));
	}
	return 0;
}

