int n, deg[N], dep[N], mxdeg[N];
int bfs(int x, int y) {
	int res = 0;
	for(int i = 1; i <= n; ++ i) dep[i] = 0;
	q.push(x); dep[x] = 1;
	if(y) q.push(y), dep[y] = 1;
	while(! q.empty()) {
		int x = q.front(); q.pop();
		mxdeg[dep[x]] = max(mxdeg[dep[x]], deg[x]);
		res = max(res, dep[x]);
		for(Edge *i = head[x]; i; i = i->nxt) {
			if(dep[i->to] == 0) dep[i->to] = dep[x] + 1, q.push(i->to);
		}
	}
//	cout << x << " " << y << " " << res << endl;
	return res;
}
