	res = (pr){bfs(x, y), mxdeg[1] - (y != 0)};
//	cout << mxdeg[1] << endl;
	for(int i = 2; i <= n; ++ i) {
		if(mxdeg[i] == 1) break;
		res.se *= (mxdeg[i] - 1);
	}
	if(y) res.se *= 2;
//	cout << x << " " << y << " " << res.fi << " " << res.se << endl;
//	for(int i = 1; i <= n; ++ i) cout << mxdeg[i] << " "; puts("");
	return res;
}
