ll min3(ll a, ll b, ll c)
{
	if (a < b && a < c) return a;
	if (b < c) return b;
	return c;
}

class Diameter
{
public:
	vec<vec<int>> g;
	pair<int, int> ps;
	vec<int> path;
	int n;
	Diameter(int num): g(num) {
		ps.first = 0;
		ps.second = 0;
		n = num;
	}

	void edge(int a, int b) {
		g[a].pb(b);
		g[b].pb(a);
	}

	int longest(int a) {
		queue<pair<int, vec<int>>> keep;
		vec<int> hoge = {a};
		keep.push(mp(a, hoge));
		vec<int> dp(n, 0);

		pair<int, vec<int>> cur;
		while(!keep.empty()) {
			pair<int, vector<int>> get = keep.front();
			keep.pop();
			int cur_p = get.first;
			if (dp[cur_p]) continue;
			dp[cur_p] = 1;
			cur = get;
			rep(i, g[cur_p].size()) {
				int v = g[cur_p][i];
				vec<int> v_path = get.second;
				v_path.pb(v);

				keep.push(mp(v, v_path));
			}
		}

		path = cur.second;
		return cur.first;
	}

	vec<int> diameter(void) {
		ps.first = longest(0);
		ps.second = longest(ps.first);
		return path;
	}
};

ll solve(vec<int> cur_p, vec<vec<int>> g)
{
	vec<int> dp(g.size(), 0);
	ll ans;
	if (cur_p.size() == 1) {
		int c = cur_p[0];
		dp[c] = 1;
		ans = (ll)g[c].size();;
		vec<int> next_p;
		rep(i, g[c].size()) {
			next_p.pb(g[c][i]);
		}
		cur_p = next_p;
	} else ans = 2;
	// rep(i, cur_p.size()) cout << cur_p[i] + 1 << " ";
	// cout << endl;

	rep(i, cur_p.size()) dp[cur_p[i]] = 1;

	while(!cur_p.empty()) {
		vec<int> next_p;
		rep(i, cur_p.size()) {
			rep(j, g[cur_p[i]].size()) {
				if (dp[g[cur_p[i]][j]]) continue;
				dp[g[cur_p[i]][j]] = 1;
				next_p.pb(g[cur_p[i]][j]);
			}
		}

		ll Max = 1;
		rep(i, cur_p.size()) {
			ll temp = (ll)g[cur_p[i]].size() - 1;
			Max = Max < temp ? temp : Max;
		}
		// cout << Max << endl;
		ans *= Max;
		cur_p = next_p;
		// rep(i, cur_p.size()) cout << cur_p[i] + 1 << " ";
		// cout << endl;
	}
	return ans;
}

int main(void)
{
	int n;
	cin >> n;
	Diameter d(n);
	rep(i, n - 1) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		d.edge(a, b);
	}

	vec<int> path = d.diameter();

	int l = (int)path.size();
	ll ans = 1;
	if (l % 2 == 0) {
		vec<int> cur_p = {path[l / 2 - 1], path[l / 2]};
		ans = solve(cur_p, d.g);
	} else {
		vec<int> cur_p1 = {path[l / 2]};
		ll ans1 = solve(cur_p1, d.g);
		// cout << endl;
		vec<int> cur_p2 = {path[l / 2 - 1], path[l / 2]};
		ll ans2 = solve(cur_p2, d.g);
		// cout << endl;
		vec<int> cur_p3 = {path[l / 2 + 1], path[l / 2]};
		ll ans3 = solve(cur_p3, d.g);
		// cout << endl;

		ans = min3(ans1, ans2, ans3);
	}

	cout << (l + 1) / 2 << " " << ans << endl;
	return 0;
}

