void DFS(int v, int h = 0) {
    H = max(H, h);
    U[v] = iter;
    int deg = 0;
    FOR(i, 0, SZ(G[v])) {
        int to = G[v][i];
        if (U[to] == iter)continue;
        deg++;
        DFS(to, h+1);
    }
    X[h] = max(X[h], deg);
}

LL calc() {
    LL res = 1LL;
    FOR(i, 0, n)res *= max(1, X[i]);
    return res;
}

