using namespace std;

int N;
int height[100];
int edge_count[100];

vector<int> edges[100];
int max_di;
vector<int> max_path;
vector<int> path;

int childs[100];

void diameter(int s, int f, int d) {
    if(edge_count[s] == 1 && f != s) {
        if(max_di < d) {
            max_di = d;
            max_path = path;
        }
        return;
    }
    for(int n : edges[s]) {
        if(n != f) {
            path.push_back(n);
            diameter(n, s, d+1);
            path.pop_back();
        }
    }
}

void calc_height(int s, int f, int h) {
    if(height[s] != 0) return;
    height[s] = h;
    for(int n : edges[s]) {
        if(n != f) {
            calc_height(n, s, h-1);
        }
    }
}


int main() {
    scanf("%d", &N);
    for(int i = 1; i < N; ++i) {
        int a, b;
        scanf("%d%d", &a, &b);
        --a; --b;
        edge_count[a]++;
        edge_count[b]++;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    for(int i = 0; i < N; ++i) {
        height[i] = 0;
    }
    for(int i = 0; i < N; ++i) {
        if(edge_count[i] == 1) {
            diameter(i, i, 0);
        }
    }
    int di = (max_di/2)+1;
    printf("%d ", di);
    {
        int h = 1;
        for(int n : max_path) {
            height[n] = h;
            if(h > di) height[n] = max_di-h;
            ++h;
        }
        h = 1;
        for(int n : max_path) {
            if(h > di) calc_height(n, n, max_di-h);
            else calc_height(n, n, h);
            ++h;
        }
    }
    long long num=1;
    for(int i = 0; i < N; ++i) {
        if(edges[i].size()-1>childs[height[i]]) {
            childs[height[i]] = edges[i].size()-1;
        }
    }
    for(int i = 1; i <= di; ++i) {
        num *= childs[i];
    }
    printf("%lld\n", num);
}

