        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int u : g[v]) {
                if (depth[u]) continue;
                depth[u] = depth[v] + 1;
                kek[depth[u]] = max<int>(kek[depth[u]], g[u].size());
                q.push(u);
            }
        }
