        if(chmin(cmi, ma + 1)) {
            vector<int> cnt(cmi + 1, 0);
            cnt[0] = (int)g[i].size();
            rep(j, n) {
                if(j == i) continue;
                chmax(cnt[d[j]], (int)g[j].size() - 1);
            }
            int res = 1LL;
            for(int j = 0; j < ma; ++ j) {
                res *= cnt[j];
            }
            if(cm == ma + 1) chmin(lmi, res);
            else lmi = res;
        }
    }
    //中心が2つ
