	for (int i = 0; i < (int)vec[v].size(); i++) {
		if (vec[v][i] == p)continue;
		ma = max(ma, dfs(vec[v][i], v));
	}
	return ma + 1;
}

ll dfs2(int v, int p) {
	ll ma = 0;
	int cnt = 0;
	for (int i = 0; i < (int)vec[v].size(); i++) {
		if (vec[v][i] == p)continue;
		ma = max(ma, dfs2(vec[v][i], v));
		cnt++;
	}
	if (cnt == 0)return 1;
	else if (INF / ma < cnt)return INF;
	else return ma * cnt;
}

