    forn(i, sz) {
        solve(cand[i], (sz == 1 ? -1 : cand[i ^ 1]), 0);
    }
    int res1 = 0;
    LL res2 = 1;
    forn(i, 105) if (mxv[i] > 0) {
        res1++;
        res2 *= mxv[i];
    }
