	rep(i, n - 1) {
		if (d1[A[i]] > d1[B[i]])swap(A[i], B[i]);
		if (d1[A[i]] == d&&d1[B[i]] == d + 1 && d1[A[i]] + d2[B[i]] + 1 == dia) {
			epos = i; break;
		}
	}
	fill(d3, d3 + n, -1);
	d3[A[epos]] = d3[B[epos]] = 0;
	dfs2(A[epos]); dfs2(B[epos]);

	fill(r, r + n, 0);
	rep(i, n) {
		r[d3[i]] = max(r[d3[i]], (int)G[i].size() - 1);
	}

	int res = 2;
	rep(i, d)res *= r[i];
	return res;
}

void reset() {
	rep(i, n) {
		d0[i] = 0; d1[i] = 0; d2[i] = 0;
	}
}

signed main() {
	cin >> n;
	rep(i, n - 1) {
		cin >> A[i] >> B[i];
		A[i]--; B[i]--;
		G[A[i]].push_back(B[i]);
		G[B[i]].push_back(A[i]);
	}

	dfs1(0, -1, d0);
	int X = maxpos(d0);
	dfs1(X, -1, d1);
	int Y = maxpos(d1);
	dfs1(Y, -1, d2);
	int dia = d1[Y];

	if (dia & 1) {
		cout << (dia + 1) / 2 << ' ' << calc(dia) << endl;
	}
	else {
		int ans = 1;

		//中心1個

		int center;
		rep(i, n) {
			if (d1[i] == d2[i] && d1[i] + d2[i] == dia) {
				center = i; break;
			}
		}

		fill(d3, d3 + n, -1);
		d3[center] = 0;
		dfs2(center);

		rep(i, n) {
			r[d3[i]] = max(r[d3[i]], (int)G[i].size() - 1);
		}
		r[0] = G[center].size();
		rep(i, dia / 2)ans *= r[i];

		//中心2個

		for(int e:G[center]) {
			fill(d3, d3 + n, -1);
			d3[center] = 0;
			d3[e] = 0;
			int t1=dfs2(center),t2= dfs2(e);
			if (t1 + t2 + 3 != dia)continue;
			int res = 1;
			fill(r, r + n, 0);
			rep(i, n) {
				r[d3[i]] = max(r[d3[i]], (int)G[i].size() - 1);
			}
			rep(i, dia / 2)res *= r[i];
			ans = min(ans, res);
		}

		cout <<dia/2+1<<' '<< ans << endl;
	}
}

