    for(int i = 0; i + 1 < n; ++i)
    {
        int x, y;
        cin >> x >> y;
        v[x].push_back(y);
        v[y].push_back(x);
    }

    unsigned long long k1 = solve();

    ++n;
    for(int i = 1; i < n; ++i)
    {
        v[i].push_back(n);
        v[n].push_back(i);

        unsigned long long kk = solve();
        if(kk != 0)
            k1 = min(k1, kk);

        v[i].pop_back();
        v[n].pop_back();
    }

    if(n == 3)
        while(1);

    cout << ans << ' ' << k1 << '\n';

    return 0;
}

