	scanf("%d", &n);
	for (i = 1; i < n; ++i) scanf("%d%d", &u, &v), addedge(u, v);
	dfs(ret =  1, 0), D1 = ret;
	dfs(ret = D1, 0), D2 = ret;
	for (diam = dep[D2], u = D2; u && dep[u] * 2 > diam; v = u, u = p[u]);
	if (diam & 1) {
