using namespace std;

inline int nxt() {
	int x;
	scanf("%d", &x);
	return x;
}

struct Tree {
	int n;
	vector<vector<int>> a;
	vector<int> level;
	vector<int> par;

	Tree(int _n): n(_n), a(_n), par(_n) {}

	void dfs(int v, int p = -1) {
		par[v] = p;
		for (int x : a[v]) {
			if (x == p) {
				continue;
			}
			level[x] = level[v] + 1;
			dfs(x, v);
		}
	}

	void addEdge(int u, int v) {
		a[u].push_back(v);
		a[v].push_back(u);
	}

	int getDiam() {
		level.assign(n, 0);
		dfs(0);
		int v = max_element(all(level)) - level.begin();
		level.assign(n, 0);
		dfs(v);
		return *max_element(all(level));
	}

	void addVertex(itn v) {
		a.emplace_back(1, v);
		a[v].push_back(n);
		n += 1;
		par.push_back(0);
	}

	void markLevels() {
		int d = getDiam();
		int end = max_element(all(level)) - level.begin();

		for (int i = 0; i < d / 2; ++i) {
			end = par[end];
		}

		if (d % 2 == 0) {
			level.assign(n, 0);
			dfs(end);
		} else {
			int r1 = end;
			int r2 = par[r1];
			level.assign(n, 0);
			dfs(r1, r2);
			dfs(r2, r1);
		}
	}
};

void remax(int& what, int x) {
	what = max(what, x);
}

unsigned long long getAnswer(Tree tree) {
	int d = tree.getDiam();
	tree.markLevels();
	unsigned long long ans = d % 2 + 1;
	int cols = d / 2 + 1;
	vector<int> max_deg(cols);
	int n = tree.n;
	for (int i = 0; i < n; ++i) {
		remax(max_deg[tree.level[i]], (int)tree.a[i].size() - 1);
	}
	if (d % 2 == 0) {
		max_deg[0] += 1;
	}
	max_deg.pop_back();
	for (int x : max_deg) {
		ans *= x;
	}
	return ans;
}

int main() {
	int n = nxt();
	Tree tree(n);
	for (int i = 0; i < n - 1; ++i) {
		int u = nxt() - 1, v = nxt() - 1;
		tree.addEdge(u, v);
	}

	int d = tree.getDiam();

	auto ans = getAnswer(tree);

	if (d % 2 == 0) {
		for (int i = 0; i < n; ++i) {
			Tree cur = tree;
			cur.addVertex(i);
			if (cur.getDiam() > d) {
				ans = min(ans, getAnswer(cur));
			}
		}
	}

	cout << d / 2 + 1 << " " << ans << "\n";

	return 0;
}

