void getfar(int now,int fa){
	Fa[now]=fa;
	dep[now]=dep[fa]+1;
	if (dep[now]>Dis) Far=now,Dis=dep[now];
	for (int i=H[now];i;i=E[i].nxt)
		if (E[i].to!=fa) getfar(E[i].to,now);
}

long long ansmin=std::numeric_limits<long long>::max();

void calc(int now,int fa){
	int D=0;
	dep[now]=dep[fa]+1;
	for (int i=H[now];i;i=E[i].nxt){
		if (E[i].to==fa) continue;
		D++;
		calc(E[i].to,now);
	}
	DD[dep[now]]=std::max(DD[dep[now]],D);
}

