const int limit = 110;
vector<int> tree[limit];
int par[limit];

void dfs(int v,int p,int d,vector<int> &dist){
	par[v] = p,dist[v] = d;
	for(auto &v2:tree[v]){
		if(v2 == p) continue;
		dfs(v2,v,d+1,dist);
	}
}


string tree_bucket(int v,int p){
	vector<string> cand;

	for(auto &v2:tree[v]){
		if(v2 == p) continue;
		cand.push_back(tree_bucket(v2,v));
	} 

	sort(begin(cand),end(cand));
	string ret = "(";
	for(auto &it:cand) ret += it;
		return ret + ")"; 
}

int total = 1,max_depth = 1;
int adj[10010][limit];
bool leaf[10010];
int depth[limit];

void tree_travasal(int v,int d,string& bucket,int& idx){
	if(bucket[idx] == '(') idx++;
	chmax(max_depth,d);

	rep(i,limit){
		if(bucket[idx] == ')') break;

		if(adj[v][i] == -1){
			adj[v][i] = total;
			leaf[v] = false;
			leaf[total] = true;
			rep(j,limit) adj[total][j] = -1;
			total++;
		}

		error(d,i+1);
		chmax(depth[d],i+1);
		tree_travasal(adj[v][i],d+1,bucket,idx);
	}

	idx++;
	return;
}

ll calc(int a,int b){
	error("subcalc",a,b);
	total = 1, max_depth = 1;
	rep(i,limit) adj[0][i] = -1,depth[i] = 0;
	leaf[0] = true;

	for(auto &c:{a,b}){
		const int ab = a^b;
		string ret = tree_bucket(c,c^ab);
		error(ret);
		int idx = 0;
		tree_travasal(0,0,ret,idx);
	}

	error(depth[0],depth[1]);
	ll ret = depth[0];
	rep(i,1,max_depth) ret *= depth[i];
	error(2 * ret);
	return 2 * ret;
}

int main(void){
	int n;
	cin >> n;

	rep(i,n-1){
		int a,b;
		cin >> a >> b;
		a--,b--;
		tree[a].push_back(b);
		tree[b].push_back(a);
