        d[r]=d[q]+1;
        chmax(m[d[r]],(int)(edge[q].size()-1));
        LF[r]=LF[q]*(edge[q].size()-1);
        que.push(r);
      }
    }
  }
  L=1;for(auto q:m)L*=q.second;
  L*=edge[a].size();
  for(int i=0;i<n;i++)chmax(D,d[i]);
  if(color>D){color=D,leaf=L;}
