vll max_child(101, 1);
void DFS(ll now, ll from, ll d){
  max_child[d] = max(max_child[d], (ll)G[now].size() - 1);
  for(int i=0;i<G[now].size();i++){
    if(G[now][i]==from) continue;
    DFS(G[now][i], now, d+1);
  }
}
