  vll t = getTreeDiameter(1);
  calc(t[1], -1);
  if(t[0]%2==0){
    //3pat
    ll c = t[2];
    for(int i=0;i<t[0]/2;i++) c = pre[c];
    //std::cout << c << '\n';
    throw runtime_error("error");
  }else{
    //1pat
    ll c = t[2];
    for(int i=0;i<t[0]/2;i++) c = pre[c];
    ll d = pre[c];
    DFS(c, d, 0);
    DFS(d, c, 0);
    ll ans = 1;
    for(int i=0;i<101;i++) ans *= max_child[i];
