// Edge X-Y is forbidden
void dfs(int u, int p2, int d, int X = -1, int Y = -1){
    if(visited[u]){return;}
    visited[u] = true;
    p[u] = p2;
    int children = 0;
    for(int v: AdjList[u]){
        if(!visited[v] && !(u == X && v == Y) && !(u == Y && v == X)){
            children ++;
            dfs(v, u, d+1, X, Y);
        }
    }
    maxChildren[d] = max(maxChildren[d], children);
}

int main(){
