        AdjList[y].push_back(x);
    }

    ll ans = ll(N+2, 1);
    for(int i = 1; i <= N; i ++){
        memset(p, -1, sizeof(p));
        memset(maxChildren, 0, sizeof(maxChildren));
        memset(visited, false, sizeof(visited));

        //printf("i=%d\n", i);

        dfs(i, -1, 1, -1, -1);

        long long temp = 1;
        int maxDepth = 0;
        for(int d = 1; d <= N; d ++){
            if(maxChildren[d] == 0){
                maxDepth = d;
                break;
            }else{
                temp = temp*maxChildren[d];
            }
        }

        //printf("%d ll(%d, %lld)\n", i, maxDepth, temp);

        ans = min(ans, ll(maxDepth, temp));
    }

    for(int u = 1; u <= N; u ++){
        for(int v: AdjList[u]){
            AdjList[0].push_back(u);
            AdjList[0].push_back(v);

            memset(p, -1, sizeof(p));
            memset(maxChildren, 0, sizeof(maxChildren));
            memset(visited, false, sizeof(visited));

            dfs(0, -1, 0, u, v);

            AdjList[0].clear();

            long long temp = 1;
            int maxDepth = 0;
            for(int d = 0; d <= N; d ++){
                if(maxChildren[d] == 0){
                    maxDepth = d;
                    break;
                }else{
                    temp = temp*maxChildren[d];
                }
            }

            ans = min(ans, ll(maxDepth, temp));
        }
    }

    printf("%lld %lld", ans.first, ans.second);

    return 0;
}

