    else A=2;
    used[x]=1;
    used[y]=1;
    if(x!=y){
        l[0].pb(x);
        r[0].pb(y);
    }
    else{
        l[0].pb(x);
    }
    rep(i,0,100){
        int m=1;
        rep(j,0,sz(l[i])){
            m=max(m,sz(E[l[i][j]]));
            rep(k,0,sz(E[l[i][j]])){
                if(used[E[l[i][j]][k]]==0){
                    l[i+1].pb(E[l[i][j]][k]);
                    used[E[l[i][j]][k]]=1;
                }
            }
        }
        rep(j,0,sz(r[i])){
            m=max(m,sz(E[r[i][j]]));
