                if(used[E[r[i][j]][k]]==0){
                    r[i+1].pb(E[r[i][j]][k]);
                    used[E[r[i][j]][k]]=1;
                }
            }
        }
        if(x==y&&i==0) A*=m;
        else A*=max(m-1,1);
    }
    return A;
}
