class DiameterOfTree{
public:
  typedef pair<int,int> P;
  int V;
  vector<vector<P> > G; //(to, cost)
  vector<int> nodeCost; //ノードに重みがある場合
  int start, end, length;
  int ok;
  DiameterOfTree():V(-1){}
  DiameterOfTree(int V):V(V),G(V),nodeCost(V, 0),ok(false){};

  void add_edge(int a,int b,int c = 1){
    ok = false;
    assert(a < V && b < V);
    assert(a >= 0 && b >= 0);
    G[a].push_back( P(b, c) );
    G[b].push_back( P(a, c) );
  }

  void dfs(int pos,int pre = -1,int len = 0){
    if(pre == -1) start = pos, length = -1;
    len += nodeCost[pos];
    if(len > length) length = len, end = pos;
    for(P p:G[pos]) if(p.first != pre) dfs(p.first, pos, len+p.second);
  }

  //s-t間のパスを取得 : O(V + E)
  vector<int> getPath(int s,int t){
    assert(s >= 0 && s < V);
    assert(t >= 0 && t < V);

    vector<int> res;
    function<int(int,int)> dfs=[&](int pos,int pre){
      if(pos == t) {res.push_back(end); return 1;}
      for(P p:G[pos]){
        int to = p.first;
        if(to != pre && dfs(to, pos)){res.push_back(pos); return 1;}
      }
      return 0;
    };

    dfs(s, -1);
    return res;
  }

  //O(V + E);
  void build(int start=0){
    ok = true;
    assert(start < V);
    dfs(start);
    dfs(end);
  }
};

int n;
vector<vector<int> > G;

//deg, sum, cnt
tuple<int,int, int> calcMaxDegree(vector<int> &D, queue<int> &Q,int target, int flag){
  int deg = 0,sum = 0, cnt = 0;
  while(!Q.empty()){
    int pos = Q.front();
    int cost = D[pos];
    if(cost > target) break;

    if(cost == target) {
      Max(deg, (int)G[pos].size() - flag);
      sum += G[pos].size() - flag;
      cnt++;
    }

    Q.pop();

    for(int to:G[pos]){
      if(D[to] != -1) continue;
      D[to] = cost + 1;
      Q.push(to);
    }
  }
  return tie(deg, sum, cnt);
}


P solve(vector<int> start){
  vector<int> D(n,-1);
  queue<int> Q;
  for(int s:start){Q.push(s); D[s] = 0;}

  int col = 1, leaf = start.size();
  int flag = leaf != 1;

  for(int i=0;i<n;i++, flag = 1){
    int deg, sum, cnt; 
    tie(deg, sum, cnt) = calcMaxDegree(D, Q, i, flag);
    if(deg == 0) break;
    col++;
    leaf = leaf * deg;
  }
  return {col, leaf};
}

