void find_max(int now, int fa, int dis)
{
	int tmp = 0;
	for(int to : edge[now])
	{
		if(to == fa) continue;
		tmp ++;
		find_max(to, now, dis + 1);
	}
	sum[dis] = max(sum[dis], tmp);
}

