#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {

	void Solve() {
		UL N; cin >> N;
		vector<vector<UL>> E(N);
		rep(i, N - 1) {
			UL a, b; cin >> a >> b; a--; b--;
			E[a].push_back(b);
			E[b].push_back(a);
		}
		UL r = 0;
		vector<UL> D(N);
		{
			vector<UL> L(N); rep(i, N) L[i] = E[i].size() - 1;
			queue<UL> Q;  rep(i, N) if (L[i] == 0) Q.push(i);
			while (Q.size()) {
				UL p = Q.front(); Q.pop();
				r = max(r, D[p]);
				for (UL e : E[p]) {
					if (L[e] == 0) continue;
					D[e] = max(D[e], D[p] + 1);
					L[e]--;
					if (L[e] != 0) continue;
					Q.push(e);
				}
			}
		}
		UL Cs = 0; rep(i, N) if (D[i] == r) Cs++;
		queue<UL> Q;
		rep(i, N) if (D[i] == r) Q.push(i);
		while (Q.size()) {
			UL p = Q.front(); Q.pop();
			for (UL e : E[p]) {
				if (D[e] < D[p]) Q.push(e);
				if (D[e] > D[p]) D[p] = D[e] - 1;
			}
		}
		vector<UL> d(r + 1);
		rep(i, N) d[D[i]] = max(d[D[i]], (UL)E[i].size());
		ULL ans = 1;
		for (UL i = 1; i < r; i++) { ans *= (d[i] - 1); }
		if (Cs == 2) ans *= (d[r] - 1) * 2; else ans *= d[r];
		//rep(i, D.size()) cout << D[i] << " "; cout << endl;
		//rep(i, d.size()) cout << d[i] << " "; cout << endl;
		if (Cs == 1) {
			UL C = 0; rep(i, N) if (D[i] == r) C = i;
			for (UL v : E[C]) {
				queue<UL> Q; Q.push(C); Q.push(v);
				vector<UL> D2 = D;
				D2[v] = r;
				while (Q.size()) {
					UL p = Q.front(); Q.pop();
					for (UL e : E[p]) {
						if (D2[e] < D2[p]) Q.push(e);
						if (D2[e] > D2[p]) D2[p] = D2[e] - 1;
					}
				}
				vector<UL> d2(r + 1);
				rep(i, N) d2[D2[i]] = max(d2[D2[i]], (UL)E[i].size());
				ULL ansbuf = 1;
				for (UL i = 1; i < r; i++) { ansbuf *= (d2[i] - 1); }
				ansbuf *= (d2[r] - 1) * 2;
				//rep(i, D2.size()) cout << D2[i] << " "; cout << endl;
				//rep(i, d2.size()) cout << d2[i] << " "; cout << endl;
				ans = min(ans, ansbuf);
			}
		}
		cout << (r + 1) << " " << ans << endl;
	}


	Problem();
};
