        solve(w[nr / 2 + 1], 1);
        sol = 1;
        for(i = 1; i <= s; i++){
            sol = sol * d[i];
        }
        nod = w[nr / 2 + 1];
        for(i = 0; i < v[nod].size(); i++){
            memset(viz, 0, sizeof(viz));
            memset(d, 0, sizeof(d));
            d[1] = 2;
            viz[ v[nod][i] ] = viz[nod] = 1;
            solve(nod, 1);
            solve(v[nod][i], 1);
            if(d[s + 1] != 0){
                continue;
            }
            sum = 1;
            for(j = 1; j <= s; j++){
                sum = sum * d[j];
            }
            sol = min(sol, sum);
        }
    }
    cout<< s <<" "<< sol;
}

