using namespace std;
typedef long long int lli;
const lli inf = 1e18;

int dfs(int node, int depth, vector<int> &div, vector<bool> &used, vector<vector<int> > &adj){
	//cerr << "dfs " << node << endl;
	if(used[node]) return 0;
	used[node] = true;
	div[depth] = max(div[depth], (int)adj[node].size()-1);
	int res = 0;
	for(int i=0; i<(int)adj[node].size(); i++){
		res = max(res, dfs(adj[node][i], depth+1, div, used, adj) );
	}
	return res+1;
}

int main(){
	int n;
	cin >> n;
	vector<vector<int> > adj(n);
	vector<vector<int> > edge(n-1);
	for(int i=0; i<n-1; i++){
		int a,b;
		cin >> a >> b;
		a--; b--;
		adj[a].push_back(b);
		adj[b].push_back(a);
		edge[i].push_back(a);
		edge[i].push_back(b);
	}

	lli mincol = inf;
	lli minleaf = inf;
	//頂点について
	for(int i=0; i<n; i++){
		//cerr << "i " << i << endl;
		vector<int> div(n, 0);
		int depth = 0;
		int dir = adj[i].size();
		for(int j=0; j<dir; j++){
			//cerr << "j " << j << endl;
			vector<bool> used(n, false);
			used[i] = true;
			depth = max(depth, dfs(adj[i][j], 0, div, used, adj) );
		}
		if(depth +1 <= mincol){
			lli leaf = dir;
			for(int k=0; k<depth-1; k++){
				leaf *= div[k];
			}
			if(depth +1 == mincol){
				minleaf = min(minleaf, leaf);
			}
			if(depth +1 < mincol){
				mincol = depth+1;
				minleaf = leaf;
			}
		}
	}
	//辺について
	for(int i=0; i<n-1; i++){
		vector<int> div(n, 0);
		int depth = 0;
		int dir = 2;
		for(int j=0; j<2; j++){
			vector<bool> used(n, false);
			used[edge[i][1-j]] = true;
			depth = max(depth, dfs(edge[i][j], 0, div, used, adj));
		}
		if(depth <= mincol){
			lli leaf = dir;
			for(int k=0; k<depth-1; k++){
				leaf *= div[k];
			}
			if(depth == mincol){
				minleaf = min(minleaf, leaf);
			}
			if(depth < mincol){
				mincol = depth;
				minleaf = leaf;
			}
		}
	}

	cout << mincol << " " << minleaf << endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int maxn = 1010;

vector<int> g[maxn];
int n;
int d[maxn], father[maxn], maxson[maxn], son[maxn];
int s,t,len;

void link(int u, int v) { g[u].push_back(v); g[v].push_back(u); }

void del(int u, int v)
{
	for (int i=0;i<g[u].size();i++)
		if (g[u][i] == v) g[u].erase(g[u].begin()+i);
	for (int i=0;i<g[v].size();i++)
		if (g[v][i] == u) g[v].erase(g[v].begin()+i);
}

int find(int ss)
{
	queue<int> que;
	int maxd = 0, maxu;
	while (!que.empty()) que.pop();
	for (int i=0;i<=n;i++) d[i] = 0, son[i] = 0;
	que.push(ss);
	while (!que.empty())
	{
		int u = que.front();
		if (d[u] > maxd) { maxd = d[u]; maxu = u; }
		que.pop();
		for (auto v:g[u])
		{
			if (d[v] || v == ss) continue;
			son[u]++;
			d[v] = d[u] + 1;
			father[v] = u;
			que.push(v);
		}
	}
	return maxu;
}


int findd()
{
	s = find(1);
	t = find(s);
	return d[t];
}

ll solve1(int c1, int c2)
{
	del(c1,c2);
	find(c1);
	memset(maxson,0,sizeof(maxson));
	for (int i=1;i<=n;i++)
	{
		if (!d[i] && i != c1) continue;
		maxson[d[i]] = max(maxson[d[i]],son[i]);
	}
	find(c2);
	for (int i=1;i<=n;i++)
	{
		if (!d[i] && i != c2) continue;
		maxson[d[i]] = max(maxson[d[i]],son[i]);
	}
	ll ret = 1;
	for (int i=0;i<=len/2;i++)
		if (maxson[i]) ret = ret * (ll)maxson[i];
	link(c1,c2);
	return ret * 2LL;
}

ll solve2(int c)
{
	find(c);
	memset(maxson,0,sizeof(maxson));
	for (int i=1;i<=n;i++)
	{
		if (!d[i] && i != c) continue;
		maxson[d[i]] = max(maxson[d[i]],son[i]);
	}
	ll ret = 1;
	for (int i=0;i<=len/2;i++) 
		if (maxson[i]) ret = ret * (ll)maxson[i];
	return ret;
}

int main()
{
	//freopen("D.in","r",stdin);
	cin >> n;
	for (int i=1;i<n;i++)
	{
		int u,v;
		cin >> u >> v;
		link(u,v);
	}
	len = findd();
	ll ans;
	if (len % 2 == 1)
	{
		for (int i=1;i<=len/2;i++) t = father[t];
		ans = solve1(t,father[t]);
	}
	else
	{
		for (int i=1;i<=len/2;i++) t = father[t];
		ans = solve2(t);
		len++;
		vector<int> list; list.clear();
		for (auto v : g[t]) list.push_back(v);
		for (auto v : list)
		{
			ans = min(ans,solve1(t,v));
		}
	}

	cout << len/2 + 1 << " " << ans << endl;
	return 0;
}

