const int N = 106;
vector<int> g[N];
int md;
vector<int> mu;
int pa[N];
int dm[N];
void far(int u,int p = 0,int d = 0)
{
    if (d == md) {
        mu.push_back(u);
    } else if (d > md) {
        md = d;
        mu = {u};
    }
    pa[u] = p;
    for (int v : g[u]) if (v != p) {
        far(v,u,d+1);
    }
}
void solve(int u,int p = 0,int d = 0)
{
    int deg = 0;
    for (int v : g[u]) if (v != p) {
        solve(v,u,d+1);
        ++deg;
    }
    dm[d] = max(dm[d], deg);
}
pii get_dia()
{
    mu = {};
    md = 0;
    far(1);
    int a = mu[0];
    md = 0;
    far(a);
    int b = mu[0];
    return pii(a,b);
}
ll solve_even()
{
    int a,b;
    tie(a,b) = get_dia();
    int w = md+1;
    if (w % 2)
        return LLONG_MAX;
    int mi = b;
    for (int i = 0; i < w/2-1; ++i)
        mi = pa[mi];
    int mj = pa[mi];
    memset(dm,0,sizeof(dm));
    solve(mi,mj);
    solve(mj,mi);
    __int128 ans = 2;
    for (int i = 0; i < w/2-1; ++i)
        ans *= dm[i];
    if (LLONG_MAX < ans)
        return LLONG_MAX;
    return ans;
}
