    ll ans;
    if (w % 2 == 0) {
        ans = solve_even();
    } else {
        int mi = dia.S;
        for (int i = 0; i < w/2; ++i)
            mi = pa[mi];
        memset(dm,0,sizeof(dm));
        solve(mi);
        ans = 1;
        __int128 tmp = 1;
        for (int i = 0; i < w/2; ++i)
            tmp *= dm[i];
        ans = min(tmp,__int128(LLONG_MAX));
    /*
 cerr << "w="<< w << endl;
for (int i = 0; i < w; ++i)
