ll gcd(ll a,ll b){
    if(a<b)swap(a,b);
    if(b==0)return a;
    if(a%b==0)return b;
    return gcd(b,a%b);
}
ll lcm(ll a,ll b){
    ll c=gcd(a,b);
    return a*b/c;
}
ll Pow(ll n,ll k){
    ll ret=1;
    ll now=n;
    while(k>0){
        if(k&1)ret*=now;
        now*=now;
        k/=2;
    }
    return ret;
}
ll beki(ll n,ll k,ll md){
  ll ret=1;
  ll now=n;
    now%=md;
  while(k>0){
    if(k%2==1){
      ret*=now;
      ret%=md;
    }
    now*=now;
    now%=md;
    k/=2;
  }
  return ret;
}
ll gyaku(ll n,ll md){
  return beki(n,md-2,md);
}
ll popcount(ll n){
    ll ret=0;
    ll u=n;
    while(u>0){
        ret+=u%2;
        u/=2;

    }
    return ret;
}
struct ST{
private:
    ll n;
    vector<pll> dat;
public:
    ST(vector<ll> v){
        ll sz=v.size();
        n=1;while(n<sz)n*=2;
        pll p={inf,inf};
        dat.resize(2*n-1,p);
        rep(i,0,sz)dat[i+n-1]={v[i],i};
        rrep(i,n-2,0){
            dat[i]=min(dat[i*2+1],dat[i*2+2]);
        }
    }
    void add(ll k,ll x){
        ll i=k+n-1;
        dat[i]={x,k};
        while(i>0){
            i=(i-1)/2;
            dat[i]=min(dat[2*i+1],dat[2*i+2]);
        }
    }
    pll que(ll a,ll b,ll k=0,ll l=0,ll r=-1){
        if(r<0)r=n;
        if(b<=l||a>=r)return {inf,inf};
        if(a<=l&&b>=r)return dat[k];
        pll m1=que(a,b,2*k+1,l,(l+r)/2);
        pll m2=que(a,b,2*k+2,(l+r)/2,r);
        return min(m1,m2);
    }
};
