ll solve(ll n){
    queue<int> q;
    q.push(0);
    int r=0;
    bool used[n];
    fill(used,used+n,false);
    used[0]=true;
    while(q.size()>0){
        int now=q.front();q.pop();
        r=now;
        rep(i,0,v[now].size()){
            int ne=v[now][i];
            if(used[ne])continue;
            q.push(ne);
            used[ne]=true;
        }
    }
    int dis[n];
    fill(dis,dis+n,1000000000);
    dis[r]=0;
    int r2=r;
    q.push(r);
    int par[n];
    par[r]=-1;
    while(q.size()>0){
        int now=q.front();q.pop();
        r2=now;
        rep(i,0,v[now].size()){
            int ne=v[now][i];
            if(dis[ne]>dis[now]+1){
                dis[ne]=dis[now]+1;
                q.push(ne);
                par[ne]=now;
            }
        }
    }
    int tyo=dis[r2];
    ll ans[101];
    int dis2[n];
    fill(dis2,dis2+n,1000000000);
    while(dis[r2]>(tyo+1)/2){
        r2=par[r2];
    }
    dis2[r2]=0;
    q.push(r2);
    if(tyo%2){
        r2=par[r2];
        q.push(r2);
        dis2[r2]=0;
    }
    vector<int> w[101];
    while(q.size()>0){
        int now=q.front();q.pop();
        w[dis2[now]].push_back(now);
        rep(i,0,v[now].size()){
            int ne=v[now][i];
            if(dis2[ne]>dis2[now]+1){
                dis2[ne]=dis2[now]+1;
                q.push(ne);
            }
        }
    }
    ans[0]=w[0].size();
    rep(i,0,tyo/2){
        ll ma=0;
        rep(j,0,w[i].size()){
            int now=w[i][j];
            Max(ma,(ll)v[now].size());
        }
        ma--;
        if(tyo%2==0&&i==0)ma++;
        ans[i+1]=ans[i]*ma;
    }
    return ans[tyo/2];
}
