const int N = 100;
int dep[N];
int dep2[N];
vector<int> g[N];

template <class T, class U> inline void smax(T &a, U b) { a = a > b ? a : b; }
template <class T, class U> inline void smin(T &a, U b) { a = a < b ? a : b; }

void dfs(int i, int p = -1, int d = 0) {
  dep[i] = d;
  for(int j : g[i]) if(j != p) {
    dfs(j, i, d + 1);
  }
}

int dfs2(int i, int go, int p = -1, int d = 0) {
  dep2[i] = d;
  int f = i == go;
  for(int j : g[i]) if(j != p) {
    f |= dfs2(j, go, i, d + 1);
  }
  if(!f) dep2[i] = -1;
  return f;
}

