  for(int i = 0; i < n; i++) if(dep[i] > dep[d1]) d1 = i;
  dfs(d1);
  for(int i = 0; i < n; i++) if(dep[i] > dep[d2]) d2 = i;
  if(dep[d2] % 2) {
    // center is edge
