      smax(deg[dep[i]], g[i].size() - 1);
    }
    ll ans = 1;
    for(int i = 0; i < n; i++) {
      if(deg[i] != 0) ans *= deg[i];
    }
    cout << dis + 1 << " " << ans * 2 << endl;
  } else {
    // center is vertex
    int center = 0;
    int dis = dep[d2] / 2;
    dfs2(d1, d2);
    for(int i = 0; i < n; i++) if(dep2[i] == dep[d2] / 2) center = i;
    dfs(center);
    vector<int> deg(N);
    for(int i = 0; i < n; i++) {
      smax(deg[dep[i]], g[i].size() - 1);
    }
    ll ans = 1;
    for(int i = 1; i < n; i++) {
      if(deg[i] != 0) ans *= deg[i];
    }
    ans *= g[center].size();
    for(int j : g[center]) {
      dfs(center, j);
