      }
      ll res = 1;
      for(int i = 0; i < n; i++) {
        if(deg[i] != 0) res *= deg[i];
      }
      smin(ans, res * 2);
      dump(j, center, res);
    }
    cout << dis + 1 << " " << ans << endl;
  }
}

