int n;

namespace Tree {
	int head[N], nxt[N*2], to[N*2], eid;
	void init() {
		eid = 0;
		memset(head, -1, sizeof head);
	}
	void link( int u, int v ) {
		to[eid] = v, nxt[eid] = head[u], head[u] = eid++;
		to[eid] = u, nxt[eid] = head[v], head[v] = eid++;
	}
}

int maxd, leaf[N];

void dfs( int u, int fa, int d ) {
	using namespace Tree;
	maxd = max( maxd, d );
	int ch = 0;
	for( int i = head[u]; ~i; i = nxt[i] ) {
		int v = to[i];
		if( v == fa ) continue;
		dfs(v, u, d+1), ++ch;
	}
	leaf[d] = max( leaf[d], ch );
}

pll solve1( int u ) {
	maxd = 0;
	memset(leaf, 0, sizeof leaf);
	dfs(u, 0, 1);
	ll ans = 1;
	for( int i = 1; i < maxd; ++i )
		ans *= leaf[i];
	return pll(maxd, ans);
}

pll solve2( int e ) {
	maxd = 0;
	memset(leaf, 0, sizeof leaf);
	int u = Tree::to[e];
	int v = Tree::to[e^1];
	dfs(u, v, 1);
	dfs(v, u, 1);
	ll ans = 2;
	for( int i = 1; i < maxd; ++i )
		ans *= leaf[i];
	return pll(maxd, ans);
}

pll mymin( pll a, pll b ) {
	if( a.first < b.first )
		return a;
	else if( a.first > b.first )
		return b;
	else {
		return a.second < b.second ? a : b;
	}
}

int main() {
	cin >> n;
	Tree::init();
	for( int i = 0; i < n-1; ++i ) {
		int u, v;
		cin >> u >> v;
		Tree::link(u, v);
	}
	pll ans(INFLL, INFLL);
	for( int i = 1; i <= n; ++i )
		ans = mymin( ans, solve1(i) );
	for( int i = 0; i < Tree::eid; i += 2 )
		ans = mymin( ans, solve2(i) );
	printf( "%lld %lld\n", ans.first, ans.second );
	return 0;
}

