//        cout << 1 << endl;
//        return 0;
//    }

    vector<int> d(N, 1<<30);
    d[0] = 0;
    dfs(N, G, d, 0);

    int id = max_element(d.begin(), d.end()) - d.begin();
    vector<int> d2(N, 1<<30);
    d2[id] = 0;
    dfs(N, G, d2, id);
    int id2 = max_element(d2.begin(), d2.end()) - d2.begin();

    vector<int> d3(N, 1<<30);
    d3[id2] = 0;
    dfs(N, G, d3, id2);

    int dmx = d2[id2];
    if(dmx % 2 == 0){
        int id3;
        vector<bool> flg1(N, true);
        for(int i=0; i<N; i++)
            if(d2[i] != dmx / 2) flg1[i] = false;
        for(int i=0; i<N; i++)
            if(d3[i] != dmx / 2) flg1[i] = false;
        for(int i=0; i<N; i++)
            if(flg1[i]) id3 = i;

        auto sol = solve(N, G, id3);
        int dep = sol.first;
        long long ans = sol.second;

        for(auto t : G[id3]){
            sol = solve(N, G, id3, t);
            int dep0 = sol.first;
            long long ans0 = sol.second;
            if(dep0 == dep){
                ans = min(ans, ans0);
            }
        }
        cout << dep << " " << ans << endl;
    }else{
        int id3, id4;
        vector<bool> flg1(N, true), flg2(N, true);
        for(int i=0; i<N; i++){
            if(d2[i] != dmx / 2) flg1[i] = false;
            if(d2[i] != dmx / 2 + 1) flg2[i] = false;
        }
        for(int i=0; i<N; i++){
            if(d3[i] != dmx / 2) flg2[i] = false;
            if(d3[i] != dmx / 2 + 1) flg1[i] = false;
        }
        for(int i=0; i<N; i++){
            if(flg1[i])
                id3 = i;
            if(flg2[i])
                id4 = i;
        }
        auto sol = solve(N, G, id3, id4);
        cout << sol.first << " " << sol.second << endl;
    }

    return 0;
}

