vector<int>Center(vector<vector<int>>&edge) {
	int n = edge.size();
	vector<int>center;
	vector<int>dis(n, MOD);
	dis[0] = 0;
	queue<int>Q;
	Q.push(0);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : edge[cn]) {
			if (dis[i] > dis[cn] + 1) {
				dis[i] = dis[cn] + 1;
				Q.push(i);
			}
		}
	}
	int nx = 0;
	for (int i = 1; i < n; i++) {
		if (dis[i] > dis[nx])nx = i;
	}
	for (int i = 0; i < n; i++)dis[i] = MOD;
	dis[nx] = 0;
	Q.push(nx);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : edge[cn]) {
			if (dis[i] > dis[cn] + 1) {
				dis[i] = dis[cn] + 1;
				Q.push(i);
			}
		}
	}
	int snx = 0;
	for (int i = 1; i < n; i++) {
		if (dis[i] > dis[snx])snx = i;
	}
	vector<int>rev_dis(n, MOD);
	rev_dis[snx] = 0;
	Q.push(snx);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : edge[cn]) {
			if (rev_dis[i] > rev_dis[cn] + 1) {
				rev_dis[i] = rev_dis[cn] + 1;
				Q.push(i);
			}
		}
	}
	int m = dis[snx] + 1;
	m /= 2;
	M = dis[snx] / 2 + 1;
	for (int i = 0; i < n; i++) {
		if (dis[i] <= m && rev_dis[i] <= m)center.push_back(i);
	}
	return center;
}

