using namespace std;

typedef long long ll;

const int MN = 102;

int N;
vector<int> adj[MN];
int dist[MN], par[MN], dmx[MN];

void dfs0(int u, int p) {
    for(int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(v == p) continue;
        dist[v] = dist[u] + 1;
        par[v] = u;
        dfs0(v, u);
    }
}

void dfs1(int u, int p, int d) {
    dmx[d] = max(dmx[d], (int)adj[u].size() - (p != -1));
    for(int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(v == p) continue;
        dfs1(v, u, d + 1);
    }
}

ll calc() {
    ll ret = 1;
    for(int i = 0; i < N; i++) ret *= dmx[i];
    return ret;
}

int main() {
    scanf("%d", &N);

    for(int i = 0; i < N - 1; i++) {
        int u, v; scanf("%d %d", &u, &v);
        u--; v--;

        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    dfs0(0, -1);
    int p = 0;
    for(int i = 0; i < N; i++) if(dist[i] > dist[p]) p = i;
    dist[p] = 0;
    dfs0(p, -1);
    for(int i = 0; i < N; i++) if(dist[i] > dist[p]) p = i;
    int len = dist[p];
    while(len - dist[p] < len / 2) p = par[p];

    printf("%d ", len / 2 + 1);

    ll ans = 9e18;
    if(len % 2) {
        for(int i = 0; i < N; i++) dmx[i] = 1;
        dfs1(p, -1, 0);
        ans = min(ans, calc());

        for(int i = 0; i < N; i++) dmx[i] = 1;
        dfs1(par[p], -1, 0);
        ans = min(ans, calc());

        for(int i = 0; i < N; i++) dmx[i] = 1;
        dfs1(p, par[p], 0);
        dfs1(par[p], p, 0);
        ans = min(ans, 2 * calc());
    }
    else {
        for(int i = 0; i < N; i++) dmx[i] = 1;
        dfs1(p, -1, 0);
        ans = min(ans, calc());

        for(int i = 0; i < adj[p].size(); i++) {
            int v = adj[p][i];

            for(int j = 0; j < N; j++) dmx[j] = 1;
            dfs1(p, v, 0);
            dfs1(v, p, 0);
            ans = min(ans, 2 * calc());
        }
    }

    printf("%lld", ans);
}

