vector<int> dchain;
int n;

static void get_diameter() {
	int slut, diam;

	function<void(int, int, int)> dfs1 = [&](int u, int pap, int tdist) {
		if (tdist > diam) {
			diam = tdist;
			slut = u; }
		for (auto v: g[u]) if (v != pap)
			dfs1(v, u, tdist + 1); };

	function<void(int, int, int)> dfs2 = [&](int u, int pap, int tdist) {
		if (tdist > diam) {
			diam = tdist;
			slut = u; }
		far[u] = pap;
		for (auto v: g[u]) if (v != pap)
			dfs2(v, u, tdist + 1); };

	diam = -1;
	dfs1(1, 0, 1);
	diam = -1;
	dfs2(slut, 0, 1);

	dchain.clear();
	while (slut) {
		dchain.push_back(slut);
		slut = far[slut]; } }

static void bfs(int a, int b) {
	deque<int> dq;
	int u;

	for (int i = 1; i <= n; ++i)
		lvl[i] = 0;

	dq.push_back(a);
	if (a != b)
		dq.push_back(b);
	lvl[a] = lvl[b] = 1;

	while (!dq.empty()) {
		u = dq.front();
		dq.pop_front();
		for (auto v: g[u]) if (!lvl[v]) {
			lvl[v] = lvl[u] + 1;
			dq.push_back(v); } } }


static pll solve0(int a = 0, int b = 0) {
	pll ant;

	if (n == 2)
		return {1, 2};

	get_diameter();
	if (!a && !b) {
		a = dchain[dchain.size() / 2];
		b = dchain[dchain.size() / 2 - (1 - dchain.size() % 2)]; }

	bfs(a, b);
	for (int i = 0; i <= n; ++i)
		sons[i] = 0;
	for (int i = 1; i <= n; ++i)
		sons[lvl[i]] = max(sons[lvl[i]], int(g[i].size() - 1));

	ant.first = (1 + dchain.size()) / 2;
	ant.second = 1;
	for (int i = 2; i <= n; ++i)
		ant.second*= max(1, sons[i]);

	if (a != b)
		ant.second*= (max(g[a].size(), g[b].size()) - 1) * 2;
	else
		ant.second*= g[a].size();

	return ant; }

static pll solve1() {
	pll ant = solve0();
	int mid = dchain[dchain.size() / 2];

	for (auto v: g[mid])
		ant = min(ant, solve0(mid, v));

	return ant; }

