void dfs(int v, int pr = -1) {
	if (pr == -1)
		dist[v] = 0;
	else
		dist[v] = dist[pr] + 1;
	if (dist[v] > mx) {
		mx_x = v;
		mx = dist[v];
	}
	p[v] = pr;
	I(to, a[v]) {
		if (to != pr)
			dfs(to, v);
	}
}

pair <ll, ll> solve() {
	mx = 0;
	mx_x = -1;
	clean(p);
	clean(dist);
	dfs(1);
	mx = 0;
	clean(p);
	clean(dist);
	dfs(mx_x);
	int x = mx_x;
	while (dist[x] != dist[mx_x] / 2 + dist[mx_x] % 2) {
		x = p[x];
	}
	vector <int> b, c;
	if (mx % 2 == 0) {
		b.pb(x);
		p[x] = -1;
	} else {
		b.pb(x);
		b.pb(p[x]);
		p[p[x]] = x;
	}
	/*
	cout << "B:" << endl;
	I(x, b)
		cout << x << " " << p[x] << endl;
	cout << endl;
	*/
	ll ansx = mx / 2 + 1;
	ll ans = 0;
	ll copies = 0;
//	exit(0);
//	int num = 0;
	while (1) {
		c.clear();
		ll mxcnt = 0;
		I(v, b) {
//			cout << v << " ";
			ll cnt = 0;
			I(to, a[v]) {
				if (to != p[v]) {
					++cnt;
					c.pb(to);
					p[to] = v;
				}
			}
			mxcnt = max(mxcnt, cnt);
		}
//		cout << endl;
		if (mxcnt == 0) {
//			cout << sz(b) << " " << copies << endl;
			ans = sz(b) + copies;
			break;
		}
		ll new_copies = 0;
		I(v, b) {
			ll cnt = 0;
			I(to, a[v]) {
				if (to != p[v])
					++cnt;
			}
			new_copies += (mxcnt - cnt);
		}
		new_copies += copies * mxcnt;
		copies = new_copies;
		swap(b, c);
	}
	return mp(ansx, ans);
}

