    }
}

VI branches;

void dfs2(int u, int p, int d) {
    int b = 0;
    for (int v: adj[u]) {
        if (v != p) {
            b++;
            dfs2(v, u, d+1);
        }
    }
    branches[d] = max(branches[d], b);
}

int main() {
    int N;
    RI(N);
    adj.resize(N+1);
    parent.resize(N+1);
    REP(i, N-1) {
        DRI(a, b);
        adj[a].PB(b);
        adj[b].PB(a);
    }
    dfs(1, 0, 0);
    int a = deepest.Y;
    deepest = MP(-1, 0);
    dfs(a, 0, 0);
    int d = deepest.X, b = deepest.Y, m = b;
    REP(i, (d-1)/2) {
        m = parent[m];
    }
    unsigned long long ans = -1;
    auto update = [&ans](unsigned long long prod) {
        for (int br : branches) {
            if (br == 0) break;
            prod *= br;
        }
        ans = min(ans, prod);
    };
    branches = VI(N+1);
    dfs2(m, parent[m], 0);
    dfs2(parent[m], m, 0);
    update(2);
