ll maxx, ans = linf;

ll sum[105];

ll find_len(ll now, ll fa)
{
	ll ret = 1;
	for(ll to : edge[now])
	{
		if(to == fa) continue;
		ret = max(ret, find_len(to, now) + 1);
	}
	return ret;
}

void find_max(ll now, ll fa, ll dis)
{
	ll tmp = 0;
	for(ll to : edge[now])
	{
		if(to == fa) continue;
		tmp ++;
		find_max(to, now, dis + 1);
	}
	sum[dis] = max(sum[dis], tmp);
}

void get_ans()
{
	rep(i, 1, n - 1) if(find_len(e[i].fi, e[i].se) == maxx / 2 && find_len(e[i].se, e[i].fi) == maxx / 2)
	{
		clr(sum);
		find_max(e[i].fi, e[i].se, 1), find_max(e[i].se, e[i].fi, 1);
		ll tmp = 2;
		rep(i, 1, maxx / 2 - 1) tmp = min(tmp * sum[i], linf);
		ans = min(ans, tmp);
	}
}

signed main()
{
