	if(n == 1) return puts("1 1"), 0;
	rep(i, 1, n - 1)
	{
		e[i].fi = read(), e[i].se = read();
		edge[e[i].fi].pb(e[i].se), edge[e[i].se].pb(e[i].fi);
	}
	rep(i, 1, n) maxx = max(maxx, find_len(i, 0));
