void add(int x,int y)
{
	cnt++;
	to[cnt]=y;
	nxt[cnt]=head[x];
	head[x]=cnt;
}
int bfs(int s)
{
	memset(d,-1,sizeof(d));
	queue<int> q;
	while (!q.empty())
	{
		q.pop();
	}
	d[s]=0;
	q.push(s);
	int x;
	while (!q.empty())
	{
		x=q.front();
		q.pop();
		for (int i=head[x];i;i=nxt[i])
		{
			int y=to[i];
			if (d[y]!=-1)
			{
				continue;
			}
			d[y]=d[x]+1;
			q.push(y);
		}
	}
	return x;
}
void dfs(int x,int f)
{
	int s=0;
	for (int i=head[x];i;i=nxt[i])
	{
		int y=to[i];
		if (y==f)
		{
			continue;
		}
		d[y]=d[x]+1;
		dfs(y,x);
		s++;
	}
	son[d[x]]=max(son[d[x]],1LL*s);
	mxd=max(mxd,d[x]);
}
int main()
{
	scanf("%d",&n);
	for (int i=1;i<n;i++)
	{
		int x,y;
		scanf("%d%d",&x,&y);
		add(x,y);
		add(y,x);
	}
	int g=bfs(1);
	g=bfs(g);
	int dis=d[g]/2+1;
	printf("%d ",dis);
	long long ans=1e18;
	for (int i=1;i<=n;i++)
	{
		memset(son,0,sizeof(son));
		d[i]=0;
		mxd=0;
		dfs(i,0);
		if (mxd>=dis)
		{
			continue;
		}
		for (int j=n;j>=0;j--)
		{
			if (!son[j])
			{
				mx[j]=1;
			}
			else
			{
				mx[j]=son[j]*mx[j+1];
			}
		}
		ans=min(ans,mx[0]);
	}
	for (int i=1;i<n;i++)
	{
		int x=to[i<<1];
		int y=to[i*2-1];
		memset(son,0,sizeof(son));
		mxd=0;
		d[x]=d[y]=0;
		dfs(x,y);
