  }
  lli ans1=2*n, ans2=0;
  auto test = [&](lli x, lli y) {
    if(x<ans1) {
      ans1=x; ans2=y;
    }
    if(x==ans1) ans2 = min(ans2,y);
  };
  // test roots
  FOR(i,n) {
    lli depth=0;
    vi NC;
    function<void(lli,lli,lli)> dfs = [&](lli d,lli i, lli p) {
      depth=max(depth,d);
      while(d>=(lli)NC.size()) NC.pb(0);
      lli nc=0;
      for(lli j : G[i]) if(j!=p) {
          dfs(d+1,j,i);
          nc++;
        }
      NC[d] = max(NC[d],nc);
    };
    dfs(0,i,-1);
    lli cur2=1;
    for(auto j : NC) if(j) cur2*=j;
    test(depth+1,cur2);
  }
  // test edges
  FOR(i0,n) for(int j0 : G[i0]) {
    lli depth=0;
    vi NC;
    function<void(lli,lli,lli)> dfs = [&](lli d,lli i, lli p) {
      depth=max(depth,d);
      while(d>=(lli)NC.size()) NC.pb(0);
      lli nc=0;
      for(lli j : G[i]) if(j!=p&&j!=i0&&j!=j0) {
          dfs(d+1,j,i);
          nc++;
        }
      NC[d] = max(NC[d],nc);
    };
    dfs(0,i0,-1);
    dfs(0,j0,-1);
    lli cur2=2;
    for(auto j : NC) if(j) cur2*=j;
    test(depth+1,cur2);
  }
  cout << ans1 << " " << ans2 << endl;
  return 0;
}

