void dfs(int x) {
    for (auto to : g[x])
        if (to != p[x])
            {d[to] = d[x] + 1; p[to] = x; dfs(to);}
}

void dcount(int x, int p, int lvl) {
    dg[x] = 0;
    v[lvl].pb(x);
    for (auto to : g[x])
        if (to != p)
            {dcount(to, x, lvl + 1); ++dg[x];}
}

ll sav[N][N];

ll solveforv(int x, int y) {
    if (x > y) swap(x, y);
    if (sav[x][y]) return sav[x][y];
    forn(i, 0, n - 1) v[i].clear();
    dcount(x, y, 0);
    if (x != y) dcount(y, x, 0);
    ll ans = 0;
    for1(i, n - 1, 0) {
        if (!v[i].size()) continue;
        if (!v[i + 1].size()) {
            ans = v[i].size();
            c[i] = 1;
            continue;
        }
        ll mx = 0;
        for (auto q : v[i])
            mx = max(mx, dg[q]);
        for (auto q : v[i])
            ans += (mx - dg[q]) * c[i + 1];
        c[i] = mx * c[i + 1];
    }
    return sav[x][y] = ans;
}

ll solve(int x, int y) {
    bool ok = (x == 1 && y == 7);
    int len = d[y];
    forn(i, 1, len / 2) y = p[y];
    ll ans = 0;
    if (len % 2 == 0) {
        ans = solveforv(y, y);
        for (auto to : g[y])
            ans = min(ans, solveforv(y, to));
    }
    else
        ans = solveforv(y, p[y]);
    return ans;
}

