	Tree tr2 = Tree(a, b, _);
	ll __ = argmax(tr2.depth);
	Tree tr3 = Tree(a, b, __);
	ll diameter = *max_element(ALL(tr2.depth));
	vector<ll> centers;
	for(int i=0;i<tr2.depth.size();i++){
		if (diameter%2 && llabs(diameter - tr2.depth[i]*2)==1 && llabs(diameter - tr3.depth[i]*2)==1){
			centers.pb(i);
