int treediameter(void)
{
	int FAR=0,MA=0;
	for (int i = 0; i < n; ++i)
	{
		MEMO[i]=-1;
	}
	MEMO[0]=0;
	queue<int> que;
	que.push(0);
	while (!que.empty())
	{
		int now=que.front();que.pop();
		for (auto v:edge[now])
		{
			if (MEMO[v]==-1)
			{
				MEMO[v]=MEMO[now]+1;
				if (MEMO[v]>MA)
				{
					MA=MEMO[v];
					FAR=v;
				}
				que.push(v);
			}
		}
	}
	for (int i = 0; i < n; ++i)
	{
		MEMO[i]=-1;
	}
	int ans=0;
	MEMO[FAR]=0;
	queue<int> qu;
	qu.push(FAR);
	while (!qu.empty())
	{
		int now=qu.front();qu.pop();
		for (auto v:edge[now])
		{
			if (MEMO[v]==-1)
			{
				back[v]=now;
				MEMO[v]=MEMO[now]+1;
				if (ans<MEMO[now]+1)
				{
					la=v;
				}
				ans=max(ans,MEMO[v]);
				qu.push(v);
			}
		}
	}
	return ans;
}

