struct Graph {
	vector<vector<int> > edges;
	vector<int> dst;
	int size;
	Graph(int n) {
		size = n;
		edges.resize(n);
		dst.resize(n);
	}

	int deg(int i) {
		return edges[i].size();
	}

	void bfs(vector<int> s) {
		fill(dst.begin(), dst.end(), -1);
		queue<int> q;
		for (int i = 0; i < s.size(); i++) {
			q.push(s[i]);
			dst[s[i]] = 0;
		}
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			for (int i = 0; i < edges[v].size(); i++) {
				int new_dst = dst[v] + 1;
				if (dst[edges[v][i]] == -1) {
					dst[edges[v][i]] = new_dst;
					q.push(edges[v][i]);
				}
			}
		}
		return;
	}

	void bfs(int s) {
		fill(dst.begin(), dst.end(), -1);
		queue<int> q;
		q.push(s);
		dst[s] = 0;
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			for (int i = 0; i < edges[v].size(); i++) {
				int new_dst = dst[v] + 1;
				if (dst[edges[v][i]] == -1) {
					dst[edges[v][i]] = new_dst;
					q.push(edges[v][i]);
				}
			}
		}
		return;
	}
