    for(int child: adj[cur]){
        if(child != P){
            vi temp =dfs(child, cur);
            if(temp.size() >= a.size()){
               swap(a, b); 
               swap(a, temp);
            }
            else if(temp.size() >= b.size()){
                swap(temp, b);
