    }
    return a;
}

void pre(int cur, int P, int l){
    int cnt = 0;
    for(int child: adj[cur]){
        if(child == P)continue;
        pre(child, cur, l + 1);
        cnt++;
    }
    levels[l] = max(levels[l], cnt);
}
