    for (int i = fir[rt]; i; i = con[i].la)
      ckmn(ans, calc(rt, con[i].b));
  } else {
    int r1 = 0, r2 = 0;
    rep (i, 1, n) if (rec[0][i] == (len+1)/2 && rec[1][i] == (len-1)/2)
      r1 = i;
    rep (i, 1, n) if (rec[0][i] == (len-1)/2 && rec[1][i] == (len+1)/2)
      r2 = i;
    ans = calc(r1, r2);
  }
  cout << len/2+1 << ' ' << ans << endl;
  return 0;
}

