    int a, b;
    cin>>a>>b; a--, b--;
    G[a].push_back(b);
    G[b].push_back(a);
    DoT.add_edge(a, b);
  }

  DoT.build();
  vector<int> start;
  auto path = DoT.getPath();
  start.push_back( path[DoT.length/2] );
  if(DoT.length % 2) start.push_back( path[DoT.length/2 + 1] );

  P a = solve(start);
  P b = P(INF,INF);
  if(start.size() == 1){
    int center = start[0];
    for(int center2:G[center]){
      start = {center, center2};
      Min(b, solve(start));
    }
  }

  P ans = min(a, b);
  cout<<ans.first<<" "<<ans.second<<endl;
  return 0;
}

