VL dfs(int now, int past){
    VL deg;
    ll c = 0;
    for (int next : e[now]){
        if (next == past) continue;
        c++;
        VL tmp = dfs(next, now);
        if (tmp.size() > deg.size()) deg.swap(tmp);
        REP(i,tmp.size()){
            deg[i] = max(deg[i], tmp[i]);
        }
    }
    VL ret;
    if (c) ret.push_back(c);
    for (int x : deg) ret.push_back(x);
    return ret;
}

