    ll ret = 2;
    VL deg = dfs(u, v);
    VL deg2 = dfs(v, u);
    if (deg2.size() > deg.size()) deg.swap(deg2);
    REP(i,deg2.size()) deg[i] = max(deg[i], deg2[i]);
    for (ll x : deg) ret *= x;
    return ret;
}

