pa<int, ll> solve() {
    forn(i, n) {
        dfs(i, -1, 0, i);
    }
    int globmin = 1e9, globmax = -1;
    int mini = -1;
    forn(i, n) {
        int maxx = -1;
        forn(j, n) {
            umx(maxx, d[i][j]);
        }
        if (umn(globmin, maxx)) {
            mini = i;
        }
        umx(globmax, maxx);
    }
    if (2 * globmin != globmax) {
        int v = -1;
