            int to = a[mini][i];
            int maxx = -1;
            forn(j, n) {
                umx(maxx, d[to][j]);
            }
            if (maxx == globmin) {
                v = to;
                break;
            }
        }
        assert(v >= 0);
        a[n].pb(v);
