        a[v].pb(n);
        a[mini].pb(n);
        del(mini, v);
        del(v, mini);
        //debug(mt(v, mini));
        mini = n;
        n++;
    }
    q[0].clear();
    q[1].clear();
    return mp(globmax / 2 + 1, calc(mini));
