void dfs1(int p, int b, int d){
  dist1[p] = d;
  for(int to : g[p])if(to!=b){
    dfs1(to,p,d+1);
  }
}

void dfs2(int p, int b, int d){
  dist2[p] = d;
  for(int to : g[p])if(to!=b){
    dfs2(to,p,d+1);
  }
}

int degs[125];

void dfs3(int p, int b, int d){
  int deg = 0;
  for(int to : g[p])if(to!=b){
    deg++;
    dfs3(to,p,d+1);
  }
  CHMAX(degs[d], deg);
}

pll solve1(int root){
  REP(i,n)degs[i] = -1;
  dfs3(root, -1, 0);
  ll dep = 1, lvs = 1;
  REP(i,n+1){
    if(degs[i]==0)break;
    dep++;
    // lvs * degsi >= 1ll<<60
    // lvs >= 1ll<<60 / degsi
    if(lvs >= (1ll<<60) / degs[i]){
      lvs = 1ll<<60;
    }else{
      lvs *= degs[i];
    }
  }
  return pll(dep, lvs);
}
pll solve2(int a, int b){
  REP(i,n)degs[i] = -1;
  dfs3(a, b, 0);
  dfs3(b, a, 0);
  ll dep = 1, lvs = 2;
  REP(i,n+1){
    if(degs[i]==0)break;
    dep++;
    if(lvs >= (1ll<<60) / degs[i]){
      lvs = 1ll<<60;
    }else{
      lvs *= degs[i];
    }
  }
  return pll(dep, lvs);
}

