void dfs(int u){
	ans[deep[u]] = max(ans[deep[u]],(ll)edge[u].size()-1);
	for(unsigned i=0;i<edge[u].size();++i){
		int v = edge[u][i];
		if(v == fa[u]) continue;
		fa[v] = u;
		deep[v] = deep[u] + 1;
		dfs(v);
	}
}
void solve(int u,int v){
//	printf("[%d %d]\n",u,v);
	//u -> v这条边
