		fr(i,0,e[a[m/2]].size()-1) if(e[a[m/2]][i]==a[m/2+1]) e[a[m/2]][i]=n+1;
		fr(i,0,e[a[m/2+1]].size()-1) if(e[a[m/2+1]][i]==a[m/2]) e[a[m/2+1]][i]=n+1;
		e[n+1]={a[m/2],a[m/2+1]};
		dfs(n+1);
	}
