	fr(i,0,n+1) s[i]=0;
//	fr(i,1,n) printf("%d%c",d[i],i==n?'\n':' ');
	fr(i,1,n+1) s[d[i]]=std::max(s[d[i]],(i64)e[i].size());
	s[0]=1;
