	fr(i,1,m/2) s[0]=s[0]*(s[i]-(i!=1));
	if(m%2==0)
	{
		fr(i,0,e[a[m/2]].size()-1) if(e[a[m/2]][i]==n+1) e[a[m/2]][i]=a[m/2+1];
