template<typename T>
void chmax(T &a,T b){
  if(a<b)a=b;
}
template<typename T>
void chmin(T &a,T b){
  if(a>b)a=b;
}

void f(int a){
  memset(d,0,sizeof(d));
  memset(LF,0,sizeof(LF));
  int L=0,D=0;
  map<int,int> m;
  for(int p:edge[a]){
    d[p]=1;
    queue<int> que;
    que.push(p);LF[p]=1;
    while(que.size()){
      int q=que.front();que.pop();
      for(int r:edge[q]){
        if(d[r])continue;
        if(r==a)continue;
        d[r]=d[q]+1;
        chmax(m[d[r]],(int)(edge[q].size()-1));
        LF[r]=LF[q]*(edge[q].size()-1);
        que.push(r);
      }
    }
  }
  L=1;for(auto q:m)L*=q.second;
  L*=edge[a].size();
  for(int i=0;i<n;i++)chmax(D,d[i]);
  if(color>D){color=D,leaf=L;}
  else if(color==D)chmin(leaf,L);
}
