		res *= l[i++];
	}
	return res;
}

ll tryroot(pii s) {
	fill(d, d+n+1, 0);
	fill(l, l+n+1, 0);
	queue<ll> next;
	d[s.first] = 0;
	d[s.second] = 0;
	next.push(s.first);
	next.push(s.second);
	while(!next.empty()) {
		ll cur = next.front();
		next.pop();
		ll lev = d[cur];
		// DEBUG(cur);
		// DEBUG(g[cur].size()-1);
		l[lev] = max(l[lev], (ll)(g[cur].size()-1));
		for(ll v : g[cur]) {
			if(!d[v] && v != s.first && v != s.second) {
				d[v] = 1+d[cur];
				next.push(v);
			}
		}
	}
	int i = 0;
	ll res = 1;
	while(l[i]) {
		// DEBUG(i);
		// DEBUG(l[i]);
		res *= l[i++];
	}
	return 2*res;
}

void safeinsert(pii x) {
	if(poss.count(x) == 0 && poss.count({x.second, x.first}) == 0) poss.insert(x);
}

pii far(ll s) {
	fill(d, d+n+1, 0);
	queue<ll> next;
	next.push(s);
	d[s] = 1;
	pii res = {1, s};
	while(!next.empty()) {
		ll cur = next.front();
		next.pop();
		for(ll v : g[cur]) {
			if(!d[v]) {
				next.push(v);
				d[v] = 1+d[cur];
				res = max(res, {d[v], v});
			}
		}
	}
	return res;
}

ll diameter() {
	return far(far(1).second).first;
}

//start dis at 0
bool getposs(ll s, ll p, ll dis) {
	// DEBUG(s);
	// DEBUG(dis);
	if(g[s].size() == 1 && p != -1) return dis+1 == diam;
	bool ever = false;
	for(ll v : g[s]) {
		bool cur = false;
		if(v != p) cur = getposs(v, s, dis+1);
		ever |= cur;
		if(cur && (dis == diam/2 || dis == (diam-1)/2)) {
			if(diam & 1) {
				safeinsert({s, 0});
			} else {
				if(dis == diam/2) safeinsert({s, p});
			}
		}
	}
	// DEBUG(s);
	// DEBUG(ever);
	return ever;
}

