    FOR(i, 1, n) {
    	if(g[i].size() == 1) {
    		getposs(i, -1, 0);
    	}
    }
    if(diam & 1) {
    	int root = poss.begin()->first;
    	for(int v : g[root]) {
    		safeinsert({root, v});
    	}
    }
    for(pii p : poss) {
    	// DEBUG(p.first);
    	// DEBUG(p.second);
    	if(p.second) ans2 = min(ans2, tryroot(p));
    	else ans2 = min(ans2, tryroot(p.first));
    }
    cout << ans1 << ' ' << ans2 << endl;

    return 0;
}

