void dfs1(int u, int p, int d) {
    dmx[d] = max(dmx[d], (int)adj[u].size() - (p != -1));
    for(int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(v == p) continue;
        dfs1(v, u, d + 1);
    }
}

ll calc() {
    ll ret = 1;
    for(int i = 0; i < N; i++) {
        if(ret > 9e18 / dmx[i]) return 9e18;
        ret *= dmx[i];
    }
    return ret;
}

