  }

  for (int k = 1; k <= n; ++k) {
    for (int i = 1; i <= n; ++i) {
      for (int j = 1; j <= n; ++j) {
        if (d[i][k] != -1 && d[k][j] != -1) {
          if (d[i][j] == -1) d[i][j] = d[i][k] + d[k][j];
          else d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
        }
      }
    }
  }

  int max_d = 0, U, V;
  for (int i = 1; i <= n; ++i) {
    for (int j = i + 1; j <= n; ++j) {
      if (d[i][j] > max_d) {
        max_d = d[i][j];
        U = i;
        V = j;
      }
    }
  }

  vector<int> path;
//  cout << U << "," << V << endl;
  path.push_back(U);
  for (int i = 0, u; i < max_d; ++i) {
    u = path.back();
    for (int j = 0; j < e[u].size(); ++j) {
      int v = e[u][j];
      if (d[v][V] == d[u][V] - 1) {
        path.push_back(v);
        break;
      }
    }
  }

//  for (int i = 0; i < path.size(); ++i) cout << path[i] << " ";
//  cout << endl;

  vector<int> src;
  long long deg;
  if (path.size() & 1) {
    src.push_back(path[path.size() / 2]);
    deg = 1;
  } else {
    src.push_back(path[path.size() / 2 - 1]);
    src.push_back(path[path.size() / 2]);
    deg = 2;
  }

  int res = (path.size() + 1) / 2;

  memset(vis, 0x00, sizeof(vis));

  bool very_first = true;

  while (src.size() > 0) {

    int max_deg = 1;
    for (int i = 0; i < src.size(); ++i) {
      vis[src[i]] = true;
      max_deg = max(max_deg, (int)e[src[i]].size() -  (very_first && src.size() == 1 ? 0 : 1));
 //     cout << " " << src[i];
    }
   // cout << endl;

    very_first = false;

//    cout << "max_deg: " << max_deg << endl;
    deg *= max_deg;


    vector<int> n_src;
    for (int i = 0; i < src.size(); ++i) {
      int u = src[i];
      for (int j = 0; j < e[u].size(); ++j) {
        int v = e[u][j];
        if (vis[v]) continue;
        n_src.push_back(v); 
      }
    }

    src = n_src;
  }

  cout << res << " " << deg << endl;


  return 0;
}

