pair<ll,ll> DFS(int u,int p,int root){
    pair<ll,ll> res={0,0};
    if(G[u].size()==1) res.second++;

    for(int to:G[u]){
        if(to==p) continue;

        pair<ll,ll> p=DFS(to,u,root);

        res.first=max(res.first,p.first+1);
        res.second=max(res.second,p.second);
    }

    if(u==root){
        res.second*=G[u].size();
    }else{
        if(G[u].size()>=2) res.second*=(G[u].size()-1);
    }

    return res;
}

