				}
				for (int i = 0; i < vals.size() - 1; i++) {
					if (vals[i] != 0) cur *= vals[i];
				}
				if (dim % 2 != 0) cur *= 2;
				ans = min(ans, cur);

				if (dim % 2 == 0) {
					sv.clear();
					sv.resize(dim + 1);
					for (int i = 0; i < n; i++) used[i] = 0;
					check2(v, dim, v);
				}

			}
		}
	}

	cout << (dim) / 2 + 1 << " " << ans;
	return 0;
}

