unsigned long long w = 1;
void mul(int x) {
    w *= x;
}

int n;
vector<int> e[N];
vector<int> st, lng;

void dfs(int v, int p = -1) {
    st.push_back(v);
    if (sz(st) > sz(lng))
        lng = st;
    for (int nv : e[v])
        if (nv != p)
            dfs(nv, v);
    st.pop_back();
}

int cc[N];
void dfs2(int v, int p, int cd = 0) {
    cc[cd] = max(cc[cd], sz(e[v]) - (p == -1 ? 0 : 1));
    for (int nv : e[v])
        if (nv != p)
            dfs2(nv, v, cd + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin >> n;
    for (int i = 0; i < n - 1; ++i) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        e[x].push_back(y);
        e[y].push_back(x);
    }

    dfs(0);
    int v0 = lng.back();
    lng.pop_back();
    dfs(v0);

    int dep;
    if (sz(lng) % 2 == 1) {
        dep = sz(lng) / 2 + 1;
        cout << dep << " ";
        int v = lng[sz(lng) / 2];
        dfs2(v, -1);

        ull bw = 1;
        for (int i = 0; i < dep - 1; ++i) {
            bw *= cc[i];
        }
        for (int v2 : e[v]) {
            memset(cc, 0, sizeof(cc));
            dfs2(v, v2, 0);
            dfs2(v2, v, 0);
            ull cw = 2;
            for (int i = 0; i < dep - 1; ++i)
                cw *= cc[i];
            bw = min(bw, cw);
        }
        w = bw;
    } else {
        dep = sz(lng) / 2 + 1;
        cout << dep - 1 << " ";
        int v1 = lng[sz(lng) / 2 - 1];
        int v2 = lng[sz(lng) / 2];
        cc[0] = 2;
        dfs2(v1, v2, 1);
        dfs2(v2, v1, 1);
        for (int i = 0; i < dep - 1; ++i) {
            assert(cc[i]);
            mul(cc[i]);
        }
    }

    cout << w << "\n";

    return 0;
}

