int n,a[N],d[N],xx[N],yy[N],fa[N];
ll dmx;
vector<int>g[N];
pair<ll,ll>ans;
void dfs(int x,ll de=1){
	dmx=max(dmx,de);
	d[x]=0;
	for(int i=0;i<g[x].size();++i)
	if(g[x][i]!=fa[x]){
		d[x]++;
		fa[g[x][i]]=x;
		dfs(g[x][i],de+1);
	}
}

void cal(int x,int y=0){
	static int k[N],q[N];
	q[0]=k[0]=0;
	q[++q[0]]=x;
	if(y)q[++q[0]]=y;
	ll zero=0;int dn=dmx;
	while(q[0]){
		dn--;
		if(!dn){
			if(make_pair(dmx,zero+q[0])<ans)ans=make_pair(dmx,zero+q[0]);
			return;
		}
		int dx=0;
		for(int i=1;i<=q[0];++i)dx=max(dx,d[q[i]]);
		zero=zero*dx;
		for(int i=0;i<=q[0];++i)k[i]=q[i];
		q[0]=0;
		for(int i=1;i<=k[0];++i){
			int x=k[i];
			for(int j=0;j<g[x].size();++j)
			if(g[x][j]!=fa[x]){
				q[++q[0]]=g[x][j];
			}
			zero+=dx-d[x];
		}
	}
}

