				sz.push_back(g[depth[i][j]].size() - 1);
				if (g[depth[i][j]].size() == 1) ans++;
			}
			sort(ALL(sz));
			reverse(ALL(sz));
			REP(i, sz.size()) {
				ans += (sz.front() - sz[i]) * prev;
				if (sz[i] == 0 && sz.front() > sz[i]) ans--;
			}
			prev *= max(1ll, sz.front());
		}
		return pair<ll, ll>(depth.size() + (c.size() == 1), ans);
	};

	auto p = f(c);
	if (c.size() == 1) {
		for (ll next : g[c.front()]) {
			MINC(p, f({ c.front(), next }));
		}
	}

	cout << p.first << " " << p.second << endl;

	return 0;
}

