int num_sons[105];

int furthest(int nod,int tata){
    longest[nod] = 1;
    link[nod] = 0;
    int far = nod;
    for(auto it:G[nod]){
        if(it != tata){
            int tmp = furthest(it,nod);
            if(longest[nod] < longest[it] + 1){
                longest[nod] = longest[it] + 1;
                link[nod] = it;
                far = tmp;
            }
        }
    }
    return far;
}

vector<int> get_diameter(int nod){
    vector<int> ans;
    while(nod){
        ans.push_back(nod);
        nod = link[nod];
    }
    return ans;
}

pair<int,long long> propagate_labes(vector<int> diameter){
    memset(label,0,sizeof(label));
    memset(num_sons_per_label,0,sizeof(num_sons_per_label));
    memset(num_sons,0,sizeof(num_sons));
    memset(min_leafs_for_label,0,sizeof(min_leafs_for_label));

    queue<int> Q;
    if(diameter.size() & 1){
        Q.push(diameter[diameter.size() / 2]);
        label[ diameter[diameter.size() / 2] ] = 1;
    }
    else{
        Q.push(diameter[diameter.size() / 2]);
        Q.push(diameter[diameter.size() / 2 - 1]);
        label[ diameter[diameter.size() / 2] ] = 1;
        label[ diameter[diameter.size() / 2 - 1] ] = 1;
    }

    while(!Q.empty()){
        int nod = Q.front();
        Q.pop();
        for(auto it:G[nod]){
            if(!label[it]){
                label[it] = label[nod] + 1;
                num_sons[nod]++;
                Q.push(it);
            }
        }
    }

    int max_label = 0;

    for(int i = 1;i <= N;i++){
        num_sons_per_label[ label[i] ] = max(num_sons_per_label[ label[i] ] , num_sons[i]);
        max_label = max(max_label,label[i]);
    }

    min_leafs_for_label[max_label] = 1;
    for(int i = max_label - 1;i;i--){
        min_leafs_for_label[i] = (long long)min_leafs_for_label[i + 1] * num_sons_per_label[i];
    }
    return {diameter.size() / 2 + diameter.size() % 2,(long long)min_leafs_for_label[1] * ( (diameter.size() % 2 == 0) + 1)};
}

