const ll N = 105, inf = 9223372036854775807ll;

ll n, l, c[N], d[N], x[N], ans = inf;

vector<ll> adj[N];

void getd (ll D[], ll C, ll P) {
	D[C] = D[P] + 1;
	for(auto &T : adj[C]) {
		if(T == P) continue;
		getd(D, T, C);
	}
}

pll mxd (ll I) {
	getd(d, I, 0);
	pll R = {-1, -1};
	for(ll i=1;i<=n;i++) {
		R = max(R, {d[i], i});
	}
	return R;
}

void solve (ll A, ll B) {
	getd(c, A, 0);
	getd(d, B, 0);
	fill(x+1, x+1+n, 0);
	ll M = 0;
	for(ll i=1;i<=n;i++) {
		ll D = min(c[i], d[i]);
		M = max(M, D);
		x[D] = max(x[D], (ll)adj[i].size());
	}
	if(M != (l+1)/2) return;
	ll R = (A == B ? x[1] : (x[1]-1)*2);
	for(ll i=2;i<=M;i++) {
		if(x[i] == 1) continue;
		if(x[i] != 2 && R >= inf / (x[i] - 1) + 1) return;
		R *= x[i] - 1;
	}
	ans = min(ans, R);
}

int main() {
	scanf("%lld",&n);
	if(n == 2) {
		puts("1 2");
		return 0;
	}
	for(ll i=1;i<n;i++) {
		ll A, B;
		scanf("%lld%lld",&A,&B);
		adj[A].push_back(B);
		adj[B].push_back(A);
	}
	l = mxd(mxd(1).Y).X;
	for(ll i=1;i<=n;i++) {
		solve(i, i);
	}
	for(ll i=1;i<=n;i++) {
		for(auto &T : adj[i]) {
			if(i > T) continue;
			solve(i, T);
		}
	}
	printf("%lld %lld\n",(l+1)/2,ans);
}

