{
	v[i].vis = true;
	for(int j = 0;j < v[i].next.size();++j) {
		int to = v[i].next[j];
		if(!v[to].vis) {
			v[to].depth = v[i].depth + 1;
			v[to].parent = i;
			dfs(to);
		}
	}
	v[i].vis = false;
}
int n;
int maxd[303];
int main()
{
	scanf("%d",&n);
	for(int i = 0;i < n - 1;++i) {
		int a,b;
		scanf("%d%d",&a,&b);--a,--b;
		v[a].next.push_back(b);
		v[b].next.push_back(a);
	}
	int64 min = 99999999999999999LL;
	int mind = 1000;
	for(int addi = -1;addi < n;++addi) {
		if(addi != -1) {
			v[addi].next.push_back(n);
			v[n].next.push_back(addi);
			++n;
		}
		int addn = 0;
		for(;;) {
			v[0].depth = 0;dfs(0);
			int root = 0;
			for(int i = 1;i < n;++i) if(v[i].depth > v[root].depth) root = i;
			v[root].depth = 0;dfs(root);
			int root2 = 0;
			for(int i = 1;i < n;++i) if(v[i].depth > v[root2].depth) root2 = i;
			int dia = v[root2].depth;
			int c1 = root2;
			for(int i = 0;i < dia / 2;++i) c1 = v[c1].parent;
			bool doub;
			if(dia % 2 == 0) {
				doub = false;
				v[c1].depth = 0;dfs(c1);
			} else {
				doub = true;
				int c2 = v[c1].parent;
				v[c1].vis = true;v[c2].depth = 0;dfs(c2);v[c1].vis = false;
				v[c2].vis = true;v[c1].depth = 0;dfs(c1);v[c2].vis = false;
			}
			for(int i = 0;i < n;++i) maxd[i] = 0;
			for(int i = 0;i < n;++i) if(v[i].next.size() > maxd[v[i].depth]) maxd[v[i].depth] = v[i].next.size();
			if(!doub) ++maxd[0];
			int64 ans = 1;
			for(int i = n - 1;i >= 0;--i) if(maxd[i] > 1) ans = ans * (maxd[i]-1);
			if(doub) ans *= 2;
			int cnt = dia/2+1;
			if(cnt < mind || (cnt == mind && ans < min)) {
				mind = cnt;
				min = ans;
			}
			if(addi == -1 || cnt > mind) break;
			v[n-1].next.push_back(n);
			v[n].next.push_back(n-1);
			++n;++addn;
		}
		if(addi != -1) {
			for(int j = 0;j < addn;++j) {
				--n;
				v[n-1].next.pop_back();
				v[n].next.pop_back();
			}
			--n;
			v[n].next.pop_back();
			v[addi].next.pop_back();
		}
	}
	printf("%d %lld\n", mind, min);
}

