typedef long long ll;
const int N = 123;
int n, dep[N];
vector<int> G[N], diam;
void dfs(int x, int pr) {
  dep[x] = dep[pr] + 1;
  for (auto y : G[x]) if (y != pr) {
    dfs(y, x);
  }
}
bool dfs2(int x, int tar, int pr) {
  diam.push_back(x);
  if (x == tar) return true;
  for (auto y : G[x]) if (y != pr) {
    if (dfs2(y, tar, x)) return true;
  }
  diam.pop_back();
  return false;
}
int cnt[N];
void dfs3(int x, int pr, int d) {
  cnt[d] = max(cnt[d], (int) G[x].size() - 1);
  for (auto y : G[x]) if (y != pr) {
    dfs3(y, x, d + 1);
  }
}

inline ll solve(int x, int y) {
  for (int i = 1; i <= n; i++) {
    cnt[i] = 1;
  }
  dfs3(x, y, 0);
  if (~y) dfs3(y, x, 0);
  cnt[0] = ~y ? (int) max(G[x].size(), G[y].size()) - 1 : (int) G[x].size();
  ll ret = 1;
  for (int i = 0; i <= n; i++) {
    ret *= cnt[i];
  }
  return ret * (~y ? 2 : 1);
}

int main() {
  scanf("%d", &n);
  for (int i = 1, x, y; i < n; i++) {
    scanf("%d%d", &x, &y);
    G[x].push_back(y);
    G[y].push_back(x);
  }
  dfs(1, 0);
  int g = 0, h = 0;
  for (int i = 1; i <= n; i++) {
    if (dep[i] > dep[g]) g = i;
  }
  dfs(g, 0);
  for (int i = 1; i <= n; i++) {
    if (dep[i] > dep[h]) h = i;
  }
  dfs2(g, h, 0);
  printf("%d ", (int) (diam.size() + 1) / 2);
  if ((int) diam.size() & 1) {
    int x = diam[diam.size() / 2];
    ll ans = solve(x, -1);
    for (auto y : G[x]) {
      ans = min(ans, solve(x, y));
    }
    printf("%lld\n", ans);
  } else {
    printf("%lld\n", solve(diam[diam.size() / 2 - 1], diam[diam.size() / 2]));
  }
}

#include <bits/stdc++.h>
#define int long long

using namespace std;

const int MaxN = 2e4 + 15;
const int MOD = 1e9 + 7;
const long long INF = 1e18;

int d[MaxN];
int parent[MaxN];
vector <int> v[MaxN];

int n;

void dfs(int x, int y, int p, int & r)
{
    d[x] = y;
    parent[x] = p;

    if(y > d[r])
        r = x;

    for(int to : v[x])
        if(to != p)
            dfs(to, y + 1, x, r);
}

vector <int> bfs[MaxN];

int end1, end2, dd;

 long long ans = 0;

 long long solve()
{
    memset(d, 0, sizeof(d));
    memset(parent, 0, sizeof(parent));
    for(int i = 0; i < MaxN ; ++i)
        bfs[i].clear();

    end1 = end2 = dd = 0;


    dfs(rand() % n + 1, 1, 0, end1);

    memset(d, 0, sizeof(d));
    memset(parent, 0, sizeof(parent));
    for(int i = 0; i < MaxN ; ++i)
        bfs[i].clear();

    dfs(end1, 1, 0, end2);

    dd = d[end2];

    if(!ans)
        ans = dd / 2 + dd % 2;
    else
        if(ans != dd / 2 + dd % 2)
            return 0;

    int x = end2;

    for(int i = 1; i < dd / 2 + dd % 2; ++i)
    {
        x = parent[x];
    }

    long long add = 0;

    for(int i = 1; i <= n; ++i)
        d[i] = MOD;

    bfs[0].push_back(x);
    d[x] = 0;

    if(dd % 2 == 0)
    {
        bfs[0].push_back(parent[x]);
        d[parent[x]] = 0;
    }

    int cntLast = 0;

    for(int step = 0; !bfs[step].empty(); ++step)
    {
        int mx = 0;

        long long sumCnt = 0;

        for(int x : bfs[step])
        {
            int cnt = 0;

            for(int to : v[x])
                if(d[to] == MOD)
                {
                    d[to] = d[x] + 1;
                    bfs[step + 1].push_back(to);
                    ++cnt;
                }

            mx = max(mx, cnt);
            sumCnt += cnt;
        }

        long long allCount = (bfs[step].size() + add) * mx;

        if(mx)
        {
            add = allCount - sumCnt;
        }
        cntLast = bfs[step].size();
    }

    return cntLast + add;
}

main()
{
//    freopen("output.txt", "r", stdin);

    ios_base :: sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n;

    for(int i = 0; i + 1 < n; ++i)
    {
        int x, y;
        cin >> x >> y;
        v[x].push_back(y);
        v[y].push_back(x);


    }

    int kk = 0;

    for(int i = 1; i <= n; ++i)
        if(v[i].size() == 1)
            ++kk;

    long long k1 = INF;

    ++n;
    for(int i = 1; i < n; ++i)
    {
        v[i].push_back(n);
        v[n].push_back(i);

        long long kk = solve();
        if(kk > 0)
            k1 = min(k1, kk);

        v[i].pop_back();
        v[n].pop_back();
    }

    cout << ans << ' ' << k1 << '\n';

    return 0;
}

