const int N = 105;

int n, dep[N], par[N];
vector <int> adj[N], seq[N];
LL ans, f[N], g[N];

inline void DFS(int x, int p) {
  par[x] = p, dep[x] = dep[p] + 1;
  for (auto y : adj[x]) {
    if (y != p) {
      DFS(y, x);
    }
  }
}

inline LL Solve(int x) {
  DFS(x, 0);
  int maxdep = 0;
  for (int i = 1; i <= n; ++i) {
    CheckMax(maxdep, dep[i]);
  }
  for (int i = 1; i <= maxdep; ++i) {
    seq[i].clear();
  }
  for (int i = 1; i <= n; ++i) {
    seq[dep[i]].pb(i);
  }
  LL ret = 1;
  for (int i = maxdep - 1; i; --i) {
    int maxson = 0;
    for (auto x : seq[i]) {
      int cnt = 0;
      for (auto y : adj[x]) {
        if (dep[y] == i + 1) {
          ++cnt;
        }
      }
      CheckMax(maxson, cnt);
    }
    ret *= maxson;
  }
  return ret;
}

inline LL Solve(int x, int y) {
  dep[y] = 0, DFS(x, y), dep[x] = 0, DFS(y, x), dep[x] = 1;
  int maxdep = 0;
  for (int i = 1; i <= n; ++i) {
    CheckMax(maxdep, dep[i]);
  }
  for (int i = 1; i <= maxdep; ++i) {
    seq[i].clear();
  }
  for (int i = 1; i <= n; ++i) {
    seq[dep[i]].pb(i);
  }
  LL ret = 1;
  for (int i = maxdep - 1; i; --i) {
    int maxson = 0;
    for (auto x : seq[i]) {
      int cnt = 0;
      for (auto y : adj[x]) {
        if (dep[y] == i + 1) {
          ++cnt;
        }
      }
      CheckMax(maxson, cnt);
    }
    ret *= maxson;
  }
  return ret << 1;
}

