using ll = long long;

int N;
vector<vector<int>> graph;

ll calc(vector<int> roots) {
    ll muls[100]; fill(muls, muls+100, 1LL);

    for (int root : roots) {
        int dist[100]; fill(dist, dist+N, -1); dist[root] = 0;
        queue<int> que; que.push(root);
        while (!que.empty()) {
            int v = que.front(); que.pop();
            int n_children = 0;
            for (int w : graph[v]) {
                bool found = false;
                for (int r : roots) if (r == w) found = true;
                if (!found && dist[w] == -1) {
                    ++n_children;
                    dist[w] = dist[v] + 1;
                    que.push(w);
                }
            }
            muls[dist[v]] = max(muls[dist[v]], (ll)n_children);
        }
    }

    ll ans = roots.size();
    for (int j = 0; j < 100; ++j) ans *= muls[j];
    return ans;
}

pair<int, int> farthest_one(int x) {
    int dist[100];
    fill(dist, dist+N, -1);

    queue<int> que;
    dist[x] = 0; que.push(x);

    int ans = x;
    while (!que.empty()) {
        int v = que.front(); que.pop();
        for (int w : graph[v]) {
            if (dist[w] == -1) {
                dist[w] = dist[v] + 1;
                ans = w; que.push(w);
            }
        }
    }
    return make_pair(ans, dist[ans]);
}

int main() {
    cin >> N;
    graph.resize(N);
    for (int j = 0; j < N-1; ++j) {
        int a, b; cin >> a >> b; --a; --b;
        graph[a].emplace_back(b); graph[b].emplace_back(a);
    }

    auto vsp = farthest_one(0), vgp = farthest_one(vsp.first);

    int diag = vgp.second;


    ll ans = 1LL << 60;

    vector<int> roots;
    for (int j = 0; j < N; ++j) {
        auto pr = farthest_one(j);
        if (pr.second <= (diag % 2 == 0 ? diag/2 : diag/2+1)) {
            roots.push_back(j);
        }
    }

    ans = calc(roots);

    if (diag % 2 == 0) {
        assert(roots.size() == 1);
        int centre = roots[0];
        for (int w : graph[centre]) {
            roots.clear();
            roots.push_back(centre); roots.push_back(w);
            ans = min(ans, calc(roots));
        }
    }

    cout << (1 + diag / 2) << " " << ans << endl;
    return 0;
}

