using namespace std;

struct Node {
	int dist;
	vector<int> nexts;
};

const int INF = 1000;

int N;
vector<Node> nodes;

pair<int, int> solveNode(int idx) {
	rep(i, N) nodes[i].dist = INF;

	queue<int> q;
	q.push(idx);
	nodes[idx].dist = 0;
	while (!q.empty()) {
		int now = q.front(); q.pop();
		int nowdist = nodes[now].dist;
		for (int next : nodes[now].nexts) {
			if (nodes[next].dist <= nowdist) continue;
			nodes[next].dist = nowdist + 1;
			q.push(next);
		}
	}

	map<int, int> m;
	rep(i, N) m[nodes[i].dist] = max(m[nodes[i].dist], (int) nodes[i].nexts.size());

	int ret = 1;
	for (auto it : m) {
		int dist = it.first;
		int edgeNum = it.second;
		if (dist == 0) {
			ret *= edgeNum;
		} else if (edgeNum > 1) {
			ret *= edgeNum - 1;
		}
	}

	return make_pair((int) m.size(), ret);
}

pair<int, int> solveEdge(int idx1, int idx2) {
	rep(i, N) nodes[i].dist = INF;

	queue<int> q;
	q.push(idx1);
	q.push(idx2);
	nodes[idx1].dist = 0;
	nodes[idx2].dist = 0;
	while (!q.empty()) {
		int now = q.front(); q.pop();
		int nowdist = nodes[now].dist;
		for (int next : nodes[now].nexts) {
			if (nodes[next].dist <= nowdist) continue;
			nodes[next].dist = nowdist + 1;
			q.push(next);
		}
	}

	map<int, int> m;
	rep(i, N) m[nodes[i].dist] = max(m[nodes[i].dist], (int) nodes[i].nexts.size());

	int ret = 2;
	for (auto it : m) {
		int dist = it.first;
		int edgeNum = it.second;
		if (edgeNum > 1) {
			ret *= edgeNum - 1;
		}
	}

	return make_pair((int) m.size(), ret);
}

signed main() {
	cin >> N;

	nodes.resize(N);

	rep(i, N - 1) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		nodes[a].nexts.push_back(b);
		nodes[b].nexts.push_back(a);
	}

	pair<int, int> ret(1000, 1000);

	// 点について全探索
	rep(i, N) {
		ret = min(ret, solveNode(i));
	}

	// 辺について全探索
	rep(i, N) {
		for (int next : nodes[i].nexts) {
			ret = min(ret, solveEdge(i, next));
		}
	}

	cout << ret.first << " " << ret.second << endl;

	return 0;
}

