}
int n,d,b[N],depth[N],deg[N],fa[N];
ll ans;
vector<int> e[N];
void chkmax(int &x,int y){if (x<y) x=y;}
void work(int x,int fath){
	fa[x]=fath;deg[x]=0;
	for (auto y : e[x])
	if (y!=fath){
		deg[x]++;depth[y]=depth[x]+1;
		work(y,x);
	}
}
void calc(int x,int y){
	depth[x]=depth[y]=0;
	work(x,y);work(y,x);
	for (int i=0;i<=d;i++) b[i]=0;
	for (int i=1;i<=n;i++) chkmax(b[depth[i]],deg[i]);
	ll t=(x==y) ? 1 : 2;
	for (int i=0;i<d;i++) t*=b[i];
	ans=min(ans,t);
}
