    a--; b--;
    g[a].emplace_back(b);
    g[b].emplace_back(a);
  }
  dfs(0);
  int d1 = 0, d2 = 0;
  for(int i = 0; i < n; i++) if(dep[i] > dep[d1]) d1 = i;
  dfs(d1);
  for(int i = 0; i < n; i++) if(dep[i] > dep[d2]) d2 = i;
  if(dep[d2] % 2) {
    // center is edge
    vector<int> v;
    dfs2(d1, d2);
    int dis = dep[d2] / 2;
    for(int i = 0; i < n; i++) if(dep2[i] == dis || dep2[i] == dis + 1) v.emplace_back(i);
    dfs(dep[0], dep[1]);
    dfs(dep[1], dep[0]);
    vector<int> deg(N);
    for(int i = 0; i < n; i++) {
      smax(deg[dep[i]], g[i].size() - 1);
    }
    ll ans = 1;
    for(int i = 0; i < n; i++) {
      if(deg[i] != 0) ans *= deg[i];
    }
