    for(int i = 0; i < n; i++) {
      smax(deg[dep[i]], g[i].size() - 1);
    }
    ll ans = 1;
    for(int i = 0; i < n; i++) {
      if(i != center && deg[i] != 0) ans *= deg[i];
    }
    ans *= g[center].size();
    for(int j : g[center]) {
      dfs(center, j);
