void dfs(int q,int lst){
	dpt[q] = dpt[lst] + 1;
	if(dpt[q] > mx){
		mx = dpt[q];
		gen = q;
	}
	for(int i = fir[q];i;i = e[i].nxt){
		int j = e[i].to;
		if(j == lst) continue;
		dfs(j,q);
	}
}
li ans1,ans2;
int jl[1010],ct;
void dfs2(int q,int lst){
	jl[++ct] = q;
	for(int i = fir[q];i;i = e[i].nxt){
		int j = e[i].to;
		if(j == lst || dpt[j] != dpt[q] - 1) continue;
		dfs2(j,q);
	}
}
int sd[1010],sl[1010];
int mxas[1010];
void dfs3(int q,int lst){
	sd[q] = sd[lst] + 1;
	int ss = 0;
	for(int i = 1;i <= n;++i) if(ed[q][i]){
		if(i == lst) continue;
		++ss;
		dfs3(i,q);
	}
	sl[q] = ss;
}
void work(int q){
	for(int i = 1;i <= n;++i) mxas[i] = sd[i] = sl[i] = 0;
	dfs3(q,0);
	for(int i = 1;i <= n;++i) mxas[sd[i]] = max(mxas[sd[i]],sl[i]);
	ans2 = 1;
	for(int i = 1;i <= ans1;++i) if(mxas[i] >= 1) ans2 *= mxas[i]; 
}
int dp4[1010];
void dfs4(int q,int lst){
	for(int i = fir[q];i;i = e[i].nxt){
		int j = e[i].to;
		if(j == lst) continue;
		dfs4(j,q);
		dp4[q] = max(dp4[q],dp4[j]);
	}
	++dp4[q];
}
