	li ans3 = 9000000000000000000ll;
	if(mx % 2 == 0){
		u = jl[mx / 2];
		v = jl[mx / 2 + 1];
		//cout<<u<<" "<<v<<endl;
		ed[u][v] = ed[v][u] = 0;
		++n;
		ed[n][u] = ed[n][v] = ed[u][n] = ed[v][n] = 1;
		work(n);
		ans3 = ans2;
	}
	else{
		work(jl[mx + 1 >> 1]);
		ans3 = ans2;
		u = jl[mx + 1 >> 1];
		dfs4(u,0);
		++n;
		ed[n][u] = ed[u][n] = 1;
		//cout<<"***"<<endl;
		for(i = fir[u];i;i = e[i].nxt) if(dp4[e[i].to] == ans1 - 1){
