using namespace std;
const int INF = 1e9;
const long long LLINF = 1e18;

int dfs(const vector<vector<int>> &G, int v, int p){
  int ret = 0;
  for(auto v_ : G[v]){
    if(v_ == p) continue;
    ret = max(ret,dfs(G,v_,v)+1);
  }
  return ret;
}

long long solve(const vector<vector<int>> &G, const vector<int> &C){
  int N = G.size();
  vector<int> D(N,INF);
  queue<int> Q;
  for(auto v : C) Q.push(v), D[v] = 0;
  while(not Q.empty()){
    int v = Q.front();
    Q.pop();
    for(auto v_ : G[v]){
      if(D[v_] < INF) continue;
      D[v_] = D[v]+1;
      Q.push(v_);
    }
  }
  int d = *max_element(D.begin(), D.end());
  vector<int> dig_max(d+1,0);
  for(int i = 0; i < N; ++i){
    if(C.size() == 1 and not D[i]){
      dig_max[D[i]] = max(dig_max[D[i]],(int)G[i].size());
      continue;
    }
    dig_max[D[i]] = max(dig_max[D[i]],(int)G[i].size()-1);
  }
  long long l = C.size();
  for(int i = 0; i < d; ++i){
    l *= dig_max[i];
  }
  return l;
}

int main(){
  int N;
  cin >> N;
  vector<vector<int>> G(N);
  for(int i = 0; i < N-1; ++i){
    int a,b;
    cin >> a >> b;
    --a,--b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  int ans = 0;
  for(int i = 0; i < N; ++i){
    ans = max(ans,dfs(G,i,-1));
  }
  int d = (ans+1)/2;
  vector<int> C;
  for(int i = 0; i < N; ++i){
    if(dfs(G,i,-1) != d) continue;
    C.push_back(i);
  }
  long long l = LLINF;
  if(C.size() == 2) l = solve(G,C);
  else{
    l = min(l,solve(G,C));
    int c = C[0];
    for(auto c_ : G[c]){
      //if(dfs(G,c_,-1) != d+1) continue;
      C.push_back(c_);
      l = min(l,solve(G,C));
      C.pop_back();
    }
  }
  cout << ans/2+1 << " " << l << endl;
}

