#include<bits/stdc++.h>
using namespace std;
using ll = long long;
using Edge = pair<int,int>;
using P = pair<ll,ll>;
const ll inf = numeric_limits<ll>::max()/3;

int visit[110];
ll deg[110];
vector< vector<int> > T;
vector< Edge > E;

ll dfs(int n,int d){
  visit[n] = 1;
  ll res = 0;
  ll cnt = 0;
  for(int i : T[n]){
    if(!visit[i]){
      ++cnt;
      res = max(res,dfs(i,d+1));
    }
  }
  deg[d] = max(deg[d],cnt);
  return res + 1;
}

P calc(int n){
  fill(visit,visit+110,0);
  fill(deg,deg+110,0);
  visit[n] = 1;
  ll d = dfs(n,0);
  ll l = 1;
  for(int i = 0;i < d-1;++i){
    l *= deg[i];
  }
  return P(d,l);
}

P calc2(Edge e){
  fill(visit,visit+110,0);
  fill(deg,deg+110,0);
  visit[e.first] = 1;
  visit[e.second] = 1;
  ll d = max(dfs(e.first,0),dfs(e.second,0));
  ll l = 1;
  for(int i = 0;i < d-1;++i){
    l *= deg[i];
  }
  l *= 2;
  return P(d,l);
}


int main(void){
  ll n;
  cin >> n;
  T.clear();E.clear();
  T.resize(n);
  for(int i = 0;i < n-1;++i){
    int a,b;
    cin >> a >> b;
    --a;--b;
    T[a].push_back(b);
    T[b].push_back(a);
    E.push_back(Edge(a,b));
  }
  ll color = inf;
  ll leaf = inf;
  for(int i = 0;i < n;++i){
    ll newc,newl;
    tie(newc,newl) = calc(i);
    if(newc < color){
      color = newc;
      leaf = newl;
    }else if(newc == color){
      leaf = min(leaf,newl);
    }
  }
  for(Edge e : E){
    ll newc,newl;
    tie(newc,newl) = calc2(e);
    if(newc < color){
      color = newc;
      leaf = newl;
    }else if(newc == color){
      leaf = min(leaf,newl);
    }
  }
  cout << color << " " << leaf << endl;
  return 0;
}

