            best = std::max(best, cat);
            sum += cat;
        }

        cnt = (cnt + r[p][0]) * best - sum;
        ans = cnt + sum;

        r[p][0] = 0;
        p = 1 - p;
    }

    for (int i = 1; i <= r[p][0]; i++)
        cul[r[p][i]] = q;
    for (int i = 1; i <= r[p][0]; i++)
        for (auto &x : g[r[p][i]])
            if (cul[x] == 0)
                return {MAXN, 0};

    return {val, ans};
}

inline myc solve(int n) {
    for (int i = 1; i <= n; i++)
        viz[i] = 0;
    t = 0;
    d[0][1] = 0;
    dfs(1);
    int a = 1;
    for (int i = 2; i <= n; i++)
        if (d[0][i] > d[0][a])
            a = i;

    for (int i = 1; i <= n; i++)
        viz[i] = 0;
    t = 1;
    d[1][a] = 0;
    dfs(a);
    int b = 1;
    for (int i = 2; i <= n; i++)
        if (d[1][i] > d[1][b])
            b = i;

    v[0] = 0;
    while (b != a) {
        v[++v[0]] = b;
        b = urm[b];
    }
    v[++v[0]] = a;

    r[0][0] = r[1][0] = 0;
    for (int i = 1; i <= n; i++)
        cul[i] = 0;
    if (v[0] % 2 == 1) {
        r[0][++r[0][0]] = v[v[0] / 2 + 1];
        return adevSolve();
    } else {
        myc ans = {MAXN, 0};
        for (auto &x : g[v[v[0] / 2]]) {
            r[0][0] = r[1][0] = 0;
            for (int i = 1; i <= n; i++)
                cul[i] = 0;
            r[0][++r[0][0]] = v[v[0] / 2];
            r[0][++r[0][0]] = x;
            ans = std::min(ans, adevSolve());
        }
        return ans;
    }

    return {MAXN, 0};
}

