        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
        }
    }

    vector<int> cnt(n), fa(n);

    function<void(int, int)> DfsFa = [&](int x, int p) {
        fa[x] = p;
        for (int u : g[x]) {
            if (u != p) DfsFa(u, x);
        }
    };

    function<void(int, int, int)> Dfs = [&](int x, int p, int d) {
        int ch = 0;
        for (int u : g[x]) ch += u != p;
        cnt[d] = max(cnt[d], ch);
        for (int u : g[x]) {
            if (u != p) Dfs(u, x, d + 1);
        }
    };

    auto Solve = [&](int x) { 
        fill(cnt.begin(), cnt.end(), 0);
        Dfs(x, -1, 0);
        long long res = 1;
        for (int i = 0; i < n; ++i) {
            if (cnt[i] == 0) break;
            res *= cnt[i];
        }
        return res;
    };

    auto Solve2 = [&](int x, int y) { 
        fill(cnt.begin(), cnt.end(), 0);
        Dfs(x, y, 0);
        Dfs(y, x, 0);
        long long res = 2;
        for (int i = 0; i < n; ++i) {
            if (cnt[i] == 0) break;
            res *= cnt[i];
        }
        return res;
    };

    int color = n + 1;
    long long ans = 1'000'000'000'000'000'000;
    for (int i = 0; i < n; ++i) {
        int pd = 0;
        for (int j = 0; j < n; ++j) pd = max(pd, d[i][j]);
        if (pd > color) continue;
        long long res = Solve(i);
        if (pd < color) color = pd, ans = res;
        else ans = min(ans, res);
    }
    for (int i = 0; i < n; ++i) {
        for (int j : g[i]) {
            int pd = 0;
            for (int k = 0; k < n; ++k) pd = max(pd, min(d[i][k], d[j][k]));
            if (pd > color) continue;
            long long res = Solve2(i, j);
            if (pd < color) color = pd, ans = res;
            else ans = min(ans, res);
        }
    }
    printf("%d %lld\n", color + 1, ans);
    return 0;
}

