void dfs(int x,int pre,int d,vector<ll>&p){
    if(d==0){
        if(pre!=-1){
            p[d] = max(p[d],(ll)g[x].size()-1);
        }else{
            p[d] = max(p[d],(ll)g[x].size());
        }
    }else{
        p[d] = max(p[d],(ll)g[x].size()-1);
    }
    for(auto s:g[x]){
        if(s!=pre){
            dfs(s,x,d+1,p);
        }
    }
}

pair<ll,ll> solve(int s){
    vector<ll> p(n);
    dfs(s,-1,0,p);
    pair<ll,ll> res=MP(0,1);
    rep(i,n){
        if(p[i]==0)break;
        res.first = i+2;
        res.second *= p[i];
    }
    //cerr << s << " " << res.first << " " << res.second << endl;
    return res;
}

pair<ll,ll> solve(pair<int,int> w){
    vector<ll> p(n);
    int s = w.first;
    int t = w.second;
    dfs(s,t,0,p);
    dfs(t,s,0,p);
    pair<ll,ll> res=MP(0,1);
    rep(i,n){
        if(p[i]==0)break;
        res.first = i+2;
        res.second *= p[i];
    }
    res.second *= 2;
    //cerr << s << " " << t << " " << res.first << " " << res.second << endl;
    return res;


}

