const int N=1e3+5;
const int inf=INT_MAX;
int n,now,w[N],v[N],nex[N],head[N];
void addedges(int x,int y){
	nex[++now]=head[x];
	head[x]=now,v[now]=y;
}
long long leaf;
int ans,col=inf,dep[N],_max[N];
void dfs(int x,int fa){
	int cnt=0;
	dep[x]=dep[fa]+1,ans=max(ans,dep[x]);
	for(int i=head[x];i;i=nex[i])
		if(v[i]!=fa)	dfs(v[i],x),++cnt;
	_max[dep[x]]=max(_max[dep[x]],cnt);
}
int vx[N],vy[N];
int main(){
	scanf("%d",&n);
	for(int i=1;i<n;i++){
		scanf("%d%d",&vx[i],&vy[i]);
		addedges(vx[i],vy[i]);
		addedges(vy[i],vx[i]);
	}
	for(int i=1;i<=n;i++){
		long long sum=1;
		ans=0,dep[i]=0,dfs(i,i);
		for(int i=1;i<ans;i++)	sum=sum*_max[i];
		if(col>ans)	col=ans,leaf=sum;
		else	if(col==ans&&sum<leaf)	leaf=sum;
		for(int i=1;i<=ans;i++)	_max[i]=0;
	}
	for(int i=1;i<n;i++){
		long long sum=2;
		ans=0;
		dep[vy[i]]=0,dfs(vx[i],vy[i]);
		dep[vx[i]]=0,dfs(vy[i],vx[i]);
