const int N = 150;
const LL INF = 9E18;
int n;
vector<int> G[N];
int d[N], vis[N], p[N];
void bfs(int s, int ban = -1) {
    queue<int> q;
    memset(vis, 0, sizeof vis);
    q.push(s); d[s] = 0; p[s] = 0; vis[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v: G[u]) {
            if (v == ban || vis[v]) continue;
            q.push(v); d[v] = d[u] + 1; p[v] = u; vis[v] = 1;
        }
    }
}

vector<int> go() {
    bfs(1);
    int s = max_element(d, d + n + 1) - d;
    bfs(s);
    int t = max_element(d, d + n + 1) - d;
    vector<int> ans;
    while (t) {
        ans.push_back(t);
        t = p[t];
    }
    return ans;
}

int main() {
