        int a, b; cin >> a >> b;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    vector<int> D = go();
    dbg(D);
    int dsz = D.size();
    LL ans1 = (dsz + 1) / 2, ans2 = INF;
    if (dsz % 2) {
        ans1 = (dsz + 1) / 2;
        bfs(D[dsz / 2]);
        vector<int> deg(ans1);
        FOR (i, 1, n + 1) deg[d[i]] = max(deg[d[i]], (int) G[i].size());
        ans2 = deg[0];
        FOR (i, 1, ans1 - 1) ans2 *= deg[i] - 1;
    }

    FOR (c1, 1, n + 1) for (int c2: G[c1]) {
        bfs(c2, c1); bfs(c1, c2);
        int maxd = *max_element(d + 1, d + n + 1);
        if (maxd >= ans1) continue;
        vector<int> deg(ans1);
        FOR (i, 1, n + 1) deg[d[i]] = max(deg[d[i]], (int) G[i].size());
        dbg(c1, c2); dbg(deg);
        LL t = 2; FOR (i, 0, ans1 - 1) t *= deg[i] - 1;
        ans2 = min(ans2, t);
    }

    printf("%lld %lld\n", ans1, ans2);
}

