bool multicase = false;

ll n,m,num,a,b,c,d,e,q, ans;

ll x[100005], y[100005];
ll maxi[100005];
ll k;
vector<ll> G[100005];

void look(ll a,ll b){
    x[a]=b; //aまでの距離はb
    for(int i=0;i<G[a].size();i++){
        if(x[G[a][i]]>=0)continue;
        look(G[a][i],b+1);
    }
}

void looko(ll a,ll b){
    y[a]=b; //aまでの距離はb
    for(int i=0;i<G[a].size();i++){
        if(y[G[a][i]]>=0)continue;
        looko(G[a][i],b+1);
    }
}

void dfs(ll v, ll p){
    ll idx = y[v];
    ll cnt = 0;
    for(int i=0;i<G[v].size();i++){
        ll nv = G[v][i];
        ll idx_2 = y[nv];
        if(idx > idx_2){
            cnt ++;
        }
        if(nv != p)dfs(nv, v);
    }
    maxi[idx] = max(maxi[idx], cnt);
    return;
}
void solve(){
    cin >> n;
    if(n >= 1000)return;
    ll num = 0;
    for(ll i=0;i<n-1;i++){
        cin >> a >> b;
        G[a].pb(b);
        G[b].pb(a);
    }
    for(int i=1;i<=n;i++){
        x[i] = y[i] = -1;
    }
    look(1, 0);
    for(int i=1;i<=n;i++){
        if(num < x[i]){
            num = x[i], a = i;
        }
    }
    looko(a, 0);
    num = 0;
    for(int i=1;i<=n;i++){
        if(num < y[i])num = y[i];
    }
    num ++;
    ll color = (num + 1) / 2;
    for(int i=1;i<=n;i++){
        y[i] = min(y[i], num - 1 - y[i]);
