  for (int i = 0; i < n-1; ++i) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  vi mad(n);
  int mi = n;
  for (int i = 0; i < n; ++i) {
    dfs(i, -1, 0, g);
    for (int j = 0; j < n; ++j) mad[i] = max(mad[i], d[j]);
    mi = min(mi, mad[i]);
  }
  vi roots;
  for (int i = 0; i < n; ++i) if (mad[i] == mi) roots.push_back(i);
  assert(roots.size() && roots.size() < 3);
  if (roots.size() == 1) cout << mi + 1 << ' ';
  else cout << mi << ' ';
  if (roots.size() == 2) {
    g.resize(n + 1);
    for (int t = 0; t < 2; ++t) {
      g[roots[t]].erase(find(g[roots[t]].begin(), g[roots[t]].end(), roots[1-t]));
      g[n].push_back(roots[t]);
      g[roots[t]].push_back(n);
    }
    ++n;
    cout << solve(g, n) << endl;
  } else {
    int res = solve(g, roots[0]);
    vi cands = g[roots[0]];
    g.resize(n + 1);
    g[n].push_back(roots[0]);
    g[roots[0]].push_back(n);
    for (int v : cands) {
      g[roots[0]].erase(find(g[roots[0]].begin(), g[roots[0]].end(), v));
      g[v].erase(find(g[v].begin(), g[v].end(), roots[0]));
      g[n].push_back(v);
      g[v].push_back(n);
      res = min(res, solve(g, n));
      g[n].pop_back();
      g[v].pop_back();
      g[roots[0]].push_back(v);
      g[v].push_back(roots[0]);
    }
    cout << res << endl;
  }
  return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ull = uint64_t;

int main() {
   ios_base::sync_with_stdio(false); cin.tie(nullptr);
   int N;
   cin >> N;
   vector<vector<int>> adj(N);
   for (int i = 0; i < N - 1; ++i) {
      int v, u;
      cin >> v >> u;
      adj[--v].emplace_back(--u);
      adj[u].emplace_back(v);
   }
   int dep;
   ull ans = numeric_limits<ull>::max();
   vector<int> diam;
   {
      vector<int> par(N);
      int start = 0;
      for (int z = 0; z < 2; ++z) {
         fill(par.begin(), par.end(), -1);
         vector<int> bfs;
         bfs.emplace_back(start);
         for (int i = 0; i < N; ++i) {
            int v = bfs[i];
            for (int u : adj[v]) if (u != par[v]) {
               par[u] = v;
               bfs.emplace_back(u);
            }
         }
         start = bfs.back();
      }
      while (~start) {
         diam.emplace_back(start);
         start = par[start];
      }
   }
   vector<int> deg(N);
   function<void(int, int, int d)> dfs = [&](int v, int p, int d) {
      deg[d] = max(deg[d], int(adj[v].size()) - (p != -1));
      for (int u : adj[v]) if (u != p) {
         dfs(u, v, d + 1);
      }
   };
   if (diam.size() % 2 == 0) {
      dep = diam.size() / 2;
      int v0 = diam[(diam.size() / 2) - 1];
      int v1 = diam[(diam.size()) / 2];
      fill(deg.begin(), deg.end(), 0);
      dfs(v0, v1, 0);
      dfs(v1, v0, 0);
      ull cur = 2;
      for (int i = 0; i < dep - 1; ++i) cur *= deg[i];
      ans = cur;
   } else {
      int v = diam[diam.size() / 2];
      dep = (diam.size() + 1) / 2;
      fill(deg.begin(), deg.end(), 0);
      dfs(v, -1, 0);
      ull cur = 1;
      for (int i = 0; i < dep - 1; ++i) cur *= deg[i];
      ans = min(ans, cur);
      for (int u : adj[v]) {
         fill(deg.begin(), deg.end(), 0);
         dfs(v, u, 0);
         dfs(u, v, 0);
         ull cur = 2;
         for (int i = 0; i < dep - 1; ++i) cur *= deg[i];
         ans = min(ans, cur);
      }
   }
   cout << dep << " " << ans << "\n";
   return 0;
}

