	rep(i, 1, n) maxx = max(maxx, find_len(i, 0));
	if(!(maxx & 1)) get_ans();
	else
	{
		maxx ++;
		rep(i, 1, n)
		{
			ll flag = 0;
			for(ll to : edge[i])
			{
				ll tmp = find_len(to, i);
				if(tmp == maxx / 2 - 1) flag ++;
			}
			if(flag < 2) continue;
			clr(sum);
			for(ll to : edge[i]) find_max(to, i, 1);
			ll tmp = siz(edge[i]);
			rep(j, 1, maxx / 2 - 2) tmp = min(tmp * sum[j], linf);
			ans = min(ans, tmp);
		}
		get_ans();
	}
	write(maxx / 2), putchar(' '), write(ans), enter;
	return 0;
}

