vector <int> diag;
ll child_leaf[N];
int deg[N];
int cnt[N];

void add(int x, int y) {
    e[x].push_back(y);
    e[y].push_back(x);
}

void dfs0(int u, int p) {
    dep[u] = dep[p] + 1;
    for (auto &v : e[u]) {
        if (v != p) dfs0(v, u);
    }
}

void clear() {
    fill_n(child_leaf, n + 1, 0);
    fill_n(cnt, n + 1, 0);
}

void go(int u, int t, int p, vector <int> &tmp) {
    tmp.push_back(u);
    if (u == t) {
        diag = tmp;
    }
    for (auto &v : e[u]) if (v != p) {
        go(v, t, u, tmp);
    }
    tmp.pop_back();
}

pair <ll, int> dfs(int u, int p) {
    cnt[u] = 0;
    int mx_child_deg = 0;
    ll mx_child_child_leaf = 0;
    for (auto &v : e[u]) if (v != p) {
        dfs(v, u);
        maxi(mx_child_deg, cnt[v]);
        maxi(mx_child_child_leaf, child_leaf[v]);
        cnt[u]++;
    }
    if (mx_child_deg == 0) {
        child_leaf[u] = 1;
    } else {
        child_leaf[u] = 1ll * mx_child_deg * mx_child_child_leaf;
    }
    return make_pair(child_leaf[u], cnt[u]);
}

void run() {
    cin >> n;

    for (int i = 1; i < n; ++i) {
        cin >> a[i] >> b[i];
        add(a[i], b[i]);
    }

    dfs0(1, 0);
    int remote = max_element(dep + 1, dep + n + 1) - dep;
    dfs0(remote, 0);
    int remote2 = max_element(dep + 1, dep + n + 1) - dep;
    vector <int> tmp;
    go(remote, remote2, 0, tmp);

    int z = diag.size();
    ll ans1 = n, ans2 = inf;
    ans1 = (z + 1) / 2;
    if (z % 2 == 0) {
        clear();
        dfs(diag[ans1 - 1], diag[ans1 - 2]);
        dfs(diag[ans1 - 2], diag[ans1 - 1]);
        int tmpx = max(cnt[diag[ans1 - 1]], cnt[diag[ans1 - 2]]);
        ll tmpy = max(child_leaf[diag[ans1 - 1]], child_leaf[diag[ans1 - 2]]);
        ans2 = 2 * tmpy * tmpx;
    } else {
        int rt = diag[ans1 - 1];
        clear();
        dfs(rt, 0);
        if (cnt[rt] == 0) {
            ans2 = 1;
        } else {
            ans2 = cnt[rt] * child_leaf[rt];
        }
        for (int x : e[rt]) {
            clear();
            dfs(x, rt);
            dfs(rt, x);
            int tmpx = max(cnt[x], cnt[rt]);
            ll tmpy = max(child_leaf[rt], child_leaf[x]);
            mini(ans2, 2 * tmpy * tmpx);
        }
    }

    cout << ans1 << " " << ans2 << endl;

}

int main() {
    run();
    return 0;
}

