ll modpow(ll a,ll b){a%=mod;if(b==0)return 1;if(b&1)return a*modpow(a,b-1)%mod;ll k=modpow(a,b/2);return k*k%mod;}
vi diameter(vvi g){
    ll n=g.size();
    vi dis(n,inf);
    queue<ll> q;
    q.emplace(0);
    dis[0]=0;
    while(!q.empty()){
        auto t=q.front();q.pop();
        for(ll x:g[t]){
            if(chmin(dis[x],dis[t]+1))q.emplace(x);
        }
    }
    P far=P(-1,-1);
    rep(i,n)chmax(far,P(dis[i],i));
    dis=vi(n,inf);
    ll ne=far.se;
    dis[ne]=0;
    q.emplace(ne);
    vi par(n,-1);
    while(!q.empty()){
        auto i=q.front();q.pop();
        for(ll x:g[i])if(x!=par[i]){
            dis[x]=dis[i]+1;q.emplace(x);par[x]=i;
        }
    }
    far=P(-1,-1);
    rep(i,n)chmax(far,P(dis[i],i));
    ll w=far.se;
    vi res;
    while(w!=ne){
        res.pb(w);
        w=par[w];
    }
    res.pb(ne);
    return res;
}
ll solve(vvi g,vi d){
    ll n=g.size();
    vi dp;
    if(d.size()&1)dp.pb(d[d.size()/2]);
    else rep(i,2)dp.pb(d[d.size()/2-i]);
    ll res=dp.size();
    vb used(n,false);
    for(ll x:dp)used[x]=true;
    while(true){
        vi ndp;
        ll ma=0;
        for(ll i:dp){
            ll cnt=0;
            for(ll x:g[i])if(!used[x]){
                used[x]=true;
                cnt++;
                ndp.pb(x);
            }
            chmax(ma,cnt);
        }
        if(ma==0)break;
        res*=ma;
        dp=ndp;
    }
    return res;
}
int main(){
    ll n;cin>>n;
    vvi g(n);
    rep(i,n-1){
        ll a,b;cin>>a>>b;a--;b--;
        g[a].pb(b);
        g[b].pb(a);
    }
    vi t=diameter(g);
    cout<<(t.size()+1)/2<<' ';
    ll ans=solve(g,t);
    rep(i,n){
        if(t.size()%2==0)break;
        vi vv(1,i);
        vvi gg=g;
        gg.pb(vv);
        gg[i].pb(n);
        vi tt=diameter(gg);
        if(tt.size()==t.size()+1)chmin(ans,solve(gg,tt));
    }
    out(ans);
}

