        --b[i];
        tree[a[i]].push_back(b[i]);
        tree[b[i]].push_back(a[i]);
    }

    static i64 height[128][128];
    static i64 leaf[128][128];
    fill_n((i64*)height,128*128,-1);
    fill_n((i64*)leaf,128*128,-1);

    function<i64(int,int)> calc_height=[&](int u,int p){
        i64& res=height[u][p];
        if(res!=-1) return res;
        res=1;
        rep(i,0,tree[u].size()){
            if(tree[u][i]==p) continue;
            res=max(res,calc_height(tree[u][i],u)+1);
        }
        return res;
    };

    function<i64(int,int)> calc_leaf=[&](int u,int p){
        i64& res=leaf[u][p];
        if(res!=-1) return res;
        if(tree[u].size()==1) return res=i64(1);
        res=0;
        rep(i,0,tree[u].size()){
            if(tree[u][i]==p) continue;
            res+=calc_leaf(tree[u][i],u);
        }
        return res;
    };

    i64 ans=inf64,ans_leaf=inf64;
    rep(i,0,N-1){
        int x=a[i],y=b[i];
        i64 max_height=0,cnt=0,max_leaf=0;
        {
            rep(j,0,tree[x].size()){
                if(tree[x][j]==y) continue;
                max_height=max(max_height,calc_height(tree[x][j],x)+1);
                max_leaf=max(max_leaf,calc_leaf(tree[x][j],x));
            }
        }
        {
            rep(j,0,tree[y].size()){
                if(tree[y][j]==x) continue;
                max_height=max(max_height,calc_height(tree[y][j],y)+1);
                max_leaf=max(max_leaf,calc_leaf(tree[y][j],y));
            }
        }
        if(max_height>ans) continue;
        if(max_height<ans){
            ans=max_height;
            ans_leaf=max_leaf*max<i64>(tree[x].size()-1,tree[y].size()-1)*2;
        }else{
            ans_leaf=min<i64>(ans_leaf,max_leaf*max<i64>(tree[x].size()-1,tree[y].size()-1)*2);
        }
    }

    print(ans);
    print(ans_leaf);

    rep(i,0,N){
        int x=i;
        if(tree[x].size()==1) continue;
        i64 max_height=0,max_leaf=0;
        rep(j,0,tree[x].size()){
            max_height=max(max_height,calc_height(tree[x][j],x)+1);
            max_leaf=max(max_leaf,calc_leaf(tree[x][j],x));
        }
        print(i);
        print(max_height);
        print(max_leaf);
        if(max_height>ans) continue;
        if(max_height<ans){
            ans=max_height;
            ans_leaf=max_leaf*tree[x].size();
        }else{
            ans_leaf=min<i64>(ans_leaf,max_leaf*tree[x].size());
        }
    }

    cout << ans << " " << ans_leaf << endl;
}

