void do_calc(set<int> centroidInit)
{
    vector<bool> treated(n, false);
    set<int> centroid = centroidInit;

    int colorNum = 0;
    vector<int> prod(1, centroidInit.size());
    while (!centroid.empty())
    {
        colorNum++;
        if (colorNum > minColorful) break;
        set<int> centroidNext;
        for (auto i : centroid)
        {
            treated[i] = true;
        }
        int maxBranch = 0;
        for (auto i : centroid)
        {
            int branch = 0;
            for (auto j : to[i])
            {
                if (treated[j] == false)
                {
                    branch++;
                    centroidNext.insert(j);
                }
            }
            maxBranch = max(maxBranch, branch);
        }
        centroid = centroidNext;
        if (maxBranch > 0) prod.push_back(maxBranch);
    }

    long long leaf = 1;
    for (auto i : prod) leaf *= i;
    if (colorNum < minColorful)
    {
        minColorful = colorNum;
        minLeaf = leaf;
    }
    else if (colorNum == minColorful)
    {
        if (leaf < minLeaf) minLeaf = leaf;
    }
}

