int n, dep[maxn], par[maxn], mx[maxn];
long long ans;
vector<int> g[maxn], v;

void dfs(int u, int p = 0) {
	par[u] = p;
	dep[u] = dep[p] + 1;
	for (int v: g[u]) {
		if(v != p) {
			dfs(v, u);
		}
	}
	return;
}

void dfs2(int u, int p, int d = 0) {
	int cnt = 0;
	for (int v: g[u]) {
		if(v != p) {
			dfs2(v, u, d + 1);
			++cnt;
		}
	}
	debug("dfs2(%d, %d) cnt = %d\n", u, p, cnt);
	mx[d] = max(mx[d], cnt);
	return;
}

void F2(int u, int v) {
	debug("F2(%d, %d)\n", u, v);
	for (int i = 0; i < maxn; ++i) {
		mx[i] = 0;
	}
	dfs2(u, v);
	dfs2(v, u);
	long long ret = 1;
	for (int i = 0; i < maxn; ++i) {
		if(!mx[i]) {
			break;
		}
		ret = (long long) ret * mx[i];
	}
	ans = min(ans, ret * 2);
}

