int n; 
void dfs(int now, int par, int d[]) {
	for (int e : G[now]) {
		if (e == par)continue;
		d[e] = d[now] + 1;
		dfs(e, now, d);
	}
}
void dfs2(int now, int d[]) {
	for (int e : G[now]) {
		if (d[e] == -1) {
			d[e] = d[now] + 1;
			dfs2(e, d);
		}
