pair<int,int> DFS(int u,int p,int root){
    pair<int,int> res={0,0};
    if(G[u].size()==1) res.second++;

    for(int to:G[u]){
        if(to==p) continue;

        pair<int,int> p=DFS(to,u,root);

        res.first=max(res.first,p.first+1);
        if(u==root) res.second=max(res.second,p.second);
        else res.second+=p.second;
    }

    if(u==root){
        if(p==-1) res.second*=G[u].size();
        else res.second*=(G[u].size()-1);
    }

    return res;
}

