}
long f(int u,int v)
{
	vector<int>d(111,n);
	d[u]=d[v]=0;
	queue<int>P;
	P.push(u);P.push(v);
	while(!P.empty())
	{
		int x=P.front();P.pop();
		for(int i=0;i<G[x].size();i++)
		{
			int y=G[x][i];
			if(d[y]>d[x]+1)
			{
				d[y]=d[x]+1;
				P.push(y);
			}
		}
	}
	long ans=1;
	for(int i=0;;i++)
	{
		bool flag=0;
		long now=1;
		for(int j=0;j<n;j++)
		{
			if(d[j]==i)
			{
				flag=1;
				now=max(now,(long)G[j].size()-1);
			}
		}
		if(!flag)break;
		ans*=now;
	}
	return ans*2;
}
