	for(;!cnt[mind];mind++);
	if(cnt[mind]%2)
	{
		int mindi=0;
		for(;d[mindi]!=mind;mindi++);
		ansb=G[mindi].size();
		for(int i=mind+1;cnt[i];i++)
		{
			int now=1;
			for(int j=0;j<n;j++)
			{
				if(d[j]==i)now=max(now,(int)G[j].size()-1);
			}
			ansb*=now;
		}
		for(int i=0;i<G[mindi].size();i++)
