		g[a[i]].push_back(b[i]);
		g[b[i]].push_back(a[i]);
	}
	function<vector<int>(int, int)> shortest_paths = [&](int p1, int p2) {
		vector<int> dist(n, -1);
		queue<int> que;
		dist[p1] = 0, que.push(p1);
		if (p2 != -1) dist[p2] = 0, que.push(p2);
		while (!que.empty()) {
			int u = que.front(); que.pop();
			for (int i : g[u]) {
				if (dist[i] == -1) {
					dist[i] = dist[u] + 1;
					que.push(i);
				}
			}
		}
		return dist;
	};
	vector<int> dz = shortest_paths(0, -1);
	vector<int> dx = shortest_paths(max_element(dz.begin(), dz.end()) - dz.begin(), -1);
	vector<int> dy = shortest_paths(max_element(dx.begin(), dx.end()) - dx.begin(), -1);
	int ans = *max_element(dx.begin(), dx.end()) / 2 + 1;
	long long ret = 1LL << 62;
	if (n == 2) ret = 2;
	else {
		for (int i = 0; i < n; i++) {
			if (dx[i] < ans && dy[i] < ans) {
				vector<int> d = shortest_paths(i, -1);
				vector<int> mx(ans - 1);
				for (int j = 0; j < n; j++) {
					if (d[j] == ans - 1) continue;
					mx[d[j]] = max(mx[d[j]], (int)g[j].size());
				}
				long long mul = mx[0];
				for (int j = 1; j < ans - 1; j++) {
					mul *= mx[j] - 1;
				}
				ret = min(ret, mul);
			}
		}
		for (int i = 0; i < n - 1; i++) {
			vector<int> d = shortest_paths(a[i], b[i]);
			if (*max_element(d.begin(), d.end()) < ans) {
				vector<int> mx(ans - 1);
				for (int j = 0; j < n; j++) {
					if (d[j] == ans - 1) continue;
					mx[d[j]] = max(mx[d[j]], (int)g[j].size());
				}
				long long mul = mx[0] - 1;
				for (int j = 1; j < ans - 1; j++) {
					mul *= mx[j] - 1;
				}
				ret = min(ret, mul * 2);
			}
		}
	}
	cout << ans << ' ' << ret << '\n';
	return 0;
}

