const int N = 110;
VI g[N];

void chmax_vi(VI &x, const VI &y) {
  while (x.size() < y.size()) x.push_back(0);
  REP(i, 0, y.size()) {
    x[i] = max(x[i], y[i]);
  }
}


VI flatten(int v, int par) {
  VI ma;
  REP(i, 0, g[v].size()) {
    int w = g[v][i];
    if (w == par) continue;
    VI res = flatten(w, v);
    chmax_vi(ma, res);
  }
  ma.insert(ma.begin(), g[v].size() - 1);
  return ma;
}



const ll inf = 1e18;

