      }
      while (ma.size() < fl.size()) ma.push_back(0);
      REP(i, 0, fl.size()) ma[i] = max(ma[i], fl[i]);
    }
    ll prod = g[i].size();
    REP(j, 0, ma.size() - 1) {
      ll lim = inf / ma[j] + 1;
      if (prod >= lim) {
	prod = inf;
      } else {
	prod *= ma[j];
      }
    }
    mi = min(mi, PIL(ma.size() + 1, prod));
  }
