int calc(int c1,int c2){
	d[c1] = 0;
	d[c2] = 0;
	dfs(c1,c2);
	dfs(c2,c1);
	int cnt[110][110] = {};
	for(int i = 0;i < n;i++){
		cnt[d[i]][G[i].size()]++;
	}
	for(int i = 0;i < ma / 2;i++){
		int m = 0;
		for(int j = 0;j < n;j++){
			if(cnt[i][j]) chmax(m,j);
		}
		for(int j = 0;j < n;j++){
			cnt[i + 1][1] += (m - j) * cnt[i][j];
		}
	}
	return cnt[ma / 2][1];
}

