using namespace std;

vector<vector<int>> link(110);
vector<pair<int, int>> edge;
int vis[110];

vector<int> branch;

int dfs(int u, int dep) {
	vis[u] = 1;
	int son = 0;
	int res = dep;
	for (int i = 0; i < link[u].size(); i++) {
		int v = link[u][i];
		if (!vis[v]) {
			son++;
			res = max(dfs(v, dep + 1), res);
		}
	}
	branch[dep] = max(branch[dep], son);
	return res;
}

int main() {
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n - 1; i++) {
		int x, y;
		scanf("%d %d", &x, &y);
		link[x].push_back(y);
		link[y].push_back(x);
		edge.push_back(make_pair(x, y));
	}
	int col = n + 1;
	long long ans = -1;
	for (int i = 1; i <= n; i++) {
		memset(vis, 0, sizeof(vis));
		branch.resize(0);
		branch.resize(n + 1);
		int dep = dfs(i, 1);
		if (dep <= col) {
			long long tmp = max(branch[1], 2);
			for (int j = 2; j < dep; j++) {
				tmp *= branch[j];
			}
			ans = col == dep ? min(ans, tmp) : tmp;
			col = dep;
		}
	}
	for (int i = 0; i < edge.size(); i++) {
		int x = edge[i].first;
		int y = edge[i].second;
		memset(vis, 0, sizeof(vis));
		branch.resize(0);
		branch.resize(n + 1);
		vis[y] = 1;
		int dep = dfs(x, 1);
		dep = max(dep, dfs(y, 1));
		if (dep <= col) {
			long long tmp = 2;
			for (int j = 1; j < dep; j++) {
				tmp *= branch[j];
			}
			ans = col == dep ? min(ans, tmp) : tmp;
			col = dep;
		}
	}
	printf("%d %lld\n", col, ans);
	return 0;
}

