const int limit = 110;
vector<int> tree[limit];
int par[limit];

void dfs(int v,int p,int d,vector<int> &dist){
	par[v] = p,dist[v] = d;
	for(auto &v2:tree[v]){
		if(v2 == p) continue;
		dfs(v2,v,d+1,dist);
	}
}

int max_depth,depth[limit];

void tree_travasal(int v,int p,int d){
	chmax(max_depth,d + 1);
	chmax(depth[d],tree[d].size() - 1);

	for(auto &v2:tree[v]){
		if(v2 == p) continue;
		tree_travasal(v2,v,d+1);
	}
}

const ll inf = 1LL << 60;

ll calc(int a,int b){
	max_depth = 1;
	rep(i,limit) depth[i] = 0;

	for(auto &c:{a,b}){		
		const int ab = a^b;
		string ret = tree_travasal(c,c^ab,0);
	}

	ll ret = 2LL;

	rep(i,max_depth){
		if(ret > inf/depth[i]) 
			ret = inf;
		else
			ret *= depth[i];
	}

	return ret;
}

int main(void){
	int n;
	cin >> n;

	rep(i,n-1){
		int a,b;
		cin >> a >> b;
		a--,b--;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}

	vector<int> udist(n,0),vdist(n,0);
	dfs(0,-1,1,udist);
	const int v = max_element(begin(udist),end(udist)) - begin(udist);

	dfs(v,-1,1,vdist);
	const int u = max_element(begin(vdist),end(vdist)) - begin(vdist);

	const int ans1 = (vdist[u] + 1) / 2;
	ll ans2 = inf;

	deque<int> roots;
	{
		int cur = u;
		while(cur != -1){
			roots.push_back(cur);
			cur = par[cur];
		}

		while(roots.size() > 2){
			roots.pop_front();
			roots.pop_back();
		}
	}


	if(roots.size() == 1){
		const int root = roots[0];

		for(auto &c:tree[root]) tree_travasal(c,root,0);
		ll ret = tree[root].size();

		rep(i,max_depth){
			if(ret > inf/depth[i]) 
				ret = inf;
			else
				ret *= depth[i];
		}

		chmin<ll>(ans2, ret);
		for(auto &c:tree[root]) chmin<ll>(ans2,calc(c,root));
	}else{
		const int a = roots[0], b = roots[1];
		chmin<ll>(ans2,calc(a,b));
	}

	cout << ans1 << " " << ans2 << endl;

	return 0;
}

