#define MAXN 110
typedef long long lnt;
int n, head[MAXN], to[MAXN << 1], next[MAXN << 1], tot = 0;
inline void $(int u, int v) {
	next[tot] = head[u], to[tot] = v, head[u] = tot++;
	next[tot] = head[v], to[tot] = u, head[v] = tot++;
}
std::queue<int> Q;
int vis[MAXN];
inline int farthest(int s) {
	memset(vis, 0, sizeof(vis));
	vis[s] = 1;
	Q.push(s);
	int t = s;
	while (Q.size()) {
		int x = Q.front();
		Q.pop();
		t = x;
		for (int i = head[x]; ~i; i = next[i]) {
			if (!vis[to[i]]) {
				vis[to[i]] = 1;
				Q.push(to[i]);
			}
		}
	}
	return t;
}
int path[MAXN], plen = 0;
bool dfs(int s, int t, int fa) {
	if (s == t) return path[++plen] = s, 1;
	for (int i = head[s]; ~i; i = next[i]) {
		if (to[i] == fa) continue;
		if (dfs(to[i], t, s)) return path[++plen] = s, 1;
	}
	return 0;
}
int count[MAXN], maxdeep;
void fill(int x, int deep, int fa) {
	int sc = 0;
	for (int i = head[x]; ~i; i = next[i]) {
		if (to[i] == fa) continue;
		sc++;
		fill(to[i], deep + 1, x);
	}
	if (sc) {
		count[deep] = std::max(count[deep], sc);
		maxdeep = std::max(maxdeep, deep);
	}
}
int main() {
	memset(head, -1, sizeof(head));
	for (int i = scanf("%d", &n), u, v; i < n; i++) scanf("%d%d", &u, &v), $(u, v);
	int x = farthest(1);
	int y = farthest(x);
	dfs(x, y, 0);
	printf("%d ", (plen + 1) / 2);
	if (plen & 1) {
		int x = path[plen / 2 + 1];
		fill(x, 1, 0);
		lnt ans = 1;
		for (int i = 1; i <= maxdeep; i++) ans *= count[i];
		for (int j = head[x]; ~j; j = next[j]) {
			memset(count, 0, sizeof(count));
			maxdeep = 0;
			fill(x, 1, to[j]);
			fill(to[j], 1, x);
			lnt tmp = 2;
			for (int i = 1; i <= maxdeep; i++) tmp *= count[i];
			ans = std::min(ans, tmp);
		}
		printf("%lld\n", ans);
	} else {
		int u = path[plen / 2];
		int v = path[plen / 2 + 1];
		fill(u, 1, v);
		fill(v, 1, u);
		lnt ans = 2;
		for (int i = 1; i <= maxdeep; i++) ans *= count[i];
		printf("%lld\n", ans);
	}
	return 0;
}

