const long long mod = 1000000007;

const int mxN = 110;

vector<int> tree[mxN];
int par[mxN][20];
int h[mxN];

pair<int,int> up(pair<int,int> c) {return {c.first+1,c.second};}

pair<int,int> di(int v,int p = -1) {
	pair<int,int> res = {1,v};
	for(auto u : tree[v]) if(p != u) res = max(res,up(di(u,v)));
	return res;
}

void dfs(int v = 0,int p = -1){
	h[v] = (p==-1?0:h[p]+1);
	par[v][0] = p;
	for(int i = 1;par[v][i-1] != -1;i++)
		par[v][i] = par[par[v][i-1]][i-1];
	for(auto u : tree[v]){
		if(u != p)
			dfs(u,v);
	}
}
int lca(int u,int v){
	if(h[u] > h[v])
		swap(u,v);
	for(int i = 19;i >= 0;i--){
		if(par[v][i] != -1 && h[par[v][i]] >= h[u])v = par[v][i];
	}
	if(u == v)return u;
	for(int i = 19;i >= 0;i--){
		if(par[v][i] != par[u][i])v = par[v][i],u = par[u][i];
	}
	return par[v][0];
}

int dst(int u,int v) {
	return h[u] + h[v] - 2 * h[lca(u,v)] + 1;
}

int mn[mxN];
int get(int u,int p = -1) {
	int res = 1;
	for(auto v : tree[u]) if(v != p) res = max(res,get(v,u));
	res *= tree[u].size() - (p != -1);
	return res;
}

int N;
int solve(int d) {
	int u,v;
	u = di(0).second;
	v = di(u).second;
	memset(par,-1,sizeof par);
	dfs();
	if((d+1)/2 != (dst(u,v)+1)/2) return INT_MAX;
	d = dst(u,v);
	cerr<<u<<' '<<v<<' '<<d<<'\n';
	int a = -1,b = -1;
	for(int i = 0;i <= N && a == -1;i++) {
		for(int j = 0;j <= N && a == -1;j++) {
			int cd = d + (i == j);
			if(cd&1) continue;
			if(dst(i,v)<<1 == cd && dst(j,u)<<1 == cd) {
				a = i,b = j;
				break;
			}
		}
	}
	cerr<<a<<' '<<b<<'\n';
	return  (a == b)? get(a) : 2 * max(get(a,b),get(b,a));
}

