	{
		int L=cir[ctp>>1],R=cir[ctp+2>>1];
		vis[L]=vis[R]=1;
		static int f[maxn]; memset(f,0,sizeof(int)*(n+1));
		int len=ctp>>1;
		function<void(int u,int fa,int dis)>dfs =[&](int u,int fa,int dis) {
			int son=0;
			for(int v:ed[u])
				if(v!=fa && !vis[v])
				{
					++son;
					dfs(v,u,dis+1);	
				}
			chkmax(f[dis],son);
		};
		dfs(L,0,1); dfs(R,0,1);
		ll res=1;
		REP(i,1,len-1)res*=f[i];
		res*=2;
		num=res;
	}else
	{
		static int f[maxn]; memset(f,0,sizeof(int)*(n+1));
		int len=ctp+1>>1;
		int RT=cir[ctp+1>>1];
		function<void(int u,int fa,int dis)>dfs =[&](int u,int fa,int dis) {
			int son=0;
