int maxelement(int a[],int n) {
	int ans = 0,pos;
	rep(i, n) {
		ans = max(ans, a[i]);
		if (ans == a[i])pos = i;
	}
	return pos;
}

int solve(int X) {
	int D = d2[X] / 2;
	int pos;
	rep(i, n - 1) {
		if (d2[A[i]] > d2[B[i]])swap(A[i], B[i]);
		if (d2[A[i]] == D&&d2[B[i]] == D + 1 && d2[A[i]] + d1[B[i]] + 1 == d2[X])pos = i;
	}
	fill(d3, d3 + n, -1);
	d3[A[pos]] = 0, d3[B[pos]] = 0;
	dfs2(A[pos], d3); dfs2(B[pos], d3);
	fill(r, r + D, 0);
	rep(i, n) {
		r[d3[i]] = max(r[d3[i]], (int)G[i].size() - 1);
	}
	int ans = 2;
	rep(i, D)ans *= r[i];
	return ans;
}

