	typedef long long ll;
	const int N = 105;

	int n, dep[N], fa[N], deg[N], mxd[N];
	vector<int> E[N];

	void dfs(const int u, const int f)
	{
		dep[u] = dep[fa[u] = f] + 1;
		for (int v : E[u])
			if (v != f)
				dfs(v, u);
	}

	inline void add(const int u, const int v)
	{
		E[n].clear();
		E[n].push_back(u);
		E[n].push_back(v);
		E[u].erase(find(E[u].begin(), E[u].end(), v));
		E[v].erase(find(E[v].begin(), E[v].end(), u));
	}

	inline void restore(const int u, const int v)
	{
		E[n].clear();
		E[u].push_back(v);
		E[v].push_back(u);
	}

	ll solve(const int o)
	{
		dfs(o, 0);
		memset(mxd, 0, sizeof(int[n + 1]));
		int len = 0;
		for (int i = 1; i <= n; i++)
		{
			len = max(len, dep[i]);
			mxd[dep[i]] = max(mxd[dep[i]], deg[i] - (i != o));
		}
		ll ans = 1;
		for (int i = len - 1; i; i--)
			ans = ans * mxd[i];
		return ans;
	}

	void work()
	{
		scanf("%d", &n);
		if (n == 2)
			return void(puts("2"));
		for (int i = 1, u, v; i < n; i++)
		{
			scanf("%d%d", &u, &v);
			deg[u]++, deg[v]++;
			E[u].push_back(v);
			E[v].push_back(u);
		}
		int s = 1, t = 1;
		dfs(1, 0);
		for (int i = 2; i <= n; i++)
			if (dep[s] < dep[i])
				s = i;
		dfs(s, 0);
		for (int i = 2; i <= n; i++)
			if (dep[t] < dep[i])
				t = i;
		int o = t;
		while (dep[o] > (dep[t] + 1) / 2)
			o = fa[o];
		printf("%d ", dep[o]);
		if (dep[t] & 1)
		{
			ll ans = solve(o);
			deg[++n] = 2;
			vector<int> P;
			for (int p : E[o])
				P.push_back(p);
			for (int p : P)
			{
				add(o, p);
				ans = min(ans, solve(n));
				restore(o, p);
			}
			printf("%lld\n", ans);
		}
		else
		{
			int p = t;
			while (fa[p] != o)
				p = fa[p];
			deg[++n] = 2;
			add(o, p);
			printf("%lld\n", solve(n));
		}
	}
