const int N = 222;
int S[N], X, Y, top, ban[N], dep[N], dd[N];
int n, d[N][N], maxdep;
vector <int> G[N];

inline void dfs(int u, int fat, int to) {
	S[++top] = u;
	if (u == to) {
		top & 1 ? X = Y = S[top / 2 + 1] : X = S[top / 2], Y = S[top / 2 + 1];
		// cout << u << " " << to << "\n";
		// rep (i, top) cout<< S[i] << " \n"[i == top];
		// cout << X << " " << Y << "\n";
	}
	for (int v : G[u])
		if (v != fat) dfs(v, u, to);
	--top;
}

inline void gao(int u, int fat) {
	maxdep = max(maxdep, dep[u] = dep[fat] + 1);
	int son = 0;
	for (int v : G[u]) {
		if (v != fat && !ban[v]) gao(v, u), ++son;
	}
	dd[dep[u]] = max(dd[dep[u]], son);
}

pair <int, lo> doit(int X, int Y) {
	maxdep = 0;
	rep (i, n) dd[i] = 1, ban[i] = 0;
	ban[X] = ban[Y] = true;
	gao(X, 0); if (Y != X) gao(Y, 0);
	lo ans = 1;
	rep (i, n) ans *= dd[i];
	// cout << maxdep << " " << 2 * ans << "\n";
	return {maxdep, (X != Y ? 2 : 1) * ans};
}

