#define Foreachson(i , x) for(int i = fir[x];i;i = ne[i])

int dis[N][N] , fa[N][N];

void get(int x , int f , int no) {
  fa[no][x] = f;
  Foreachson(i , x) {
    if(to[i] != f)
      dis[no][to[i]] = dis[no][x] + 1 ,
	get(to[i] , x , no);
  }
}

