  run();
  return 0;
}

#include <stdio.h>

typedef struct List {
	struct List *next;
	int v;
} list;

int main()
{
	int i, u, w, N;
	scanf("%d", &N);
	list *adj[101], d[200];
	for (i = 1; i <= N; i++) adj[i] = NULL;
	for (i = 0; i < N; i++) {
		scanf("%d %d", &u, &w);
		d[i*2].v = w;
		d[i*2+1].v = u;
		d[i*2].next = adj[u];
		d[i*2+1].next = adj[w];
		adj[u] = &(d[i*2]);
		adj[w] = &(d[i*2+1]);
	}

	list *p;
	int dist[101] = {0, -1}, par[101] = {}, q[101] = {1}, head, tail;
	for (head = 0, tail = 1; head < tail; head++) {
		for (p = adj[q[head]]; p != NULL; p = p->next) {
			if (dist[p->v] == 0) {
				dist[p->v] = -1;
				q[tail++] = p->v;
			}
		}
	}
	q[0] = q[tail-1];
	dist[q[tail-1]] = 0;
	par[q[tail-1]] = q[tail-1];
	for (head = 0, tail = 1; head < tail; head++) {
		for (p = adj[q[head]]; p != NULL; p = p->next) {
			if (dist[p->v] == -1) {
				dist[p->v] = dist[q[head]] + 1;
				par[p->v] = q[head];
				q[tail++] = p->v;
			}
		}
	}

	int j, k, r, s, t, diam = dist[q[tail-1]], h[101];
	long long ans, tmp, deg[101] = {};
	if (diam % 2 == 0) {
		for (r = q[tail-1]; dist[r] > diam / 2; r = par[r]);
		for (i = 1; i <= N; i++) dist[i] = -1;
		q[0] = r;
		dist[r] = 0;
		for (head = 0, tail = 1; head < tail; head++) {
			for (p = adj[q[head]], tmp = 0; p != NULL; p = p->next) {
				if (dist[p->v] == -1) {
					dist[p->v] = dist[q[head]] + 1;
					q[tail++] = p->v;
					tmp++;
				}
			}
			if (tmp > deg[dist[q[head]]]) deg[dist[q[head]]] = tmp;
		}
		for (i = 0, ans = 1; i < diam / 2; i++) ans *= deg[i];

		for (k = 1; dist[q[k]] == 1; k++) h[k] = q[k];
		for (j = 1; j < k; j++) {
			for (i = 1; i <= N; i++) dist[i] = -1;
			for (i = 0; i <= diam / 2; i++) deg[i] = 0;
			q[0] = r;
			q[1] = h[j];
			dist[r] = 0;
			dist[h[j]] = 0;
			for (head = 0, tail = 2; head < tail; head++) {
				for (p = adj[q[head]], tmp = 0; p != NULL; p = p->next) {
					if (dist[p->v] == -1) {
						dist[p->v] = dist[q[head]] + 1;
						q[tail++] = p->v;
						tmp++;
					}
				}
				if (tmp > deg[dist[q[head]]]) deg[dist[q[head]]] = tmp;
			}
			for (i = 0, tmp = 2; i < diam / 2; i++) tmp *= deg[i];
			if (tmp < ans) ans = tmp;
		}
	} else {
		for (s = q[tail-1]; dist[s] > (diam + 1) / 2; s = par[s]);
		t = par[s];
		for (i = 1; i <= N; i++) dist[i] = -1;
		q[0] = s;
		q[1] = t;
		dist[s] = 0;
		dist[t] = 0;
		for (head = 0, tail = 2; head < tail; head++) {
			for (p = adj[q[head]], tmp = 0; p != NULL; p = p->next) {
				if (dist[p->v] == -1) {
					dist[p->v] = dist[q[head]] + 1;
					q[tail++] = p->v;
					tmp++;
				}
			}
			if (tmp > deg[dist[q[head]]]) deg[dist[q[head]]] = tmp;
		}
		for (i = 0, ans = 2; i < diam / 2; i++) ans *= deg[i];
	}

	printf("%d %lld\n", diam / 2 + 1, ans);
	fflush(stdout);
	return 0;
}

import sun.plugin.cache.OldCacheEntry
import java.util.*

fun getDistanceArray(graph: Array<IntArray>, s: Int): IntArray {
  val n = graph.size
  val distanceArray = IntArray(n, { -1 })
  fun dfs(v: Int, d: Int) {
    distanceArray[v] = d
    for (u in graph[v]) {
      if (distanceArray[u] >= 0) continue
      dfs(u, d + 1)
    }
  }
  dfs(s, 0)
  return distanceArray
}

fun getDistanceArray(graph: Array<IntArray>, cs: List<Int>): IntArray {
  val n = graph.size
  val distanceArray = IntArray(n, { -1 })
  data class BFSState(val v: Int, val d: Int)
  val queue = ArrayDeque<BFSState>()
  for (c in cs) {
    queue.offerLast(BFSState(c, 0))
    distanceArray[c] = 0
  }
  while (queue.isNotEmpty()) {
    val s = queue.pollFirst()
    for (u in graph[s.v]) {
      if (distanceArray[u] == -1) {
        queue.offerLast(BFSState(u, s.d + 1))
        distanceArray[u] = s.d + 1
      }
    }
  }
  return distanceArray
}

fun main(args: Array<String>) {
  val n = readLine()!!.toInt()
  val mutableGraph = Array(n, { mutableListOf<Int>() })
  repeat(n - 1) {
    val (v1Raw, v2Raw) = readLine()!!.split(" ").map { it.toInt() }
    val v1 = v1Raw - 1
    val v2 = v2Raw - 1
    mutableGraph[v1].add(v2)
    mutableGraph[v2].add(v1)
  }
  val graph = mutableGraph.map { it.toIntArray() }.toTypedArray()
  val x0 = 0
  val x0DistanceArray = getDistanceArray(graph, x0)
  val x1 = x0DistanceArray.indexOf(x0DistanceArray.max()!!)
  val x1DistanceArray = getDistanceArray(graph, x1)
  val x2 = x1DistanceArray.indexOf(x1DistanceArray.max()!!)
  val x2DistanceArray = getDistanceArray(graph, x2)

  val diameter = x2DistanceArray.max()!!
  val radius = diameter / 2
  // println("diameter: $diameter")
  // println("radius: $radius")
  val centroids = (0 until n).filter {
    if (diameter % 2 == 1) {
      (x1DistanceArray[it] == radius && x2DistanceArray[it] == radius + 1) ||
          (x1DistanceArray[it] == radius + 1 && x2DistanceArray[it] == radius)
    } else {
      x1DistanceArray[it] == radius && x2DistanceArray[it] == radius
    }
  }
  // println("centroids: $centroids")

  fun leafCountForCentroids(inputCentroids: List<Int>): Long {
    val distanceArray = getDistanceArray(graph, inputCentroids)
    val maxChildren = IntArray(radius)
    for (v in 0 until n) {
      val d = distanceArray[v]
      if (d == radius) continue
      val childrenCount = graph[v].count { distanceArray[it] == d + 1 }
      maxChildren[d] = Math.max(maxChildren[d], childrenCount)
    }

    val leafCount = inputCentroids.size.toLong() *
        maxChildren.fold(1L, { l: Long, r: Int -> l * r.toLong() })
    return leafCount
  }

  val colorCount = radius + 1
  if (centroids.size == 2) {
    val leafCount = leafCountForCentroids(centroids)
    println("$colorCount $leafCount")
  } else if (centroids.size == 1) {
    val c = centroids[0]
    var minLeafCount = leafCountForCentroids(centroids)
    for (v in graph[c]) {
      minLeafCount = Math.min(minLeafCount, leafCountForCentroids(listOf(c, v)))
    }
    println("$colorCount $minLeafCount")
  } else {
    throw RuntimeException()
  }


}

