/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 29);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            DIsomorphismFreak solver = new DIsomorphismFreak();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class DIsomorphismFreak {
        int[] seq;
        int depthest;
        int minDepth;
        long minLeaf;

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            Node[] nodes = new Node[n];
            for (int i = 0; i < n; i++) {
                nodes[i] = new Node();
                nodes[i].id = i;
            }
            int[][] edges = new int[n - 1][2];
            for (int i = 0; i < n - 1; i++) {
                edges[i][0] = in.readInt() - 1;
                edges[i][1] = in.readInt() - 1;
                Node a = nodes[edges[i][0]];
                Node b = nodes[edges[i][1]];
                a.adj.add(b);
                b.adj.add(a);
            }
            seq = new int[n];


            minDepth = n;
            minLeaf = Long.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                reset();
                dfs(nodes[i], null, 0);
                update(1);
            }

            for (int[] e : edges) {
                Node a = nodes[e[0]];
                Node b = nodes[e[1]];
                reset();
                dfs(a, b, 0);
                dfs(b, a, 0);
                update(2);
            }

            out.println(minDepth + 1).println(minLeaf);
        }

        public void update(int mul) {
            int depth = depthest;
            long leaf = mul;
            for (int j = 0; j <= depth; j++) {
                leaf *= seq[j];
            }

            if (depth < minDepth) {
                minDepth = depth;
                minLeaf = Long.MAX_VALUE;
            }
            if (depth == minDepth) {
                minLeaf = Math.min(minLeaf, leaf);
            }
        }

        public void reset() {
            Arrays.fill(seq, 1);
            depthest = 0;
        }

        public void dfs(Node root, Node p, int d) {
            depthest = Math.max(depthest, d);
            int degree = root.adj.size() - (p == null ? 0 : 1);
            seq[d] = Math.max(seq[d], degree);
            for (Node node : root.adj) {
                if (node == p) {
                    continue;
                }
                dfs(node, root, d + 1);
            }
        }

    }

    static class Node {
        List<Node> adj = new ArrayList<>();
        int id;

        public String toString() {
            return "" + (id + 1);
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput append(CharSequence csq) {
            cache.append(csq);
            return this;
        }

        public FastOutput append(CharSequence csq, int start, int end) {
            cache.append(csq, start, end);
            return this;
        }

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput append(char c) {
            cache.append(c);
            return this;
        }

        public FastOutput append(int c) {
            cache.append(c);
            return this;
        }

        public FastOutput append(long c) {
            cache.append(c);
            return this;
        }

        public FastOutput println(int c) {
            return append(c).println();
        }

        public FastOutput println(long c) {
            return append(c).println();
        }

        public FastOutput println() {
            cache.append(System.lineSeparator());
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String toString() {
            return cache.toString();
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.Objects;
import java.util.OptionalInt;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        var g = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new IntArrayList();
        }
        for (int i = 0; i < n - 1; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
        }
        int x = farthestPath(g, 0)[0];
        int[] path = farthestPath(g, x);
        int y = path[0];
        int d = path.length;
        out.write(d / 2 + 1).writeSpace();
        if (d % 2 == 1) {
            long leaves = 2;
            int r1 = path[(d - 1) / 2];
            int r2 = d == 1 ? x : path[(d + 1) / 2];
            int[] dep = new int[n];
            int[] max = new int[(d + 1) / 2];
            Arrays.fill(dep, -1);
            dep[r1] = dep[r2] = 0;
            IntDeque dq = new IntDeque();
            dq.addLast(r1);
            dq.addLast(r2);
            while (dq.size() > 0) {
                int u = dq.removeFirst();
                max[dep[u]] = Math.max(max[dep[u]], g[u].size() - 1);
                for (var it = g[u].iterator(); it.hasNext();) {
                    int v = it.nextInt();
                    if (dep[v] < 0) {
                        dq.addLast(v);
                        dep[v] = dep[u] + 1;
                    }
                }
            }
            for (int i = 0; i < (d - 1) / 2; i++) {
                leaves *= max[i];
            }
            out.writeln(leaves);
        } else {
            long[] leaves = new long[d / 2 + 1];
            int r = path[d / 2];
            int[] dep = new int[n];
            Arrays.fill(dep, -1);
            dep[r] = 0;
            int c = g[r].size();
            leaves[0] = c;
            IntArrayList[] max = new IntArrayList[c];
            IntDeque dq = new IntDeque();
            for (int i = 0; i < c; i++) {
                max[i] = new IntArrayList();
                int ch = g[r].get(i);
                dep[ch] = 1;
                dq.addLast(ch);
                while (dq.size() > 0) {
                    int u = dq.removeFirst();
                    int chs = g[u].size() - 1;
                    if (max[i].size() > dep[u] - 1) {
                        max[i].set(dep[u] - 1, Math.max(max[i].get(dep[u] - 1), chs));
                    } else {
                        max[i].add(chs);
                    }
                    leaves[dep[u]] = Math.max(leaves[dep[u]], chs);
                    for (var it = g[u].iterator(); it.hasNext();) {
                        int v = it.nextInt();
                        if (dep[v] < 0) {
                            dq.addLast(v);
                            dep[v] = dep[u] + 1;
                        }
                    }
                }
            }
            // out.writeln();
            leaves[d / 2] = 1;
            for (int i = d / 2; i > 0; i--) {
                leaves[i - 1] *= leaves[i];
                // out.writeln("l[" + (i - 1) + "] = " + leaves[i - 1]);
            }
            long min = leaves[0];
            IntOrderedMultiSet[] sets = new IntOrderedMultiSet[d / 2 + 1];
            for (int i = 0; i <= d / 2; i++) {
                sets[i] = new IntOrderedMultiSet();
            }
            // out.writeln();
            for (int i = 0; i < c; i++) {
                // out.writeln("ch: " + g[r].get(i));
                for (int j = 0; j < max[i].size(); j++) {
                    sets[j + 1].insertKey(max[i].get(j));
                    // out.writeln("max[" + g[r].get(i) + "][" + (j + 1) + "] = " + max[i].get(j));
                }
            }
            // out.writeln();
            // out.writeln("min = " + min);
            for (int i = 0; i < c; i++) {
                long lvs = 2 * Math.max(c - 1, g[g[r].get(i)].size() - 1);
                int k = max[i].size();
                lvs *= leaves[k];
                // out.writeln(lvs);
                for (int j = 0; j < Math.min(k - 1, d / 2 - 1); j++) {
                    int siz = sets[j + 1].size();
                    int l = sets[j + 1].kthElement(siz - 1);
                    int lij = j + 1 < k ? max[i].get(j + 1) : 0;
                    // out.writeln("lij = " + lij);
                    if (l == max[i].get(j)) {
                        lvs *= Math.max(sets[j + 1].kthElement(siz - 2), lij);
                    } else {
                        lvs *= Math.max(l, lij);
                    }
                }
                // out.writeln("leaves[" + g[r].get(i) + "] = " + lvs);
                min = Math.min(min, lvs);
            }
            out.writeln(min);
        }
    }

    public static int[] farthestPath(IntArrayList[] g, int from) {
        int n = g.length;
        int[] d = new int[n];
        int[] p = new int[n];
        Arrays.fill(d, -1);
        d[from] = 0;
        p[from] = -1;
        int dst = from;
        IntDeque dq = new IntDeque();
        dq.addLast(from);
        while (dq.size() > 0) {
            int u = dq.removeFirst();
            for (var it = g[u].iterator(); it.hasNext();) {
                int v = it.nextInt();
                if (d[v] < 0) {
                    dq.addLast(v);
                    if (d[dst] < (d[v] = d[u] + 1)) dst = v;
                    p[v] = u;
                }
            }
        }
        int len = d[dst];
        int[] path = new int[len];
        for (int v = dst, idx = 0; v != from; v = p[v]) {
            path[idx++] = v;
        }
        return path;
    }
}


