public class Main {
    InputStream is;

    int __t__ = 1;
    int __f__ = 0;
    int __FILE_DEBUG_FLAG__ = __f__;
    String __DEBUG_FILE_NAME__ = "src/D4";

    FastScanner in;
    PrintWriter out;

    public void solve() {
        int N = in.nextInt();
        int[] a = new int[N - 1];
        int[] b = new int[N - 1];
        for (int i = 0; i < N - 1; i++) {
            a[i] = in.nextInt() - 1;
            b[i] = in.nextInt() - 1;
        }
        ArrayList<Integer>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i < N - 1; i++) {
            g[a[i]].add(b[i]);
            g[b[i]].add(a[i]);
        }
        int[] depth = new int[N];
        dfs(0, -1, 0, depth, g);
        int l1 = 0;
        for (int u = 0; u < N; u++) {
            if (depth[u] > depth[l1]) l1 = u;
        }
        dfs(l1, -1, 0, depth, g);
        int l2 = 0;
        for (int u = 0; u < N; u++) {
            if (depth[u] > depth[l2]) l2 = u;
        }

        int[] depthL1 = new int[N];
        int[] depthL2 = new int[N];
        dfs(l1, -1, 0, depthL1, g);
        dfs(l2, -1, 0, depthL2, g);

        int diam = depthL1[l2];
        if (diam % 2 != 0) {
            int c1 = -1, c2 = -1;
            for (int u = 0; u < N; u++) {
                if ((diam / 2 == depthL1[u] && (diam + 1) / 2 == depthL2[u]) ||
                        (diam / 2 == depthL2[u] && (diam + 1) / 2 == depthL1[u])) {
                    if (c1 == -1)
                        c1 = u;
                    else if (c2 == -1)
                        c2 = u;
                    else
                        throw new RuntimeException();
                }
            }
            if (c1 == -1 || c2 == -1) {
                throw new RuntimeException();
            }
            System.out.println(((diam + 1) / 2) + " " + calc(c1, c2, g));
        } else {
            int c1 = -1;
            for (int u = 0; u < N; u++) {
                if (depthL1[u] == depthL2[u] && diam / 2 == depthL1[u]) {
                    if (c1 == -1)
                        c1 = u;
                    else
                        throw new RuntimeException();
                }
            }
            if (c1 == -1)
                throw new RuntimeException();

            long res = calc(c1, c1, g);
            for (int c2 : g[c1]) {
                res = Math.min(res, calc(c1, c2, g));
            }
            System.out.println((diam / 2 + 1) + " " + res);
        }
    }

    private long calc(int c1, int c2, ArrayList<Integer>[] g) {
        int N = g.length;
        int[] depthC1 = new int[N];
        int[] depthC2 = new int[N];
        dfs(c1, -1, 0, depthC1, g);
        dfs(c2, -1, 0, depthC2, g);
        int[] deg = new int[N];
        Arrays.fill(deg, 1);
        if (c1 == c2) {
            deg[0] = Math.max(1, g[c1].size());
        } else {
            deg[0] = Math.max(1, Math.max(g[c1].size(), g[c2].size()) - 1);
        }
        for (int u = 0; u < N; u++) {
            if (c1 == u || c2 == u) continue;
            int d = Math.min(depthC1[u], depthC2[u]);
            deg[d] = Math.max(deg[d], g[u].size());
        }
        long res = deg[0];
        for (int u = 1; u < N; u++) {
            res *= Math.max(deg[u] - 1, 1);
        }
        if (c1 != c2) res *= 2;
        return res;
    }

    void dfs(int u, int pre, int d, int[] depth, ArrayList<Integer>[] g) {
        depth[u] = d;
        for (int v : g[u]) {
            if (v == pre) continue;
            dfs(v, u, d + 1, depth, g);
        }
    }

    public void run() {
        if (__FILE_DEBUG_FLAG__ == __t__) {
            try {
                is = new FileInputStream(__DEBUG_FILE_NAME__);
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
            System.out.println("FILE_INPUT!");
        } else {
            is = System.in;
        }
        in = new FastScanner(is);
        out = new PrintWriter(System.out);

        solve();
    }

