import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class Main {

	static class IntList {

		int data[] = new int[3];
		int size = 0;

		boolean isEmpty() {
			return size == 0;
		}

		int size() {
			return size;
		}

		int get(int index) {
			if (index < 0 || index >= size) {
				throw new IndexOutOfBoundsException();
			}
			return data[index];
		}

		void clear() {
			size = 0;
		}

		void set(int index, int value) {
			if (index < 0 || index >= size) {
				throw new IndexOutOfBoundsException();
			}
			data[index] = value;
		}

		void expand() {
			if (size >= data.length) {
				data = copyOf(data, (data.length << 1) + 1);
			}
		}

		void insert(int index, int value) {
			if (index < 0 || index > size) {
				throw new IndexOutOfBoundsException();
			}
			expand();
			arraycopy(data, index, data, index + 1, size++ - index);
			data[index] = value;
		}

		int delete(int index) {
			if (index < 0 || index >= size) {
				throw new IndexOutOfBoundsException();
			}
			int value = data[index];
			arraycopy(data, index + 1, data, index, --size - index);
			return value;
		}

		void push(int value) {
			expand();
			data[size++] = value;
		}

		int pop() {
			if (size == 0) {
				throw new NoSuchElementException();
			}
			return data[--size];
		}

		void unshift(int value) {
			expand();
			arraycopy(data, 0, data, 1, size++);
			data[0] = value;
		}

		int shift() {
			if (size == 0) {
				throw new NoSuchElementException();
			}
			int value = data[0];
			arraycopy(data, 1, data, 0, --size);
			return value;
		}
	}

	static IntList edges[];

	static void solve() throws Exception {
		int n = scanInt();
		edges = new IntList[n];
		for (int i = 0; i < n; i++) {
			edges[i] = new IntList();
		}
		for (int i = 0; i < n - 1; i++) {
			int a = scanInt() - 1;
			int b = scanInt() - 1;
			edges[a].push(b);
			edges[b].push(a);
		}
		up = new int[n];
		resLongest = resLongestEnd = 0;
		dfs(0, -1);
		for (int i = 0; i < resLongest / 2; i++) {
			resLongestEnd = up[resLongestEnd];
		}
		degrees = new int[n];
		long ans;
		if ((resLongest & 1) != 0) {
			dfs2(resLongestEnd, up[resLongestEnd], 0);
			dfs2(up[resLongestEnd], resLongestEnd, 0);
			ans = 2;
		} else {
			dfs2(resLongestEnd, -1, 0);
			degrees[0] = edges[resLongestEnd].size() + 1;
			ans = 1;
		}
		for (int i = 0; i < n && degrees[i] > 1; i++) {
			ans *= degrees[i] - 1;
		}
		if ((resLongest & 1) == 0) {
			for (int i = 0; i < edges[resLongestEnd].size(); i++) {
				int e = edges[resLongestEnd].get(i);
				fill(degrees, 0);
				long cans = 2;
				dfs2(resLongestEnd, e, 0);
				dfs2(e, resLongestEnd, 0);
				for (int j = 0; j < n && degrees[j] > 1; j++) {
					cans *= degrees[j] - 1;
				}
				ans = min(ans, cans);
			}
		}
		out.print((resLongest / 2 + 1) + " " + ans);
	}

	static int up[];
	static int resDepth, resEnd, resLongest, resLongestEnd;
	static void dfs(int cur, int prev) {
		up[cur] = prev;
		int d1 = 0, e1 = cur, d2 = 0;
		for (int i = 0; i < edges[cur].size(); i++) {
			int next = edges[cur].get(i);
			if (next == prev) {
				continue;
			}
			dfs(next, cur);
			if (resDepth + 1 > d1) {
				d2 = d1;
				d1 = resDepth + 1;
				e1 = resEnd;
			} else if (resDepth + 1 > d2) {
				d2 = resDepth + 1;
			}
		}
		if (resLongest < d1 + d2) {
			resLongest = d1 + d2;
			resLongestEnd = e1;
		}
		resDepth = d1;
		resEnd = e1;
	}

	static int degrees[];
	static void dfs2(int cur, int prev, int depth) {
		degrees[depth] = max(degrees[depth], edges[cur].size());
		for (int i = 0; i < edges[cur].size(); i++) {
			int next = edges[cur].get(i);
			if (next == prev) {
				continue;
			}
			dfs2(next, cur, depth + 1);
		}
	}

	static int scanInt() throws IOException {
		return parseInt(scanString());
	}

	static long scanLong() throws IOException {
		return parseLong(scanString());
	}

	static String scanString() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.io.*;
import java.util.*;

public class Main {
    FastScanner in;
    PrintWriter out;

    ArrayList<Integer>[] g;

    void go(int v, int p, int curH) {
        int cntCh = 0;
        for (int to : g[v]) {
            if (to == p) {
                continue;
            }
            cntCh++;
            go(to, v, curH + 1);
        }
        cntCh = Math.max(cntCh, 1);
        maxCh[curH] = Math.max(maxCh[curH], cntCh);
    }

    int[] maxCh;

    void updateAns(long start) {
        double curCost = start;
        int curMaxH = 0;
        long curCostLong = start;
        for (int h = 0; h <= maxCh.length - 1; h++) {
            if (maxCh[h] != 0) {
                curCost *= maxCh[h];
                curMaxH = h;
                curCostLong *= maxCh[h];
            }
        }
        if (curCost > Long.MAX_VALUE) {
            return;
        }
        if (curMaxH < ansH || (curCostLong < ans && ansH == curMaxH)) {
            ansH = curMaxH;
            ans = curCostLong;
        }
    }

    long ans;
    int ansH;

    void solve() {
        int n = in.nextInt();
        g = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i + 1< n; i++) {
            int fr = in.nextInt() - 1;
            int to = in.nextInt() -1 ;
            g[fr].add(to);
            g[to].add(fr);
        }
        ans = Long.MAX_VALUE;
        ansH = Integer.MAX_VALUE;
        maxCh = new int[n + 1];
        for (int v = 0;v < n; v++) {
            Arrays.fill(maxCh, 0);
            go(v, v, 0);
            updateAns(1);
        }
        for (int v =0 ;v < n; v++) {
            for (int to : g[v]) {
                if (to > v) {
                    Arrays.fill(maxCh, 0);
                    go(v, to, 0);
                    go(to, v, 0);
                    updateAns(2);
                }
            }
        }
        out.println((ansH + 1)  + " " + ans);
    }

    void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new Main().runIO();
    }
}

import java.io.*;
import java.util.*;

class Solver {
  private static final int INF = 1 << 20;

  final int n;
  final int[][] abs;
  List<List<Integer>> graph;

  Solver(int n, int[][] abs) {
    this.n = n;
    this.abs = abs;
  }

  private long calculateNumLeaf(List<Integer> centers) {
    Deque<Integer> queue = new ArrayDeque<>();
    Set<Integer> visited = new HashSet<>();
    queue.addAll(centers);
    visited.addAll(centers);
    long numLeaf = centers.size();
    while (!queue.isEmpty()) {
      int maxChildrenSize = 1;
      Deque<Integer> nextQueue = new ArrayDeque<>();
      for (int index : queue) {
        int childrenSize = 0;
        for (int childIndex : graph.get(index)) {
          if (visited.contains(childIndex)) {
            continue;
          }
          visited.add(childIndex);
          nextQueue.add(childIndex);
          childrenSize++;
        }
        maxChildrenSize = Math.max(maxChildrenSize, childrenSize);
      }
      queue = nextQueue;
      numLeaf *= maxChildrenSize;
    }
    return numLeaf;
  }

  public String solve() {
    graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }
    for (int[] ab : abs) {
      int a = ab[0];
      int b = ab[1];
      graph.get(a).add(b);
      graph.get(b).add(a);
    }

    int[][] matrix = new int[n + 1][n + 1];
    for (int i = 0; i <= n; i++) {
      for (int j = 0; j <= n; j++) {
        matrix[i][j] = INF;
      }
      matrix[i][i] = 0;
    }
    for (int[] ab : abs) {
      int a = ab[0];
      int b = ab[1];
      matrix[a][b] = 1;
      matrix[b][a] = 1;
    }
    for (int k = 0; k <= n; k++) {
      for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
          matrix[i][j] = Math.min(matrix[i][j], matrix[i][k] + matrix[k][j]);
        }
      }
    }
    List<Integer> centers = null;
    int minMaxDistance = INF;
    for (int i = 1; i <= n; i++) {
      int maxDistance = 0;
      for (int j = 1; j <= n; j++) {
        maxDistance = Math.max(maxDistance, matrix[i][j]);
      }
      if (minMaxDistance > maxDistance) {
        minMaxDistance = maxDistance;
        centers = new ArrayList<>();
        centers.add(i);
      } else if (minMaxDistance == maxDistance) {
        centers.add(i);
      }
    }
    int depth;
    long numLeaf;
    if (centers.size() == 2) {
      depth = minMaxDistance;
      numLeaf = calculateNumLeaf(centers);
    } else {
      int center = centers.get(0);
      depth = minMaxDistance + 1;
      numLeaf = calculateNumLeaf(Arrays.asList(center));
      for (int next : graph.get(centers.get(0))) {
        numLeaf = Math.min(numLeaf, calculateNumLeaf(Arrays.asList(center, next)));
      }
    }

    return String.format("%d %d", depth, numLeaf);
  }
}

public class Main {
  private static void execute(ContestReader reader, ContestWriter out) {
    int n = reader.nextInt();
    int[][] abs = reader.nextInt(n - 1, 2);
    out.println(new Solver(n, abs).solve());
