public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        var g = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new IntArrayList();
        }
        for (int i = 0; i < n - 1; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
        }
        int x = farthestPath(g, 0)[0];
        int[] path = farthestPath(g, x);
        int y = path[0];
        int d = path.length;
        out.write(d / 2 + 1).writeSpace();
        if (d % 2 == 1) {
            long leaves = 2;
            int r1 = path[(d - 1) / 2];
            int r2 = path[(d + 1) / 2];
            int[] dep = new int[n];
            int[] max = new int[(d + 1) / 2];
            Arrays.fill(dep, -1);
            dep[r1] = dep[r2] = 0;
            IntDeque dq = new IntDeque();
            dq.addLast(r1);
            dq.addLast(r2);
            while (dq.size() > 0) {
                int u = dq.removeFirst();
                max[dep[u]] = Math.max(max[dep[u]], g[u].size() - 1);
                for (var it = g[u].iterator(); it.hasNext();) {
                    int v = it.nextInt();
                    if (dep[v] < 0) {
                        dq.addLast(v);
                        dep[v] = dep[u] + 1;
                    }
                }
            }
            for (int i = 0; i < (d - 1) / 2; i++) {
                leaves *= max[i];
            }
            out.writeln(leaves);
        } else {
            long[] leaves = new long[d / 2 + 1];
            int r = path[d / 2];
            int[] dep = new int[n];
            Arrays.fill(dep, -1);
            dep[r] = 0;
            int c = g[r].size();
            leaves[0] = c;
            IntArrayList[] max = new IntArrayList[c];
            IntDeque dq = new IntDeque();
            for (int i = 0; i < c; i++) {
                max[i] = new IntArrayList();
                int ch = g[r].get(i);
                dep[ch] = 1;
                dq.addLast(ch);
                while (dq.size() > 0) {
                    int u = dq.removeFirst();
                    int chs = g[u].size() - 1;
                    if (max[i].size() > dep[u] - 1) {
                        max[i].set(dep[u] - 1, Math.max(max[i].get(dep[u] - 1), chs));
                    } else {
                        max[i].add(chs);
                    }
                    leaves[dep[u]] = Math.max(leaves[dep[u]], chs);
                    for (var it = g[u].iterator(); it.hasNext();) {
                        int v = it.nextInt();
                        if (dep[v] < 0) {
                            dq.addLast(v);
                            dep[v] = dep[u] + 1;
                        }
                    }
                }
            }
            // out.writeln();
            leaves[d / 2] = 1;
            for (int i = d / 2; i > 0; i--) {
                leaves[i - 1] *= leaves[i];
                // out.writeln("l[" + (i - 1) + "] = " + leaves[i - 1]);
            }
            long min = leaves[0];
            IntOrderedMultiSet[] sets = new IntOrderedMultiSet[d / 2 + 1];
            for (int i = 0; i <= d / 2; i++) {
                sets[i] = new IntOrderedMultiSet();
            }
            // out.writeln();
            for (int i = 0; i < c; i++) {
                // out.writeln("ch: " + g[r].get(i));
                for (int j = 0; j < max[i].size(); j++) {
                    sets[j + 1].insertKey(max[i].get(j));
                    // out.writeln("max[" + g[r].get(i) + "][" + (j + 1) + "] = " + max[i].get(j));
                }
            }
            // out.writeln();
            // out.writeln("min = " + min);
            for (int i = 0; i < c; i++) {
                long lvs = 2 * Math.max(c - 1, g[g[r].get(i)].size() - 1);
                int k = max[i].size();
                lvs *= leaves[k];
                // out.writeln(lvs);
                for (int j = 0; j < Math.min(k - 1, d / 2 - 1); j++) {
                    int siz = sets[j + 1].size();
                    int l = sets[j + 1].kthElement(siz - 1);
                    int lij = j + 1 < k ? max[i].get(j + 1) : 0;
                    // out.writeln("lij = " + lij);
                    if (l == max[i].get(j)) {
                        lvs *= Math.max(sets[j + 1].kthElement(siz - 2), lij);
                    } else {
                        lvs *= Math.max(l, lij);
                    }
                }
                // out.writeln("leaves[" + g[r].get(i) + "] = " + lvs);
                min = Math.min(min, lvs);
            }
            out.writeln(min);
        }
    }

    public static int[] farthestPath(IntArrayList[] g, int from) {
        int n = g.length;
        int[] d = new int[n];
        int[] p = new int[n];
        Arrays.fill(d, -1);
        d[from] = 0;
        p[from] = -1;
        int dst = from;
        IntDeque dq = new IntDeque();
        dq.addLast(from);
        while (dq.size() > 0) {
            int u = dq.removeFirst();
            for (var it = g[u].iterator(); it.hasNext();) {
                int v = it.nextInt();
                if (d[v] < 0) {
                    dq.addLast(v);
                    if (d[dst] < (d[v] = d[u] + 1)) dst = v;
                    p[v] = u;
                }
            }
        }
        int len = d[dst];
        int[] path = new int[len];
        for (int v = dst, idx = 0; v != from; v = p[v]) {
            path[idx++] = v;
        }
        return path;
    }
}


