class IntOrderedMultiSet extends IntRandomizedBinarySearchTree<Object> {
    Node root;
    int kthElement(Node t, int k) {
        int c = size(t.l);
        if (k < c) return kthElement(t.l, k);
        if (k == c) return t.key;
        return kthElement(t.r, k - c - 1);
    }
    public int kthElement(int k) {
        if (k < 0 || k >= size()) throw new IndexOutOfBoundsException();
        return kthElement(root, k);
    }
    Node insertKey(Node t, int key) {
        return insert(t, leqCount(t, key), key, null);
    }
    public void insertKey(int key) {
        root = insertKey(root, key);
    }
    Node eraseKey(Node t, int key) {
        if (count(t, key) == 0) return t;
        return super.erase(t, leqCount(t, key) - 1);
    }
    public void eraseKey(int key) {
        root = eraseKey(root, key);
    }
    int count(Node t, int key) {
        return leqCount(t, key) - ltCount(t, key);
    }
    public int count(int key) {
        return count(root, key);
    }
    int leqCount(Node t, int key) {
        if (t == null) return 0;
        if (key < t.key) return leqCount(t.l, key);
        return leqCount(t.r, key) + size(t.l) + 1;
    }
    public int leqCount(int key) {
        return leqCount(root, key);
    }
    int ltCount(Node t, int key) {
        if (t == null) return 0;
        if (key <= t.key) return ltCount(t.l, key);
        return ltCount(t.r, key) + size(t.l) + 1;
    }
    public int ltCount(int key) {
        return ltCount(root, key);
    }
    public int size() {
        return size(root);
    }
    public void clear() {
        this.root = null;
    }
}


/**
 * @author https://atcoder.jp/users/suisen
 * 
 * Implementation of deque for primitive int type, using Ring Buffer.
 */
final class IntDeque implements Iterable<Integer> {
    static final int DEFAULT_CAPACITY = 1 << 6;
    int[] buf;
    int len = 1;
    int mask;
    int head = 0;
    int tail = 0;
    public IntDeque(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException(
                String.format("Capacity %d is negative.", capacity)
            );
        }
        while (this.len < capacity) {
            this.len <<= 1;
        }
        this.mask = this.len - 1;
        this.buf = new int[len];
    }
    public IntDeque() {
        this(DEFAULT_CAPACITY);
    }
    public int getLast() {
        if (size() == 0) throw new NoSuchElementException();
        return buf[(tail - 1) & mask];
    }
    public int getFirst() {
        if (size() == 0) throw new NoSuchElementException();
        return buf[head];
    }
    public int get(int index) {
        if (index < 0 || index >= size()) {
            throw new IndexOutOfBoundsException(
                String.format("Index %d out of bounds for length %d.", index, size())
            );
        }
        return buf[(head + index) & mask];
    }
    public void addLast(int v) {
        if (size() == len) grow();
        buf[tail++ & mask] = v;
    }
    public void addFirst(int v) {
        if (size() == len) grow();
        buf[--head & mask] = v;
    }
    public int removeLast() {
        if (size() == 0) throw new NoSuchElementException();
        return buf[--tail & mask];
    }
    public int removeFirst() {
        if (size() == 0) throw new NoSuchElementException();
        return buf[head++ & mask];
    }
    public OptionalInt pollLast() {
        if (size() == 0) return OptionalInt.empty();
        return OptionalInt.of(removeLast());
    }
    public OptionalInt pollFirst() {
        if (size() == 0) return OptionalInt.empty();
        return OptionalInt.of(removeFirst());
    }
    public int size() {
        return tail - head;
    }
    public boolean isEmpty() {
        return size() == 0;
    }
    public void clear() {
        head = tail = 0;
    }
    public int[] toArray() {
        int[] ret = new int[size()];
        PrimitiveIterator.OfInt it = iterator();
        Arrays.setAll(ret, i -> it.nextInt());
        return ret;
    }
    private void grow() {
        int[] newBuf = new int[len << 1];
        head &= mask;
        tail &= mask;
        int len1 = len - head;
        int len2 = head;
        System.arraycopy(buf, head, newBuf, 0, len1);
        System.arraycopy(buf, 0, newBuf, len1, len2);
        this.head = 0;
        this.tail = this.len;
        this.len <<= 1;
        this.mask = this.len - 1;
        this.buf = newBuf;
    }
    public PrimitiveIterator.OfInt iterator() {
        return new PrimitiveIterator.OfInt(){
            int it = head;
            public boolean hasNext() {return it < tail;}
            public int nextInt() {return buf[it++ & mask];}
        };
    }
    public PrimitiveIterator.OfInt descendingIterator() {
        return new PrimitiveIterator.OfInt(){
            int it = tail;
            public boolean hasNext() {return it > head;}
            public int nextInt() {return buf[--it & mask];}
        };
    }

    /***************************** DEBUG *********************************/

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        PrimitiveIterator.OfInt it = iterator();
        while (it.hasNext()) {
            sb.append(it.next().toString());
            if (it.hasNext()) sb.append(',');
        }
        sb.append(']');
        return sb.toString();
    }
}

import java.util.Arrays;

public class Main {
  private static void solve() {
    int n = ni();
    int[] from = new int[n - 1];
    int[] to = new int[n - 1];

    for (int i = 0; i < n - 1; i ++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
    }
    int[][] g = packU(n, from, to);
    int[] center = center(g);

    long[] ret;
    if (center.length == 1) {
      int v = center[0];
      ret = f1(v, g);
      for (int next : g[v]) {
        long[] now = f2(v, next, g);
        if (now[0] < ret[0] || now[0] == ret[0] && now[1] < ret[1]) {
          ret = now;
        }
      }
    } else {
      ret = f2(center[0], center[1], g);
    }
    System.out.println(ret[0] + " " + ret[1]);
  }

  private static long[] f2(int root1, int root2, int[][] g) {
    int n = g.length;
    int[] deg1 = new int[n + 1];
    int[] deg2 = new int[n + 1];
    Arrays.fill(deg1, -1);
    Arrays.fill(deg2, -1);
    dfs(root1, root2, g, deg1, 0);
    dfs(root2, root1, g, deg2, 0);

    int[] deg = new int[n + 1];
    int maxDepth = 0;
    for (int i = 0; i < deg.length; i ++) {
      deg[i] = Math.max(deg1[i], deg2[i]);
      if (deg[i] < 0) {
        maxDepth = i;
        break;
      }
    }

    long leaf = 2;
    for (int i = 0; i < maxDepth - 1; i ++) {
      leaf *= deg[i];
    }
    return new long[] {maxDepth, leaf};
  }

  private static void dfs(int now, int pre, int[][] g, int[] deg, int depth) {

    for (int next : g[now]) {
      if (next == pre) continue;

      dfs(next, now, g, deg, depth + 1);
    }

    deg[depth] = Math.max(deg[depth], g[now].length - 1);
  }

  private static long[] f1(int root, int[][] g) {
    int[][] p3 = parents(g, root);
    int[] depth = p3[2];
    int maxDepth = Arrays.stream(depth).max().getAsInt() + 1;
    int[] deg = new int[maxDepth];
    int n = g.length;

    for (int i = 0; i < n; i ++) {
      int x = i == root ? 0 : -1;
      deg[depth[i]] = Math.max(deg[depth[i]], g[i].length + x);
    }

    long leaf = 1;
    for (int i = 0; i < maxDepth - 1; i ++) {
      leaf *= deg[i];
    }
    return new long[] {maxDepth, leaf};
  }

  public static int[][] parents(int[][] g, int root)
  {
      int n = g.length;
      int[] par = new int[n];
      Arrays.fill(par, -1);

      int[] depth = new int[n];
      depth[0] = 0;

      int[] q = new int[n];
      q[0] = root;
      for(int p = 0, r = 1;p < r;p++) {
          int cur = q[p];
          for(int nex : g[cur]){
              if(par[cur] != nex){
                  q[r++] = nex;
                  par[nex] = cur;
                  depth[nex] = depth[cur] + 1;
              }
          }
      }
      return new int[][] {par, q, depth};
  }

  public static int[][] packU(int n, int[] from, int[] to){ return packU(n, from, to, from.length); }
  public static int[][] packU(int n, int[] from, int[] to, int sup)
  {
      int[][] g = new int[n][];
      int[] p = new int[n];
      for(int i = 0;i < sup;i++)p[from[i]]++;
      for(int i = 0;i < sup;i++)p[to[i]]++;
      for(int i = 0;i < n;i++)g[i] = new int[p[i]];
      for(int i = 0;i < sup;i++){
          g[from[i]][--p[from[i]]] = to[i];
          g[to[i]][--p[to[i]]] = from[i];
      }
      return g;
  }

  public static int[] center(int[][] g)
  {
      int n = g.length;
      int start = 0;
      int[] d1 = dist(g, start);
      int maxd1 = -1;
      int argmaxd1 = -1;
      for(int i = 0;i < n;i++){
          if(d1[i] > maxd1){
              maxd1 = d1[i];
              argmaxd1 = i;
          }
      }

      int[] d2 = dist(g, argmaxd1);
      int maxd2 = -1;
      int argmaxd2 = -1;
      for(int i = 0;i < n;i++){
          if(d2[i] > maxd2){
              maxd2 = d2[i];
              argmaxd2 = i;
          }
      }

      if(maxd2 % 2 == 0){
          int h = maxd2/2;
          int j = argmaxd2;
          outer:
          for(int i = maxd2;i > h;i--){
              for(int e : g[j]){
                  if(d2[e] == i-1){
                      j = e;
                      continue outer;
                  }
              }
              throw new RuntimeException();
          }
          return new int[]{j};
      }else{
          int h = maxd2/2;
          int j = argmaxd2;
          int[] cs = new int[2];
          int p = 0;
          outer:
          for(int i = maxd2;i >= h;i--){
              if(i <= h+1)cs[p++] = j;
              if(i > h){
                  for(int e : g[j]){
                      if(d2[e] == i-1){
                          j = e;
                          continue outer;
                      }
                  }
                  throw new RuntimeException();
              }
          }
          return cs;
      }
  }

  public static int[] dist(int[][] g, int start)
  {
      int n = g.length;
      int[] d = new int[n];
      Arrays.fill(d, n+3);
      int[] q = new int[n];
      int p = 0;
      q[p++] = start;
      d[start] = 0;
      for(int r = 0;r < p;r++){
          int cur = q[r];
          for(int e : g[cur]){
              if(d[e] > d[cur] + 1){
                  d[e] = d[cur] + 1;
                  q[p++] = e;
              }
          }
      }
      return d;
  }

