public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        var g = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new IntArrayList();
        }
        for (int i = 0; i < n - 1; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
        }
        int x = farthestPath(g, 0)[0];
        int[] path = farthestPath(g, x);
        int y = path[0];
        int d = path.length;
        out.write(d / 2 + 1).writeSpace();
        if (d % 2 == 1) {
            long leaves = 2;
            int r1 = path[(d - 1) / 2];
            int r2 = d == 1 ? x : path[(d + 1) / 2];
            int[] dep = new int[n];
            int[] max = new int[(d + 1) / 2];
            Arrays.fill(dep, -1);
            dep[r1] = dep[r2] = 0;
            IntDeque dq = new IntDeque();
            dq.addLast(r1);
            dq.addLast(r2);
            while (dq.size() > 0) {
                int u = dq.removeFirst();
                max[dep[u]] = Math.max(max[dep[u]], g[u].size() - 1);
                for (var it = g[u].iterator(); it.hasNext();) {
                    int v = it.nextInt();
                    if (dep[v] < 0) {
                        dq.addLast(v);
                        dep[v] = dep[u] + 1;
                    }
                }
            }
            for (int i = 0; i < (d - 1) / 2; i++) {
                leaves *= max[i];
            }
            out.writeln(leaves);
        } else {
            int r = path[d / 2];
            int[] dep = new int[n];
            Arrays.fill(dep, -1);
            dep[r] = 0;
            int c = g[r].size();
            int[][] maxch = new int[c][d / 2 + 1];
            IntDeque dq = new IntDeque();
            for (int i = 0; i < c; i++) {
                int ch = g[r].get(i);
                dep[ch] = 1;
                dq.addLast(ch);
                while (dq.size() > 0) {
                    int u = dq.removeFirst();
                    maxch[i][dep[u]] = Math.max(maxch[i][dep[u]], g[u].size() - 1);
                    for (var it = g[u].iterator(); it.hasNext();) {
                        int v = it.nextInt();
                        if (dep[v] < 0) {
                            dq.addLast(v);
                            dep[v] = dep[u] + 1;
                        }
                    }
                }
            }
            long min = c;
            for (int i = 1; i < d / 2; i++) {
                int max = 0;
                for (int j = 0; j < c; j++) {
                    max = Math.max(max, maxch[j][i]);
                }
                min *= max;
            }
            for (int i = 0; i < c; i++) {
                long leaves = 2 * Math.max(c - 1, g[g[r].get(i)].size() - 1);
                for (int j = 1; j < d / 2; j++) {
                    int max = 1;
                    for (int k = 0; k < c; k++) {
                        if (k == i) {
                            max = Math.max(max, maxch[k][j + 1]);
                        } else {
                            max = Math.max(max, maxch[k][j]);
                        }
                    }
                    leaves *= max;
                }
                min = Math.min(min, leaves);
            }
            out.writeln(min);
        }
    }

    public static int[] farthestPath(IntArrayList[] g, int from) {
        int n = g.length;
        int[] d = new int[n];
        int[] p = new int[n];
        Arrays.fill(d, -1);
        d[from] = 0;
        p[from] = -1;
        int dst = from;
        IntDeque dq = new IntDeque();
        dq.addLast(from);
        while (dq.size() > 0) {
            int u = dq.removeFirst();
            for (var it = g[u].iterator(); it.hasNext();) {
                int v = it.nextInt();
                if (d[v] < 0) {
                    dq.addLast(v);
                    if (d[dst] < (d[v] = d[u] + 1)) dst = v;
                    p[v] = u;
                }
            }
        }
        int len = d[dst];
        int[] path = new int[len];
        for (int v = dst, idx = 0; v != from; v = p[v]) {
            path[idx++] = v;
        }
        return path;
    }
}


