  static class TaskD {

    ArrayList<Integer>[] g;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      //int n = 99;
      g = new ArrayList[n + 2];
      for (int i = 0; i < g.length; ++i) {
        g[i] = new ArrayList<>();
      }
      for (int i = 0; i < n - 1; ++i) {
        int x = in.nextInt() - 1;
        int y = in.nextInt() - 1;
        // int x, y;
        // if (i < 48) {
        //     x = i;
        //     y = i + 1;
        // } else {
        //     x = i - 48;
        //     y = i + 1;
        // }
        g[x].add(y);
        g[y].add(x);
      }
      ComparablePair<Long, Long> ans = solveSimple(n);
      for (int z = 0; z < n; ++z) {
        if (g[z].size() == 1) {
          g[n].add(z);
          g[z].add(n);
          {
            ComparablePair<Long, Long> cur = solveSimple(n + 1);
            if (cur.compareTo(ans) < 0) {
              ans = cur;
            }
          }
          for (int t = 0; t < n + 1; ++t) {
            if (g[t].size() == 1) {
              g[n + 1].add(t);
              g[t].add(n + 1);
              ComparablePair<Long, Long> cur = solveSimple(n + 2);
              if (cur.compareTo(ans) < 0) {
                ans = cur;
              }
              g[n + 1].clear();
              g[t].remove(g[t].size() - 1);
            }
          }
          g[n].clear();
          g[z].remove(g[z].size() - 1);

        }
      }
      out.printLine(ans.first, ans.second);
    }

    public ComparablePair<Long, Long> solveSimple(int n) {
      ArrayList<Integer>[] layers = new ArrayList[n + 2];
      for (int i = 0; i < layers.length; ++i) {
        layers[i] = new ArrayList<>();
      }
      for (int i = 0; i < n; ++i) {
        layers[dfs(i, -1)].add(i);
      }
      long[] d = new long[layers.length];
      int res = 0;
      int rs = 0;
      for (int i = layers.length - 2; i >= 0; --i) {
        if (layers[i].isEmpty()) {
          d[i] = d[i + 1];
          continue;
        }
        ++res;
        int deg = 0;
        for (int x : layers[i]) {
          deg = Math.max(deg, g[x].size());
        }
        --deg;
        rs = layers[i].size();
        if (d[i + 1] == 0) {
          Assert.assertTrue(deg == 0);
          d[i] = 1;
          continue;
        }
        if ((i == 0 || layers[i - 1].isEmpty()) && layers[i].size() == 1) {
          ++deg;
        }
        long cur = d[i + 1] * (long) deg;
        d[i] = cur;
      }
      return new ComparablePair<Long, Long>((long) res, d[0] * (long) rs);
    }

    private int dfs(int x, int p) {
      int res = 0;
      for (int y : g[x]) {
        if (y != p) {
          res = Math.max(res, dfs(y, x) + 1);
        }
      }
      return res;
    }

  }

