  static class InputReader {

    private InputStream stream;
    private byte[] buffer = new byte[10000];
    private int cur;
    private int count;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public static boolean isSpace(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int read() {
      if (count == -1) {
        throw new InputMismatchException();
      }
      try {
        if (cur >= count) {
          cur = 0;
          count = stream.read(buffer);
          if (count <= 0) {
            return -1;
          }
        }
      } catch (IOException e) {
        throw new InputMismatchException();
      }
      return buffer[cur++];
    }

    public int readSkipSpace() {
      int c;
      do {
        c = read();
      } while (isSpace(c));
      return c;
    }

    public int nextInt() {
      int sgn = 1;
      int c = readSkipSpace();
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9') {
          throw new InputMismatchException();
        }
        res = res * 10 + c - '0';
        c = read();
      } while (!isSpace(c));
      res *= sgn;
      return res;
    }

  }

  static class ComparablePair<P extends Comparable, Q extends Comparable> extends
      Pair<P, Q> implements Comparable<Pair<P, Q>> {

    public ComparablePair() {
    }

    public ComparablePair(P first, Q second) {
      super(first, second);
    }

    public int compareTo(Pair<P, Q> other) {
      int valP = first.compareTo(other.first);
      if (valP != 0) {
        return valP;
      }
      return second.compareTo(other.second);
    }

  }
}

import java.util.*;

public class Main {

  public static void main(String args[]) {
    (new Main()).solve();
  }

  void solve() {

    Scanner cin = new Scanner(System.in);

    int N = cin.nextInt();
    int rank[] = new int[N];
    int mat[][] = new int[N][N];

    for( int i = 0; i < N - 1; ++i ) {
    	int L = cin.nextInt() - 1;
    	int R = cin.nextInt() - 1;
    	++rank[L];
    	++rank[R];
    	mat[L][R] = mat[R][L] = 1;
    }

    for( int k = 0; k < N; ++k ) {
    	for( int i = 0; i < N; ++ i ) {
    		for( int j = 0; j < N; ++j ) {
    			if( mat[i][k] > 0 && mat[k][j] > 0 ) {
    				if( mat[i][j] == 0 ) {
    					mat[i][j] = mat[i][k] + mat[k][j];
    				}
    				else {
    					mat[i][j] = Math.min(mat[i][j], mat[i][k] + mat[k][j]);
    				}
    			}
    		}
    	}
    }

    int S = -1;
    int T = -1;
    int maxD = 0;
    for( int i = 0; i < N; ++i ) {
    	if( rank[i] != 1 ) { continue; }
    	for( int j = i + 1; j < N; ++j ) {
    		if( rank[j] != 1 ) { continue; }
    		if( maxD < mat[i][j] ) {
    			maxD = mat[i][j];
    			S = i;
    			T = j;
    		}
    	}
    }

    // even length == odd nodes (path);
    if( maxD % 2 == 0 ) {
    	int C = -1;
    	int D = maxD / 2;
    	for( int i = 0; i < N; ++i ) {
    		if( mat[S][i] == D && mat[T][i] == D ) {
    			if( C != -1 ) {
    				throw new RuntimeException("double center...");
    			}
    			C = i;
    		}
    	}
    	int tmp[] = new int[N];
    	Arrays.fill(tmp, 1);
    	score(C, -1, mat, N, 0, tmp);
    	long ans = 1;
    	for( int v : tmp ) {
    		ans *= v;
    	}
    	// add many edges to make tree like below;
    	for( int i = 0; i < N; ++i ) {
    		if( mat[C][i] == 1 ) {
    			int tmp2[] = new int[N];
    			Arrays.fill(tmp2, 1);
    			score(C, i, mat, N, 0, tmp2);
    			score(i, C, mat, N, 0, tmp2);
    			long ans2 = 2;
    			for( int v : tmp2 ) {
    				ans2 *= v;
    			}
    			ans = Math.min(ans, ans2);
    		}
    	}

    	System.out.println((maxD / 2 + 1) + " " + ans);

    }

    // odd length == even nodes (path);
    else {
    	int C1 = -1;
    	int C2 = -1;
    	int D = maxD / 2;
    	for( int i = 0; i < N; ++i ) {
    		if( mat[S][i] == D && mat[T][i] == D + 1 ) {
    			if( C1 != -1 ) {
    				throw new RuntimeException("double center...");
    			}
    			C1 = i;
    		}
    		if( mat[T][i] == D && mat[S][i] == D + 1 ) {
    			if( C2 != -1 ) {
    				throw new RuntimeException("double center...");
    			}
    			C2 = i;
    		}
    	}
		int tmp[] = new int[N];
		Arrays.fill(tmp, 1);
		score(C1, C2, mat, N, 0, tmp);
		score(C2, C1, mat, N, 0, tmp);
		long ans = 2;
		for( int v : tmp ) {
			ans *= v;
		}

    	System.out.println((maxD / 2 + 1) + " " + ans);

    }


    // ans 1;
    // maxD / 2 + 1;

    // ans 2 is ?;

    cin.close();

  }

  void score(int cur, int parent, int mat[][], int N, int level, int maxRank[]) {
	  int rank = 0;
	  for( int i = 0; i < N; ++i ) {
		  if( i == cur || i == parent ) { continue; }
		  if( mat[cur][i] == 1 ) {
			  ++rank;
			  score(i, cur, mat, N, level + 1, maxRank);
		  }
	  }
	  maxRank[level] = Math.max(maxRank[level], rank);
  }

}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[] from = new int[n - 1];
		int[] to = new int[n - 1];
		for (int i = 0; i < n - 1; i++) {
			from[i] = ni() - 1;
			to[i] = ni() - 1;
		}
		int[][] g = packU(n, from, to);

		int min = 99999999;
		long val = 0;
		outer:
		for(int root = 0;root < n;root++){
			int[][] pars = parents3(g, root);
			int[] par = pars[0], ord = pars[1], dep = pars[2];

			int maxdep = 0;
			for(int i = 0;i < n;i++){
				maxdep = Math.max(maxdep, dep[i]);
			}

			int[] ch = new int[n];
			Arrays.fill(ch, 1);
			for(int i = 0;i < n;i++){
				ch[dep[i]] = Math.max(ch[dep[i]], i == root ? g[i].length : g[i].length-1);
			}
			long lret = 1;
			for(int i = 0;i < n;i++){
				double dlret = (double)lret * ch[i];
				if(dlret >= Long.MAX_VALUE)continue outer;
				lret = lret * ch[i];
			}
			if(maxdep < min || maxdep == min  && lret < val){
				val = lret;
				min = maxdep;
			}
		}

		outer:
		for(int root1 = 0;root1 < n;root1++){
			int[][] pars = parents3(g, root1);
			int[] par = pars[0], ord = pars[1], dep = pars[2];
			for(int root2 : g[root1]){
				if(root1 > root2)continue;
				int maxdep = 0;
				for(int i = 0;i < n;i++){
					int d = dep[i];
					for(int x = i;x != root1;x = par[x]){
						if(x == root2){
							d--;
						}
					}
					maxdep = Math.max(maxdep, d);
				}

				int[] ch = new int[n];
				Arrays.fill(ch, 1);
				for(int i = 0;i < n;i++){
					int d = dep[i];
					for(int x = i;x != root1;x = par[x]){
						if(x == root2){
							d--;
						}
					}
					ch[d] = Math.max(ch[d], g[i].length-1);
				}
				long lret = 2;
				for(int i = 0;i < n;i++){
					double dlret = (double)lret * ch[i];
					if(dlret >= Long.MAX_VALUE)continue outer;
					lret = lret * ch[i];
				}
				if(maxdep < min || maxdep == min && lret < val){
					val = lret;
					min = maxdep;
				}
			}
		}
		out.println((min+1) + " " + val);
	}

	public static int[][] parents3(int[][] g, int root) {
		int n = g.length;
		int[] par = new int[n];
		Arrays.fill(par, -1);

		int[] depth = new int[n];
		depth[0] = 0;

		int[] q = new int[n];
		q[0] = root;
		for (int p = 0, r = 1; p < r; p++) {
			int cur = q[p];
			for (int nex : g[cur]) {
				if (par[cur] != nex) {
					q[r++] = nex;
					par[nex] = cur;
					depth[nex] = depth[cur] + 1;
				}
			}
		}
		return new int[][] { par, q, depth };
	}

	static int[][] packU(int n, int[] from, int[] to) {
		int[][] g = new int[n][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]];
		for (int i = 0; i < from.length; i++) {
			g[from[i]][--p[from[i]]] = to[i];
			g[to[i]][--p[to[i]]] = from[i];
		}
		return g;
	}


	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

