    public void solve() {
        int N = in.nextInt();
        int[] a = new int[N - 1];
        int[] b = new int[N - 1];
        for (int i = 0; i < N - 1; i++) {
            a[i] = in.nextInt() - 1;
            b[i] = in.nextInt() - 1;
        }
        ArrayList<Integer>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i < N - 1; i++) {
            g[a[i]].add(b[i]);
            g[b[i]].add(a[i]);
        }
        int[] depth = new int[N];
        dfs(0, -1, 0, depth, g);
