class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        List<int>[] G = re.g(N,N-1);
        Tree T = new Tree(G);
        T.Center();
        int center1 = T.center1;
        int center2 = T.center2;
        sb.Append((T.diamater+2)/2);
        sb.Append(" ");
        if(center2 != -1){
            sb.Append(ans(G,center1,center2,N)+"\n");    
        }
        else{
            long min = ans(G,center1,N);
            for(int i=0;i<G[center1].Count;i++){
                min = Math.Min(min,ans(G,center1,G[center1][i],N));
            }
            sb.Append(min+"\n");
        }
    }
    long ans(List<int>[] G,int center1,int center2,int N){
        int[] dist1 = new int[N];
        int[] dist2 = new int[N];
        dfs(center1,dist1,-1,G,0);
        dfs(center2,dist2,-1,G,0);
        int[] dist = new int[N];
        for(int i=0;i<N;i++){
            dist[i] = Math.Min(dist1[i],dist2[i]);
        }
        int[] max = new int[N];
        for(int i=0;i<N;i++){
            max[dist[i]] = Math.Max(max[dist[i]],G[i].Count-1);
        }
        long answer = 1;
        for(int i=0;i<N;i++){
            if(max[i] != 0){
                answer *= max[i];
            }
        }
        return answer*2;
    }
    long ans(List<int>[] G,int center,int N){
        int[] dist = new int[N];
        dfs(center,dist,-1,G,0);
        int[] max = new int[N];
        for(int i=0;i<N;i++){
            max[dist[i]] = Math.Max(max[dist[i]],G[i].Count-1);
        }
        long answer = 1;
        max[0]++;
        for(int i=0;i<N;i++){
            if(max[i] != 0){
                answer *= max[i];
            }
        }
        return answer;
    }
    void dfs(int v,int[] dist,int f,List<int>[] G,int d){
        for(int i=0;i<G[v].Count;i++){
            int t = G[v][i];
            if(t != f){
                dfs(t,dist,v,G,d+1);
            }
        }
        dist[v] = d;
    }
}
