                    colors = vertices.Max(v => v.Depth) + 1;
                    lists = 2 * (Math.Max(vertices[i].Edges.Count, t.Edges.Count) - 1);
                    for (int j = 1; j < colors; j++)
                    {
                        lists *= Vertex.DepthMax[j];
                    }
                    if (lists == 0)
                    {
                        lists = 2;
                    }
                    if (ansColors > colors || ansColors == colors && ansLists > lists)
                    {
                        ansColors = colors;
                        ansLists = lists;
                    }
                }
            }

