    internal class Solution
    {
        public int N, M;
        public Graph G;

        public void Run()
        {
            N = Input.ReadInt();
            G = new Graph(N);
            for (int i = 0; i < N - 1; i++)
            {
                var line = Input.ReadIntArray();
                int a = line[0] - 1;
                int b = line[1] - 1;
                G[a].Edges.Add(new Edge(a, b, 0));
                G[b].Edges.Add(new Edge(b, a, 0));
            }


            // それぞれ、一番遠い葉への距離
            var D = new int[N];
            for (int i = 0; i < N; i++)
            {
                D[i] = Dist(i);
            }

            // 色は最大距離に同じ
            int colors = D.Max() - D.Min() + 1;

            // 中心の候補（１か２種類）
            var cand = new List<int>();
            for (int i = 0; i < N; i++)
            {
                if(D[i] == D.Min()) cand.Add(i);
            }

            if (cand.Count == 2)
            {
                long leaves = Math.Max(LeavesEq(cand[0], cand[1]), LeavesEq(cand[1], cand[0])) * 2;
                Console.WriteLine("{0} {1}", colors, leaves);
            }
            else
            {
                // N >= 2

                // 自分から対称に広げる
                long leaves = LeavesEq(cand[0], -1);

                // 自分ともう一つから対称に広げる
                foreach (var e in G[cand[0]].Edges)
                {
                    long l = Math.Max(LeavesEq(cand[0], e.To), LeavesEq(e.To, cand[0])) * 2;
                    leaves = Math.Min(leaves, l);
                }
                Console.WriteLine("{0} {1}", colors, leaves);
            }

        }

        // 一番遠い葉への距離
        public int Dist(int x)
        {
            return DfsDist(x, -1);
        }

        public int DfsDist(int x, int fr)
        {
            int ret = 0;
            foreach (var e in G[x].Edges)
            {
                if(fr != e.To) ret = Math.Max(DfsDist(e.To, e.From) + 1, ret);
            }
            return ret;
        }

        // 片方をカットした場合、対称になるための葉の数（最低でも１）
        public long LeavesEq(int x, int cut)
        {
            return DfsLeavesEq(x, cut);
        }

        public long DfsLeavesEq(int x, int fr)
        {
            var lst = new List<long>();
            foreach (var e in G[x].Edges)
            {
                if (fr != e.To) lst.Add(DfsLeavesEq(e.To, e.From));
            }

            if (lst.Count == 0) return 1;
            return lst.Max() * lst.Count;
        }
    }

