class Program
{
    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
    const int M = 1000000007;
    // const int M = 998244353;
    const long LM = (long)1e18;
    const double eps = 1e-11;
    static readonly int[] dd = { 0, 1, 0, -1, 0 };
    const string dstring = "RDLU";
    static void Main()
    {
        int n = sc.Int;
        var edge = new List<int>[n];
        for (int i = 0; i < n; i++)
        {
            edge[i] = new List<int>();
        }
        var edges = new P[n - 1];
        for (int i = 0; i < n - 1; i++)
        {
            int a, b;
            sc.Multi(out a, out b);
            --a;
            --b;
            edge[a].Add(b);
            edge[b].Add(a);
            edges[i] = new P(a, b);
        }
        int mincol = n;
        long minleaf = LM;
        for (int i = 0; i < n; i++)
        {
            var q = new Queue<int>();
            var dist = new int[n];
            var maxdeg = new int[n];
            for (int j = 0; j < n; j++)
            {
                dist[j] = M;
            }
            maxdeg[0] = edge[i].Count;
            int maxdis = 0;
            dist[i] = 0;
            q.Enqueue(i);
            while (q.Any())
            {
                int p = q.Dequeue();
                foreach (var item in edge[p])
                {
                    if (dist[item] > dist[p] + 1) {
                        dist[item] = dist[p] + 1;
                        maxdeg[dist[item]] = Math.Max(maxdeg[dist[item]], edge[item].Count - 1);
                        maxdis = Math.Max(maxdis, dist[item] + 1);
                        q.Enqueue(item);
                    }
                }
            }
            long leaf = 1;
            for (int j = 0; j < n; j++)
            {
                if (maxdeg[j] > 0) {
                    if (leaf * (double)maxdeg[j] > LM) {
                        leaf = LM;
                    }
                    else
                        leaf *= maxdeg[j];
                }
            }
            if (mincol > maxdis) {
                mincol = maxdis;
                minleaf = leaf;
            }
            else if (mincol == maxdis && minleaf > leaf) {
                minleaf = leaf;
            }
        }
        foreach (var es in edges)
        {
            var q = new Queue<int>();
            var dist = new int[n];
            var maxdeg = new int[n];
            for (int j = 0; j < n; j++)
            {
                dist[j] = M;
            }
            int i1 = es.v1, i2 = es.v2;
            maxdeg[0] = Math.Max(edge[i1].Count, edge[i2].Count) - 1;
            int maxdis = 0;
            dist[i1] = 0;
            dist[i2] = 0;
            q.Enqueue(i1);
            q.Enqueue(i2);
            while (q.Any())
            {
                int p = q.Dequeue();
                foreach (var item in edge[p])
                {
                    if (dist[item] > dist[p] + 1) {
                        dist[item] = dist[p] + 1;
                        maxdeg[dist[item]] = Math.Max(maxdeg[dist[item]], edge[item].Count - 1);
                        maxdis = Math.Max(maxdis, dist[item] + 1);
                        q.Enqueue(item);
                    }
                }
            }
            long leaf = 2;
            for (int j = 0; j < n; j++)
            {
                if (maxdeg[j] > 0) {
                    if (leaf * (double)maxdeg[j] > LM) {
                        leaf = LM;
                    }
                    else
                        leaf *= maxdeg[j];
                }
            }
            if (mincol > maxdis) {
                mincol = maxdis;
                minleaf = leaf;
            }
            else if (mincol == maxdis && minleaf > leaf) {
                minleaf = leaf;
            }
        }

        Prt(mincol, minleaf);
        sw.Flush();
    }

