        private static void SolveCase()
        {
            int n = ReadInt();

            var vertices = new Vertex[n];
            for (int i = 0; i < n; i++)
            {
                vertices[i] = new Vertex(i);
            }

            for (int i = 0; i < n - 1; i++)
            {
                int x = ReadInt() - 1;
                int y = ReadInt() - 1;
                vertices[x].Edges.Add(vertices[y]);
                vertices[y].Edges.Add(vertices[x]);
            }

            int ansColors = int.MaxValue;
            long ansLists = int.MaxValue;

            for (int i = 0; i < n; i++)
            {
                // vertex
                for (int j = 0; j < n; j++)
                {
                    vertices[j].Visited = false;
                }

                vertices[i].Dfs(null);

                int colors = vertices[i].Height;
                long lists = vertices[i].MaxLists * vertices[i].Edges.Count;
                if (lists == 0)
                {
                    lists = 1;
                }
                if (ansColors > colors || ansColors == colors && ansLists > lists)
                {
                    ansColors = colors;
                    ansLists = lists;
                }

                // edge
                foreach (Vertex t in vertices[i].Edges)
                {
                    for (int j = 0; j < n; j++)
                    {
                        vertices[j].Visited = false;
                    }

                    vertices[i].Dfs(t);
                    t.Dfs(vertices[i]);

                    colors = Math.Max(vertices[i].Height, t.Height);
                    lists = Math.Max(vertices[i].MaxLists, t.MaxLists) * 2 * (Math.Max(vertices[i].Edges.Count, t.Edges.Count) - 1);
                    if (lists == 0)
                    {
                        lists = 2;
                    }
                    if (ansColors > colors || ansColors == colors && ansLists > lists)
                    {
                        ansColors = colors;
                        ansLists = lists;
                    }
                }
            }

            Writer.WriteLine($"{ansColors} {ansLists}");
        }

        public class Vertex
        {
            public Vertex(int id)
            {
                Id = id;
                Edges = new List<Vertex>();
            }

            public int Id;

            public List<Vertex> Edges;

            public int Height;

            public long ListsCount;

            public long MaxLists;

            public bool Visited;

            public void Dfs(Vertex p)
            {
                Visited = true;
                Height = 1;
                MaxLists = 0;
                foreach (Vertex vertex in Edges)
                {
                    if (!vertex.Visited && vertex != p)
                    {
                        vertex.Dfs(p);
                        Height = Math.Max(Height, vertex.Height + 1);
                        MaxLists = Math.Max(MaxLists, vertex.ListsCount);
                    }
                }
                ListsCount = Edges.Count > 1 ? (Edges.Count - 1) * MaxLists : 1;
            }
        }

