        {
            int ret = 0;
            foreach (var e in G[x].Edges)
            {
                if(fr != e.To) ret = Math.Max(DfsDist(e.To, e.From) + 1, ret);
            }
            return ret;
        }

    }

    internal class CountLeaves
    {
        public Graph G;
        public long[] Degrees;

        public static long Run(Graph G, int c)
        {
            var CL = new CountLeaves();
            CL.G = G;
            CL.Degrees = new long[100];
            CL.Count(c, -1, 0);

            long ret = 1;
            for (int i = 0; i < CL.Degrees.Length; i++)
            {
                if (CL.Degrees[i] != 0) ret *= CL.Degrees[i];
            }
            return ret;
        }

        public static long Run(Graph G, int c1, int c2)
        {
            var CL = new CountLeaves();
            CL.G = G;
            CL.Degrees = new long[100];
            CL.Count(c1, c2, 0);
            CL.Count(c2, c1, 0);

            long ret = 1;
            for (int i = 0; i < CL.Degrees.Length; i++)
            {
                if (CL.Degrees[i] != 0) ret *= CL.Degrees[i];
            }

            ret *= 2;
            return ret;
        }

        public void Count(int x, int cut, int d)
        {
            var edges = G[x].Edges.Where(e => e.To != cut).ToArray();
            Degrees[d] = Math.Max(Degrees[d], edges.Length);

            foreach (var e in edges)
            {
                Count(e.To, e.From, d+1);
            }
        }
