		public void Solve() {
			var n = ri;
			var g = Enumerate(n, x => new int[n]);
			for (int i = 0; i < n; i++)
				for (int j = i + 1; j < n; j++) g[i][j] = g[j][i] = 100000;
			var G = Enumerate(n, x => new List<int>());
			var pair = new List<int[]>();
			for (int i = 0; i < n; i++) pair.Add(new int[] { i, i });

			for (int i = 0; i < n - 1; i++) {
				var u = ri - 1;
				var v = ri - 1;
				g[u][v] = g[v][u] = 1;
				G[u].Add(v);
				G[v].Add(u);
				pair.Add(new int[] { u, v });
			}
			for (int k = 0; k < n; k++) for (int i = 0; i < n; i++) for (int j = 0; j < n; j++)
						g[i][j] = Min(g[i][j], g[i][k] + g[k][j]);

			var val = Enumerate(n + 5, x => INF);

			foreach (var p in pair) {
				var c = p[0];
				var d = p[1];
				var pos = Enumerate(n + 5, x => new List<int>());
				for (int i = 0; i < n; i++) {
					var max = Max(g[c][i], g[d][i]);
					pos[max].Add(i);
				}
				var used = new bool[n + 5];
				var sz = new long[n + 5];
				int dep = 0;
				for (int i = n + 3; i >= 0; i--) {
					if (pos[i].Count == 0) continue;
					sz[i] = 1;
					dep = Max(dep, i);
					foreach (var v in pos[i]) {
						var cnt = 0;
						foreach (var t in G[v])
							if (used[t]) cnt++;
						sz[i] = Max(sz[i], cnt * sz[i + 1]);
					}
					foreach (var v in pos[i]) used[v] = true;
				}
				if (c == d) val[dep + 1] = Min(val[dep + 1], sz[0]);
				else val[dep] = Min(val[dep], 2 * sz[1]);
			}
			for (int i = 0; i <= n; i++)
				if (val[i] != INF) { Console.WriteLine($"{i} {val[i]}"); return; }

		}
		const long INF = 1L << 60;
		static int[] dx = { -1, 0, 1, 0 };
		static int[] dy = { 0, 1, 0, -1 };
		int ri { get { return sc.Integer(); } }
		long rl { get { return sc.Long(); } }
		double rd { get { return sc.Double(); } }
		string rs { get { return sc.Scan(); } }
		public IO.StreamScanner sc = new IO.StreamScanner(Console.OpenStandardInput());

		static T[] Enumerate<T>(int n, Func<int, T> f) {
			var a = new T[n];
			for (int i = 0; i < a.Length; ++i) a[i] = f(i);
			return a;
		}
		static public void Swap<T>(ref T a, ref T b) { var tmp = a; a = b; b = tmp; }
	}
