  max := A[0]
  for _, a := range A {
    if max < a { max = a }
  }
  return max
}
func MinInt(A ...int) int {
  min := A[0]
  for _, a := range A {
    if a < min { min = a }
  }
  return min
}
func SumInt(A ...int) int {
  sum := 0
  for _, a := range A {
    sum += a
  }
  return sum
}
func AbsInt(x int) int {
  if x < 0 { x = -x }
  return x
}

func Solve() {
  var N int
  NextInt(&N)
  T := make([][]int, N)
  G := make([][]int, N)
  for i := range G {
    T[i] = make([]int, 0)
    G[i] = make([]int, N)
    for j := range G[i] {
      G[i][j] = N
    }
    G[i][i] = 0
  }
  var a, b int
  for i := 1; i < N; i++ {
    NextInt(&a, &b)
    a, b = a - 1, b - 1
    T[a] = append(T[a], b)
    T[b] = append(T[b], a)
    G[a][b] = 1
    G[b][a] = 1
  }
  for k := range G {
    for i := range G {
      for j := range G {
        G[i][j] = MinInt(G[i][k] + G[k][j], G[i][j])
      }
    }
  }
  R := N
  for _, g := range G {
    R = MinInt(MaxInt(g...), R)
  }
  Calc := func(u, v int) int {
    D := make([]int, R + 1)
    for w, t := range T {
      r := MinInt(G[u][w], G[v][w])
      D[r] = MaxInt(len(t), D[r])
    }
    cnt := 2 * MaxInt(D[0] - 1, 1)
    if u == v { cnt = D[0] }
    for _, d := range D[1:] {
      if d < 2 { break }
      cnt *= d - 1
    }
    return cnt
  }
  C := make([]int, 0)
  for i := range G {
    if R == MaxInt(G[i]...) { C = append(C, i) }
  }
  if len(C) < 2 { C = append(C, C...) }
  ans := Calc(C[0], C[1])
  if C[0] == C[1] {
    R++
    for _, v := range T[C[0]] {
      ans = MinInt(Calc(C[0], v), ans)
    }
  }
  WriteIntVec([]int{R, ans})
}

