  for _,v := range g[u] {
    if v == p { continue }
    d = max(d,dfs(v,u)+1)
  }
  return d
}
func center() (int,[]int) {
  m := n+1
  x := make(map[int][]int)
  for i:=0;i<n;i++ {
    d := dfs(i,-1)
    if _,ok := x[d];!ok { x[d] = []int{} }
    x[d] = append(x[d],i)
    m = min(m,d)
  }
  return m,x[m]
}
func sub(c []int) int64 {
  var cat func(int,int,int)
  a := make([]int,n)
  b := make([]int,n)
  cat = func(u,p,d int) {
    a[u] = d
    k := 0
    for _,v := range g[u] {
      if v == p { continue }
      k++
      cat(v,u,d+1)
    }
    b[u] = k
  }
  if len(c) == 1 {
    cat(c[0],-1,0)
  } else {
    cat(c[0],c[1],0)
    cat(c[1],c[0],0)
  }
  m := map[int]int{}
  for i:=0;i<n;i++ { m[a[i]] = max(m[a[i]],b[i]) }
  ret := int64(len(c))
  for _,v := range m {
    if v < 2 { continue }
    ret *= int64(v)
  }
  return ret
}

type Input struct { reader *bufio.Reader }
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInt() int {
