        g[a] ~= b; g[b] ~= a;        
    }
    int dfs(int p, int b, int ndps) {
        int ans = ndps;
        foreach (d; g[p]) {
            if (d == b) continue;
            ans = max(ans, dfs(d, p, ndps+1));
        }
