fn solve(graph: &Vec<Vec<usize>>, c1: usize, c2: usize) -> (usize, usize) {
    let n = graph.len();
    let dist = bfs(&graph, c1, c2);
    let mut max_dist = *dist.iter().max().unwrap();
    let mut max_children = vec![0; max_dist + 1];
    for i in 0..n {
        let dist = dist[i];
        max_children[dist] = max(max_children[dist], graph[i].len() - 1);
    }
    if c1 == c2 {
        max_children[0] = graph[c1].len();
    }
    let mut cur = if c1 == c2 { 1 } else { 2 };
    for i in 0..max_dist {
        cur *= max_children[i];
    }
    (max_dist + 1, cur)
}

fn get_centers(graph: &Vec<Vec<usize>>) -> (usize, usize) {
    let n = graph.len();
    let dist0 = bfs(graph, 0, 0);

    let root1 = dist0
        .into_iter()
        .enumerate()
        .map(|(i, d)| (d, i))
        .max()
        .unwrap()
        .1;
    let dist1 = bfs(graph, root1, root1);

    let root2 = dist1
        .iter()
        .enumerate()
        .map(|(i, &d)| (d, i))
        .max()
        .unwrap()
        .1;
    let diameter = dist1[root2];
    let dist2 = bfs(graph, root2, root2);
    let mut c1 = 0;
    let mut c2 = 0;
    for i in 0..n {
        if dist1[i] + dist2[i] == diameter {
            if dist1[i] * 2 == diameter {
                c1 = i;
                c2 = i;
            } else if dist1[i] == diameter / 2 {
                c1 = i;
            } else if dist2[i] == diameter / 2 {
                c2 = i;
            }
        }
    }
    (c1, c2)
}

fn bfs(graph: &Vec<Vec<usize>>, root1: usize, root2: usize) -> Vec<usize> {
    let n = graph.len();
    let mut dist = vec![n; n];
    dist[root1] = 0;
    dist[root2] = 0;
    let mut q = VecDeque::new();
    q.push_back(root1);
    q.push_back(root2);
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if dist[next] > dist[v] + 1 {
                dist[next] = dist[v] + 1;
                q.push_back(next);
            }
        }
    }
    dist
}

