            for t in g[v].iter() {
                if f != *t {
                    que.push((*t, v, c + 1));
                }
            }
        }
        let mut leave = 1;
        res[0] += 1;
        res.pop();
        for x in res.iter()  {
            leave *= x;
        }
        ans = std::cmp::min(ans, (res.len() + 1, leave));
    }
    for (a, b) in E {
        let mut que = Vec::new();
        let mut res = Vec::new();
        que.push((a, b, 0));
        que.push((b, a, 0));
        while let Some((v, f, c)) = que.pop() {
            if res.len() == c {
                res.push(g[v].len() - 1);
            }
            else if res[c] < g[v].len() - 1 {
                res[c] = g[v].len() - 1;
            }
            for t in g[v].iter() {
                if f != *t {
                    que.push((*t, v, c + 1));
                }
            }
        }
        let mut leave = 1;
        res.pop();
        for x in res.iter()  {
            leave *= x;
        }
        ans = std::cmp::min(ans, (res.len() + 1, leave * 2));
    }
    let (a, b) = ans;
    println!("{} {}\n", a, b);
}

