fn dfs(
    u: usize,
    p: usize,
    memo: &mut HashMap<(usize, usize), (usize, usize)>,
    next: &Vec<Vec<usize>>,
) -> (usize, usize) {
    let key = (u, p);
    if memo.contains_key(&key) {
        return memo[&key];
    }
    let mut res = Vec::new();
    for &v in &next[u] {
        if v != p {
            let (d, l) = dfs(v, u, memo, next);
            res.push((d, l));
        }
    }
    let ans = if res.len() == 0 {
        (1, 1)
    } else {
        let max_d = res.iter().map(|&(d, _)| d).max().unwrap();
        let max_l = res.iter().map(|&(_, l)| l).max().unwrap();
        (max_d + 1, max_l * res.len())
    };
    memo.insert(key, ans);
    ans
}
fn main() {
    let n = readln();
    let mut next: Vec<Vec<usize>> = vec![vec![]; n];
    let mut edges = Vec::new();
    for _ in 0..n - 1 {
        let (a, b): (usize, usize) = readln();
        next[a - 1].push(b - 1);
        next[b - 1].push(a - 1);
        edges.push((a - 1, b - 1));
    }

    let mut memo = HashMap::new();
    let mut answer = dfs(0, usize::max_value(), &mut memo, &next);
    for r in 0..n {
        answer = min(answer, dfs(r, usize::max_value(), &mut memo, &next));
    }
    for (a, b) in edges {
        let (d1, l1) = dfs(a, b, &mut memo, &next);
        let (d2, l2) = dfs(b, a, &mut memo, &next);
        let ans = (max(d1, d2), 2 * max(l1, l2));
        answer = min(answer, ans);
    }
    println!("{} {}", answer.0, answer.1);
}

