#[derive(Debug)]
pub struct TreeRec {
    pub n: usize,
    pub deg: Vec<usize>,
    pub dep: (usize, usize),
}
impl TreeRec {
    pub fn new(n: usize) -> TreeRec {
        TreeRec {
            n: n,
            deg: vec![0; n],
            dep: (0, 0),
        }
    }
    pub fn init(&mut self) {
        let n = self.n;
        self.deg = vec![0; n];
        self.dep = (0, 0);
    }
    pub fn dfs(&mut self, u: usize, p: usize, d: usize, graph: &Graph) {
        let mut de = 0;
        if self.dep.0 < d {
            self.dep = (d, u);
        }
        for v in graph.adjacency(u) {
            if v.to != p {
                self.dfs(v.to, u, d + 1, graph);
                de += 1;
            }
        }
        self.deg[d] = max(self.deg[d], de);
    }
}
