fn main() {
    input! { n, ab: [(usize1, usize1); n-1] };
    let mut g = Graph::new(n);
    let mut r = TreeRec::new(n);
    for &(a, b) in &ab {
        g.add_undirected_edge(a, b);
    }
    r.dfs(0, n, 0, &g);
    let u = r.dep.1;
    r.init();
    r.dfs(u, n, 0, &g);
    let x = r.dep.0 / 2 + 1;
    let mut ans = std::usize::MAX;
    for u in 0..n {
        r.init();
        r.dfs(u, n, 0, &g);
        let mut y = 1usize;
        for i in 0..n {
            if r.deg[i] == 0 {
                break;
            }
            y = y.saturating_mul(r.deg[i]);
        }
        if r.dep.0 == x - 1 {
            ans = min(ans, y);
        }
    }
    for &(a, b) in &ab {
        r.init();
        r.dfs(a, b, 1, &g);
        r.dfs(b, a, 1, &g);
