use io::*;
use std::cmp::max;

fn main() {
    let con = read_string();
    let mut sc = Scanner::new(&con);

    let n: usize = sc.next();
    let es: Vec<(usize, usize)> = (0..n - 1)
        .map(|_| {
            let f: usize = sc.next();
            let t: usize = sc.next();
            (f - 1, t - 1)
        })
        .collect();

    let mut g: Vec<Vec<usize>> = vec![vec![]; n];

    for &(f, t) in es.iter() {
        g[f].push(t);
        g[t].push(f);
    }

    let mut ans = (n + 1, 0);

    for root in 0..n {
        let t = bfs(&g, &[root]);
        if t < ans {
            ans = t;
        }
    }

    for &(f, t) in es.iter() {
        let t = bfs(&g, &[f, t]);
        if t < ans {
            ans = t;
        }
    }

    println!("{} {}", ans.0, ans.1);
}

fn bfs(g: &Vec<Vec<usize>>, start: &[usize]) -> (usize, usize) {
    let mut cur: Vec<usize> = start.iter().cloned().collect();

    let mut dep = 0;
    let mut leafs = start.len();
    let mut used = vec![false; g.len()];

    for &c in start.iter() {
        used[c] = true;
    }

    while cur.len() > 0 {
        let mut next = vec![];
        let mut maxl = 0;

        for &c in cur.iter() {
            if dep == 0 && start.len() == 1 {
                maxl = max(maxl, g[c].len());
            } else {
                maxl = max(maxl, g[c].len() - 1);
            }

            for &d in g[c].iter() {
                if used[d] {
                    continue;
                }
                used[d] = true;
                next.push(d);
            }
        }

        if maxl != 0 {
            leafs *= maxl;
        }

        dep += 1;

        cur = next;
    }

    (dep, leafs)
}

