            dfs(&mut cc, &g, e.to, s, 0);
            let lc = cc.into_iter().fold(1, |x, y| x*y) * 2;
            if rd < cans {
                cans = rd;
                lans = lc;
            } else if cans == rd {
                lans = min(lans, lc);
            }
        }
    }
    printfln!("{} {}", cans, lans);
}

use std::cmp;
use std::collections::VecDeque;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let x = sc.read::<usize>() - 1;
        let y = sc.read::<usize>() - 1;
        graph[x].push(y);
        graph[y].push(x);
    }

    let (c0, c1) = center(&graph);
    let dist = if c0 == c1 {
        let mut dist = vec![n; n];
        dist[c0] = 1;
        let mut q = VecDeque::new();
        q.push_back(c0);
        while let Some(v) = q.pop_front() {
            for &next in graph[v].iter() {
                if dist[next] > dist[v] + 1 {
                    dist[next] = dist[v] + 1;
                    q.push_back(next);
                }
            }
        }
        dist
    } else {
        let mut dist = vec![n; n];
        dist[c0] = 1;
        dist[c1] = 1;
        let mut q = VecDeque::new();
        q.push_back(c0);
        q.push_back(c1);
        while let Some(v) = q.pop_front() {
            for &next in graph[v].iter() {
                if dist[next] > dist[v] + 1 {
                    dist[next] = dist[v] + 1;
                    q.push_back(next);
                }
            }
        }
        dist
    };

    let max = *dist.iter().max().unwrap();

    let mut count = vec![0; max + 1];
    let mut max_d = vec![0; max + 1];
    for i in 0..n {
        count[dist[i]] += 1;
        let d = graph[i].len();
        max_d[dist[i]] = cmp::max(max_d[dist[i]], d - 1);
        if dist[i] == 1 && c0 == c1 {
            max_d[dist[i]] = cmp::max(max_d[dist[i]], d);
        }
    }

    let mut leaves = if c0 == c1 { 1 } else { 2 };
    for color in 1..max {
        leaves *= max_d[color];
    }

    println!("{} {}", max, leaves);
}

fn center(graph: &Vec<Vec<usize>>) -> (usize, usize) {
    let n = graph.len();
    let dist0 = bfs(0, graph);
    let last = dist0.iter().enumerate().max_by_key(|&(_, &d)| d).unwrap().0;

    let dist1 = bfs(last, graph);
    let last2 = dist1.iter().enumerate().max_by_key(|&(_, &d)| d).unwrap().0;

    let d = dist1[last2];
    if d % 2 == 0 {
        for i in 0..n {
            if dist1[i] == d / 2 {
                return (i, i);
            }
        }
        unreachable!()
    } else {
        let dist2 = bfs(last2, graph);
        let mut c0 = 0;
        let mut c1 = 0;
        for i in 0..n {
            if dist1[i] + dist2[i] == d {
                if dist2[i] == d / 2 {
                    c0 = i;
                }
                if dist2[i] == d / 2 + 1 {
                    c1 = i;
                }
            }
        }
        return (c0, c1);
    }
}

fn bfs(start: usize, graph: &Vec<Vec<usize>>) -> Vec<usize> {
    let n = graph.len();
    let mut dist = vec![n; n];
    dist[start] = 0;
    let mut q = VecDeque::new();
    q.push_back(start);
    while let Some(v) = q.pop_front() {
        for &next in graph[v].iter() {
            if dist[next] > dist[v] + 1 {
                dist[next] = dist[v] + 1;
                q.push_back(next);
            }
        }
    }
    dist
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::Read;

fn solve(g: &Vec<Vec<usize>>, s1: usize, s2: usize) -> (i64, i64) {
    let mut color = vec![-1; g.len()];
    let mut res = 1;
    color[s1] = 1;
    if s2 != !0 { color[s2] = 1; res += 1; }
    let mut cur = 1;
    loop {
        let mut mx = 0;
        for i in 0..g.len() {
            if color[i] != cur { continue }
            let mut cnt = 0;
            for &t in &g[i] {
                if color[t] != -1 { continue; }
                cnt += 1;
                color[t] = cur + 1;
            }
            mx = std::cmp::max(mx, cnt);
        }
        if mx == 0 { break }
        res *= mx;
        if res >= 1 << 60 { return (100000, 1 << 60) }
        cur += 1;
    }
    (cur, res)
}

