fn solve(g: &Vec<Vec<usize> >, vs: Vec<usize>) -> usize {
    let n = g.len();
    let mut d = vec![n; n];
    let mut q = VecDeque::new();
    let mut b = Vec::new();
    for &v in vs.iter() {
        q.push_back(v);
        d[v] = 0;
    }
    while !q.is_empty() {
        let v = q.pop_front().unwrap();
        let mut cnt = 0;
        for &w in g[v].iter() {
            if d[w] < n {
                continue;
            }
            cnt += 1;
            d[w] = d[v] + 1;
            q.push_back(w);
        }
        if b.len() == d[v] {
            b.push(cnt);
        } else {
            b[d[v]] = cmp::max(b[d[v]], cnt);
        }
    }
    let mut ret: usize = vs.len();
    // println!("{:?}", b);
    b.pop();
    for &cnt in b.iter() {
        ret *= cnt;
    }
    return ret;
}


