fn calc(c0: usize, c1: usize, dist: Vec<usize>, graph: &Vec<Vec<usize>>) -> (usize, usize) {
    let n = dist.len();
    let max = *dist.iter().max().unwrap();
    let mut max_d = vec![0; max + 1];
    for i in 0..n {
        let d = graph[i].len();
        max_d[dist[i]] = cmp::max(max_d[dist[i]], d - 1);
        if dist[i] == 1 && c0 == c1 {
            max_d[dist[i]] = cmp::max(max_d[dist[i]], d);
        }
    }

    let mut leaves = if c0 == c1 { 1 } else { 2 };
    for color in 1..max {
        leaves *= max_d[color];
    }
    (max, leaves)
}

fn get_dist(c0: usize, c1: usize, graph: &Vec<Vec<usize>>) -> Vec<usize> {
    let n = graph.len();
    if c0 == c1 {
        let mut dist = vec![n; n];
        dist[c0] = 1;
        let mut q = VecDeque::new();
        q.push_back(c0);
        while let Some(v) = q.pop_front() {
            for &next in graph[v].iter() {
                if dist[next] > dist[v] + 1 {
                    dist[next] = dist[v] + 1;
                    q.push_back(next);
                }
            }
        }
        dist
    } else {
        let mut dist = vec![n; n];
        dist[c0] = 1;
        dist[c1] = 1;
        let mut q = VecDeque::new();
        q.push_back(c0);
        q.push_back(c1);
        while let Some(v) = q.pop_front() {
            for &next in graph[v].iter() {
                if dist[next] > dist[v] + 1 {
                    dist[next] = dist[v] + 1;
                    q.push_back(next);
                }
            }
        }
        dist
    }
