fn main() {
    #![allow(unused_imports, unused_macros)]
    use std::io::{stdin, stdout, BufWriter, Read as _, Write as _};
    let mut _in_buf = Vec::new();
    stdin().read_to_end(&mut _in_buf).expect("io error");
    let _in_buf = unsafe { String::from_utf8_unchecked(_in_buf) };
    let mut scanner = Scanner::new(&_in_buf);
    macro_rules !scan {() =>{scan !(usize ) } ;(($($t :tt ) ,*) ) =>{($(scan !($t ) ) ,*) } ;([$t :tt ;$len :expr ] ) =>{(0 ..$len ) .map (|_ |scan !($t ) ) .collect ::<Vec <_ >>() } ;([$t :ty ;$len :expr ] ) =>{scanner .scan_vec ::<$t >($len ) } ;([$t :ty ] ) =>{scanner .iter ::<$t >() } ;({$e :expr } ) =>{scanner .mscan ($e ) } ;($t :ty ) =>{scanner .scan ::<$t >() } ;}
    let _out = stdout();
    let mut _out = BufWriter::new(_out.lock());
    macro_rules !print {($($arg :tt ) *) =>(::std ::write !(_out ,$($arg ) *) .expect ("io error" ) ) }
    macro_rules !println {($($arg :tt ) *) =>(::std ::writeln !(_out ,$($arg ) *) .expect ("io error" ) ) }
    macro_rules! echo {
        ($iter :expr ) => {
            echo!($iter, '\n')
        };
        ($iter :expr ,$sep :expr ) => {
            let mut iter = $iter.into_iter();
            if let Some(item) = iter.next() {
                print!("{}", item);
            }
            for item in iter {
                print!("{}{}", $sep, item);
            }
            println!();
        };
    }
    let n = scan!();
    let (g, _) = scan!({ TreeGraphScanner::<marker::Usize1, ()>::new(n) });
    let mut ans = (n * 2, std::usize::MAX);
    for u in 0..n {
        let deg = g.tree_deg(u);
        let x = deg.iter().cloned().fold(1usize, |x, y| x.saturating_mul(y));
        chmin!(ans, (deg.len() + 1, x));
    }
    for (u, v) in g.edges.iter().cloned() {
        let deg = g.tree_deg2(u, v);
        let x = deg.iter().cloned().fold(1usize, |x, y| x.saturating_mul(y));
        chmin!(ans, (deg.len(), x));
    }
    println!("{} {}", ans.0, ans.1);
}
impl UndirectedSparseGraph {
    fn deg_dfs(&self, u: usize, p: usize, d: usize, deg: &mut Vec<usize>) {
        let mut dg = 0;
        if deg.len() == d {
            deg.push(0);
        }
        for a in self.adjacencies(u).filter(|a| a.to != p) {
            dg += 1;
            self.deg_dfs(a.to, u, d + 1, deg);
        }
        chmax!(deg[d], dg);
    }
    pub fn tree_deg(&self, root: usize) -> Vec<usize> {
        let mut deg = vec![];
        self.deg_dfs(root, self.vertices_size(), 0, &mut deg);
        deg.pop();
        deg
    }
    pub fn tree_deg2(&self, root: usize, root2: usize) -> Vec<usize> {
        let mut deg = vec![2];
        self.deg_dfs(root, root2, 1, &mut deg);
        self.deg_dfs(root2, root, 1, &mut deg);
        deg.pop();
        deg
    }
}
